INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(4, 1, 37, '<p>tentang eksponen</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-11 19:01:07', '2025-11-11 19:01:07'),
(5, 1, 98, '<p>berikan saya soal </p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:16:11', '2025-11-17 18:16:11'),
(6, 1, 94, '<p>apa itu trigonometri </p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:17:54', '2025-11-17 18:17:54'),
(7, 1, 113, '<p>apa saja konsep dari eksponen</p>', NULL, '<p>mengerjakan secara perlahan</p>', NULL, '<p>mengerjakan dari yg lebih mudah dulu</p>', NULL, '2025-11-17 18:18:42', '2025-11-17 18:22:34'),
(8, 1, 88, '<p>Mengetahui materi aljabar</p>', NULL, '<p>menggunakan rumus</p>', NULL, '<p>dengan belajar dengan sungguh sungguh </p>', NULL, '2025-11-17 18:20:07', '2025-11-17 18:21:23'),
(9, 1, 115, '<p>cara menyederhanakan eksponen</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:21:15', '2025-11-17 18:21:15'),
(10, 1, 91, '<p>ekspononen</p>', NULL, '<p>tulisan dikerahuinsandan penyelesaian </p>', NULL, '<p>tau aoa yang di tanyakan di soalnya </p>', NULL, '2025-11-17 18:21:41', '2025-11-17 18:22:56'),
(11, 1, 95, NULL, NULL, '<p>menganalis dan memahami maksud soal itu, lalu jika sudah mengerti mengerjakan</p>', NULL, '<p>memahami konsep dasarnya terlebih dahulu, lalu lanjut ke yang lebih sulit</p>', NULL, '2025-11-17 18:21:51', '2025-11-17 18:24:15'),
(12, 1, 105, '<p>Materi mengenai eksponen </p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:22:56', '2025-11-17 18:22:56'),
(13, 1, 111, '<p>Sy mengetahui materi ini bisa di gunakan di kehidupan sehari-hari </p>', NULL, '<p>Kita harus mengetahui dari mana angka itu bisa di temukan dan kita harus memakai rumus supaya dapat membantu dalam mengerjakan hitung menghitung </p>', NULL, '<p>Menyelesaikannya sesuai dengan soal yang di tnyan supaya tidak melenceng jawaban nya</p>', NULL, '2025-11-17 18:23:12', '2025-11-17 18:27:37'),
(14, 1, 110, '<p>lumayan banyak</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:23:43', '2025-11-17 18:23:43'),
(15, 1, 107, '<p>saya mengetahui bahwa AI nya hanya menjawab pada materi yang kita pilih, contoh aljabar, AI nya hanya bisa menjelaskan tentang materi-materi yang berkaitan dengan aljabar </p>', NULL, NULL, NULL, '<p>pahami soalnya, dan cari kata kunci pada soal tersebut </p>', NULL, '2025-11-17 18:24:07', '2025-11-17 18:28:19'),
(16, 1, 93, '<p>eksplorasi konsep</p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Ekspresi eksponen merupakan representasi matematis dari operasi perpangkatan. Dalam eksplorasi konsep ini, kita memahami bahwa eksponen mengindikasikan jumlah pengulangan suatu angka atau variabel.</span></p>', NULL, '<p>Ekspresi eksponen merupakan representasi dari operasi perpangkatan yang melibatkan basis dan eksponen. Eksponen menunjukkan berapa kali basis akan dikalikan dengan dirinya sendiri.</p>', NULL, '2025-11-17 18:24:22', '2025-11-17 18:29:05'),
(17, 1, 109, '<p>Ekspresi eksponen melibatkan penggunaan pangkat atau eksponen untuk menunjukkan berapa kali suatu angka (yang disebut sebagai dasar) akan dikalikan dengan dirinya sendiri. </p>', NULL, NULL, NULL, NULL, NULL, '2025-11-17 18:25:25', '2025-11-17 18:25:25'),
(18, 1, 114, '<p>Eksplorasi teks</p>', NULL, '<p>Membaca dengan teliti</p>', NULL, '<p>Dengan cara mengerjakan dengan teliti</p>', NULL, '2025-11-17 18:32:50', '2025-11-17 18:34:05'),
(19, 1, 134, '<p><span style=\"color: rgb(51, 65, 85);\">Eksponen merupakan bilangan yang menunjukkan seberapa kali suatu angka (yang disebut basis) akan dikalikan dengan dirinya sendiri.</span></p>', NULL, NULL, NULL, NULL, NULL, '2025-11-18 18:47:32', '2025-11-18 18:47:32'),
(20, 1, 146, '<p>perbedaan eksponen dan logaritma </p>', NULL, '<p>memahami dengan baik apa yang diminta dalam soal tersebut</p>', NULL, '<p>memahami konsep dasarnya terlebih dahulu</p>', NULL, '2025-11-18 18:49:43', '2025-11-18 18:52:46'),
(21, 1, 143, '<p>dari materi ini saya jadi tahu tentang apa itu eksponen</p>', NULL, '<p>sebelum mulai menghitung hasil akhirnya adalah kita perlu memahami informasi dari soal tersebut</p>', NULL, '<p>memahami konsep eksponen </p>', NULL, '2025-11-18 18:49:58', '2025-11-18 18:55:11'),
(22, 1, 148, '<p>Dalam topik eksplorasi konsep mengenai ekspresi eksponen, kita belajar tentang bagaimana mengungkapkan operasi matematika dengan pangkat. </p>', NULL, NULL, NULL, NULL, NULL, '2025-11-18 18:53:34', '2025-11-18 18:53:34'),
(23, 1, 172, '<p>saya sudah tau</p>', NULL, '<p>yaitu dengan cara seperti pada pembelajaran sebelumnya </p>', NULL, '<p>yaitu dengan cara membaca soal terlebih dahulu dan memahami sebelum mengerjakan</p>', NULL, '2025-11-25 20:50:56', '2025-11-25 20:55:09'),
(24, 1, 160, '<p>sy sudah tau</p>', NULL, '<p>seperti pada pembahasan sebelumnya </p>', NULL, '<p>yaitu dengan cara membaca soal lebih teliti dan memahami </p>', NULL, '2025-11-25 20:52:03', '2025-11-25 20:55:22'),
(25, 1, 169, '<p>bagus</p>', NULL, '<p>keren</p>', NULL, NULL, NULL, '2025-11-25 20:57:37', '2025-11-25 20:58:04'),
(26, 1, 161, '<p>Aku belum tau apa konsep nya</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-25 20:58:17', '2025-11-25 20:58:17'),
(27, 1, 170, '<p>bagusssssssdssd bgttttttttttyttttttt</p>', NULL, '<p>dear mom everything you did was worth it</p>', NULL, '<p>be great or die trying</p>', NULL, '2025-11-25 20:58:38', '2025-11-25 21:00:39'),
(28, 1, 158, '<p><strong>APLIKASI INI KEREN DAN CANGGIH</strong></p>', NULL, '<p>BERIMAJINASI</p>', NULL, '<p>BERDOA KEPADA ALLAH</p>', NULL, '2025-11-25 20:58:51', '2025-11-25 21:02:41'),
(29, 1, 166, '<p>Cara menghitung Dangan mudah </p>', NULL, '<p>Dengan cara melihat rumusnya</p>', NULL, '<p>Melihat rumusnya </p>', NULL, '2025-11-25 21:02:15', '2025-11-25 21:04:22'),
(30, 1, 181, NULL, NULL, '<p>Sebaiknya saya akan mendengar kan dengan baik terlebih dahulu agar saya lebih paham lagi </p>', NULL, NULL, NULL, '2025-11-25 21:04:08', '2025-11-25 21:04:08'),
(31, 1, 179, '<p>Ekspresi eksponen digunakan untuk menyatakan proses atau peristiwa yang mengalami peningkatan atau penurunan secara berlipat.</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-25 21:06:10', '2025-11-25 21:06:10'),
(32, 1, 182, '<p><strong>Ekspresi eksponen</strong>&nbsp;digunakan untuk menyatakan proses atau peristiwa yang mengalami peningkatan atau penurunan secara berlipat.</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-25 21:06:27', '2025-11-25 21:06:27'),
(33, 1, 159, '<p>Ekspresi eksponen digunakan untuk menyatakan proses atau peristiwa yang mengalami peningkatan atau penurunan secara berlipat.</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-25 21:06:30', '2025-11-25 21:06:30'),
(34, 1, 165, '<p>Eksponen adalah bilangan yang berpangkat</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-25 21:06:55', '2025-11-25 21:06:55'),
(35, 1, 156, '<p>hhhhh</p>', NULL, '<p>bbbbbbbbbbbbbb</p>', NULL, '<p>bbbbbbbbbbbbbbbbbbbbbbbb</p>', NULL, '2025-12-07 16:52:12', '2025-12-07 16:52:58'),
(36, 1, 124, '<p>nnnnnnnnnnnnnnnnnnnnnnnn</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-10 22:15:08', '2025-12-10 22:54:39'),
(37, 3, 124, '<p>nnnnnnnnnnnnnnnnnnnnnnnnnnn</p>', NULL, '<p>menuliskan apa yang diketahui, memhami masalah, kemudian menyelesaikannya</p>', NULL, NULL, NULL, '2025-12-10 23:23:59', '2026-04-26 09:01:19'),
(38, 1, 195, '<p>saya telah mengetauhui tentang defenisi eksponen, sifat-sifat eksponen, dan pengoperasian eksponen.</p>', NULL, '<p>memahami soal dan apa perintahya lalu mengerjakanya</p>', NULL, '<p>memahami konsep eksponen,mengidentifikasi jenis soal, menggunakan sifat-sifat eksponen, mengubah bentuk eksponen, menggunakan aturan-aturan eksponen,dan memeriksa hasilnya.</p>', NULL, '2025-12-12 16:27:14', '2025-12-12 19:47:40'),
(39, 1, 346, '<p>Pengetahuan yang saya peroleh setelah mempelajari topik ini, yaitu di antaranya: Mengetahui defenisi dan bentuk umum bilangan eksponen, mengetahui sifat-sifat eksponen, serta langkah-langkah penyelesaian soal bilangan eksponen. </p>', NULL, '<p> masing-masing menulari 2 orang, maka bentuknya yaitu 2 x 2 x.. x 2. Untuk melakukan penularan ke seluruh populasi di wilayah tersebut, dibutuhkan 8 kali penularan. Bentuk eksponennya yaitu 2^8.</p>', NULL, '<p>cermati soal dan bentuk bilangan eksponennya, apabila terdapat soal yang menginstruksikan untuk menyederhanakan bentuk eksponen, maka gunakan sifat-sifat eksponen untuk menyederhanakannya. </p>', NULL, '2025-12-12 18:10:33', '2025-12-12 18:51:42'),
(40, 1, 194, '<p>Eksponen adalah konsep matematika untuk menyatakan perkalian berulang dan memodelkan perubahan berlipat ganda, yang banyak digunakan dalam berbagai bidang dan mempermudah perhitungan matematika.</p>', NULL, '<p>Pahami cerita, tentukan kata kunci dan yang ditanyakan, ubah ke model matematika, lalu hitung dan sesuaikan hasil dengan soal.</p>', NULL, '<p>Saya menyusun strategi dengan mengidentifikasi informasi penting dalam soal, menentukan bentuk eksponen yang tepat, dan menyelesaikannya sesuai aturan eksponen yang berlaku.</p>', NULL, '2025-12-12 18:14:23', '2025-12-12 18:16:32'),
(41, 1, 345, '<p>Saya memahami bahwa eksponen adalah cara menuliskan perkalian berulang secara ringkas dan konsep ini banyak digunakan untuk menjelaskan pertumbuhan atau penurunan yang terjadi secara cepat dalam kehidupan sehari-hari.</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, lalu mengubahnya ke dalam bentuk eksponen sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menyesuaikan strategi penyelesaian dengan konteks soal, apakah termasuk pertumbuhan, peluruhan, atau penyederhanaan bentuk eksponen, agar solusi yang digunakan tepat.</p>', NULL, '2025-12-12 18:21:37', '2025-12-12 18:34:48'),
(42, 1, 330, '<p>definisi eksponen,sifat-sifat eksponen dan cara menyederhanakan eksponen</p>', NULL, '<p>pertama membaca dengan seksama materi yang ada,kemudian memahami isi materi dan mulai menghitung dan mengerjakan soal yang diberikan</p>', NULL, NULL, NULL, '2025-12-12 18:26:03', '2025-12-12 18:29:27'),
(43, 1, 214, '<p>Definisi eksponen, sifat-sifat eksponen, dan cara menyederhanakan eksponen</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-12 18:26:32', '2025-12-12 18:26:32'),
(44, 1, 276, '<p>Bilangan berpangkat (a^n) menyatakan hasil perkalian bilangan (a) dengan dirinya sendiri sebanyak (n) kali.</p>', NULL, '<p>Baca soal dengan teliti untuk memahami masalahnya.</p><p>Tentukan data yang diketahui dan ditanyakan lalu ubah ke bentuk eksponen.</p><p>Gunakan sifat eksponen yang tepat untuk memperoleh hasil akhir.</p><p><br></p>', NULL, '<p>Saya memahami konteks soal dan menentukan apa yang diketahui serta ditanyakan.</p><p>Kemudian, saya mengubahnya ke bentuk bilangan berpangkat.</p><p>Terakhir, saya menggunakan sifat eksponen yang sesuai untuk menyelesaikan soal.</p><p><br></p>', NULL, '2025-12-12 18:44:36', '2025-12-12 18:50:13'),
(45, 1, 277, '<p>Definisi dan sifat-sifat eksponen menunjukkan bahwa eksponen menyatakan perkalian berulang, dapat diperluas ke berbagai bentuk pangkat, dan memiliki aturan yang memudahkan penyederhanaan serta penyelesaian masalah matematika</p>', NULL, '<p>Soal cerita eksponen diselesaikan dengan membaca soal, mengubahnya ke bentuk eksponen, menentukan sifat yang digunakan, lalu menyusun langkah perhitungan</p>', NULL, '<p>Strategi penyelesaian dilakukan dengan memahami konteks masalah, menentukan besaran yang diketahui dan ditanyakan, mengubahnya ke bentuk eksponen yang sesuai, lalu menerapkan sifat-sifat eksponen secara tepat untuk memperoleh solusi</p>', NULL, '2025-12-12 18:46:43', '2025-12-12 18:52:51'),
(46, 1, 344, '<p>Dapat menginterpretasi bagian dari ekspresi (bentuk) eksponen sederhana,  dan kompleks,  dan dapat menjelaskan pengertian solusi dari sistem persamaan linear tiga variabel berdasarkan pemahaman solusi dari sistem persamaan linear dua variabel.</p>', NULL, '<p>langkah yang sebaiknya di lakukan sebelum menyelesaikan soal cerita matematika yaitu baca dengan teliti agar mendapatkan hasil akhir yang bagus</p>', NULL, '<p><span style=\"background-color: rgb(248, 250, 252);\">strategi untuk menyelesaiakan soal pada topik ini sesuai konteks masalah matematika yaitu dengan penalaran logika</span></p>', NULL, '2025-12-12 18:47:36', '2025-12-12 19:24:34'),
(47, 2, 276, '<p>Dari materi ini, saya memahami persamaan dan pertidaksamaan linear serta sistem persamaan linear dua dan tiga variabel. Saya juga mengetahui bentuk umum, kemungkinan solusi, dan metode penyelesaiannya seperti grafik, eliminasi, dan substitusi.</p>', NULL, '<p>Pahami soal dengan teliti.</p><p>Tentukan data dan buat model matematika.</p><p>Pilih metode yang tepat sebelum menghitung.</p>', NULL, '<p>Saya memahami konteks soal dan menentukan variabel.</p><p>Kemudian memodelkannya ke bentuk matematika.</p><p>Terakhir memilih metode penyelesaian yang tepat.</p>', NULL, '2025-12-12 19:10:33', '2025-12-12 19:14:05'),
(48, 1, 337, NULL, NULL, '<p>Langkah-langkah yang saya lakukan yaitu:</p><ol><li>Yang pertama pastinya saya harus memahami dulu permintaan soal </li><li>Melengkapi pola penularan</li><li>Menentukan fase penularan</li><li>Lalu melengkapi tabel penularan dan tabel eksponen</li></ol>', NULL, '<p>Saat menemukan soal perkalian berulang, saya menggunakan bentuk bilangan berpangkat untuk memudahkan saya, menggunakan sifat-sifat eksponen untuk menyelesaikan </p>', NULL, '2025-12-12 19:13:09', '2025-12-12 19:16:45'),
(49, 2, 277, '<p>Dari materi pada topik ini, saya mengetahui pengertian, bentuk, dan cara menyelesaikan sistem persamaan serta pertidaksamaan linear dua dan tiga variabel beserta penerapannya dalam masalah kontekstual.\\</p><p><br></p>', NULL, '<p>Langkah penyelesaian dilakukan dengan memahami soal, menentukan variabel dan informasi penting, memodelkannya ke dalam sistem persamaan atau pertidaksamaan linear, lalu merencanakan cara penyelesaiannya sebelum menghitung</p><p><br></p>', NULL, '<p>Strategi penyelesaian dilakukan dengan memahami konteks masalah, menentukan variabel yang tepat, membentuk model sistem persamaan atau pertidaksamaan linear, lalu memilih metode penyelesaian yang paling sesuai</p><p><br></p>', NULL, '2025-12-12 19:18:31', '2025-12-12 19:21:13'),
(50, 1, 286, '<p>Saya memahami tentang definisi dan sifat-sifat eksponen.</p>', NULL, '<p>bacalah soal dengan cermat  ubah dalam bentuk ekspresi eksponen dan tentukan sifatnya</p><p><br></p>', NULL, '<p>memahami konteks masalah, memilih konsep  yang sesuai, lalu menyusun langkahnya</p>', NULL, '2025-12-12 19:39:16', '2025-12-13 21:22:09'),
(51, 4, 276, '<p>Fungsi kuadrat f(x)=ax²+bx+c (a≠0): parabola atas (a&gt;0, min) atau bawah (a&lt;0, maks).​</p><p>Persamaan ax²+bx+c=0: faktorisasi, kuadrat sempurna, atau x=[-b±√(b²-4ac)]/2a.</p>', NULL, '<ol><li>Pahami cerita, identifikasi variabel dan bentuk fungsi kuadrat.​</li><li>Buat persamaan dari data (titik potong, puncak).​</li><li>Hitung diskriminan, optimum, interpretasi hasil.​</li></ol><p><br></p>', NULL, '<p>Baca soal dan kenali variabel dengan pola kuadrat.</p><p>Bentuk rumus dari data potong sumbu atau puncak.</p><p>Hitung akar dan optimum, lalu jelaskan artinya.</p>', NULL, '2025-12-12 19:43:58', '2025-12-12 19:47:41'),
(52, 1, 268, '<p>Saya sudah memahami eksponen sebagai perkalian berulang, penerapannya dalam kehidupan, serta cara menyelesaikan soal dengan sifat-sifat eksponen.</p>', NULL, '<p>Saya membaca soal dengan cermat, mengubah informasi penting jadi kalimat matematika, lalu mengecek kembali sebelum menghitung hasil akhir.</p>', NULL, '<p>Saya memahami konteks soal, lalu mengidentifikasi informasi penting seperti jenis pertumbuhan atau peluruhan, dan memilih sifat eksponen yang sesuai untuk menyusun kalimat matematikanya.</p>', NULL, '2025-12-12 19:49:41', '2025-12-12 19:56:30'),
(53, 4, 277, '<p> Fungsi kuadrat f(x) = ax^2 + bx + c memiliki arah bukaan yang ditentukan oleh a, titik puncak  P(-b/2a, -D/4a), diskriminan D menentukan jumlah perpotongan sumbu x, dan akarnya dicari melalui faktorisasi, kuadrat sempurna, atau rumus abc</p>', NULL, '<p>Penyelesaian soal cerita fungsi kuadrat memerlukan pemodelan ke bentuk f(x)=ax^2+bx+c, kemudian menentukan  apakah tujuan soal mencari Titik Puncak atau Akar, serta memvalidasi arah grafik dari koefisien a</p>', NULL, '<p>Strategi utamanya adalah memodelkan masalah ke f(x)=ax^2+bx+c, lalu menentukan apakah yang dicari adalah Titik Puncak (optimasi) atau Akar (titik potong sumbu x), didukung oleh analisis koefisien a</p>', NULL, '2025-12-12 19:50:55', '2025-12-12 20:02:56'),
(54, 2, 195, '<p>Ynag saya telah ketahui dari materi ini yaitu tentang defenisi, penyelesaian, dan pengoperasa sistem persaaman linear dan pertidaksamaan linear, </p>', NULL, '<p>dengan cara membaca dan memahami soal dan apa perinah dari soal tersubut dan melakukan pengoperasian</p>', NULL, '<p>memahami konsep soal,mengidentifikasi jenis soal, menggunakan sifat-sifat eksponen, mengubah bentuk eksponen, menggunakan aturan-aturan eksponen,dan memeriksa hasilnya.</p>', NULL, '2025-12-12 19:55:15', '2025-12-12 20:00:34'),
(55, 1, 237, '<p>Pengertian eksponen dan sifat-sifat eksponen.</p>', NULL, '<ol><li>membaca soal dengan teliti</li><li>mengidentifikasi informasi penting</li><li>menentukan model matematika</li><li>menentukan sifat-sifat eksponen yang sesuai</li><li>melakukan perhitungan</li></ol>', NULL, '<p>memahami konteks soal, mengubahnya ke bentuk model eksponen yang sesuai, lalu menerapkan sifat-sifat bilangan berpangkat untuk mendapatkan situasi yang tepat.</p>', NULL, '2025-12-12 19:57:47', '2025-12-12 20:08:36'),
(56, 1, 199, '<p>Dari materi ini saya mengetahui bahwa eksponen adalah berapa kali suatu bilangan dikalikan dengan dirinya sendiri dengan bentuk umumnya a pangkat n</p>', NULL, '<p>Pahami cerita</p><p><br></p><p>Tentukan jumlah awal</p><p><br></p><p>Tentukan cara berubah</p><p><br></p><p>Hitung berapa kali berubah</p><p><br></p><p>Gunakan eksponen</p><p><br></p><p>Hitung hasilnya</p><p><br></p><p>Buat kesimpulan</p>', NULL, '<p>Pahami dulu pertanyaan yang ada pada soal, kemudian tentukan nilai² awal yang akan diperhitungkan, setelah kita tahu cara apa yang akan digunakan maka mulailah menghitung hasil dan berikan kesimpulan diakhir </p>', NULL, '2025-12-12 19:59:38', '2025-12-12 22:14:31'),
(57, 1, 230, '<p>Yang sudah saya ketahui tentang materi pada topik ini adalah definisi dari eksponen serta sifat-sifat dari eksponen dan beberapa cara menyelesaikan soal yang berkaitan materi tersebut</p>', NULL, NULL, NULL, '<p>dengan cara berpikir kritis tentang cara yang dilakukan untuk menyelesaikan soalnya</p>', NULL, '2025-12-12 20:06:31', '2025-12-12 20:13:46'),
(58, 1, 333, '<p>Eksponen (bilangan berpangkat) adalah bentuk perkalian berulang yang ditulis a^n, dengan a sebagai basis dan n sebagai pangkat. Sifat-sifat eksponen dan penggunaannya.</p>', NULL, '<p>Membaca dan memahami soal, menentukan data yang diketahui dan ditanyakan, mengidentifikasi pola atau model eksponen, menuliskan model matematika, melakukan perhitungan</p>', NULL, '<p>Strategi saya adalah mengubah soal cerita ke bentuk eksponen, menggunakan sifat-sifat eksponen yang sesuai<strong>,</strong> dan mengecek kembali hasil agar sesuai dengan konteks masalah.</p>', NULL, '2025-12-12 20:07:54', '2025-12-12 20:12:05'),
(59, 2, 344, '<p>pada topik tersebuut saya dapat memahami persamaan dan pertidaksamaan liner dua variabel</p>', NULL, '<p>dibaca dengan teliti dan diidentifikasi ssuai soal yang diberikan</p>', NULL, '<p>selesaiakn sesuai prosesur pengerjaan</p>', NULL, '2025-12-12 20:09:59', '2025-12-12 20:15:08'),
(60, 2, 337, '<p>Dari materi pada topik ini saya sudah mengetahui definisi dari sistem persamaan linear, kemudian ada beberapa  macam sistem persamaan linear contoh spldv, spltv, dst..</p>', NULL, '<p>Mengubahnya terlebih dahulu ke dalam bentuk matematika, lalu memilih cara penyelesaian yang sesuai, apakah eliminasi, substitusi, campuran,maupun grafik</p>', NULL, NULL, NULL, '2025-12-12 20:14:37', '2025-12-12 20:15:59'),
(61, 4, 195, '<p>yang saya ketahui tentang meteri ini yaitu karakteristik fungsi kuadrat dan cara menentukan akar-akar persamaan kuadrat</p>', NULL, '<p>dengan cara membaca dan memahami soal dan apa perinah dari soal tersubut dan melakukan pengoperasian.</p>', NULL, '<p>memahami konsep soal,mengidentifikasi jenis soal, menggunakan sifat-sifat eksponen, mengubah bentuk eksponen, menggunakan aturan-aturan eksponen,dan memeriksa hasilnya.</p>', NULL, '2025-12-12 20:30:22', '2025-12-12 22:45:52'),
(62, 1, 196, '<p>bahwa eksponen adalah bentuk pangkat</p>', NULL, '<p>baca, tentukan, kenali, rumuskan, substitusikan, sederhanakan, dan hitung hasil akhir</p>', NULL, '<p>menyesuaikan strategi sesuai jenis masalah. contoh jika soal tentang persamaan eksponensial maka samakan pangkat atau gunakan logaritma</p>', NULL, '2025-12-12 20:43:16', '2025-12-12 20:51:01'),
(63, 5, 276, '<p>Fungsi eksponen adalah fungsi dengan bilangan berpangkat yang dapat bertambah (pertumbuhan) atau menurun (peluruhan) secara konsisten. Grafiknya selalu di atas sumbu x, memiliki batas horizontal, dan memotong sumbu y di satu titik.</p>', NULL, '<p>Langkah-langkahnya: pahami soal, tentukan data dan yang ditanya, pilih metode atau rumus eksponen yang sesuai, lalu susun strategi sebelum menghitung hasil akhir.</p><p><br></p>', NULL, '<p>Saya menentukan strategi saat memahami soal dan mengetahui data serta yang ditanya, lalu memilih metode atau rumus yang paling sesuai dengan konteks masalah agar perhitungan lebih tepat dan efisien.</p>', NULL, '2025-12-12 20:43:49', '2025-12-12 20:47:57'),
(64, 1, 279, '<p>Pada topik ini, saya jadi tahu definisi dari eksponen, sifat-sifat dan cara untuk menyederhanakannya.</p>', NULL, '<p>analisis soal, periksa sifat eksponen yang berkaitan, sederhanakan, tentukan nilai akhir. </p>', NULL, '<p>bekerja secara kelompok, bertanya pada teman dan guru, mencari di internet.</p>', NULL, '2025-12-12 20:54:28', '2025-12-12 21:47:38'),
(65, 1, 191, '<p>Eksponen adalah&nbsp;cara singkat untuk menulis perkalian berulang suatu bilangan dengan dirinya sendiri</p>', NULL, '<p>langkah-langkahnya yaitu pertama baca dan pahami soal terlebih dahulu lalu mengidentifikasi apa yang diketahui didalam soal, cara atau langkah-langkah apa yang seharusnya digunakan dan terakhir mulai menyelesaikan soal.</p>', NULL, '<p>kita harus mengetahui dulu masalah yang ada pada soal lalu mengidentifikasi metode yang cocok dengan soal dan mulai mengerjakan.</p>', NULL, '2025-12-12 21:02:33', '2025-12-12 21:24:49'),
(66, 1, 242, '<p>Saya sudah mengetahui konsep dasar bilangan eksponen, seperti arti basis dan pangkat serta cara menyederhanakan bentuk eksponen menggunakan sifat-sifatnya.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, memahami konteksnya, menuliskan yang diketahui dan ditanyakan, lalu menentukan model dan rumus matematika sebelum menghitung hasil akhir.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, menentukan yang diketahui dan ditanyakan, memilih rumus yang sesuai, lalu menyelesaikannya secara bertahap dan mengecek kembali hasilnya.</p>', NULL, '2025-12-12 21:09:50', '2025-12-12 21:13:11'),
(67, 6, 276, '<p>Langkah-langkah sudah benar dan urut, tapi kekeliruan bisa muncul jika pengguna tidak konsisten menganggap Titik A sebagai titik asal (0,0). Semua pengukuran harus dihitung relatif dari Titik A yang baru.</p>', NULL, '<p>Pahami soal dan tentukan yang diketahui serta yang ditanya.</p><p>Pilih strategi atau metode yang tepat.</p><p>Buat sketsa atau catatan untuk memvisualisasikan masalah.</p>', NULL, '<p>Strategi ditentukan setelah memahami soal dan mengetahui apa yang ditanya. Pilih metode yang sesuai dengan jenis soal, lalu rencanakan langkah-langkah perhitungan agar hasilnya relevan dengan konteks masalah.</p>', NULL, '2025-12-12 21:11:45', '2025-12-12 21:13:54'),
(68, 4, 340, '<p>saya jadi tau tentang materi fungsi kuadrat</p>', NULL, '<p>Langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanya, menetapkan variabel, lalu membentuk model fungsi kuadrat yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi yang saya gunakan adalah memahami konteks soal terlebih dahulu, menentukan variabel dan informasi yang diketahui, mengubahnya ke dalam model fungsi kuadrat, lalu memilih metode penyelesaian yang paling sesuai dengan tujuan masalah.</p>', NULL, '2025-12-12 21:13:26', '2025-12-12 21:57:04'),
(69, 5, 277, '<p>Fungsi eksponen adalah f(x)=n . a^x dengan a&gt;0 dan a tidak sama dengan 1, dibagi menjadi pertumbuhan (a&gt;1) dan peluruhan (0&lt;a&lt;1). Grafiknya selalu di atas sumbu x dan memiliki asimtot datar y=0</p>', NULL, '<p>Langkah-langkahnya adalah identifikasi fungsi (pertumbuhan atau peluruhan), bangun model<strong> </strong>f(x)=n . a^x dengan parameter yang tepat, dan verifikasi unit waktu sebelum menentukan nilai x untuk perhitungan akhir</p>', NULL, '<p>Strategi pemecahan soal muncul saat konteks masalah diidentifikasi (misalnya, pertumbuhan eksponen, peluruhan, kuadrat), yang kemudian mengarahkan pada pemodelan yang tepat (f(x)) dan verifikasi unit sebelum substitusi nilai x.</p>', NULL, '2025-12-12 21:19:00', '2025-12-12 21:23:19'),
(70, 3, 322, '<p>materi mengenai perbandingan trigometri dan memecahkan masalah yang melibatkan segitiga siku-siku.</p>', NULL, '<p>pertama, membaca dan memahami soal dengan seksama untuk mengenali apa yang diketahui dan ditanyakan. selanjutnya, buat sketsa atau diagram untuk menvisualkan soal, kemudia kita idintifikasi perbandingan trigonometrinya (sinus, cosinus, tangen)</p>', NULL, '<p>Caranya adalah dengan membaca soal berulang sampai memahami tujuan, mengidentifikasi informasi penting dan yang ditanyakan, mengubah situasi kontekstual menjadi model matematis (seperti diagram, persamaan, atau tabel)</p>', NULL, '2025-12-12 21:23:31', '2025-12-12 21:40:12'),
(71, 2, 346, '<p>defenisi dari persamaan linear dan bentuk umum dari persamaan linear baik SPLDV maupun SPLTV dan cara menyelesaikan soal dan menentukan himpunan penyelesaiannya; serta defenisi dari sistem pertidaksamaan linear serta cara menyelesaikannya.</p>', NULL, '<p>Langkah-langkahnya yaitu menentukan variabelnya terlebih dahulu lalu menyusun sistem persamaannya dan menyelesaikan dengan cara eliminasi dan substitusi</p>', NULL, '<p>Strateginya yaitu memahami soal dan megerjakannya dengan prosedur yang benar</p>', NULL, '2025-12-12 21:29:20', '2025-12-12 21:31:59'),
(72, 2, 286, '<p>definisi, bentuk umum, dan fungsi persamaan dan pertidaksamaan linear</p>', NULL, '<p> memahami soal, menentukan variabel, memodelkan cerita lalu merencanakan penyelesaian</p>', NULL, '<p> memahami konteks masalah, menentukan model sistem yang tepat, lalu menyelesaikannya </p>', NULL, '2025-12-12 21:30:46', '2025-12-13 21:28:29'),
(73, 2, 196, '<p>bahwa sistem persamaan dan pertidaksamaan ini dapat juga di aplikasikan dalam kehidupan sehari-hari</p>', NULL, '<p>kenali soal, menentukan apa yang diketahui, perhatikan tanda persamaan dan pertidaksamaan, lalu selesaikan soal sesuai dengan konteks soal</p>', NULL, '<p>Saya sesuaikan strategi dengan jenis masalahnya. Kalau soal tentang harga atau uang (misalnya belanja), saya fokus pada total dan harga satuan.&nbsp;&nbsp;Intinya, saya pahami dulu konteks kehidupan nyatanya baru diubah ke matematika.</p>', NULL, '2025-12-12 21:31:15', '2025-12-12 21:38:48'),
(74, 4, 344, '<p>saya dapat mengetaahui apa itu fungsi kuadrat dan bentuk\' kuadrat </p>', NULL, '<p>cermati soal dengan teliti</p>', NULL, '<p>dengan memahami bentul konsep dan bentuk\" fungsi kuadrat kita dapat menyelesaikan permasalahan tersebut</p><p><br></p>', NULL, '2025-12-12 21:51:47', '2025-12-12 21:57:04'),
(75, 1, 319, '<p>defenisi eskponen dan sifat-sifat eksponen</p>', NULL, '<p>Tentukan bilangan pokok dan pangkat,&nbsp;Ubah eksponen menjadi perkalian berulang, Gunakan sifat-sifat eksponen jika diperlukan dan Sederhanakan bentuknya.</p><p><br></p>', NULL, '<p>memahami eksponen sebagai perkalian berulang, menerapkan sifat-sifat eksponen dengan benar, menyederhanakan bentuk terlebih dahulu, lalu menghitung hasil akhirnya dengan teliti.</p>', NULL, '2025-12-12 22:05:12', '2025-12-12 22:17:01'),
(76, 2, 330, '<p>Yang saya ketahui dari materi di topik ini adalah pengertian persamaan dan pertidaksamaan linear,bentuk umum persamaan dan pertidaksamaan linear,dan penerapan persamaan dan pertidaksamaan linear dalam kehidupan sehari-hari</p><p><br></p>', NULL, '<p>memahami soal,membuat model matematika dan mengidentifikasi jenis persamaan pada soal tersebut apakah merupakan SPLDV atau SPtLDV</p>', NULL, '<p>Strategi saya adalah mengubah soal cerita ke dalam model matematika yang tepat, memilih metode penyelesaian yang sesuai, lalu menafsirkan hasilnya agar sesuai dengan konteks masalah.</p>', NULL, '2025-12-12 22:06:37', '2025-12-12 23:48:23'),
(77, 1, 209, '<p>Yang saya ketahui dari materi eksponen ini yaitu, eksponen adalah suatu bilangan yang berpangkat untuk menyatukan perkalian berulang dari bilangan yang sama.contohnya seperti 2³ itu sama saja dengan 2×2×2.</p>', NULL, NULL, NULL, '<p>Menyesuaikan rumus dan aturan eksponen dengan konteks soal, saya akan memilih rumus yang paling sesuai dengan permasalahan dalam soal cerita. saat saya mendapatkan hasil akhirnya, saya mengecek apakah jawabannya masuk akal dengan konteks soal</p>', NULL, '2025-12-12 22:08:55', '2025-12-12 22:15:51'),
(78, 1, 338, '<p>Materi yang saya ketahui pada topik ini yaitu :</p><ol><li>Mengetahui ekspresi eksponen</li><li>Mengetahui sifat-sifat eksponen</li><li>Memahami eksponen dan logaritma</li><li>mengetahui cara menyederhanakan eksponen</li></ol>', NULL, '<p>Pertama baca soal dengan teliti dan pahami informasi penting, tentukan rumus atau konsep eksponen yang sesuai dan buat catatan atau diagram kecil untuk memudahkan perhitungan sebelum mulai menghitung.</p>', NULL, '<p>Strategiku adalah hubungkan setiap angka di soal dengan rumus eksponen yang tepat, periksa konteksnya (misal pertumbuhan atau peluruhan), dan pastikan hasil akhir logis serta sesuai satuan yang diminta.</p>', NULL, '2025-12-12 22:10:20', '2025-12-13 03:38:15'),
(79, 4, 346, '<p>Pengetahuan yang saya dapatkan setelah mempelajari materi tersebut adalah karakteristik persamaan kuadrat dan akar-akar persamaan kuadrat</p>', NULL, '<p>langkah-langkahnya yaitu melalukan pemfaktoran/melengkapi akar kuadrat/mengguanakan rumus kuadratik</p>', NULL, '<p>mencermati soalnya dan menentukan langkah penyelesaiannya apakah menggunakan  pemfaktoran/melengkapi akar kuadrat/mengguanakan rumus kuadratik</p>', NULL, '2025-12-12 22:12:31', '2025-12-12 22:15:09'),
(80, 4, 196, '<p>Dalam kehidupan sehari-hari, fungsi kuadrat banyak digunakan untuk memahami pola perubahan, membuat prediksi, dan menentukan nilai maksimum atau minimum dari suatu situasi.</p>', NULL, '<p>baca denga teliti soalnya, identivikasi variabel, tentukan apa yang diketahui, memilih bentuk kuadrat yang paling sesuai, susun persamaan dan hitung sesuai pertanyaan</p>', NULL, '<p>Saya sesuaikan dengan jenis masalahnya, Kalau soal memberikan grafik, saya manfaatkan informasi visual seperti titik potong sumbu atau titik puncak. Intinya, saya pahami dulu konteks nyatanya baru pilih metode yang paling efisien. </p>', NULL, '2025-12-12 22:12:58', '2025-12-12 22:19:21'),
(81, 6, 277, '<p>Vektor memiliki nilai dan arah. Jenisnya: Negatif (arah lawan) , Nol (panjang nol) , dan Ekuivalen (sama besar/arah). Operasi meliputi Penjumlahan (komponen atau grafis) , Pengurangan, dan Perkalian Skalar</p>', NULL, '<p>Langkah penyelesaian soal cerita vektor adalah: Memodelkan Masalah (terjemahkan ke notasi/komponen vektor), Merencanakan Operasi (pilih Penjumlahan, Pengurangan, atau Perkalian Skalar), dan Verifikasi Logika Arah sebelum hitungan.</p>', NULL, '<p>Strategi penyelesaian soal vektor ditentukan setelah memahami masalah. Jika perlu nilai numerik, gunakan Metode Aljabar (Komponen). Jika perlu representasi visual, gunakan Metode Grafis. Pastikan logika arah benar sebelum menghitung.</p>', NULL, '2025-12-12 22:15:11', '2025-12-12 22:19:39'),
(82, 4, 286, '<p>definisi fungsi kuadrat dan penerapannya dalam kehidupan sehari-hari</p>', NULL, '<p> memahami soal, menentukan variabel, memodelkan ke fungsi kuadrat, lalu merencanakan penyelesaian sebelum menghitung.</p>', NULL, '<p>Strategi yang digunakan adalah memahami konteks masalah, memilih konsep matematika yang sesuai, lalu menyusun langkah penyelesaian secara logis dan terarah.</p><p><br></p>', NULL, '2025-12-12 22:24:50', '2025-12-13 21:32:36'),
(83, 5, 340, '<p>Dari materi pada topik ini, saya mengetahui konsep dasar fungsi eksponen, bentuk umumnya, sifat-sifatnya, serta penerapannya dalam kehidupan sehari-hari seperti pertumbuhan dan peluruhan.</p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, serta menyusun model fungsi eksponen yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<ol><li>Strategi penyelesaian ditentukan sejak memahami konteks masalah, dengan memilih bentuk fungsi eksponen dan metode yang tepat agar solusi yang diperoleh sesuai, logis, dan menjawab permasalahan.</li></ol><p><br></p>', NULL, '2025-12-12 22:28:30', '2025-12-12 22:29:10'),
(84, 3, 191, '<p>Perbandingan trigonometri merupakan konsep penting dalam matematika yang menjelaskan hubungan antara besar sudut dan panjang sisi pada sebuah segitiga yang memiliki satu sudut siku-siku.</p>', NULL, '<p>pertama pahami soal, identifikasi bentuk segitiga, tentukan apa yang diketahui, Pilih perbandingan trigonometri yang paling masuk akal, susunmetode  dan kerjakan sesuai metode, dan periksa kembali metode yang dikerjakan</p>', NULL, '<p>Strategi  muncul saat memahami konteks soal. Strategi dibangun dengan mengenali jenis masalah, membuat model (gambar/persamaan), dan memilih hubungan yang relevan.</p>', NULL, '2025-12-12 22:35:39', '2025-12-12 23:13:06'),
(85, 3, 276, '<p>Trigonometri mempelajari hubungan sudut dan sisi segitiga.</p><p>Meliputi sin, cos, tan, sudut Kartesius, dan sudut istimewa.</p><p>Digunakan untuk menghitung jarak atau tinggi segitiga sembarang.</p>', NULL, '<p>Pahami soal dan tentukan data penting.</p><p>Buat diagram segitiga dan pilih perbandingan trigonometri yang tepat.</p><p>Susun persamaan dan periksa strategi sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi ketika memahami konteks soal dan data yang diberikan, lalu memilih metode atau rumus yang sesuai untuk menyelesaikannya secara sistematis dan logis.</p>', NULL, '2025-12-12 22:36:59', '2025-12-12 22:38:11'),
(86, 1, 273, '<p>saya dapat memahami dengan baik cara menyederhanakan eksponensial,dengan menggunakan sifat-sifat utama eksponen</p>', NULL, '<p>saya harus menganalisis soal terlebih dahulu,setelah itu lihat sifat eksponen yg di perlukan untuk mengerjakan soal,lalu sederhanakan dengan menggunakan sifat eksponen nya,lalu hitung nilai akhirnya.</p>', NULL, '<p>strategi saya yaitu jika saya menemukan masalah/kesulitan dalam menjawab topik ini maka saya akan bertanya pada teman/guru yang lebih paham,atau tidak saya akan mencarinya di internet.</p>', NULL, '2025-12-12 22:39:35', '2025-12-13 00:38:17'),
(87, 2, 333, '<p>Materi ini membahas sistem persamaan dan pertidaksamaan linear dua dan tiga variabel serta cara menyelesaikannya.</p>', NULL, '<p>Memahami soal, Menentukan variabel, Membuat model persamaan/pertidaksamaan, Menyelesaikan model</p><p><br></p>', NULL, '<p>Mengubah soal ke bentuk model matematika, memilih metode yang tepat, dan mengecek hasil agar sesuai dengan konteks soal.</p>', NULL, '2025-12-12 22:43:02', '2025-12-12 22:44:33'),
(88, 1, 197, '<p>Saya mengetahui bahwa eksponen adalah notasi matematika yang digunakan untuk menunjukkan berapa kali suatu angka (yang disebut sebagai dasar) akan dikalikan dengan dirinya sendiri sejumlah tertentu. </p>', NULL, NULL, NULL, NULL, NULL, '2025-12-12 22:46:02', '2025-12-12 22:46:02'),
(89, 5, 195, '<p>yang saya pahamai dari materi ini adalah defenisi fungsi eksponen dan pengoperasiannya.</p>', NULL, '<p>dengan cara membaca dan memahami soal dan apa perinah dari soal tersubut dan melakukan pengoperasian</p>', NULL, '<p>memahami konsep soal,mengidentifikasi jenis soal, menggunakan sifat-sifat eksponen, mengubah bentuk eksponen, menggunakan aturan-aturan eksponen,dan memeriksa hasilnya.</p>', NULL, '2025-12-12 22:49:52', '2025-12-12 22:51:52'),
(90, 1, 253, '<p>Yang saya sudah ketahui yaitu tentang konsep dasar dari eksponen kemudian sifat-sifat eksponen dan juga bilangan eksponen nol dan bilangan eksponen negatif.</p>', NULL, '<p>Saya akan memahami soal, identifikasi konsep relevan, membuat rencana, menulis langkah jelas, dan memeriksa kembali.</p>', NULL, '<p>Saya akan identifikasi jenis soal, memilih metode tepat, menerapkan konsep relevan, memeriksa jawaban, dan melakukan refleksi.</p>', NULL, '2025-12-12 22:51:02', '2025-12-12 23:53:30'),
(91, 2, 319, '<p>sistem persamaan dan pertidaksamaan linear</p>', NULL, '<p>Menentukan variabel, menuliskan model matematikanya, menyederhanakan bentuk persamaan atau pertidaksamaan, menyelesaikannya dengan metode yang sesuai, lalu memeriksa apakah hasilnya memenuhi soal.</p><p><br></p>', NULL, '<p>memahami konteks masalah, menentukan variabel yang sesuai, memodelkan masalah ke dalam persamaan atau pertidaksamaan linear, menyederhanakan model tersebut, lalu menyelesaikannya </p>', NULL, '2025-12-12 22:51:44', '2025-12-12 22:56:10'),
(92, 1, 329, '<p>yang saya pahami yaitu Definisi Eksponen, Sifat-sifat Eksponen serta contoh soal dan penyelesaiannya</p>', NULL, '<p>langkah langkah yang dapat dilakukan yaitu Memahami Soal Secara Menyeluruh kemudian menghubungkan ke model matematika lalu menghitung hasilnya</p>', NULL, '<p>strategi yang dapat dilakukan yaitu menganalisis mendalam terhadap struktur soal dan menerapkan sifat-sifat eksponen yang berlaku</p>', NULL, '2025-12-12 22:59:12', '2025-12-12 23:04:30'),
(93, 1, 274, '<p>Ekspresi eksponen adalah bentuk matematika yang melibatkan bilangan berpangkat, seperti a^n (a pangkat n), di mana:</p><ul><li><strong>a</strong> = bilangan pokok (basis)</li><li><strong>n</strong> = pangkat (eksponen)</li></ul><p><br></p>', NULL, '<ol><li>Baca dulu baik-baik soalnya,Ini soalnya cerita tentang apa?</li><li>Tulis yang diketahui</li><li>Bikin rumusnya</li></ol><p><br></p>', NULL, '<p>pertama-tama kita perlu memahami konsep dasar eksponen. Setlah memahaminya, langkah selanjutnya memperhatikan aturan-aturan operasi eksponen seperti perkalian dan lainnya. </p>', NULL, '2025-12-12 23:11:02', '2025-12-12 23:41:20'),
(94, 4, 337, '<p>Yang saya sudah ketahui dari materi fungsi kuadrat yaitu, definisinya dan juga 3  cara menentukan akar-akarpersaman kuadrat</p>', NULL, '<p>Langkah-langkah yang saya gunakan yaitu: memperhatikan soal dengan seksama untuk mengetahui keinginan dalam soal dan strategi yang tepat untuk menyelesaikan soal tersebut dengan cepat dan juga tepat</p>', NULL, '<p>Memilih cara yang lebih cepat untuk mendapatkan jawaban yang tepat</p>', NULL, '2025-12-12 23:23:30', '2025-12-12 23:26:31'),
(95, 6, 340, '<p>Dari materi vektor, saya mengetahui pengertian vektor, jenis-jenis vektor, operasi vektor (penjumlahan, pengurangan, dan perkalian), serta penerapannya dalam menentukan arah, besar, dan posisi suatu objek.</p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti, memahami arah dan besar vektor yang terlibat, menentukan titik acuan dan variabel, serta memodelkan permasalahan ke dalam bentuk vektor sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi penyelesaian ditentukan sejak memahami konteks soal vektor, dengan menganalisis arah dan besar vektor yang terlibat,lalu menerapkan operasi vektor yang sesuai agar solusi tepat dan logis.</p>', NULL, '2025-12-12 23:25:06', '2025-12-12 23:27:59'),
(96, 1, 353, '<p>Eksponen adalah bentuk perpangkatan yang menyatakan perkalian berulang.</p><p>Contoh: a^n=a×a×⋯×a (sebanyak nkali). sifatnya dan cara menyederhanakannya</p>', NULL, '<p>langkah-langkah : (1)Membaca dan memahami soal (2)Menentukan yang diketahui dan ditanyakan (3)Mengubah soal ke bentuk matematika (4)Menyusun langkah penyelesaian sebelum menghitung</p>', NULL, '<p>(1)Memahami konteks soal (2)Menentukan yang diketahui dan ditanyakan (3)Mengubah ke bentuk eksponen (4)Menggunakan sifat-sifat eksponen (5)Memeriksa kembali hasil sesuai konteks</p>', NULL, '2025-12-12 23:25:39', '2025-12-12 23:33:37'),
(97, 4, 319, '<p>karakteristik persamaan kuadrat dan menentukan akar akar persamaan kuadrat</p>', NULL, '<p>Langkah-langkah menyelesaikan persamaan kuadrat adalah mengubah persamaan ke bentuk umum ax^2+bx+c=0 memilih metode penyelesaian menentukan nilai akar-akarnya, lalu mengecek kembali hasilnya dengan mensubstitusikan ke persamaan awal.</p>', NULL, '<p>Strategi menyelesaikan soal persamaan kuadrat adalah mengubah persamaan ke bentuk umum, memilih metode yang paling sesuai, menyelesaikan perhitungannya dengan teliti, lalu mengecek kembali hasil yang diperoleh.</p>', NULL, '2025-12-12 23:27:47', '2025-12-12 23:31:07'),
(98, 2, 237, '<p>Saya sudah mengetahui definisi persamaaan dan pertidaksamaan, konsep dari persamaan dan pertidaksamaan, cara menyelesaikannya menggunakan beberapa metode</p><p><br></p>', NULL, '<p>Langkah yang dilakukan adalah memahami soal cerita, menentukan variabel yang digunakan, menyusun model matematika berupa persamaan atau pertidaksamaan, lalu menentukan metode penyelesaiannya</p>', NULL, '<p>Strategi yang saya gunakan adalah mengubah masalah yang ada menjadi model matematika, selanjutnya memilih metode penyelesaiannya, kemudian memeriksa kembali hasil agar sesuai dengan konteks soal</p>', NULL, '2025-12-12 23:29:53', '2025-12-12 23:34:51'),
(99, 1, 332, '<p>Eksponen adalah bentuk perpangkatan yang menyatakan perkalian berulang.</p><p>Contoh: a^n=a×a×⋯×a (sebanyak nkali). sifatnya dan cara menyederhanakannya</p>', NULL, '<p>langkah-langkah : (1)Membaca dan memahami soal (2)Menentukan yang diketahui dan ditanyakan (3)Mengubah soal ke bentuk matematika (4)Menyusun langkah penyelesaian sebelum menghitung</p>', NULL, '<p>(1)Memahami konteks soal (2)Menentukan yang diketahui dan ditanyakan (3)Mengubah ke bentuk eksponen (4)Menggunakan sifat-sifat eksponen (5)Memeriksa kembali hasil sesuai konteks</p>', NULL, '2025-12-12 23:29:56', '2025-12-12 23:34:30'),
(100, 3, 348, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi segitiga siku-siku serta perbandingannya.</p><p><br></p>', NULL, '<p>Langkah yang dilakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, membuat model atau gambar yang sesuai, lalu memilih konsep trigonometri yang tepat sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Saya memiliki strategi setelah memahami konteks soal, dengan cara mengidentifikasi informasi yang diketahui dan ditanyakan, lalu memilih rumus atau konsep matematika yang sesuai dengan permasalahan.</p><p><br></p>', NULL, '2025-12-12 23:31:26', '2025-12-12 23:33:02'),
(101, 5, 196, '<p><strong>Fungsi eksponen</strong>&nbsp;menggambarkan suatu proses perubahan yang terjadi secara sangat cepat, baik meningkat maupun menurun dan juga banyak digunakan untuk memahami berbagai fenomena yang berkembang dalam kehidupan sehari-hari.</p>', NULL, '<p>fahami soal, tentukan apa saja yang diketahui, susun rumus soal yang sesuai dan hitung hasilnya</p>', NULL, '<p>Saya menggunakan strategi berbeda tergantung konteks soalnya, Saya selalu identifikasi dulu apakah nilainya bertambah atau berkurang, lalu tentukan nilai awal dan faktor pengali, baru substitusi ke rumus yang sesuai.</p>', NULL, '2025-12-12 23:34:10', '2025-12-12 23:53:55'),
(102, 5, 286, '<p> Definisi fungsi eksponen dan penerapannya dalam kehidupan sehari-hari</p>', NULL, '<p>Langkahnya adalah memahami soal cerita, menentukan data yang diketahui dan ditanyakan, memodelkan masalah ke dalam fungsi eksponen, lalu menyusun rencana penyelesaian sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Strategi dimiliki sejak membaca soal, dengan memahami konteks masalah terlebih dahulu lalu menentukan konsep matematika yang sesuai dan menyusun langkah penyelesaian secara logis.</p>', NULL, '2025-12-12 23:34:32', '2025-12-13 21:35:19'),
(103, 4, 338, '<p>Materi yang sya ketahui pada topik ini adalah mengenai Fungsi kuadrat</p>', NULL, '<p>Pahami soal ceritanya, tentukan apa yang diketahui dan ditanya, misalkan variabel, lalu ubah masalah ke bentuk fungsi kuadrat yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menyusun strategi dengan memahami konteks soal terlebih dahulu, menentukan variabel yang tepat, lalu memodelkan masalah ke dalam bentuk fungsi kuadrat agar penyelesaiannya sesuai dengan situasi matematika yang diberikan.</p>', NULL, '2025-12-12 23:38:13', '2025-12-12 23:41:34'),
(104, 1, 320, '<p>Berdasarkan materi dan video pembelajaran, saya memahami bahwa materi ini membahas eksponen sebagai bentuk perkalian berulang. Bilangan pokok dan pangkat menentukan nilai suatu eksponen. Sifat-sifat eksponen memudahkan penyederhanaan perhitungan. </p>', NULL, '<p>Pertama, membaca soal dengan teliti untuk memahami informasi dan apa yang ditanyakan. Kedua, menentukan model matematika yang sesuai, seperti bentuk eksponen yang digunakan. Ketiga, memilih sifat eksponen yang tepat sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menentukan konsep eksponen yang sesuai dengan masalah yang diberikan. Kemudian menyusun langkah penyelesaian secara runtut sesuai konteks soal. Setelah itu, saya menyelesaikan perhitungan menggunakan sifat-sifat eksponen yang tepat.</p>', NULL, '2025-12-12 23:39:45', '2025-12-12 23:45:47'),
(105, 1, 206, '<p>Ekspresi Eksponen adalah bentuk perkalian berualng pada bilangan yang sama. Eksponen disebut juga bilangan pangkat. Ada beberapa penerapan ekspresi eksponen dalam kehidupan sehari-hari.</p>', NULL, '<p>Pertama menentukan informasi yang didapat dari soal dan menentukan apa yang ditanyakan soal. Kedua membuat kalimat matematika berdasarkan soal. Keempat menentukan sifat eksponen yang akan digunakan. Kemudian menentukan hasil akhir.</p>', NULL, '<p>Strategi yang saya miliki dan gunakan dengan memahami konteks soal, mengubahnya ke dalam bentuk eksponen(kalimat matematika), kemudian menghitung hasilnya dan terakhir cek hasilnya.</p>', NULL, '2025-12-12 23:40:28', '2025-12-13 00:13:16'),
(106, 5, 346, '<p>pengetahuan yang saya dapatkan setelah mempelajari materi tersebut adalah defenisi fungsi eksponen dan alternatif-alternatif penyelesaiannya</p>', NULL, '<p>mencermati soalnya dan membuat fungsi eksponen lagi menyelesaikannya</p>', NULL, '<p>ketika mengetahui apa yang ditanyakan soal lalu menyelesaikannya dengan langkah-langkah yang sistematis</p>', NULL, '2025-12-12 23:46:01', '2025-12-12 23:47:28'),
(107, 2, 199, '<p>Yang saya ketahui dari materi ini adalah bahwa pertidaksamaan linear dapat diselesaikan dengan beberapa metode </p><p>1. Metode eliminasi </p><p>2. Metode substitusi </p><p>3. Metode campuran </p>', NULL, '<p>Analisis dahulu soal dan pastikan kita sudah memahaminya, buat persamaan linear yang akan dikerjakan, kerjakan soal dengan metode yang sesuai dengan model soal</p>', NULL, '<p>Melakukan pengerjaan dengan metode yang tepat dan akurat, eksekusi yang mudah dipahami dan meminimalkan risiko kekeliruan </p>', NULL, '2025-12-12 23:48:55', '2025-12-13 03:31:54'),
(108, 1, 326, '<p>Materi ini membahas eksponen sebagai bentuk perkalian berulang. Contoh: a pangkat n = a x a x...x a (sebanyak n kali) sifatnya dan cara menyederhanakannya</p>', NULL, '<p>Membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanya, mengenali pola, lalu memodelkan masalah ke bentuk matematika.</p>', NULL, '<p>Mengubah masalah cerita ke model eksponen, menggunakan sifat-sifat eksponen yang sesuai, dan memastikan hasil akhir sesuai dengan konteks soal.</p>', NULL, '2025-12-12 23:49:36', '2025-12-12 23:52:18'),
(109, 1, 285, '<p><span style=\"color: rgb(51, 65, 85);\">Bilangan eksponen adalah bilangan yang digunakan untuk menunjukkan berapa kali suatu angka akan dikalikan dengan dirinya sendiri. </span></p>', NULL, '<p>perhatikan dengan cermat informasi yang diberikan dalam soal cerita. ubah informasi dalam soal, gunakan aturan-aturan eksponen, evaluasi dan hitung soal tersebut </p>', NULL, '<p>Salah satu strategi yang bisa digunakan dalam menyelesaikan soal terkait ekspresi eksponen adalah dengan menyederhanakan ekspresi tersebut terlebih dahulu sebelum melakukan operasi matematika lebih lanjut. </p><p><br></p>', NULL, '2025-12-12 23:51:46', '2025-12-13 00:02:52'),
(110, 1, 327, '<p>Definisi eksponen, sifat-sifat eksponen dan cara menyederhanakan eksponen</p>', NULL, '<p> membaca soal dengan teliti  dan tahu apa yang ditanyakan, mengubah informasi dalam soal ke bentuk ekspresi eksponen yang sesuai serta mengingat kembali aturan-aturan pangkat yang akan digunakan ,lalu lanjut ke proses perhitungannya.</p>', NULL, '<p>memahami konteks ,membentuk model eksponen , menerapkan sifat eksponen ,menafsirkan hasil secara matematis dan realistis.</p>', NULL, '2025-12-12 23:55:02', '2025-12-13 00:53:34'),
(111, 1, 342, '<p>Saya mengetahui bahwa eksponen adalah bentuk perkalian berulang yang ditulis sebagai a^n. Eksponen memiliki sifat-sifat tertentu, dan bentuk eksponen dapat disederhanakan dengan menerapkan sifat-sifat tersebut.</p>', NULL, '<p>Pertama, membaca soal dengan teliti, kemudian mengubahnya ke model matematika eksponen, lalu menentukan sifat eksponen yang tepat sebelum menghitung.</p>', NULL, '<p>Saya menyelesaikan soal dengan memahami konteks masalah terlebih dahulu, menentukan model matematika eksponen yang sesuai, lalu menerapkan sifat-sifat eksponen secara tepat agar diperoleh penyelesaian yang benar.</p>', NULL, '2025-12-13 00:02:39', '2025-12-13 00:08:26');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(112, 5, 337, '<p>Mengetahui bahwa eksponen adalah bentuk perkalian berulang dan nama lainnya adalah bilangan berpangkat </p>', NULL, '<p>Mengetahui definisi dan juga beberapa sifat-sifat, agar memudahkan mengerjakan soal-soal yang diberikan </p>', NULL, '<p>Waktu sebelum mengerjakannya, tepatnya setelah melihat apa yang dicari dalam soal tersebut</p>', NULL, '2025-12-13 00:09:14', '2025-12-13 00:10:53'),
(113, 2, 353, '<p>pada topik ini membahas persamaan dan pertidaksamaan linear dengan 2 &amp; 3 variabel, cara menyelesaikannya (substitusi, eliminasi, dan grafik), serta menentukan himpunan atau daerah penyelesaian yang memenuhi syarat.</p><p><br></p>', NULL, '<p>(1)Memahami soal cerita (2)Menentukan variabel (3)Menentukan yang diketahui dan ditanyakan (4)Membuat persamaan atau pertidaksamaan linear (5)Memilih metode penyelesaian yang tepat</p>', NULL, '<p>(1)Memahami konteks soal (2)Menentukan variabel (3)Membuat persamaan/pertidaksamaan linear (4)Memilih metode penyelesaian (5)Mengecek kembali hasil sesuai konteks</p>', NULL, '2025-12-13 00:10:19', '2025-12-13 00:16:16'),
(114, 3, 277, '<p>Materi Trigonometri ini mengajarkan: Perbandingan Trigonometri (Sin, Cos, Tan) pada Segitiga Siku-Siku (terkait Teorema Pythagoras), Definisi Sudut sebagai Rotasi (Positif CCW, Negatif CW), dan Hubungan Sudut Penyiku.</p>', NULL, '<p>Langkah-langkah penyelesaian soal cerita trigonometri adalah: Analisis data (diketahui/ditanya); Modelkan menjadi segitiga siku-siku ; Labeli sisi (Depan, Samping, Miring); dan Pilih Rasio (Sin/Cos/Tan) untuk menyusun persamaan.</p>', NULL, '<p>Strategi dimiliki setelah analisis data dan pemodelan segitiga siku-siku. Strategi utamanya adalah memilih rasio trigonometri (Sin/Cos/Tan) atau Teorema Pythagoras yang paling tepat untuk menghubungkan data yang diketahui dengan data yang dicari.</p>', NULL, '2025-12-13 00:11:27', '2025-12-13 00:22:04'),
(115, 5, 338, '<p>Materi yang sudah saya pelajari pada topik ini adalah defenisi fungsi eksponen, persamaan eksponen sederhana dan grafik eksponensial umum.</p>', NULL, '<p>Pahami dulu cerita soalnya, tentukan apa yang diketahui dan ditanyakan, lalu ubah situasi ke model fungsi eksponen yang sesuai sebelum mulai menghitung.</p><p><br></p><p><br></p>', NULL, '<p>Strategi ditentukan sejak memahami konteks soal, dengan mengenali pola pertumbuhan atau peluruhan eksponensial agar rumus dan langkah penyelesaiannya tepat.</p><p><br></p>', NULL, '2025-12-13 00:17:55', '2025-12-13 00:21:07'),
(116, 2, 332, '<p>materi Sistem Persamaan dan Pertidaksamaan Linear membahas persamaan dan pertidaksamaan dengan dua variabel, cara menyelesaikannya (substitusi, eliminasi, dan grafik), serta menentukan himpunan atau daerah penyelesaian yang memenuhi syarat.</p>', NULL, '<p>langkahnya adalah: Memahami soal cerita, Menentukan variabel, Menentukan yang diketahui dan ditanyakan,Membuat persamaan atau pertidaksamaan linear dan Memilih metode penyelesaian yang tepat</p>', NULL, '<p>strateginya adalah: Memahami konteks soal, Menentukan variabel, Membuat persamaan/pertidaksamaan linear, Memilih metode penyelesaian, dan Mengecek kembali hasil sesuai konteks</p>', NULL, '2025-12-13 00:20:07', '2025-12-13 00:21:12'),
(117, 5, 319, '<p>sifat-sifat grafik fungsi eksponen dan defenisi fungsi eksponen</p>', NULL, '<p>membaca soal dengan teliti, memahami cerita dan apa yang diketahui serta ditanyakan, menuliskan informasi penting dalam bentuk matematika, menentukan rumus atau cara yang tepat,dan melakukan perhitungan untuk memperoleh hasil akhir.</p><p><br></p>', NULL, '<p> untuk menyelesaikan soal matematika dimiliki setelah memahami konteks masalah dan mengetahui apa yang ditanyakan. yang ditentukan dengan memilih konsep, rumus, atau cara yang paling sesuai dengan soal</p>', NULL, '2025-12-13 00:28:34', '2025-12-13 00:31:50'),
(118, 1, 323, '<p>Yang saya ketahui adalah definisi eksponen, sifat-sifat eksponen (perkalian, pembagian, pangkat dari pangkat), eksponen negatif dan pecahan, serta penerapannya dalam masalah kontekstual seperti pertumbuhan virus atau populasi.</p>', NULL, '<p>baca dan pahami soal, identifikasi yang diketahui dan ditanya, kenali pola eksponensialnya (basis dan pangkat), buat model matematika, pilih sifat eksponen yang sesuai, baru hitung dan cek jawabannya.</p>', NULL, '<p>mencari pola perkalian berulang dalam soal, buat tabel kecil untuk melihat polanya, gunakan sifat eksponen yang tepat untuk menyederhanakan, dan pastikan hasil akhir logis dengan konteks soalnya.</p>', NULL, '2025-12-13 00:29:04', '2025-12-13 00:30:30'),
(119, 2, 274, '<p><span style=\"color: rgb(51, 65, 85);\">Sistem persamaan linear adalah kumpulan dua atau lebih yang memiliki variabel yang sama. Sementara itu,  Contoh pertidaksamaan linear adalah x + 3 &lt; 7 atau 2y - 5 ≥ 1. </span></p>', NULL, '<p>Baca soal dengan teliti untuk mengidentifikasi informasi yang diketahui, ditanyakan, dan hubungan eksponen yang terlibat, lalu ubah soal cerita tersebut menjadi bentuk matematis atau persamaan eksponen sebelum menghitung hasil akhirnya.</p><p><br></p>', NULL, '<p>Kuasai aturan dasar operasi eksponen dan identifikasi bentuk eksponen dalam soal, kemudian terapkan aturan yang tepat sesuai konteks untuk menyederhanakan ekspresi secara sistematis hingga mendapat hasil akhir.</p>', NULL, '2025-12-13 00:32:39', '2025-12-13 00:45:31'),
(120, 4, 353, '<p>Fungsi kuadrat adalah fungsi yang berbentuk f(x)=ax^2+bx+c = 0, dimana tidak sama dengan 0.Grafiknya berupa parabola yang memiliki titik puncak (maksimum atau minimum), sumbu simetri, dan dapat memotong sumbu-X serta sumbu-Y.&nbsp;</p>', NULL, '<p>Langkah sebelum menghitung: memahami soal, menentukan diketahui–ditanya, menetapkan variabel, dan membuat model fungsi kuadrat.</p>', NULL, '<p>Strategi penyelesaian: menyesuaikan fungsi kuadrat dengan konteks soal, memilih metode yang tepat, dan mengecek kembali hasil agar logis.</p><p><br></p>', NULL, '2025-12-13 00:36:59', '2025-12-13 00:38:41'),
(121, 1, 201, '<p><span style=\"color: rgb(51, 65, 85);\">Eksponen adalah notasi matematika yang menunjukkan berapa kali suatu bilangan (dasar) dipangkatkan dengan dirinya sendiri. Misalnya, \\(2^3\\) artinya 2 dipangkatkan 3, hasilnya 2 x 2 x 2 = 8.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Sebelum menghitung jawaban akhir, pastikan untuk mengidentifikasi eksponen dan logaritma yang terlibat dalam soal cerita matematika. dan terapkan aturan eksponen atau logaritma</span></p>', NULL, '<p>Saya memehami kondisi soal, menentukan terlebih dahulu apa yang diketahui dan yang di tanya dan saya mencari informasi menggunakan  AI </p>', NULL, '2025-12-13 00:38:03', '2025-12-13 00:45:31'),
(122, 1, 283, '<p>yang sudah saya ketahui setelah membaca materi di atas adalah pengertian eksponen dan logaritma</p>', NULL, '<p>langkah langkah yang saya lakukan adalah yang pertama yaitu memahami terlebih dahulu persoalan yang menjadi masalahnya kemudian mulai memcari tahu himpunan penyelesaiannya</p>', NULL, '<p>yaitu dengan cara mempelajari persoalan pada suatu topik sesuai konteks masalah matematika kemudian mulai menyusun strategi penyelesaiannya dimana saya juga di bantu oleh AI untuk menemukan strategi yang tepat</p>', NULL, '2025-12-13 00:38:46', '2025-12-13 00:43:41'),
(123, 6, 199, '<p>Vektor sangat berguna untuk kehidupan sehari-hari </p>', NULL, '<p>Menghitung perkalian titik, menentukan konsep </p>', NULL, '<p>Menghitung vektor, menentukan vektor resultan, menghitung perkalian titik</p>', NULL, '2025-12-13 00:40:10', '2025-12-13 00:43:04'),
(124, 1, 208, '<p>yang sudah saya ketahui dari materi topik ini adalah pemahaman tentang ekspresi eksponen </p>', NULL, '<p>saya akan memahami dulu apa yang di inginkan/ditanyakan pada soal, kemudian setelah saya ketahui saya akan menerapkan konsep konsep mengenai topik ini yang telah saya pahami. Kemudian saya langsung menghitung hasilnya</p>', NULL, '<p>Memahami konsep eksponen, menerapkan konsep eksponen dan menganalisis masalah pada soalnya</p>', NULL, '2025-12-13 00:47:20', '2025-12-13 01:03:13'),
(125, 6, 338, '<p>Materi yang telah saya pelajari dalam topik ini adalah mengenai definisi vektor dan operasi vektor </p>', NULL, '<p>Langkah awalnya adalah memahami cerita soal dan menentukan besaran vektor yang terlibat beserta arahnya, lalu memisalkan vektor dalam bentuk yang sesuai, seperti komponen atau gambar.</p><p><br></p><p><br></p>', NULL, '<p> Strategi ditentukan sejak awal dengan menyesuaikan konteks soal, apakah membutuhkan penjumlahan, pengurangan, atau operasi lain pada vektor, sehingga perhitungan menjadi tepat dan efisien.</p>', NULL, '2025-12-13 00:52:36', '2025-12-13 00:54:40'),
(126, 6, 337, '<p>representasi vektor, operasi vektor, dan kegunaannya dalam kehidupan sehari-hari </p>', NULL, '<p>Sama dengan pengerjaan sebelumnya, melihat keinginan dalam soal lalu memilih strategi yang trpat</p>', NULL, '<p>Ketika saya membaca soal, memilihnya cara yang sesuai untuk menyelesaikan soal tersebut </p>', NULL, '2025-12-13 00:53:20', '2025-12-13 00:54:55'),
(127, 4, 332, '<p><br></p><p>Fungsi kuadrat berbentuk&nbsp;</p><p>𝑓(𝑥)=𝑎𝑥^2+𝑏𝑥+𝑐dan grafiknya parabola dengan titik puncak serta sumbu simetri.</p>', NULL, '<p>Langkah sebelum menghitung: memahami soal, menentukan diketahui–ditanya, menetapkan variabel, dan membuat model fungsi kuadrat.</p>', NULL, '<p>Strategi penyelesaian: menyesuaikan fungsi kuadrat dengan konteks soal, memilih metode yang tepat, dan mengecek kembali hasil agar logis</p>', NULL, '2025-12-13 00:54:16', '2025-12-13 00:56:11'),
(128, 1, 350, '<p>Penggunaan konsep aljabar, eksponen, dan fungsi untuk memodelkan serta menyelesaikan masalah matematika. Materi menekankan pemahaman hubungan antarvariabel. Hasil perhitungan juga harus diinterpretasikan sesuai konteks soal.</p>', NULL, '<p>Sebelum menghitung, langkah yang dilakukan adalah membaca soal dengan teliti dan memahami konteksnya. Selanjutnya menentukan informasi yang diketahui dan ditanyakan. Setelah itu, mengubah masalah ke dalam model matematika yang sesuai.</p>', NULL, '<p>Strategi penyelesaian dilakukan dengan memilih konsep matematika yang tepat sesuai konteks soal. Langkah penyelesaian disusun secara runtut dan sistematis. Hasil akhir kemudian ditafsirkan agar sesuai dengan makna permasalahan.</p>', NULL, '2025-12-13 00:54:34', '2025-12-13 00:55:34'),
(129, 4, 330, '<p>Dari materi ini saya telah mempelajari tentang fungsi kuadrati, cara menyelesaikan persamaan kuadrat, melengkapi kuadrat sempurna, dan rumus abc, serta pengaruh diskriminan terhadap titik potong </p>', NULL, '<p>langkah-langkah menyelesaikan soal cerita fungsi kuadrat sebelum menghitung yaitu Baca dan pahami soal dengan teliti, Modelkan ke dalam fungsi kuadrat serta Pilih metode penyelesaian yang tepat </p><p><br></p><p><br></p>', NULL, '<p><span style=\"background-color: rgb(248, 250, 252);\"> strategi saya untuk menyelesaiakan soal pada topik ini yaitu dengan cara </span>Identifikasi konteks masalah, pilih metode sesuai yang ditanyakan, hitung, lalu verifikasi kewajaran hasilnya.</p>', NULL, '2025-12-13 00:55:30', '2025-12-13 01:02:57'),
(130, 2, 285, '<p><span style=\"color: rgb(51, 65, 85);\">Saya sudah mengetahui bahwa sistem persamaan linear melibatkan dua atau lebih persamaan untuk diselesaikan secara bersamaan dengan menggunakan metode eliminasi atau substitusi.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama adalah menentukan variabel yang akan digunakan. Selanjutnya, tulis persamaan atau pertidaksamaan linear berdasarkan informasi yang diberikan dalam soal.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama adalah menganalisis koefisien variabel dan konstanta pada setiap persamaan, kemudian gunakan metode eliminasi atau substitusi untuk mencari solusi yang memenuhi kedua persamaan.</span></p>', NULL, '2025-12-13 00:55:40', '2025-12-13 00:58:51'),
(131, 2, 320, '<p>Materi ini membahas bilangan berpangkat atau eksponen sebagai bentuk perkalian berulang. Saya memahami fungsi basis dan pangkat dalam menentukan nilai suatu eksponen. Selain itu, sifat-sifat eksponen membantu dalam menyederhanakan perhitungan.</p>', NULL, '<p>Langkah pertama adalah membaca dan memahami soal secara menyeluruh. Kemudian menentukan konsep eksponen yang sesuai dengan permasalahan. Setelah itu, menyusun langkah penyelesaian sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menyesuaikan strategi dengan jenis soal yang diberikan. Setiap langkah dikerjakan secara runtut dan sesuai konsep eksponen. Terakhir, saya mengecek kembali hasil agar sesuai dengan konteks soal.</p>', NULL, '2025-12-13 00:55:59', '2025-12-13 00:57:13'),
(132, 2, 273, '<p>saya dapat memahami dengan baik bagaimana cara menyelesaikan persamaan linear, dengan menggunakan berbagai metode yaitu:metode subsitusi,eliminasi,dan campuran.</p>', NULL, '<p>yaitu baca soal dengan teliti,identifikasi informasi kunci,tentukan variabel,buat model matematika (persamaan linear),lalu periksa kembali model.</p>', NULL, '<p>pertama kita harus memahami permasalahan yang di sajikan dalam soal,lalu kita rencana kan cara penyelesaiannya,setelah itu kita laksanakan rencana  dengan menggunakan metode aljabar, lalu memeriksa kembali.</p>', NULL, '2025-12-13 01:00:58', '2025-12-13 05:17:21'),
(133, 6, 319, '<p>defenisi vektor dan operasi vektor</p>', NULL, '<p>membaca soal dengan teliti, memahami situasi dan arah yang terlibat, menentukan besaran vektor yang diketahui dan ditanyakan, menggambarkan vektor dalam diagram atau sistem koordinat, serta memilih operasi vektor yang sesuai </p>', NULL, '<p>memahami konteks masalah, seperti arah dan besar vektor yang terlibat. Strategi dipilih dengan menggambarkan vektor, menentukan komponen vektor, dan memilih operasi vektor yang sesuai agar penyelesaian soal menjadi tepat.</p>', NULL, '2025-12-13 01:02:51', '2025-12-13 01:09:48'),
(134, 5, 344, '<p>saya dapat mengetahui apa itu fungsi ekponen, sifat\" fungsi eksponen </p>', NULL, '<p>dengan memahami soal yang diberikan</p>', NULL, '<p>ketika mendapatkan soal yang gampang dan menyelesaikannya sesuai prosedur</p>', NULL, '2025-12-13 01:05:03', '2025-12-13 01:08:02'),
(135, 1, 348, '<p>Materi tentang bilangan berpangkat (eksponen), sifat-sifatnya, dan penerapannya dalam masalah pertumbuhan atau pola perkalian berulang.</p><p><br></p>', NULL, '<p>Identifikasi pola atau informasi penting, lalu modelkan ke dalam bentuk matematika eksponen yang sesuai.</p>', NULL, '<p>Buat tabel pola pertumbuhan per fase, kemudian gunakan sifat eksponen untuk menghitung hasil akhir.</p>', NULL, '2025-12-13 01:06:22', '2025-12-13 01:07:27'),
(136, 2, 326, '<p>Cara membuat model matematika dari cerita, menyusun persamaan/pertidaksamaan, serta menyelesaikannya dengan eliminasi, substitusi, grafik, atau Sarrus.</p>', NULL, '<p>memahami apa yang diketahui dan apa yang ditanya pada soal cerita,menentukan variabel, membuat bentuk persamaan/pertidaksamaan, memilih metode penyelesaian serta melakukan perhitungan.</p>', NULL, '<p>yang saya lakukan adalah mengubah soal cerita menjadi model matematika yang tepat, menggunakan eliminasi/substitusi/grafik sesuai jenis soal serta memeriksa kembali apakah solusi memenuhi semua syarat dan masuk akal.</p>', NULL, '2025-12-13 01:07:47', '2025-12-13 01:11:24'),
(137, 4, 274, '<p><span style=\"color: rgb(51, 65, 85);\">Fungsi kuadrat merupakan fungsi matematika yang dinyatakan dalam bentuk \\( f(x) = ax^2 + bx + c \\), di mana \\( a \\), \\( b \\), dan \\( c \\) adalah konstanta.&nbsp;</span></p>', NULL, '<p>Pahami soal, buat model persamaan kuadrat, lalu selesaikan dengan metode yang tepat.</p>', NULL, '<p><span style=\"background-color: rgb(240, 238, 230); color: rgb(20, 20, 19);\">Mmbuat sketsa grafik untuk membantu visualisasi masalah,Mnggunakan pengtahuan tentang akar-akar persamaan kuadrat untuk menemukan solusi dari masalah.</span></p>', NULL, '2025-12-13 01:08:27', '2025-12-13 01:15:59'),
(138, 2, 201, '<p>Saya mengetahui bahwa persamaan dan pertidaksamaan linear adalah bentuk kalimat matematika yang melibatkan variabel berpangkat satu. Persamaan menggunakan tanda sama dengan </p>', NULL, '<p>Langkah awal adalah membaca soal dengan teliti, memahami cerita, serta menentukan apa yang diketahui dan apa yang ditanyakan.</p><p><br></p>', NULL, '<p>Saya menentukan strategi dengan memahami konteks soal terlebih dahulu, lalu memilih apakah masalah lebih tepat dimodelkan sebagai persamaan, pertidaksamaan, atau sistem persamaan linear.</p>', NULL, '2025-12-13 01:10:32', '2025-12-13 01:12:49'),
(139, 2, 253, '<p>Yang saya ketahui  dari topik ini adalah tentang konsep dari persamaan linear dan pertidaksamaan linear, dan juga penerapannya dalam kehidupan sehari-hari.</p><p><br></p>', NULL, '<p>Langkah-langkah yang akan saya lakukan yaitu:</p><ul><li>Pahami soal: identifikasi yang ditanya</li><li>Modelkan: Ubah jadi persamaan linear</li><li>Tulis Persamaan: Pastikan lengkap</li><li>Cek: pastikan semua info penting masuk</li></ul><p><br></p>', NULL, '<p>Strateginya yaitu:</p><ul><li>Pilih metode: substitusi, eliminasi, campuran</li><li>Selesaikan: Cari nilai variabel</li><li>Interpretasi: Hubungkan jawaban dengan soal cerita</li><li>Cek jawaban: Pastikan logis dan benar</li></ul>', NULL, '2025-12-13 01:24:10', '2025-12-13 01:34:54'),
(140, 6, 344, '<p>saya dapat mengetahui apa itu vektor, notasi vektor</p>', NULL, '<p>mengikuti prosedural</p>', NULL, '<p>saat mendapatkan soal yang agak menantng dengan cara mengakali soal</p>', NULL, '2025-12-13 01:24:36', '2025-12-13 01:28:49'),
(141, 2, 283, '<p>SPLTV adalah sistem tiga persamaan linear dengan tiga variabel.</p><p> Penyelesaiannya menggunakan eliminasi atau substitusi.</p><p><br></p>', NULL, '<p>Pahami soal dengan membaca cermat dan tentukan apa yang diketahui serta ditanyakan.</p><p> Misalkan variabel yang sesuai lalu buat model persamaan matematikanya.</p><p> Pilih metode penyelesaian yang tepat sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Saya memahami konteks soal dan menentukan variabel yang mewakili masalah.</p><p> Saya menyusun persamaan sesuai informasi yang diberikan.</p><p> Saya memilih metode penyelesaian yang paling efektif agar hasilnya tepat.</p><p><br></p>', NULL, '2025-12-13 01:31:16', '2025-12-13 01:34:00'),
(142, 1, 321, '<p>Saya mengetahui tentang apa itu bilangan berpangkat (eksponen), bentuk lain dari eksponen, sifat-sifat eksponen, penggunaan eksponen dalam kehidupan sehari-hari</p>', NULL, '<p>Langkah-langkahnya yaitu, Baca soal dan pahami ceritanya, catat informasi penting yang diketahui, tentukan apa yang ditanyakan, kenali pola perkalian berulang, ubah cerita ke bentuk eksponen.</p><p><br></p>', NULL, '<p>Saya memahami konteks soal dan mengenali pola perkalian berulang yang terjadi. Kemudian memodelkannya ke bentuk eksponen dan menyelesaikannya dengan sifat eksponen.</p><p><br></p>', NULL, '2025-12-13 01:31:56', '2025-12-13 01:38:06'),
(143, 1, 324, '<p>yang saya sudah ketahui pada topik ini adalah, eksponen merupakan cara menuliskan perkalian berulang agar lebih sederhana dan mudah dihitung. (a^n) =&gt; a = basis, dan n adalah pangkat/eksponen</p>', NULL, '<p>langkah-langkah yang sebaiknya dilakukan adalah membaca soal cerita dengan teliti, menentukan bilangan yang dikalikan berulang dan banyaknya perkalian, kemudian mengubah cerita kebentuk matematika yang sesuai dengan konsep eksponen </p>', NULL, '<p>strategi yang saya gunakan adalah memahami konteks masalah terlebih dahulu mengidentifikasi pola perkalian berulang yang terjadi, menuliskannya dalam bentuk eksponen, menerapkan aturan eksponen yang sesuai, menafsirkan</p>', NULL, '2025-12-13 01:32:29', '2025-12-13 01:40:15'),
(144, 4, 201, '<p>Saya mengetahui bahwa fungsi kuadrat adalah fungsi berbentuk f(x)=ax2+bx+cf(x)=ax^2+bx+cf(x)=ax2+bx+c dengan a≠0a \\neq 0a=0. Grafik fungsi kuadrat berupa parabola yang membuka ke atas atau ke bawah tergantung nilai a</p>', NULL, '<p>Langkah pertama adalah membaca soal dengan teliti dan memahami cerita serta informasi yang diketahui dan ditanyakan. Setelah itu, tentukan variabel yang sesuai dan ubah soal cerita ke dalam model matematika berupa fungsi atau persamaan kuadrat.</p>', NULL, '<p>Saya menyusun strategi dengan memahami konteks soal terlebih dahulu dan menentukan apakah masalah dapat dimodelkan sebagai fungsi atau persamaan kuadrat.</p><p><br></p>', NULL, '2025-12-13 01:34:28', '2025-12-13 01:36:58'),
(145, 2, 350, '<p>Dari materi dan video pembelajaran, saya mengetahui bahwa topik ini membahas sistem persamaan dan pertidaksamaan linear, termasuk cara memodelkan masalah kontekstual ke dalam bentuk matematika serta menentukan himpunan penyelesaiannya.</p>', NULL, '<p>Langkah yang sebaiknya dilakukan adalah memahami konteks soal, menentukan variabel, mengidentifikasi informasi yang diketahui dan yang ditanyakan, lalu menyusun model matematika berupa persamaan atau pertidaksamaan linear.</p>', NULL, '<p>Strategi penyelesaian yang digunakan adalah memilih metode yang paling sesuai dengan model yang terbentuk, seperti eliminasi, substitusi, atau grafik, kemudian mengecek kembali hasil agar sesuai dengan konteks masalah matematika.</p>', NULL, '2025-12-13 01:35:56', '2025-12-13 01:37:03'),
(146, 5, 332, '<p>setelah mempelajari materi ini saya dapat memahami definisi dari grafik fungsi...sifat-sifat grafik fungsi...</p>', NULL, '<p>Langkah sebelum menghitung soal cerita</p><p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, mengenali jenis pertumbuhan atau peluruhan, lalu mengubah cerita ke dalam model fungsi eksponen.</p><p><br></p>', NULL, '<p><br></p><p>Strategi digunakan saat soal berbentuk cerita. Caranya dengan memahami konteks masalah, memilih rumus yang sesuai, dan menafsirkan hasil sesuai cerita</p>', NULL, '2025-12-13 01:36:02', '2025-12-13 01:41:48'),
(147, 5, 353, '<p>Sebuah fungsi eksponen dinyatakan dengan f(x)= n × a^x Di mana 𝑎 adalah bilangan pokok, 𝑎 &gt; 0, 𝑎 ≠ 1, 𝑛 adalah bilangan real tak nol dan 𝑥 adalah sebarang bilangan real.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, mengenali jenis pertumbuhan atau peluruhan, lalu mengubah cerita ke dalam model fungsi eksponen.</p>', NULL, '<p>Strategi digunakan saat soal berbentuk cerita. Caranya dengan memahami konteks masalah, memilih rumus yang sesuai, dan menafsirkan hasil sesuai cerita.</p><p><br></p>', NULL, '2025-12-13 01:39:55', '2025-12-13 01:41:09'),
(148, 4, 320, '<p>Dari materi yang dipelajari, saya mengetahui bahwa persamaan kuadrat adalah persamaan dengan pangkat tertinggi dua. Persamaan ini dapat diselesaikan dengan beberapa metode seperti faktorisasi, melengkapi kuadrat sempurna, dan rumus kuadrat. </p>', NULL, '<p>Sebelum menghitung hasil akhir soal cerita, langkah yang perlu dilakukan adalah membaca soal dengan cermat dan memahami informasi yang diberikan. Selanjutnya, menentukan variabel dan menyusun model matematika dalam bentuk persamaan kuadrat. </p>', NULL, '<p>Pertama memahami konteks masalah terlebih dahulu lalu menerjemahkannya ke dalam bentuk matematika. Kemudian memilih metode penyelesaian persamaan kuadrat yang paling sesuai dan efisien. Terakhir, dicek kembali agar sesuai dengan konteks soal.</p>', NULL, '2025-12-13 01:42:28', '2025-12-13 01:46:25'),
(149, 2, 342, '<p>Materi ini membahas SPLDV untuk menentukan nilai variabel dengan metode grafik, eliminasi, dan substitusi, serta SPtLDV untuk menentukan daerah penyelesaian secara grafik pada bidang koordinat. </p>', NULL, '<p>membaca soal dengan teliti, menentukan variabel dan informasi yang diketahui serta ditanyakan, memodelkan masalah ke dalam SPLDV atau SPtLDV yang sesuai, lalu memilih metode penyelesaian yang tepat sebelum melakukan perhitungan.</p>', NULL, '<p>Memahami konteks soal cerita , menentukan variabel yang sesuai, memodelkan masalah ke dalam SPLDV atau SPtLDV. Setelah itu,  memilih metode penyelesaian yang tepat dan memastikan langkah2nya sesuai dengan konteks masalah</p>', NULL, '2025-12-13 01:42:30', '2025-12-13 01:47:52'),
(150, 4, 283, '<p>Fungsi kuadrat adalah fungsi berbentuk y=ax2+bx+cy = ax^2 + bx + cy=ax2+bx+c.</p><p> Grafiknya berupa parabola yang memiliki titik puncak dan sumbu simetri.</p><p><br></p>', NULL, '<p>Baca soal dengan cermat dan pahami konteks permasalahannya.</p><p> Tentukan variabel lalu buat model fungsi kuadrat yang sesuai.</p><p> Tentukan apa yang ditanyakan sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Memahami konteks soal dan menentukan variabel yang sesuai.</p><p> Menyusun model matematika dari informasi yang ada.</p><p> Memilih cara penyelesaian yang paling tepat dan sederhana.</p><p><br></p>', NULL, '2025-12-13 01:50:10', '2025-12-13 01:52:14'),
(151, 1, 261, '<p>Yang sa ketahui dari topik tadi adalah eksponen dan  sifat sifat nya . Eksponen yaitu suatu bilangan pokok yang di kali sebanyak pangkat nya. </p><p><br></p>', NULL, '<p>Langkah langkah nya yaitu memahami konsep soal dan menggunakan sifat  sifat yang berlaku sesuai dengan soal nya </p>', NULL, '<p>strategi nya yaitu melihat bentuk soal dan memahami soal nya </p><p><br></p>', NULL, '2025-12-13 01:52:47', '2025-12-13 02:44:00'),
(152, 1, 207, '<p>Yang saya ketahui adalah eksponen dan sifat sifat nya.</p>', NULL, '<p>memahami permasalahan dalam cerita, melihat sifat apa yang cocok dengan soal, mengerjakan sesuai dengan langkah langkahnya, menghitung hasil akhirnya.</p><p><br></p>', NULL, '<p>strategi yang saya lakukan adalah mengetahui dan memahami soal yang diberikan kemudian mencari cara paling cepat dan mudah dengan sifat-sifat yang ada untuk menyelesaikan permasalahan tersebut.</p>', NULL, '2025-12-13 01:54:31', '2025-12-13 02:46:28'),
(153, 5, 201, '<p>Saya mengetahui bahwa fungsi eksponen adalah fungsi yang variabelnya berada pada pangkat, biasanya berbentuk f(x).</p>', NULL, '<p>Langkah pertama adalah membaca soal dengan teliti dan memahami konteks permasalahan eksponen. Setelah itu, tentukan besaran yang diketahui dan yang ditanyakan serta ubah ke dalam bentuk model matematika eksponen.</p>', NULL, '<p>Saya mulai memiliki strategi sejak membaca dan memahami konteks soal, dengan menentukan konsep matematika yang sesuai. Strategi diterapkan dengan memilih model, rumus, dan langkah penyelesaian </p><p><br></p>', NULL, '2025-12-13 01:55:44', '2025-12-13 01:57:22'),
(154, 1, 251, '<p>Saya telah mengetahui bahwa eksponen adalah bentuk perkalian berulang suatu bilangan  yang di kalikan dengan dirinya sendiri </p>', NULL, '<p>Baca dan Pahami Soal</p><p>Baca ulang soal secara teliti untuk mengidentifikasi data kunci seperti jumlah awal (basis), faktor pertumbuhan/peluruhan, dan periode waktu (eksponen).</p>', NULL, '<p>pahami masalah, buat rencana, lakukan, dan periksa</p>', NULL, '2025-12-13 01:56:40', '2025-12-13 02:12:20'),
(155, 2, 327, '<p>Sistem persamaan dan pertidaksaan linier dua variabel dan tiga variabel yang terdiri dari definisi, konsep ,solusi,dan menentukan himpunan penyelesaiannya</p>', NULL, '<p>membaca soal cerita dengan teliti, menentukan variabel yang mewakili besaran yang tidak diketahui dan ubah kalimat cerita menjadi model persamaan atau pertidaksamaan linear. </p>', NULL, '<p>menentukan variabel yang sesuai, soal diubah menjadi sistem persamaan atau pertidaksamaan lineart dan memilih metode penyelesaian yang sesuai .</p>', NULL, '2025-12-13 01:57:59', '2025-12-13 02:07:47'),
(156, 4, 325, '<p>bentuk umum fungsi kuadrat, dan cara mencari akar-akarnya</p>', NULL, '<p>Pada permasalahan fungsi kudrat langkah yang dilakukan biasanya yaitu, mencari nilai maksimum dan minimum.</p>', NULL, '<p>Saya mulai dengan mencari nilai maksimum dan minimum fungsi kuadrat.</p>', NULL, '2025-12-13 01:59:29', '2025-12-13 02:00:58'),
(157, 6, 195, '<p>Yang saya telah ketahui yaitu defenisi vektor,operasi vektor, dan penerapan vektor dalam kehidupan sehari-hari.</p>', NULL, '<p>dengan cara membaca dan memahami soal dan apa perinah dari soal tersubut dan melakukan pengoperasian</p>', NULL, '<p>satrategi penyelesaian soal matematika dimiliki <strong>sejak awal memahami soal</strong> dan masalah, memodelkan secara matematis, memilih metode yang tepat, menyelesaikan secara sistematis, dan melakukan pengecekan hasil.</p>', NULL, '2025-12-13 02:00:48', '2025-12-13 02:05:31'),
(158, 2, 323, '<p>Yang saya pahami adalah definisi sistem persamaan linear (SPLDV dan SPLTV), metode penyelesaian, jenis solusi sistem persamaan, sistem pertidaksamaan linear dua variabel, serta cara menentukan daerah penyelesaian secara grafik.</p><p><br></p>', NULL, '<p>baca dan pahami soal, tentukan variabel setiap besaran, identifikasi informasi yang diketahui dan ditanya, buat model matematikanya,pilih metode penyelesaian yang tepat, baru hitung dan periksa kesesuaian jawaban dengan konteks soal.</p><p><br></p>', NULL, '<p>tentukan berapa variabel yang terlibat, susun persamaan, gunakan metode yang efisien, gambar grafik jika diperlukan untuk visualisasi, dan pastikan solusi memenuhi semua batasan yang ada dalam konteks soal.</p>', NULL, '2025-12-13 02:01:23', '2025-12-13 02:12:23'),
(159, 3, 338, '<p>Perbandingan trigonometri, hubungan sudut dan sisi dari sgitiga siku-siku, perbandingan trigonometri untuk sudut lancip, hubungan antara sinus dan cosinus untuk sudut penyiku dan perbandingan trigonometri dan teoerema phythagoras</p>', NULL, '<p>Pahami soal, buat sketsa segitiga, tentukan sisi dan sudut yang diketahui, lalu pilih perbandingan trigonometri yang sesuai sebelum menghitung.</p>', NULL, '<p>Saya menentukan strategi sejak memahami konteks soal, dengan melihat informasi yang diketahui dan ditanyakan, lalu memilih konsep atau rumus yang paling sesuai agar penyelesaiannya tepat.</p>', NULL, '2025-12-13 02:03:14', '2025-12-13 02:06:02'),
(160, 4, 326, '<p>yang sudah saya ketahui dari topik ini adalah</p><ol><li>Fungsi kuadrat berbentuk ax^2 + bx + c</li><li>Grafiknya parabola, bisa terbuka ke atas atau ke bawah.</li><li>titik puncak, sumbu simetri, dan akar-akar persamaan kuadrat.</li></ol>', NULL, '<p>membaca soal dan memahami apa yang ditanya, mencatat informasi penting dari cerita, mengubah cerita menjadi bentuk fungsi kuadrat, menentukan cara yang tepat serta memastikan hasil sesuai konteks</p>', NULL, '<p>menentukan dulu apakah parabola terbuka ke atas atau ke bawah, menggunakan rumus atau sifat fungsi kuadrat yang paling cocok serta mengecek kembali apakah hasilnya sesuai dengan situasi pada soal.</p>', NULL, '2025-12-13 02:05:36', '2025-12-13 02:13:51'),
(161, 4, 253, '<p>Yang saya ketahaui dari topik yang dipelajari yaitu konsep dari  fungsi kuadrat dan juga penerapannya dalam kehidupan sehari-hari.</p>', NULL, '<p>langkah-langkah yang dilakukan yaitu: Pahami soal, kemudian kerjakan dengan memilih metode apakah pemfaktoran, rumus ABC, atau lainnya, kemudian selesaikan.</p>', NULL, '<ol><li><strong>Cek Persamaan:</strong>&nbsp;Masukkan jawaban ke persamaan awal.</li><li><strong>Logika:</strong>&nbsp;Pastikan jawaban masuk akal.</li><li><strong>Verifikasi:</strong>&nbsp;Gunakan cara lain (misal, kalkulator).</li></ol><p><br></p>', NULL, '2025-12-13 02:08:56', '2025-12-13 02:16:22'),
(162, 4, 350, '<p> fungsi kuadrat berbentuk f(x)=ax2+bx+cf(x)=ax^2+bx+cf(x)=ax2+bx+c, grafiknya berupa parabola, memiliki titik puncak, sumbu simetri, dan dapat digunakan untuk memodelkan berbagai masalah kontekstual dalam kehidupan sehari-hari.</p>', NULL, '<p>Sebelum menghitung, langkah yang dilakukan adalah memahami soal cerita, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, lalu menyusun model matematika berupa fungsi atau persamaan kuadrat.</p>', NULL, '<p>Strategi penyelesaian dilakukan dengan menyesuaikan model fungsi kuadrat dengan konteks soal, menganalisis arah grafik dan titik puncak, kemudian menggunakan metode yang tepat agar solusi yang diperoleh logis dan sesuai masalah.</p>', NULL, '2025-12-13 02:09:09', '2025-12-13 02:10:26'),
(163, 1, 240, '<p><span style=\"color: rgb(51, 65, 85);\">Pada materi eksplorasi eksponen, kita akan membahas konsep dasar tentang eksponen. Eksponen adalah notasi matematika yang digunakan untuk menunjukkan operasi perkalian yang diulang.</span></p>', NULL, '<p>langkah langkahnya yaitu memahami konsep soal dan menggunakan sifat yang berlaku sesuai dengan soal</p>', NULL, '<p>strateginya yaitu melihat bentuk soal dan memahami soalnya kemudian mencari sifat sifat yang cocok untuk menyelesaikan masalah yang ada di soalnya</p>', NULL, '2025-12-13 02:09:10', '2025-12-13 02:33:14'),
(164, 6, 201, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki <strong>besar dan arah</strong>, berbeda dengan skalar yang hanya memiliki besar. Vektor dapat direpresentasikan dalam bentuk panah, koordinat, atau komponen pada sumbu tertentu.</p>', NULL, '<p>Langkah pertama adalah membaca soal dengan teliti dan memahami konteks masalah vektor yang diberikan. Setelah itu, tentukan besaran vektor yang diketahui dan yang ditanyakan serta arah dan satuannya.</p>', NULL, '<p>Saya mulai memiliki strategi sejak awal membaca soal dengan memahami konteks permasalahan yang diberikan.diterapkan dengan menentukan konsep yang tepat, menyusun model matematika, lalu memilih langkah penyelesaian yang paling efektif.</p><p><br></p>', NULL, '2025-12-13 02:09:38', '2025-12-13 02:11:30'),
(165, 5, 283, '<p>Fungsi eksponen adalah fungsi yang variabelnya berada pada pangkat.</p><p> Grafiknya dapat menunjukkan pertumbuhan atau peluruhan.</p><p> Fungsi ini sering digunakan untuk memodelkan perubahan yang cepat, seperti populasi atau bunga.</p>', NULL, '<p>Pahami konteks soal dan tentukan besaran yang diketahui serta ditanya.</p><p> Buat model fungsi eksponen yang sesuai.</p><p> Setelah itu, lakukan perhitungan untuk memperoleh jawabannya.</p>', NULL, '<p>Saya mulai menyusun strategi setelah memahami konteks soal eksponen.</p><p> Saya menentukan model fungsi yang tepat sebelum menghitung hasilnya.</p><p><br></p>', NULL, '2025-12-13 02:10:28', '2025-12-13 02:14:20'),
(166, 1, 328, '<p>pada topik ini saya jadi mengetahui definisi tentang eksponen dan sifat sifatnya</p>', NULL, '<p>Baca soal dengan teliti, tentukan informasi yang diketahui dan yang ditanyakan, lalu ubah cerita ke dalam model matematika eksponen dan tentukan rumus yang sesuai sebelum mulai menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan memahami konteks soal terlebih dahulu, mengidentifikasi informasi yang diketahui dan yang ditanyakan, kemudian mengubahnya ke dalam model matematika eksponen yang sesuai sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 02:12:01', '2025-12-13 02:17:18'),
(167, 1, 280, '<p>Eksponen adalah cara singkat untuk menulis perkalian satu bilangan (basis) dengan dirinya sendiri secara berulang, dimana angka kecil di atas (pangkat/eksponen) menunjukan berapa kali basis tersebut dikalikan.</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-13 02:12:15', '2025-12-13 02:20:29'),
(168, 5, 330, '<p>Fungsi eksponen f(x)=n x a^x menunjukkan pertumbuhan (a&gt;1) atau peluruhan (0&lt;a) tanpa menyentuh sumbu x.</p>', NULL, '<p>langkah yang saya lakukan yaitu Identifikasi apakah soal merupakan pertumbuhan atau peluruhan eksponen dan menentukan model fungsi eksponennya</p>', NULL, '<p>Strategi dilakukan setelah mengidentifikasi jenis masalah (pertumbuhan/peluruhan) dan menentukan fungsi modelnya</p>', NULL, '2025-12-13 02:13:03', '2025-12-13 02:16:25'),
(169, 1, 211, '<p>Yang saya ketahui adalah eksponen dan sifat sifat nya . Eksponen adalah suatu bilangan pokok yang di kalikan dengan paket nya.</p>', NULL, '<p>Langkah langkah nya yaitu memahami konsep soal dan menggunakan sifat yang berlaku sesuai dengan soal </p>', NULL, '<p>Strategi nya yaitu melihat bentuk soal dan memahami soal nya kemudian mencari sifat sifat yang cocok untuk menyelesaikan masalah yang ada di soal nya.</p>', NULL, '2025-12-13 02:14:02', '2025-12-13 02:30:22'),
(170, 2, 191, '<p><span style=\"color: rgb(51, 65, 85);\">sistem persamaan linear adalah kumpulan dua atau lebih persamaan linear yang memiliki satu set nilai yang memenuhi semua persamaan dalam sistem tersebut.</span></p>', NULL, '<p>pertama pahami soal dengan baik dan identifikasi informasi yang ada pada soal, rumuskan persamaan matematika yang sesuai, selesaikan persamaan atau pertidaksaman, dan hitung hasil akhir</p>', NULL, '<p>strategi dimulai dengan menentukan variabel dari soal. Susun persamaan atau pertidaksamaan yang sesuai. Selesaikan dengan metode yang tepat dan cek kecocokan hasil.</p>', NULL, '2025-12-13 02:15:36', '2025-12-13 02:21:43'),
(171, 2, 321, '<p>Yang saya ketahui dari topik ini yaitu tentang &nbsp;persamaan dan pertidaksamaan linear, sistem persamaan linear dua dan tiga variabel, serta cara menyelesaikannya dengan metode substitusi, eliminasi, grafik, dan determinan.</p><p><br></p>', NULL, '<p>Langkah-langkahnya yaitu, pahami soal cerita dan tentukan informasi yang diketahui serta yang ditanyakan, tentukan variabel dan modelkan masalah ke persamaan atau pertidaksamaan linear sebelum menghitung.</p><p><br></p>', NULL, '<p>Saya menyusun strategi dengan memahami konteks masalah terlebih dahulu dan menentukan model matematika yang sesuai. Selanjutnya memilih metode penyelesaian yang tepat agar solusi yang diperoleh logis dan sesuai konteks.</p>', NULL, '2025-12-13 02:16:03', '2025-12-13 02:26:30'),
(172, 6, 332, '<p>Yang saya ketahui tentang vektor</p><p>Vektor adalah besaran yang memiliki besar (nilai) dan arah. Vektor dapat dinyatakan dengan panah, koordinat, atau komponen, dan digunakan untuk menggambarkan perpindahan, kecepatan, dan gaya.</p>', NULL, '<p>Langkah sebelum menghitung soal cerita vektor</p><p>Membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menggambar sketsa arah vektor, serta menuliskan vektor dalam bentuk komponen atau koordinat yang sesuai.</p>', NULL, '<p><br></p><p>Strategi digunakan saat soal cerita melibatkan arah dan perpindahan. Caranya dengan memahami konteks masalah, menggambarkan vektor secara visual, memilih operasi vektor yang tepat, lalu menafsirkan hasil sesuai situasi pada soa</p>', NULL, '2025-12-13 02:16:59', '2025-12-13 02:18:55'),
(173, 6, 353, '<p>Vektor adalah besaran yang memiliki besar (nilai) dan arah. Vektor dapat dinyatakan dengan panah, koordinat, atau komponen, dan digunakan untuk menggambarkan perpindahan, kecepatan, dan gaya.</p>', NULL, '<p>Langkah sebelum menghitung soal cerita vektor : Membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menggambar sketsa arah vektor, serta menuliskan vektor dalam bentuk komponen atau koordinat yang sesua</p>', NULL, '<p>Strategi digunakan saat soal cerita melibatkan arah dan perpindahan. Caranya dengan memahami konteks masalah, menggambarkan vektor secara visual, memilih operasi vektor yang tepat, lalu menafsirkan hasil sesuai situasi pada soal.</p>', NULL, '2025-12-13 02:17:08', '2025-12-13 02:18:02'),
(174, 1, 258, '<ol><li>Definisi eksponen,adalah  cara untuk menulis perkalian berulang dari suatu bilangan dengan dirinya sendiri.Contoh:2³ = 2x2x2</li><li>sifat - sifat eksponen</li><li>makna dalam kehidupan nyata,</li><li>jenis - jenis eksponen</li></ol>', NULL, '<p>Pahami konteks soal cerita, tentukan apa yang diketahui dan ditanya, ubah cerita ke bentuk matematika, tentukan aturan eksponen yang sesuai, susun langkah operasi eksponen, lakukan perhitungan, dan interpretasi kembali jawaban.  </p>', NULL, '<p>Temukan pola pertumbuhan atau struktur eksponen,gunakan sifat eksponen secara tepat,visualisai/pemetaan per fase,cek kembali dengan contoh kecil,dan sederhanakan dulu bentuk aljabarnya  </p>', NULL, '2025-12-13 02:19:04', '2025-12-13 02:49:45'),
(175, 1, 282, '<p><span style=\"color: rgb(51, 65, 85);\">Pada topik ekspresi eksponen, kita belajar tentang cara mengekspresikan bilangan dengan pangkat atau eksponen. Eksponen menunjukkan berapa kali bilangan tersebut dikalikan dengan dirinya sendiri</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Langkah pertama adalah mengidentifikasi variabel eksponen dan basisnya dalam soal cerita. Selanjutnya, ubah informasi dalam soal menjadi ekspresi eksponen yang sesuai sebelum melakukan perhitungan akhir.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Tentu, satu strategi yang dapat membantu dalam menyelesaikan soal ekspresi eksponen adalah dengan menyederhanakan terlebih dahulu ekspresi tersebut sebelum melakukan operasi matematika lebih lanjut</span></p>', NULL, '2025-12-13 02:19:23', '2025-12-13 02:27:39'),
(176, 2, 208, '<p>yang saya ketahui adalah mengenai sistem persamaan dan pertidakpersamaan linier</p>', NULL, '<ol><li>Memahami soal ceritanya</li><li>menentukan variabel yang digunakan</li><li>menerjemahkan kalimat cerita ke bentuk matematika</li><li>memverifikasi terjemahaan dan hubungan antar variabel</li></ol>', NULL, '<p>untuk mempunyai suatu strategi, saya harus menguasai konsep topik ini dan kemudian dapat merancang strateginya yaitu</p><ol><li>memahami masalahnya</li><li>mennyusun model matematikanya</li><li>penerapan metode penyelesaiannya</li></ol>', NULL, '2025-12-13 02:21:41', '2025-12-13 02:31:08'),
(177, 6, 346, '<p>yang telah saya ketahui adalah defenisi vektor dan operasi vektor dan cara penyelesaian soalnya</p>', NULL, '<p>mencermati soalnya lalu mengerjakannya dengan langkah-langkah sistematis secara tepat</p>', NULL, '<p>ketika memahami soalnya dan mengerjakannya dengan pengetahuan yang ada</p>', NULL, '2025-12-13 02:23:42', '2025-12-13 02:24:51'),
(178, 1, 339, '<p>Logaritma adalah operasi invers dari eksponen yang esensial untuk mencari pangkat dan memodelkan pertumbuhan/peluruhan eksponensial.</p>', NULL, '<p>Langkah awalnya adalah menganalisis soal untuk mengubahnya menjadi model persamaan Logaritma/Eksponen yang memenuhi syarat numerus positif.</p>', NULL, '<p>Strategi utamanya adalah penguatan konsep invers dengan visualisasi, penalaran pembuktian sifat, dan penerapan soal kontekstual (misalnya, skala logaritmik) untuk menghindari hafalan.</p>', NULL, '2025-12-13 02:25:01', '2025-12-13 02:26:01'),
(179, 3, 337, '<p>Sudut segitiga siku-siku 90°</p>', NULL, '<p>Melihat keinginan soal, memikirkan cara yang tepat,lalu melaksanakan </p>', NULL, '<p>Sebelum mengerjakan soalnya</p>', NULL, '2025-12-13 02:31:53', '2025-12-13 02:33:01'),
(180, 4, 323, '<p>Definisi fungsi kuadrat,karakteristik grafik parabola ,titik puncak dan sumbu simetri, cara mencari akar persamaan kuadrat,nilai diskriminan untuk menentukan banyak titik potong, serta penerapannya dalam konteks gerak benda atau optimasi.</p>', NULL, '<p>pahami soal, identifikasi variabel dan besaran,tentukan apa yang diketahui dan ditanya,buat model fungsi kuadrat dari informasi yang ada, pilih metode penyelesaian yang sesuai,hitung dan periksa jawaban </p>', NULL, '<p>kenali bentuk fungsi kuadrat , tentukan apakah mencari nilai maksimum/minimum,atau mencari titik potong, buat tabel atau sketsa grafik jika diperlukan, gunakan nilai diskriminan untuk mengecek  solusi, pastikan hasil akhir sesuai dengan masalah </p>', NULL, '2025-12-13 02:33:17', '2025-12-13 02:37:51'),
(181, 2, 348, '<p>Sistem persamaan linear (dua/tiga variabel) dan sistem pertidaksamaan linear (dua variabel), serta metode penyelesaiannya seperti eliminasi, substitusi, grafik, dan Sarrus.</p><p><br></p>', NULL, '<p>Tentukan variabel yang dicari, identifikasi informasi penting, lalu modelkan ke dalam bentuk sistem persamaan atau pertidaksamaan linear.</p>', NULL, '<p>Pilih metode yang tepat (eliminasi/substitusi untuk SPLTV, grafik untuk pertidaksamaan), selesaikan sistematis, lalu periksa kesesuaian jawaban dengan konteks soal.</p>', NULL, '2025-12-13 02:33:25', '2025-12-13 02:34:02'),
(182, 4, 333, '<p>Fungsi kuadrat f(x) = ax² + bx + c berbentuk parabola, memiliki titik puncak (-b/2a, -D/4a), dan diselesaikan dengan pemfaktoran, melengkapkan kuadrat sempurna, atau rumus abc.</p>', NULL, '<p>Identifikasi data dan yang ditanyakan, buat model f(x) = ax² + bx + c, pilih metode penyelesaian yang sesuai, lalu interpretasikan hasil dalam konteks soal.</p>', NULL, '<p>Tentukan jenis masalah (maksimum/minimum gunakan titik puncak, titik potong gunakan akar-akar), sesuaikan interpretasi dengan konteks masalah, dan pastikan jawaban logis dan realistis.</p>', NULL, '2025-12-13 02:36:58', '2025-12-13 02:37:48'),
(183, 1, 270, '<p>Eksponen adalah notasi matematika yang digunakan untuk menunjukkan perkalian bilangan dengan dirinya sendiri beberapa kali.</p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Perhatikan apakah ada angka atau variabel yang merupakan pangkat dari bilangan tertentu, dan bagaimana hubungannya dengan informasi lain dalam soal</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">1. Identifikasi eksponen dan basisnya</span></p><p><span style=\"color: rgb(51, 65, 85);\">2. Gunakan sifat-sifat eksponen   3. Perhatikan tanda operasi</span></p><p><br></p>', NULL, '2025-12-13 02:38:50', '2025-12-13 02:53:40'),
(184, 6, 283, '<p>Vektor punya <strong>besar dan arah</strong>.</p><p> Bisa dijumlah, dikurang, atau dikali skalar.</p><p> Digunakan untuk gaya, kecepatan, dan perpindahan.</p>', NULL, '<p>Baca soal dengan cermat dan pahami informasi yang diberikan.</p><p> Tentukan vektor dan bentuknya serta operasi yang diperlukan.</p><p> Rencanakan urutan perhitungan sebelum menghitung hasil akhir.</p>', NULL, '<p>Saya membuat strategi ketika <strong>memahami konteks soal</strong> dan mengetahui apa yang ditanya.</p><p> Langkahnya: identifikasi informasi penting, pilih operasi atau metode yang tepat, lalu susun urutan penyelesaian sebelum menghitung.</p>', NULL, '2025-12-13 02:39:10', '2025-12-13 02:41:13'),
(185, 2, 328, '<p>yang saya ketahui saya jadi mengetahui tentang definisi dari persamaan dan pertidaksamaan linear seta cara menyelesaikannya</p>', NULL, '<p>Baca soal dengan teliti, tentukan yang diketahui dan ditanyakan, misalkan dengan variabel, ubah ke bentuk persamaan atau pertidaksamaan linear, lalu tentukan cara penyelesaiannya sebelum menghitung.</p>', NULL, '<p>Saya memahami konteks soal, menentukan variabel, mengubahnya ke bentuk persamaan atau pertidaksamaan linear, lalu memilih metode penyelesaian yang tepat.</p>', NULL, '2025-12-13 02:46:40', '2025-12-13 02:51:07'),
(186, 5, 350, '<p>Fungsi eksponen digunakan untuk memodelkan peristiwa pertumbuhan &amp; peluruhan,  dengan bentuk f(x)=n⋅axf(x)=n\\cdot a^xf(x)=n⋅ax, di mana a&gt;1a&gt;1a&gt;1 menunjukkan pertumbuhan dan 0&lt;a&lt;10&lt;a&lt;10&lt;a&lt;1 menunjukkan peluruhan.</p>', NULL, '<p>langkah yang perlu dilakukan adalah memahami soal cerita, menentukan nilai awal dan perubahan yang terjadi, mengidentifikasi apakah termasuk pertumbuhan atau peluruhan, serta menyusun model fungsi eksponen yang sesuai dengan konteks masalah</p>', NULL, '<p>Strategi penyelesaian soal pada topik ini adalah menghubungkan konsep fungsi eksponen dengan konteks nyata pada soal, memilih model matematika yang tepat, lalu memeriksa kembali hasilnya agar sesuai secara logis dengan permasalahan yang diberikan</p>', NULL, '2025-12-13 02:48:35', '2025-12-13 02:49:40'),
(187, 6, 196, '<p>Vektor memiliki besar dan arah, bisa direpresentasikan koordinat atau grafik geometris. Operasi vektor meliputi penjumlahan, pengurangan, perkalian skalar, dan dot product. </p>', NULL, '<p>Identifikasi besaran vektor dalam soal, Gambar sketsa atau diagram untuk memvisualisasikan vektor dan hubungannya dengan jelas. Tentukan operasi yang diperlukan: penjumlahan, pengurangan, atau mencari besar dan arah.</p>', NULL, '<p>Gunakan metode komponen saat vektor diberikan dalam bentuk koordinat atau angka. Gunakan metode geometris saat soal melibatkan sudut, arah, atau gambar visual. Pilih rumus sesuai yang ditanya: panjang vektor, sudut, proyeksi, atau resultan.</p>', NULL, '2025-12-13 02:52:24', '2025-12-13 02:54:10'),
(188, 5, 323, '<p>Definisi fungsi eksponen,jenis fungsi eksponen,karakteristik grafik fungsi eksponen,perbedaan fungsi eksponen dengan fungsi linear dan kuadrat, serta penerapannya dalam konteks pertumbuhan bakteri, peluruhan obat, atau pantulan bola.</p><p><br></p>', NULL, '<p>pahami soal, identifikasi apakah termasuk pertumbuhan atau peluruhan eksponensial, tentukan nilai awal dan basis , buat model fungsi eksponen, tentukan variabel x,hitung nilai yang ditanya dan periksa kesesuaian dengan soal.</p><p><br></p>', NULL, '<p>kenali pola pertumbuhan atau peluruhan, buat tabel untuk beberapa fase awal, susun model fungsi eksponensial, gambar grafik jika diperlukan,pastikan hasil akhir realistis dengan konteks masalah</p>', NULL, '2025-12-13 02:52:28', '2025-12-13 02:55:48'),
(189, 4, 342, '<p>Persamaan kuadrat berbentuk ax^2+bx+c dapat diselesaikan dengan pemfaktoran, melengkapi kuadrat sempurna &amp; rumus ABC. Memiliki grafik parabola dengan arah buka ditentukan oleh nilai a, titik puncak sebagai maksimum atau minimum.</p><p><br></p>', NULL, '<p>Pahami soal cerita dan identifikasi informasi yang diketahui serta yang ditanyakan,</p><p>tentukan variabel dan ubah soal ke dalam model persamaan atau fungsi kuadrat, serta</p><p>pilih metode penyelesaian yang tepat sebelum melakukan perhitungan.</p>', NULL, '<p>Memahami konteks masalah, menentukan variabel yang tepat, memodelkan masalah ke dalam persamaan atau fungsi kuadrat, memilih metode penyelesaian yang paling sesuai dan menafsirkan hasilnya kembali ke konteks soal agar jawabannya bermakna.</p>', NULL, '2025-12-13 02:53:38', '2025-12-13 02:57:17');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(190, 4, 285, '<p><span style=\"color: rgb(51, 65, 85);\">fungsi kuadrat adalah fungsi matematika yang dinyatakan dalam bentuk \\( f(x) = ax^2 + bx + c Saya juga sudah memahami bahwa grafik fungsi kuadrat berbentuk parabola.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama mengidentifikasi informasi dari soal cerita matematika. Selanjutnya, tentukan variabel yang akan digunakan untuk mewakili informasi tersebut dalam bentuk persamaan matematika.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Untuk menyelesaikan soal fungsi kuadrat, pertama identifikasi koefisien a, b, dan c. Kemudian gunakan rumus diskriminan atau lengkapi kuadrat sempurna untuk mencari akar-akarnya.</span></p>', NULL, '2025-12-13 02:57:21', '2025-12-13 03:01:34'),
(191, 4, 237, '<p>Saya sudah mengetahui tentang definisi, konsep, dan ketiga cara menyelesaikan fungsi kuadrat, serta penerapannya dalam kehidupan sehari-hari</p>', NULL, '<p>memahami soal cerita, menentukan apa yang diketahui dan apa yang ditanyakan, memisalkan variabel, memodelkan masalah ke dalam bentuk fungsi kuadrat, kemudian melakukan perhitungan</p>', NULL, '<p>Memahami konteks masalah seperti menentukan nilai maksimum atau minimum, menentukan waktu, dll. Setelah itu gunakan konsep fungsi kuadrat seperti titik puncak, akar-akar, atau grafik parabola agar sesuai dengan konteks matematika</p>', NULL, '2025-12-13 02:58:13', '2025-12-13 03:09:06'),
(192, 2, 282, '<p><span style=\"color: rgb(51, 65, 85);\">Pada topik ini, kita akan mempelajari bagaimana menyelesaikan sistem persamaan dan pertidaksamaan linear dengan metode substitusi atau eliminasi. </span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">1.adalah mengidentifikasi variabel yang diberikan dalam cerita dan menuliskan sistem persamaannya.2.tentukan metode penyelesaian yang tepat berdasarkan jenis sistem persamaan linear yang ada.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Salah satu strategi umum untuk menyelesaikan sistem persamaan dan pertidaksamaan linear adalah dengan menggunakan metode substitusi atau eliminasi. </span></p>', NULL, '2025-12-13 02:59:37', '2025-12-13 03:06:19'),
(193, 6, 323, '<p>definisi vektor, notasi vektor, vektor negatif dan vektor nol, vektor ekuivalen, operasi vektor , sifat komutatif dan asosiatif pada penjumlahan vektor, serta penerapannya dalam perpindahan, kecepatan, atau game.</p><p><br></p>', NULL, '<p>identifikasi besaran yang merupakan vektor, gambar diagram vektor jika diperlukan, tentukan operasi vektor yang akan digunakan, pilih metode penyelesaian, hitung dan periksa arah serta besar hasil akhir sesuai soal.</p><p><br></p>', NULL, '<p>gambar vektor, gunakan metode segitiga/jajar genjang untuk penjumlahan, gunakan perhitungan komponen untuk operasi aljabar, perhatikan tanda vektor,pastikan hasil akhir masuk akal dengan konteks soal</p>', NULL, '2025-12-13 03:02:31', '2025-12-13 03:06:04'),
(194, 3, 319, '<p>hubungan sudut dan sisi dari segitiga siku siku, perbandingan trigonometri untuk sudut lancip, hubungan anntara sinus dan cosinus untuk sudut penyiku, perbandingan trigonometri dan teorema phytagoras,</p>', NULL, '<p>buat gambar beri label sisi (depan, samping, miring), lalu pilih rumus trigonometri (Sin, Cos, atau Tan) yang menghubungkan data yang diketahui dan data yang dicari.</p>', NULL, '<p>Strategi diaktifkan setelah identifikasi topik dan analisis struktur soal; saya lalu memetakan konsep dan rumus kunci untuk Trigonometri,yang paling efisien untuk konteks tersebut.</p>', NULL, '2025-12-13 03:04:57', '2025-12-13 03:08:28'),
(195, 4, 321, '<p>Saya mengetahui pengertian dan bentuk umum persamaan kuadrat beserta sifat grafiknya dan cara menyelesaikan persamaan kuadrat dengan berbagai metode.</p><p><br></p>', NULL, '<ol><li>Memahami soal cerita dengan menentukan informasi yang diketahui dan yang ditanyakan. </li><li>Menentukan variabel serta memodelkan masalah ke dalam persamaan kuadrat sebelum melakukan perhitungan.</li></ol>', NULL, '<p>Saya menyusun strategi dengan memahami konteks masalah terlebih dahulu dan menentukan model persamaan kuadrat yang sesuai. Kemudian memilih metode penyelesaian yang tepat agar hasilnya logis dan sesuai dengan soal.</p><p><br></p>', NULL, '2025-12-13 03:05:40', '2025-12-13 03:08:04'),
(196, 6, 330, '<p>Vektor adalah besaran yang memiliki nilai dan arah. Vektor dapat direpresentasikan dengan panah atau komponen dan dioperasikan dengan aturan khusus yang berbeda dari skalar</p>', NULL, '<p>Untuk soal cerita vektor, langkah awalnya adalah mengidentifikasi besaran vektor (seperti perpindahan atau gaya) dan merepresentasikannya secara grafis (panah) atau komponen aljabar</p>', NULL, '<p>Saya memiliki strategi ketika konteks masalah diketahui (misalnya, vektor, aljabar, fungsi) untuk mengaplikasikan konsep dan langkah-langkah yang relevan</p>', NULL, '2025-12-13 03:06:53', '2025-12-13 03:08:53'),
(197, 5, 253, '<p>Yang saya ketahui dari materi yang telah dipelajari pada topik ini yaitu konsep dari fungsi eksponen, dan juga penerapannya dalam kehidupan sehari-hari</p>', NULL, '<p>Langkah-langkah yang saya lakukan yaitu pahami soal, ubah soal menjadi persamaan matematika, selesaikan persamaan, periksa jawaban dan tulis kesimpulan.</p><p><br></p><p><br></p><p><br></p>', NULL, '<p>Kapan saya bisa memiliki suatu strategi yaitu ketika saya bisa mengkategorikan jenis soalnya. Bagaimana saya memiliki suatu suatu strategi yaitu dengan pahami konteks soalnya kemudian menyelesaikannya dengan langkah langkah yang baik dan benar.</p>', NULL, '2025-12-13 03:07:34', '2025-12-13 03:19:26'),
(198, 1, 262, '<p>yang saya ketahui tentang materi eksponen (atau bilangan berpangkat) adalah materi yang membahas tentang perkalian berulang suatu bilangan dengan dirinya sendiri, serta bagaimana operasi ini memiliki sifat-sifat khusus yang memudahkan perhitungan.</p>', NULL, '<p>Identifikasi nilai awal, laju perubahan, dan waktu. Sesuaikan satuan dan konversi laju ke desimal. Pilih model yang sesuai, susun persamaan, lalu tentukan apakah perlu menggunakan logaritma untuk mencari pangkat.</p>', NULL, '<p>Identifikasi nilai awal, laju, dan waktu. Sesuaikan satuan waktu dan laju. Pilih model yang tepat, susun persamaan. Gunakan logaritma bila mencari pangkat.</p>', NULL, '2025-12-13 03:08:20', '2025-12-13 03:19:28'),
(199, 5, 326, '<p>Sebuah fungsi eksponen dinyatakan dengan f(x)= n × a^x Di mana 𝑎 adalah bilangan pokok, 𝑎 &gt; 0, 𝑎 ≠ 1, 𝑛 adalah bilangan real tak nol dan 𝑥 adalah sebarang bilangan real.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, mengenali jenis pertumbuhan atau peluruhan, lalu mengubah cerita ke dalam model fungsi eksponen.</p>', NULL, '<p>Strategi digunakan saat soal berbentuk cerita. Caranya dengan memahami konteks masalah, memilih rumus yang sesuai, dan menafsirkan hasil sesuai cerita</p>', NULL, '2025-12-13 03:11:23', '2025-12-13 03:12:48'),
(200, 3, 201, '<p>Saya mengetahui bahwa trigonometri dasar mempelajari hubungan antara sudut dan sisi pada segitiga siku-siku melalui perbandingan sinus, cosinus, dan tangen.</p><p><br></p>', NULL, '<p>Langkah pertama adalah membaca soal dengan teliti dan memahami situasi yang diberikan. Tentukan apa yang diketahui, apa yang ditanyakan, serta gambarkan sketsa segitiga untuk memperjelas hubungan sisi dan sudut.</p>', NULL, '<p>Saya mulai memiliki strategi sejak membaca soal dan memahami konteks permasalahannya.</p><p> Strategi dilakukan dengan menentukan konsep yang tepat, membuat sketsa, lalu memilih langkah penyelesaian yang paling sesuai.</p>', NULL, '2025-12-13 03:11:28', '2025-12-13 03:12:40'),
(201, 2, 280, '<p><strong>Sistem Persamaan dan Pertidaksamaan Linear</strong>&nbsp;adalah konsep matematika yang digunakan untuk memecahkan masalah yang melibatkan lebih dari satu variabel.</p>', NULL, '<ol><li>Membaca dengan seksama, mengidentifikasi pertanyaan dan menandai informasi yang penting</li><li>menentikan strategi dan rumus dalam menjawab soal</li><li>menjawab dan mengefaluasi jawaban</li></ol>', NULL, '<ol><li>Identifikasi soal</li><li>memilih metode penyelesaian yang tepat untuk spl</li><li>strategi visual untuk pertidaksamaan SPtL</li><li>Verifikasi dan pengecekan ulang jawaban </li></ol>', NULL, '2025-12-13 03:12:31', '2025-12-13 03:24:54'),
(202, 3, 283, '<p>Trigonometri mempelajari <strong>hubungan sudut dan sisi</strong> segitiga siku-siku.</p><p> Berguna untuk <strong>menghitung tinggi, jarak, dan kemiringan</strong>.</p><p><br></p>', NULL, '<p>Baca dan pahami soal, lalu identifikasi sisi dan sudut yang relevan.</p><p> Tentukan perbandingan trigonometri yang tepat dan rencanakan perhitungannya.</p>', NULL, '<p>Saya membuat strategi ketika <strong>memahami konteks soal dan yang ditanyakan</strong>.</p><p> Langkahnya: identifikasi data penting, pilih metode tepat, dan susun urutan penyelesaian</p>', NULL, '2025-12-13 03:12:46', '2025-12-13 03:14:45'),
(203, 4, 328, '<p>saya jadi mengetahui tentang karakteristik fungsi kuadrat dan menentukan akar-akar persamaan kuadrat</p>', NULL, '<p>Baca soal dengan teliti, tentukan yang diketahui dan ditanyakan, ubah ke model fungsi kuadrat, lalu tentukan cara penyelesaiannya sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan memahami konteks soal terlebih dahulu, menentukan variabel yang sesuai, memodelkan masalah ke dalam persamaan atau fungsi kuadrat, lalu memilih metode penyelesaian yang tepat agar hasilnya sesuai dengan permasalahan.</p>', NULL, '2025-12-13 03:13:40', '2025-12-13 03:16:14'),
(204, 5, 333, '<p>Fungsi eksponen f(x) = n × aˣ terbagi menjadi pertumbuhan (a &gt; 1, grafik naik) dan peluruhan (0 &lt; a &lt; 1, grafik turun), grafik selalu di atas sumbu x dengan asimtot y = 0, diaplikasikan dalam pertumbuhan bakteri dan peluruhan obat.</p>', NULL, '<p>Identifikasi nilai awal (n), faktor perubahan (a), dan variabel (x), tentukan jenis pertumbuhan atau peluruhan, buat model f(x) = n × aˣ dan verifikasi dengan substitusi, lalu gunakan untuk menjawab pertanyaan.</p>', NULL, '<p>Identifikasi jenis dari konteks (pertumbuhan a &gt; 1, peluruhan 0 &lt; a &lt; 1), tentukan nilai awal dan rasio perubahan, buat model f(x) = n × aˣ, lalu prediksi hasil dengan memastikan jawaban logis sesuai konteks.</p>', NULL, '2025-12-13 03:14:45', '2025-12-13 03:17:05'),
(205, 4, 282, '<p>Saya mengetahui konsep dasar dan rumus-rumus utama pada materi yang dibahas. Selain itu, saya memahami langkah-langkah penyelesaian soal serta penerapannya dalam berbagai masalah.</p><p><br></p>', NULL, '<p>Langkah pertama adalah membaca dan memahami soal cerita dengan cermat. Kemudian menentukan informasi yang diketahui, yang ditanyakan, dan menyusunnya ke dalam model matematika sebelum menghitung.</p>', NULL, '<p>Saya menentukan terlebih dahulu konsep dan rumus yang sesuai dengan konteks soal. Setelah itu, saya menyusun langkah penyelesaian secara sistematis agar solusi tepat.</p>', NULL, '2025-12-13 03:19:56', '2025-12-13 03:54:24'),
(206, 4, 324, '<p>dari materi ini saya memahami bahwa fungsi kuadrat berbentuk f(x)=ax^2 +bx+c dengan a tidak sama dengan nol, materi ini mencakup tiga cara menyelesaikan persamaan kuadrat yaitu pemfaktoran, melengkapi kuadrat sempurna, dan rumus abc.</p>', NULL, '<p>langkah yang dilakukan adalah membaca dan memahami soal, mengidentifikasi yang diketahui dan ditanyakan, membuat model fungsi kuadrat dengan menentukan nilai a,b, dan c lalu menghitung menggunakan rumus yang sesuai</p>', NULL, '<p>strategi yang digunakan adalah menyesuaikan metode dengan jenis masalah,seperti menggunakan rumus titik puncak untuk mencari maksimum/minimum, memperhatikan arah parabola sesuai konteks, dan memverifikasi jawaban</p>', NULL, '2025-12-13 03:20:46', '2025-12-13 03:27:11'),
(207, 6, 350, '<p>saya memahami bahwa vektor adalah besaran yang memiliki besar dan arah serta dapat dioperasikan melalui penjumlahan, pengurangan, dan perkalian skalar untuk menyelesaikan berbagai masalah perpindahan dan arah.</p>', NULL, '<p>Sebelum menghitung, langkah yang perlu dilakukan adalah memahami konteks soal, menentukan vektor yang diketahui dan ditanyakan, serta memilih metode penyelesaian yang sesuai seperti grafis atau komponen.</p>', NULL, '<p>Strategi penyelesaian soal adalah menyesuaikan operasi vektor dengan konteks masalah, lalu memeriksa kembali arah dan besar hasil vektor agar jawabannya logis dan sesuai.</p>', NULL, '2025-12-13 03:23:19', '2025-12-13 03:24:14'),
(208, 3, 353, '<p>Perbandingan trigonometri (sin, cos, tan) digunakan untuk menentukan hubungan sisi dan sudut pada segitiga siku-siku.</p>', NULL, '<p>Memahami soal, membuat sketsa, menentukan sudut dan sisi yang diketahui, lalu memilih perbandingan trigonometri yang tepat.</p>', NULL, '<p>Digunakan saat menghitung tinggi atau jarak. Caranya memahami konteks soal, memilih rumus yang sesuai, dan menafsirkan hasil sesuai keadaan nyata.</p>', NULL, '2025-12-13 03:23:57', '2025-12-13 03:24:53'),
(209, 5, 321, '<p>Pada topik ini saya memahami konsep fungsi eksponen, baik pertumbuhan maupun peluruhan, serta penerapannya dalam kehidupan sehari-hari. grafik fungsi eksponen dan perbedaannya dengan fungsi lain </p>', NULL, '<ol><li>Membaca soal dengan teliti untuk mengetahui informasi yang diketahui dan yang ditanyakan. </li><li>Menentukan model atau fungsi matematika yang sesuai dengan konteks masalah sebelum melakukan perhitungan.</li></ol>', NULL, '<p>Strategi penyelesaian muncul setelah memahami jenis masalah, apakah termasuk pertumbuhan atau peluruhan eksponensial. Selanjutnya, situasi pada soal diubah ke dalam model matematika yang sesuai agar penyelesaiannya tepat.</p><p><br></p><p><br></p>', NULL, '2025-12-13 03:25:01', '2025-12-13 03:26:38'),
(210, 3, 332, '<p>Perbandingan trigonometri (sin, cos, tan) digunakan untuk menentukan hubungan sisi dan sudut pada segitiga siku-siku.</p>', NULL, '<p>Memahami soal, membuat sketsa, menentukan sudut dan sisi yang diketahui, lalu memilih perbandingan trigonometri yang tepat</p>', NULL, '<p>Digunakan saat menghitung tinggi atau jarak. Caranya memahami konteks soal, memilih rumus yang sesuai, dan menafsirkan hasil sesuai keadaan nyata.</p>', NULL, '2025-12-13 03:25:58', '2025-12-13 03:26:44'),
(211, 2, 194, '<p>Sistem persamaan dan pertidaksamaan linear merupakan konsep matematika yang membantu manusia berpikir logis dan sistematis dalam menghadapi berbagai situasi, seperti mengatur keuangan, hingga menentukan strategi bisnis</p>', NULL, '<p>Langkah yang saya lakukan adalah menuliskan variabel, menyusun model matematika dari informasi yang ada, menentukan metode penyelesaian yang tepat, dan memastikan kembali model tersebut sesuai dengan konteks soal cerita.</p>', NULL, '<p>Saya terlebih dahulu memahami konteks masalah, mengidentifikasi apa yang diketahui dan apa yang ditanyakan, lalu mengubah situasi cerita ke dalam bentuk persamaan atau pertidaksamaan linear yang sesuai.</p>', NULL, '2025-12-13 03:26:26', '2025-12-13 03:28:15'),
(212, 1, 249, '<p><span style=\"color: rgb(51, 65, 85);\">Pada materi eksplorasi eksponen, kita akan membahas konsep dasar tentang eksponen. Eksponen adalah notasi matematika yang digunakan untuk menunjukkan operasi perkalian yang diulang.</span></p>', NULL, '<p>langkah langkahnya yaitu memahami konsep soal dan menggunakan sifat yang berlaku sesuai dengan soal</p>', NULL, '<p>strateginya yaitu melihat bentuk soal dan memahami soalnya kemudian mencari sifat sifat yang cocok untuk menyelesaikan masalah yang ada di soalnya</p>', NULL, '2025-12-13 03:28:41', '2025-12-13 03:30:21'),
(213, 6, 321, '<p>Saya memahami konsep aljabar dan fungsi, seperti fungsi eksponen, fungsi kuadrat, dan vektor. Materi ini digunakan untuk memodelkan dan menyelesaikan masalah dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah awal adalah membaca dan memahami soal untuk mengetahui informasi yang diketahui dan ditanyakan. Selanjutnya menentukan model atau konsep matematika yang sesuai dengan konteks soal.</p>', NULL, '<p>Strategi muncul setelah mengenali jenis masalah dan konsep yang tepat digunakan. Strategi dilakukan dengan mengubah soal cerita ke dalam model matematika yang sesuai sebelum menghitung.</p><p><br></p>', NULL, '2025-12-13 03:35:26', '2025-12-13 03:36:04'),
(214, 2, 338, '<p>Saya mengetahui sistem persamaan dan pertidaksamaan linear dua variabel begitupula metode yang digunakan dalam menyelesaikannya</p>', NULL, '<p>Baca soal dengan teliti, identifikasi variabel yang ditanya, dan catat informasi penting. Tentukan bentuk persamaan atau pertidaksamaan linear yang sesuai, bisa bikin diagram garis bilangan kalau perlu.</p><h3><br></h3>', NULL, '<p>Hubungkan data soal dengan persamaan atau pertidaksamaan yang tepat, lakukan manipulasi aljabar secara logis (menambah, mengurangi, kali, atau bagi) sambil memperhatikan aturan pertidaksamaan, lalu pastikan hasil akhir sesuai konteks soal.</p>', NULL, '2025-12-13 03:40:41', '2025-12-13 03:42:42'),
(215, 6, 326, '<p>Yang saya ketahui tentang vektor</p><p>Vektor adalah besaran yang memiliki besar (nilai) dan arah. Vektor dapat dinyatakan dengan panah, koordinat, atau komponen, dan digunakan untuk menggambarkan perpindahan, kecepatan, dan gaya.</p>', NULL, '<p>Langkah sebelum menghitung soal cerita vektor</p><p>Membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menggambar sketsa arah vektor, serta menuliskan vektor dalam bentuk komponen atau koordinat yang sesuai.</p>', NULL, '<p>Strategi digunakan saat soal cerita melibatkan arah dan perpindahan. Caranya dengan memahami konteks masalah, menggambarkan vektor secara visual, memilih operasi vektor yang tepat, lalu menafsirkan hasil sesuai situasi pada soal.</p>', NULL, '2025-12-13 03:40:53', '2025-12-13 03:41:57'),
(216, 3, 321, '<p>Saya memahami konsep trigonometri, khususnya perbandingan sinus, cosinus, dan tangen pada segitiga siku-siku. Konsep ini digunakan untuk menentukan panjang sisi atau besar sudut dalam berbagai masalah kontekstual.</p>', NULL, '<p>Langkah awal adalah memahami situasi soal dan menggambarkannya dalam bentuk segitiga. Setelah itu menentukan perbandingan trigonometri yang sesuai berdasarkan informasi yang diketahui.</p>', NULL, '<p>Strategi muncul setelah mengenali jenis permasalahan dan data yang diketahui dalam soal. Strategi dilakukan dengan memilih perbandingan trigonometri yang tepat sebelum melakukan perhitungan.</p><p><br></p>', NULL, '2025-12-13 03:42:35', '2025-12-13 03:43:12'),
(217, 2, 240, '<p><span style=\"color: rgb(51, 65, 85);\">sistem persamaan linear adalah sekumpulan persamaan linear yang dipecahkan bersama-sama, sedangkan sistem pertidaksamaan linear adalah sekelompok pertidaksamaan linear yang diselesaikan secara bersamaan.</span></p>', NULL, '<p>Baca soal dengan teliti kemudian tentukan apa yang ditanyakan. Catat data yang diketahui Perhatikan kata kunci: \"jumlah\", \"selisih\", \"total\"Buat 2 persamaan linearContoh: 2x + 3y = 15.000 dan x + y = 6.000</p>', NULL, '<p>Strategi utama adalah menganalisis konteks soal, menentukan variabel yang tepat, membuat dua persamaan dari informasi yang diberikan, lalu memilih metode penyelesaian yang paling efisien</p>', NULL, '2025-12-13 03:44:32', '2025-12-13 04:33:05'),
(218, 4, 280, '<p><strong>Fungsi kuadrat</strong>&nbsp;adalah konsep matematika yang menggambarkan hubungan antara dua besaran yang berubah secara tidak lurus atau melengkung.</p>', NULL, '<ol><li>pahami masalah</li><li>modelkan kefungsu kuadrat</li><li>cari nilai \'a\', \'b\',\'c\' atau (\'a\')</li><li>selesaikan persamaan </li><li>tuliskan jawaban dalam konteks soal</li></ol>', NULL, '<p>melakukan pendekatan yang sistimatis,mulai dari identifikasi bentuk soal hingga pemilihan metode yang paling efisien dan tepat.</p>', NULL, '2025-12-13 03:44:40', '2025-12-13 03:56:07'),
(219, 6, 333, '<p>Vektor memiliki besar dan arah, operasinya meliputi penjumlahan (segitiga, jajar genjang, poligon, komponen), pengurangan (a - b = a + (-b)), dan perkalian skalar (k·a), diaplikasikan dalam perpindahan, gaya, dan navigasi.</p>', NULL, '<p>Identifikasi besaran vektor dan arahnya, pilih metode (grafis/komponen) dan operasi yang sesuai, gambar diagram jika perlu, hitung hasilnya, lalu interpretasikan dalam konteks soal.</p>', NULL, '<p>Sesuaikan metode dengan konteks (perpindahan→penjumlahan, gaya→jajar genjang, posisi relatif→pengurangan), pilih representasi efisien (grafis/komponen), dan pastikan hasil logis.</p>', NULL, '2025-12-13 03:48:55', '2025-12-13 03:50:46'),
(220, 5, 328, '<p>saya jadi tahu tentang defini fungsi eksponen dan sifat sifatnya</p>', NULL, '<p>Baca soal dengan teliti, tentukan yang diketahui dan ditanyakan, ubah ke model fungsi eksponen, lalu tentukan rumusnya sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi sejak membaca soal, dengan memahami konteks masalah terlebih dahulu, menentukan informasi yang diketahui dan yang ditanyakan, lalu menyesuaikannya dengan konsep matematika yang tepat sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 03:49:21', '2025-12-13 03:51:30'),
(221, 6, 253, '<p>Yang saya ketahui dari materi yang telah dipelajari pada topik ini yaitu konsep dari vektor dan peranan vektor dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah-langkah yang saya lakukan yaitu: visualisasikan , Identifikasi dengan cara menentukan vektor yang diketahui dan yang dicari, pilih rumus , kemudian hitung, dan terakhir periksa pastikan jawaban logis dan sesuai dengan soal.</p><p><br></p>', NULL, '<p>Saya punya strategi ketika bisa mengidentifikasi jenis soalnya. Bagaimana caranya tergantung jenis soalnya, tapi yang paling penting yaitu pilih rumus yang tepat.</p><p><br></p><p><br></p>', NULL, '2025-12-13 03:53:27', '2025-12-13 04:05:11'),
(222, 4, 191, '<p>Fungsi kuadrat&nbsp;adalah konsep matematika yang menggambarkan hubungan antara dua besaran yang berubah secara tidak lurus atau melengkung. Bentuk grafiknya menyerupai lengkungan yang bisa terbuka ke atas atau ke bawah.</p>', NULL, '<p>Pahami konteks soal dan tentukan variabelnya. Buat model fungsi kuadrat yang sesuai.</p><p> Tentukan konsep yang diperlukan sebelum mulai menghitung.</p>', NULL, '<p>Strategi dimulai dengan memahami konteks soal dan tujuan yang dicari. Kemudian memodelkan masalah ke dalam fungsi kuadrat yang tepat. Terakhir, memilih konsep yang sesuai dan mengecek kembali hasilnya.</p>', NULL, '2025-12-13 03:53:34', '2025-12-13 04:07:23'),
(223, 4, 194, '<p>Saya mengetahui bahwa fungsi kuadrat berbentuk  dengan grafik parabola yang dapat digunakan untuk menentukan nilai maksimum atau minimum</p><p><br></p><p><br></p><p><br></p>', NULL, '<p>Sebelum menghitung, langkah yang dilakukan adalah memahami soal, menentukan diketahui dan ditanya, lalu mengubah soal cerita ke model fungsi kuadrat.</p>', NULL, '<p>Strategi penyelesaian dilakukan dengan menyesuaikan fungsi kuadrat dengan konteks masalah dan menafsirkan hasil sesuai situasi</p>', NULL, '2025-12-13 03:54:55', '2025-12-13 03:55:31'),
(224, 5, 282, '<p><span style=\"color: rgb(51, 65, 85);\">saya mengetahui fungsi eksponen melibatkan pemangkatan bilangan dengan pangkat bilangan lain yang lebih besar dari 1. Saya juga sudah memahami bahwa fungsi eksponen memiliki sifat-sifat tertentu.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama yaitu mengidentifikasi variabel dan hubungan antar variabel dalam soal cerita matematika tersebut. kedua, tentukan fungsi eksponen yang sesuai dengan informasi yang diberikan dalam soal.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Saya biasanya menggunakan strategi matematika ketika menyelesaikan soal dengan memahami konsep inti terlebih dahulu sebelum mencari solusi yang tepat. <span class=\"ql-cursor\">﻿</span></span></p>', NULL, '2025-12-13 03:55:51', '2025-12-13 04:00:29'),
(225, 5, 342, '<p>Saya memahami bahwa fungsi eksponen berbentuk (f(x)=n.a^x) dengan (a&gt;0) dan a tidak boleh =1. Fungsi ini menggambarkan pertumbuhan ((a&gt;1)) dan peluruhan ((0&lt;a&lt;1)).</p><p>Grafiknya memiliki asimtot (y=0).</p>', NULL, '<p>Membaca dan memahami soal dengan teliti, mencatat informasi yang diketahui serta yang ditanyakan, menentukan variabel dan model matematika yang sesuai (fungsi eksponen), lalu memilih strategi penyelesaian yang tepat sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menentukan strategi sejak awal dengan memahami konteks soal, memodelkannya ke bentuk matematika yang sesuai, lalu memilih cara penyelesaian yang tepat.</p>', NULL, '2025-12-13 03:56:59', '2025-12-13 03:58:19'),
(226, 4, 211, '<p><span style=\"color: rgb(51, 65, 85);\">Fungsi kuadrat merupakan jenis fungsi matematika yang dapat ditulis dalam bentuk f(x) = ax^2 + bx + c. Di sini, x merupakan variabel, sedangkan a, b, dan c adalah konstanta dengan a tidak sama dengan 0.</span></p>', NULL, '<p>Baca soal dengan teliti, tentukan diketahui dan ditanyakan, tetapkan variabel, buat model fungsi kuadrat, lalu tentukan strategi penyelesaiannya.</p>', NULL, '<p>Strateginya adalah memahami konteks soal, memodelkannya ke fungsi kuadrat, menentukan tujuan penyelesaian, memilih metode yang tepat, lalu mengecek kembali hasilnya.</p>', NULL, '2025-12-13 03:58:23', '2025-12-13 04:07:19'),
(227, 5, 280, '<p><strong>fungsi eksponen</strong>&nbsp;menggambarkan suatu proses perubahan yang terjadi secara sangat cepat, baik meningkat maupun menurun.&nbsp;</p>', NULL, '<ol><li>Memahami Konteks dan Identifikasi Variabel</li><li>Menyusun Model Matematika (Rumus)</li><li>Substitusi Nilai ke Dalam Rumus</li><li>Melakukan Perhitungan atau Logaritma</li><li>Interpretasi Hasil dan Penarikan Kesimpulan</li></ol>', NULL, '<p>untuk soal cerita, caranya dengan mengidentifikasi variabel (waktu, jumlah, laju), mengubah konteks menjadi bentuk aljabar, lalu gunakan sifat eksponen untuk mencari solusi, dan lakukan pengecekan kembali agar jawaban sesuai konteks masalah.&nbsp;</p>', NULL, '2025-12-13 04:05:48', '2025-12-13 04:14:34'),
(228, 3, 340, '<p>Saya sudah memahami perbandingan trigonometri (sin, cos, tan), hubungan sudut dan sisi pada segitiga siku-siku, serta penggunaannya untuk menentukan panjang sisi atau besar sudut.</p>', NULL, '<p>Membaca soal dengan teliti, menggambar sketsa jika perlu, menentukan sisi dan sudut yang diketahui serta ditanyakan, lalu memilih perbandingan trigonometri yang sesuai.</p>', NULL, '<p>trategi ditentukan setelah memahami konteks soal dan posisi sudut pada segitiga, kemudian memilih rumus trigonometri yang paling tepat agar penyelesaian menjadi lebih sederhana dan logis</p>', NULL, '2025-12-13 04:06:24', '2025-12-13 04:07:21'),
(229, 3, 326, '<p>Yang saya ketahui dari materi ini yaitu bahwa perbandingan trigonometri (sin, cos, tan) digunakan untuk menentukan hubungan sisi dan sudut pada segitiga siku-siku.</p>', NULL, '<p>Langkah sebelum menyelesaikan soal cerita matematika yaitu memahami soal, membuat sketsa, menentukan sudut dan sisi yang diketahui, lalu memilih perbandingan trigonometri yang tepat.</p><p><br></p>', NULL, '<p>Strategi penyelesaian soal:</p><p>Digunakan saat menghitung tinggi atau jarak. Caranya memahami konteks soal, memilih rumus yang sesuai, dan menafsirkan hasil sesuai keadaan nyata.</p>', NULL, '2025-12-13 04:08:47', '2025-12-13 04:10:12'),
(230, 1, 272, '<p>Materi eksponen membahas bilangan berpangkat, yaitu bentuk penulisan perkalian berulang dari suatu bilangan yang sama. Secara umum, eksponen dituliskan dalam bentuk a^n, dengan a sebagai bilangan pokok dan n sebagai pangkat.&nbsp;</p>', NULL, '<p>membaca soal dengan cermat, menentukan informasi yang diketahui dan ditanyakan, mengubah soal ke model matematika, memilih sifat eksponen yang sesuai, lalu menyusun langkah penyelesaian sebelum melakukan perhitungan akhir.</p>', NULL, '<p>Dengan memahami situasi pada soal, mengidentifikasi data yang diketahui dan yang ditanyakan, mengubahnya ke dalam bentuk matematika berpangkat, memilih sifat eksponen yang tepat, lalu menyelesaikannya secara runtut dan logis.</p>', NULL, '2025-12-13 04:09:21', '2025-12-13 04:17:54'),
(231, 3, 323, '<p>definisi perbandingan trigonometri  relasi sudut  setiap kuadran, aturan sinus cosinus, nilai sudut istimewa, teorema Pythagoras, hubungan sisi depan-samping-miring terhadap sudut, penerapannya untuk mengukur sesuatu yang sulit diukur langsung </p>', NULL, '<p>pahami soal, gambar sketsa dari informasi yang ada, identifikasi sudut dan sisi yang diketahui dan ditanya, menentukan sisi-sisinya, pilih perbandingan trigonometri yang tepat,baru hitung dan periksa kesesuaian hasil dengan konteks soal.</p><p><br></p>', NULL, '<p>buat sketsa gambar segitiga, tandai sisi-sisi yang diketahui dan yang dicari, identifikasi posisi sudutnya, perhatikan tinggi pengamat jika ada dalam soal dan pastikan hasil akhir masuk akal dengan konteks soal.</p>', NULL, '2025-12-13 04:10:31', '2025-12-13 04:14:18'),
(232, 4, 348, '<p>Fungsi kuadrat f(x) = ax² + bx + c, karakteristiknya (titik puncak, sumbu simetri, diskriminan), dan cara menentukan akar persamaan kuadrat (faktorisasi, melengkapi kuadrat sempurna, rumus abc).</p>', NULL, '<p>Identifikasi variabel dan informasi penting, modelkan ke bentuk fungsi kuadrat, tentukan apa yang ditanya (titik maksimum/minimum, akar, atau nilai tertentu).</p>', NULL, '<p>Buat tabel nilai atau grafik untuk visualisasi, gunakan rumus titik puncak untuk nilai maksimum/minimum, dan pilih metode yang sesuai untuk mencari akar jika diperlukan.</p>', NULL, '2025-12-13 04:11:40', '2025-12-13 04:12:10'),
(233, 6, 328, '<p>saya jadi tahu tentang definisi dan operasi vektor</p>', NULL, '<p>Sebelum menghitung, pahami dulu cerita soal dan tentukan apa yang diketahui serta yang ditanyakan, pilih arah atau sistem koordinat yang jelas, lalu gambarkan vektornya agar mudah menentukan langkah perhitungannya.</p>', NULL, '<p>Strategi penyelesaian ditentukan setelah memahami konteks soal, dengan mengaitkan informasi yang diberikan pada konsep matematika yang sesuai dan memilih langkah penyelesaian yang paling tepat.</p>', NULL, '2025-12-13 04:14:37', '2025-12-13 04:20:59'),
(234, 6, 282, '<p>vektor adalah besaran yang memiliki besar dan arah serta dapat dioperasikan dengan aturan-aturan khusus dalam aljabar. Perbedaan utama antara vektor dan skalar adalah keberadaan arah pada vektor.</p><p><br></p>', NULL, '<p>1.memahami informasi yang diberikan dalam soal tersebut dengan cermat dan mengidentifikasi apa yang diminta dalam soal.2.perlu diidentifikasi konsep vektor yang relevan dengan informasi dalam soal </p><p><br></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">1.saya akan membaca dan memahami dengan baik informasi yang diberikan dalam soal matematika.2.saya akan mencoba mengidentifikasi konsep-konsep matematika yang relevan.</span></p>', NULL, '2025-12-13 04:16:21', '2025-12-13 04:21:18'),
(235, 3, 350, '<p>Saya memahami bahwa trigonometri mempelajari hubungan sudut dan sisi segitiga siku-siku melalui perbandingan sinus, cosinus, dan tangen untuk menyelesaikan masalah jarak dan tinggi.</p>', NULL, '<p>Sebelum menghitung, saya memahami soal, menentukan data yang diketahui dan ditanya, membuat sketsa, serta memilih perbandingan trigonometri yang sesuai.</p>', NULL, '<p>Strategi penyelesaian dilakukan dengan menyesuaikan jenis perbandingan trigonometri dengan konteks masalah agar hasilnya tepat dan logis.</p>', NULL, '2025-12-13 04:17:50', '2025-12-13 04:18:28'),
(236, 5, 285, '<p><span style=\"color: rgb(51, 65, 85);\">fungsi eksponen melibatkan pangkat bilangan riil pada variabel. Selain itu, fungsi eksponen memiliki sifat-sifat khusus seperti pertumbuhan eksponensial dan nilai pangkat negatif.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama yang sebaiknya dilakukan adalah mengidentifikasi informasi yang diberikan dalam soal. Kemudian, pahami hubungan antara informasi dengan konsep fungsi eksponen.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">strategi untuk menyelesaikan soal matematika setelah memahami konsep dasarnya secara menyeluruh. Kemudian, saya mencari pola atau metode yang sesuai dengan jenis soal yang dihadapi.</span></p>', NULL, '2025-12-13 04:19:01', '2025-12-13 04:23:11'),
(237, 2, 209, '<p>Saya mengetahui bahwa sistem persamaan linear adalah kumpulan dua atau lebih persamaan yang memiliki dua variabel yang sama, dan sistem pertidaksamaan linear merupakan hubungan yang tidak sama dengan, seperti kurang dari, dan lebih dari</p>', NULL, '<p>Pertama, membaca dan memahami inti soal cerita. Kedua, mencatat informasi yang diketahui dan ditanyakan. Ketiga, mengubah soal dalam bentuk sistem persamaan atau pertidaksamaan yang sesuai. Keempat, melakukan proses perhitungan </p>', NULL, '<p>Menyesuaikan metode penyelesaian, misalnya subtitusi atau eliminasi untuk sistem persamaan, serta memperhatikan tanda pertidaksamaan pada sistem pertidaksamaan. Kemudian mengecek kembali jawaban apakah sesuai dengan konteks soal</p>', NULL, '2025-12-13 04:21:59', '2025-12-13 04:30:34'),
(238, 5, 348, '<p>Fungsi eksponen f(x) = n × aˣ, pertumbuhan eksponensial (a &gt; 1), peluruhan eksponensial (0 &lt; a &lt; 1), dan sifat-sifat grafik fungsi eksponen.</p>', NULL, '<p>Identifikasi nilai awal (n), rasio pertumbuhan/peluruhan (a), tentukan variabel waktu/fase (x), lalu modelkan ke fungsi eksponen yang sesuai.</p>', NULL, '<p>Gunakan pertumbuhan eksponensial untuk masalah yang berkembang (bakteri, populasi), dan peluruhan untuk masalah yang menurun (obat, radioaktif), lalu buat tabel atau grafik untuk visualisasi pola.</p>', NULL, '2025-12-13 04:22:46', '2025-12-13 04:23:22'),
(239, 6, 280, '<h3><br></h3><p><strong>Vektor</strong>&nbsp;adalah konsep matematika yang menggambarkan besaran yang memiliki&nbsp;<strong>arah dan besar (magnitude)</strong>.</p>', NULL, '<ol><li>Baca dan Identifikasi Besaran Vekto</li><li>Buat Model atau Visualisasi (Sketsa Gambar)&nbsp;</li><li>Pilih Operasi Vektor yang Sesuai</li><li>Hitung dan Periksa Kembali</li></ol><p><br></p>', NULL, '<ol><li>Strategi Geometris (Visual)</li><li>Strategi Aljabar (Komponen)</li><li>Strategi Perkalian Titik (Dot Product)</li><li>Strategi Perkalian Silang (Cross Product) - Khusus Vektor R3</li></ol>', NULL, '2025-12-13 04:28:19', '2025-12-13 04:38:15'),
(240, 5, 237, '<p>Saya mengetahui fungsi eksponen adalah fungsi yang variabelnya berada pada pangkat. Fungsi ini digunakan untuk menggambarkan pertumbuhan. Grafik fungsi eksponen dapat meningkat atau menurun tergantung nilai basisnya</p>', NULL, '<p>Membaca soal dengan teliti, memahami konteks soal, menentukan nilai awal dan laju pertumbuhan, memisalkan variabel, kemudian memodelkan masalah ke dalam bentuk fungsi eksponen</p>', NULL, '<p>Dengan melihat apakah masalah menunjukkan pertumbuhan atau penurunan</p>', NULL, '2025-12-13 04:29:03', '2025-12-13 04:35:42'),
(241, 4, 204, '<p>Definisi persamaan kuadrat, tiga cara untuk menentukan akar-akar (penyelesaian) persamaan kuadrat, fungsi kuadrat dalam x berbentuk f(x)=ax^2+bx+c, dan diskriminan (D): Nilai D=b^2-4ac.</p>', NULL, '<p>Yaitu dengan memahami konteks masalah, identifikasi variabel-variabel yang ada, tentukan apa yang ditanyakan oleh soal, lalu memilih cara penyelesaian yang paling efektif.</p><p><br></p>', NULL, '<p>Dengan cara mengidentifikasi serta memodelkan apa yang dminta soal.</p>', NULL, '2025-12-13 04:31:12', '2025-12-13 04:44:56'),
(242, 2, 249, '<p><span style=\"color: rgb(51, 65, 85);\">sistem persamaan linear adalah sekumpulan persamaan linear yang dipecahkan bersama-sama, sedangkan sistem pertidaksamaan linear adalah sekelompok pertidaksamaan linear yang diselesaikan secara bersamaan.</span></p>', NULL, '<p>Baca soal dengan teliti kemudian tentukan apa yang ditanyakan. Catat data yang diketahui Perhatikan kata kunci: \"jumlah\", \"selisih\", \"total\"Buat 2 persamaan linearContoh: 2x + 3y = 15.000 dan x + y = 6.000</p><p><br></p>', NULL, '<p>Strategi utama adalah menganalisis konteks soal, menentukan variabel yang tepat, membuat dua persamaan dari informasi yang diberikan, lalu memilih metode penyelesaian yang paling efisien</p>', NULL, '2025-12-13 04:32:35', '2025-12-13 04:33:43'),
(243, 6, 348, '<p>Vektor sebagai besaran berpangkal dan berarah, notasi vektor, operasi vektor (penjumlahan, pengurangan, perkalian skalar), dan metode penyelesaian (segitiga, jajar genjang, poligon, komponen).</p><p><br></p>', NULL, '<p>Identifikasi besaran vektor dan arahnya, tentukan operasi yang diperlukan, lalu pilih metode penyelesaian (grafis atau aljabar komponen) sesuai informasi yang diberikan.</p>', NULL, '<p>Gunakan metode grafis (segitiga/jajar genjang) untuk visualisasi perpindahan atau gaya, dan metode komponen untuk perhitungan presisi dengan koordinat, sesuaikan dengan konteks soal.</p>', NULL, '2025-12-13 04:33:14', '2025-12-13 04:33:50'),
(244, 6, 342, '<p>Saya memahami bahwa vektor adalah besaran yang memiliki besar dan arah, dapat direpresentasikan dalam beberapa cara, serta dapat dioperasikan dan digunakan dalam berbagai situasi sehari-hari seperti perpindahan dan arah gerak.</p>', NULL, '<p>Langkahnya adalah memahami arah dan besar perpindahan pada soal, menuliskan vektor yang diketahui, memodelkannya dalam bentuk vektor, lalu menentukan operasi vektor yang tepat sebelum menghitung hasil akhirnya.</p>', NULL, '<p>Saya menentukan strategi sejak membaca soal dengan mengidentifikasi arah dan besar vektor yang terlibat, lalu memilih representasi vektor (grafis atau komponen) dan operasi vektor yang sesuai dengan konteks masalah.</p>', NULL, '2025-12-13 04:34:27', '2025-12-13 04:36:34'),
(245, 2, 247, '<p>Materi ini membahas <strong>persamaan dan pertidaksamaan linear serta SPLDV</strong>, yaitu cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah, termasuk <strong>soal cerita</strong>.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel (misalnya xxx dan yyy), mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Strategi saya adalah memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar.</p>', NULL, '2025-12-13 04:36:45', '2025-12-13 04:44:24'),
(246, 2, 262, '<p>Materi ini membahas hubungan linear variabel dengan pangkat satu, ditandai dengan sama dengan (persamaan) atau ketidaksamaan (pertidaksamaan). Solusinya adalah nilai spesifik atau daerah penyelesaian.</p>', NULL, '<p>Langkah-langkah sebelum menghitung adalah: mengidentifikasi variabel yang belum diketahui, kemudian menerjemahkan semua informasi dari soal cerita menjadi model matematika (sistem persamaan atau pertidaksamaan).</p>', NULL, '<p>Strateginya adalah memilih metode yang sesuai konteks: untuk mencari nilai tunggal (persamaan), gunakan eliminasi atau substitusi. Untuk menentukan batasan atau daerah optimal (pertidaksamaan), gunakan metode grafik atau Program Linear.</p>', NULL, '2025-12-13 04:36:49', '2025-12-13 04:37:19'),
(247, 2, 329, '<p>yang saya ketahui yaitu Definisi Sistem Persamaan Linear, Penyelesaian Sistem Persamaan Linear, Sistem Pertidaksamaan Linear, serta contoh soal dan penyelesaiannya</p>', NULL, '<p>langkah langkah yang dapat dilakukan yaitu Membaca dan Memahami Konteks Soal lalu Menetapkan Variabel (Pemodelan Matematika) kemudian Membentuk Model Persamaan Linear selanjutnya Menghitung dan Menyelesaikannya </p>', NULL, '<p>Strategi untuk menyelesaikan soal pada topik Sistem Persamaan Linear (SPL) sesuai dengan konteks masalah matematika pada dasarnya terdiri dari dua fase besar: Fase Pemodelan (Analisis Soal Cerita) dan Fase Penyelesaian (Perhitungan).</p>', NULL, '2025-12-13 04:39:48', '2025-12-13 04:44:43'),
(248, 5, 194, '<p>Fungsi eksponen merupakan fungsi yang menunjukkan perubahan nilai yang sangat cepat, baik bertambah maupun berkurang, dengan laju perubahan yang semakin besar seiring waktu dan banyak diterapkan dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang dilakukan adalah memahami konteks soal cerita, menentukan besaran yang diketahui dan ditanyakan, menyusun model fungsi eksponen yang sesuai, kemudian melakukan perhitungan hingga memperoleh hasil akhir.</p>', NULL, '<p>Strategi penyelesaian dipilih ketika soal menunjukkan pola pertumbuhan atau peluruhan yang cepat, dengan menyesuaikan model eksponen berdasarkan konteks masalah agar solusi yang diperoleh tepat dan logis.</p>', NULL, '2025-12-13 04:40:41', '2025-12-13 04:41:22'),
(249, 4, 199, '<p>Setelah mempelajari materi ini, kita dapat mencampurkan dua metode dalam satu penyelesaian masalah </p>', NULL, '<p>Definisikan variabel yang ingin dioptimalkan, hitung nilai minimum dan maksimum </p>', NULL, '<p>Tahap pemodelan fungsi, menemukan nilai optimum, dan memastikan hasil yang masuk akal </p>', NULL, '2025-12-13 04:45:23', '2025-12-13 05:01:37'),
(250, 1, 198, '<p>Definisi eksponen dan sifat-sifatnya</p>', NULL, '<p>Membaca dan memahami soal dengan teliti, mengidentifikasi informasi yang diketahui, menentukan apa yang ditanyakan, mengenali pola atau rumus yang sesuai dan kemudian merencanakan strategi penyelesaian.</p>', NULL, '<p>Mengenali pola masalah terlebih dahulu, kemudian memilih rumus dan strategi yang tepat sesuai konteks cerita.​​​​​​​​​​​​​​​​</p>', NULL, '2025-12-13 04:50:11', '2025-12-13 05:02:06'),
(251, 1, 216, '<p>Saya dapat mengetahui sifat sifat eksponen</p>', NULL, '<p>langkah langakah</p><ol><li>Membaca soal dengan cermat</li><li>Menentukan informasi yang diketahui</li><li>Menentukan apa yang ditanyakan</li><li>Mengubah soal cerita ke dalam bentuk matematika</li><li>Merencanakan penyelesaian soal</li></ol>', NULL, '<p>Strategi untuk menyelesaikan soal pada topik ini yaitu dengan memahami konteks masalah, menentukan model matematika yang tepat, menyelesaikan soal sesuai dengan langkah langkah, setelah itu memeriksa kembali pengerjaan soal.</p>', NULL, '2025-12-13 04:51:15', '2025-12-13 04:57:23'),
(252, 3, 333, '<p>Saya memahami dasar trigonometri, perbandingan, sudut istimewa, kuadran, aturan sinus/cosinus, dan teorema Pythagoras.</p><p><br></p>', NULL, '<p>Pahami soal, identifikasi konsep relevan, tulis persamaan, selesaikan, dan periksa jawaban.</p><p><br></p>', NULL, '<p>Saat memahami konsep dasar, visualisasi masalah, analisis soal, dan berdasarkan pengalaman.</p><p><br></p>', NULL, '2025-12-13 04:55:12', '2025-12-13 04:56:08'),
(253, 1, 193, '<p>eksponen adalah bentuk penulisan ringkas untuk menotasikan perkalian bilangan berulang. eksponen disebut juga bilangan berpangkat.</p><p>selain itu, eksponen memiliki sifat-sifat penting yang perlu dipahami</p>', NULL, '<p>langkah pertama menelaah soal cerita untuk memahami sejauh mana kuantitas angka di jelaskan dalam soal. selanjutnya adalah menemukan basis dan pangkat, serta langkah terakhir adalah menotasikan semua informasi yang ditemukan dalam model matematika.</p>', NULL, '<p>strategi utama yang perlu dikuasai adlah menemukan konsep eksponensial dalam soal yang diberikan kemudian menyajikan dalam model matematika dengan memperhatikan sifat-sifat eksponen serta metode penyederhanaan eksponensial.</p>', NULL, '2025-12-13 04:55:27', '2025-12-13 05:12:25'),
(254, 2, 206, '<p>Konsep Persamaan linear dan penerapannya dalam kehidupan sehari-hari</p>', NULL, '<p>Langkah-langkah yang sebaiknnya dilakukan antara lain: Pertama, memahami soal dan tentukan apa yang ditanyakan oleh soal. Kedua, definisikan vaiabel. Ketiga, menyusun model matematika. Terakhir, tentukan metode penyelesaian.</p>', NULL, '<p>Strategi yang  saya miliki untuk menyelesaikan soal cerita pada topik ini adalah dengan berfokus pada pemodelan matematika yang akurat sesuai dengan konteks masalah.</p>', NULL, '2025-12-13 04:56:43', '2025-12-13 05:35:37'),
(255, 3, 328, '<p>saya jadi mengetahui tentang hubungan sudut dan sisi dari segitiga siku, perbandingan trigonometri untuk sudut lancip, dan hubungan antara sinus dan cosinus untuk sudut penyiku</p>', NULL, '<p>Pahami cerita soal, tentukan yang diketahui dan ditanyakan, buat sketsa gambar, lalu pilih konsep atau perbandingan trigonometri yang sesuai sebelum menghitung.</p>', NULL, '<p>Strategi penyelesaian ditentukan setelah memahami konteks soal, dengan mengidentifikasi informasi yang diketahui, apa yang ditanyakan, lalu memilih konsep dan langkah matematika yang paling sesuai.</p>', NULL, '2025-12-13 04:57:15', '2025-12-13 04:59:25'),
(256, 6, 237, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki besar dan arah. Vektor dapat dinyatakan dalam bentuk komponen, dan dapat dioperasikan dengan penjumlahan, pengurangan, serta perkalian dengan skalar</p>', NULL, '<p>Membaca soal dengan teliti, memahami konteks soal, menentukan vektor-vektor yang ada, menuliskan vektor dalam bentuk komponen, dan memilih operasi vektor yang sesuai sekaligus menentukan arah vektor</p>', NULL, '<p>Melihat konteks soal, apakah berkaitan dengan perpindahan, gaya, atau arah gerak. </p>', NULL, '2025-12-13 04:58:50', '2025-12-13 05:01:45'),
(257, 2, 268, '<p>Saya sudah memahami bentuk umum persamaan dan pertidaksamaan linear, serta cara menyusun SPLDV dan SPLTV dari soal cerita.</p>', NULL, '<p>Baca soal dengan teliti, tentukan variabel, ubah informasi ke bentuk persamaan, lalu pilih metode penyelesaian yang sesuai.</p><p><br></p>', NULL, '<p>Saya memilih strategi berdasarkan konteks soal, misalnya eliminasi jika persamaan mudah disederhanakan.</p>', NULL, '2025-12-13 04:59:14', '2025-12-13 05:00:20'),
(258, 1, 291, '<ol><li>Pengertian bilangan berpangkat (eksponen)</li><li> Contoh bilangan berpangkat</li><li>Sifat-sifat bilangan berpangkat positif</li><li>Bilangan berpangkat nol dan negatif</li><li>Bilangan berpangkat pecahan</li></ol><p><br></p>', NULL, '<p>Langkah yang dilakukan adalah memahami soal, menentukan informasi yang diketahui dan ditanyakan, mengubah cerita ke dalam bentuk eksponen, lalu menghitung hasil akhirnya setelah memastikan model yang dibuat sudah tepat.</p>', NULL, '<p>Strategi yang saya gunakan adalah memahami konteks soal, menentukan bilangan pokok dan pangkat dari pola yang ada, kemudian mengubahnya ke bentuk eksponen yang tepat sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 04:59:46', '2025-12-13 20:48:05'),
(259, 2, 214, '<p>Saya mengetahui definisi dari sistem persamaan linear, cara menentukan himpunan penyelesaian dari sistem persamaan linear dua variabel bisa dengan menggunakan metode seperti metode grafik, substiusi, dan eliminasi</p>', NULL, NULL, NULL, '<p>dentifikasi variabel dan terjemahkan cerita menjadi model matematika, membedakan persamaan atau pertidaksamaan berdasarkan kata kuncinya. Kemudian, selesaikan menggunakan metode eliminasi atau uji titik optimal sesuai tujuan masalah.</p>', NULL, '2025-12-13 05:01:49', '2025-12-13 09:48:37'),
(260, 2, 211, '<p><span style=\"color: rgb(51, 65, 85);\">Sistem persamaan linear adalah kumpulan persamaan linear yang saling berhubungan.</span></p>', NULL, '<p>Baca soal dengan teliti, tentukan diketahui dan ditanyakan, buat variabel, susun model matematika, lalu tentukan metode penyelesaiannya.</p>', NULL, '<p>Strateginya adalah memahami konteks soal terlebih dahulu, mengubahnya ke model matematika yang sesuai, menentukan tujuan penyelesaian, memilih metode yang tepat, lalu mengecek kembali hasilnya agar sesuai dengan konteks masalah.</p>', NULL, '2025-12-13 05:03:44', '2025-12-13 05:06:37'),
(261, 4, 242, '<p>Dari topik ini, saya sudah memahami pengertian persamaan dan fungsi kuadrat, bentuk umumnya, cara menentukan akar-akar persamaan kuadrat, serta cara menganalisis grafik fungsi kuadrat seperti titik puncak dan arah buka parabola.</p>', NULL, '<p>Membaca dan memahami soal, menentukan yang diketahui dan ditanyakan, memodelkan ke dalam persamaan atau fungsi kuadrat, lalu memilih metode penyelesaian yang sesuai sebelum menghitung.</p>', NULL, '<p>Strategi saya adalah menyesuaikan model matematika dengan konteks soal, memilih metode penyelesaian yang paling efektif (faktorisasi, melengkapkan kuadrat, atau rumus kuadrat), serta mengecek kembali hasil agar sesuai dengan makna soal.</p>', NULL, '2025-12-13 05:05:17', '2025-12-13 05:08:56'),
(262, 4, 262, '<p>Saya tahu fungsi kuadrat memiliki bentuk umum yang menghasilkan grafik parabola, penting untuk mencari titik tertinggi atau terendah, dan terkait dengan unsur-unsur seperti titik puncak, sumbu simetri, dan perpotongan sumbu.</p>', NULL, '<p>Langkahnya adalah memahami soal cerita, menentukan variabel, kemudian menerjemahkan cerita tersebut menjadi model matematika berupa rumus fungsi kuadrat, baru setelah itu kita putuskan fokus perhitungan pada titik puncak atau akar-akar.</p>', NULL, '<p>Strategi saya adalah mengidentifikasi apakah soal meminta nilai maksimum atau minimum (gunakan rumus titik puncak) atau menanyakan kapan hasilnya nol (gunakan rumus untuk mencari akar-akar).</p>', NULL, '2025-12-13 05:05:29', '2025-12-13 05:06:07'),
(263, 2, 324, '<p>materi sistem persamaan dan pertidakpersamaan linear mencakup SPLDV (dua variabel) dan SPLTV (tiga variabel) dengan bentuk umum menggunakan koefisien a,b, c dan konstanta d. metode penyelesaian meliputi grafik, eliminasi, substitusi,campuran</p>', NULL, '<p>membaca soal dengan cermat, menentukan variabel yang akan dicari (misal x,y,z) mengidentifikasi informasi yang diketahui dan ditanyakan, membuat model matemaikaberupa sistem persamaan atau pertidaksamaan</p>', NULL, '<p>untuk SPLTV gunakan eliminasi-substitusi atau metode sarrus, untuk sistem pertidaksamaan gambar grafik dan tentukan daerah penyelesaian dengan uji titik, gunakanstrategi tebak-perbaiki jika diperlukan</p>', NULL, '2025-12-13 05:07:02', '2025-12-13 05:10:14');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(264, 6, 194, '<p>Vektor adalah besaran yang memiliki arah dan besar, serta dapat direpresentasikan dalam berbagai bentuk. Vektor digunakan untuk menjelaskan gerak, gaya, dan arah dalam kehidupan sehari-hari dan bidang teknologi.</p>', NULL, '<p>Langkah yang dilakukan yaitu memahami soal cerita, menentukan besaran vektor yang diketahui dan ditanyakan, memilih operasi vektor yang sesuai, lalu melakukan perhitungan secara sistematis.</p>', NULL, '<p>Strategi digunakan sesuai konteks masalah, misalnya memakai diagram vektor untuk soal arah dan gerak, atau komponen vektor untuk soal yang melibatkan sumbu koordinat.</p>', NULL, '2025-12-13 05:09:40', '2025-12-13 05:10:35'),
(265, 4, 273, '<p>saya dapat memahami dengan baik cara menyelesaikan soal persamaan kuadrat dengan menggunakan tiga cara yaitu: cara faktorial,melengkapkan kuadrat,dan menggunakan rumus kuadrat (rumus ABC).</p>', NULL, '<p>Yaitu pahami dan analisis soaal cerita,rumuskan ke model matematika,selesaikan persamaan/fungsi dan interpretasi hasil akhir</p>', NULL, '<p>yaitu dengan cara memahami masalah dari soal tersebut,memformulasikan model matematika,menyelesaikan model matematika,lalu tafsirkan hasilnya.</p>', NULL, '2025-12-13 05:09:59', '2025-12-13 05:21:49'),
(266, 3, 342, '<p>Saya memahami bahwa trigonometri mempelajari hubungan antara sudut dan sisi pada segitiga siku-siku. Perbandingan sinus, cosinus, dan tangen digunakan untuk mencari sisi atau sudut yang belum diketahui. </p>', NULL, '<p>Membaca dan memahami soal dengan teliti, mengidentifikasi sudut dan sisi yang diketahui, menggambarkan sketsa segitiga, menentukan perbandingan trigonometri yang sesuai, lalu memastikan model sudah benar sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menentukan strategi sejak awal setelah membaca soal dengan memahami konteks permasalahan, membuat sketsa segitiga, lalu memilih perbandingan trigonometri yang sesuai agar penyelesaiannya tepat.</p>', NULL, '2025-12-13 05:15:20', '2025-12-13 05:16:58'),
(267, 1, 254, '<p>yang saya ketahui dari materi ini adalah tentang definisi dan sifat-sifat Ekspresi Eksponen</p>', NULL, '<p>yang pertama saya pahami soal tersebut setelah itu saya menerapkan sifat-sifat eksponen tersebut untuk menyelesaikan soal tersebut dengan menghitung dengan cermat, setelat terjawab saya melihat kembali jawaban yang sudah saya kerjakan</p>', NULL, '<p>pertama saya identifikasi dulu jenis soalnya apa, <span style=\"color: rgba(0, 0, 0, 0.85);\">apakah soal tersebut melibatkan penyederhanaan ekspresi, pemecahan persamaan, atau aplikasi eksponen dalam konteks tertentu</span></p>', NULL, '2025-12-13 05:15:37', '2025-12-13 05:31:13'),
(268, 6, 285, '<p><span style=\"color: rgb(51, 65, 85);\">saya sudah memahami bahwa vektor adalah besaran yang memiliki besar dan arah. Vektor dapat direpresentasikan dengan panah dan memiliki operasi seperti penjumlahan dan pengurangan. </span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">langkah pertama adalah mengidentifikasi vektor yang terlibat dalam soal cerita, kemudian menentukan operasi vektor yang diperlukan sebelum menghitung hasil akhirnya.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Saat menyelesaikan soal matematika, saya biasanya mulai dengan memahami konsep dasar yang terkait, lalu mencari pola-pola yang mungkin ada untuk menemukan solusi yang tepat.</span></p>', NULL, '2025-12-13 05:16:19', '2025-12-13 05:21:24'),
(269, 3, 237, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi-sisi segitiga, khususnya segitiga siku-siku</p>', NULL, '<p>Membaca soal dengan teliti, memahami konteks soal, menggambar sketsa segitiga, menentukan sudut dan sisi yang diketahui, dan memilih perbandingan trigonometri yang sesuai</p><p><br></p>', NULL, '<p>Dengan menentukan apa yang diketahui dan apa yang ditanyakan pada soal</p>', NULL, '2025-12-13 05:16:56', '2025-12-13 05:18:46'),
(270, 2, 261, '<p>Pengertian Sistem Persamaan Linear Dua Variabel, bentuk bentuk umum persamaan linear dua variabel langkah langkah metode subtitusi , langkah langkah metode eliminasi, ,metode campuran di mana menggambungkan metode subtitusi dan eliminasi</p><p> </p>', NULL, '<p>langkah langkah nya yaitu membaca soal  dengan teliti , pahami konteks cerita mensubtitusikan  ke persamaan lain dan menyelesaikan persamaan </p>', NULL, '<p>yaitu baca soal dengan teliti dan pahami seperti apa soal nya menentukan variabel yang tepat , menentukan persamaan yang akan di subtitusikan melakukan subtitusi  secara sistematis memeriksa kembali jawaban untuk mencegah adanya kesalahan</p>', NULL, '2025-12-13 05:17:59', '2025-12-13 05:26:11'),
(271, 2, 345, '<p>Saya mengetahui SPLDV/SPLTV, jenis solusi (1, 0, banyak), metode penyelesaian (Grafik, Eliminasi, Substitusi, Campuran, Sarrus), dan SPtL (Daerah Penyelesaian/DP) untuk optimasi/batasan.</p>', NULL, '<p>1. Pahami Soal. 2. Definisikan Variabel. 3. Buat Model Matematika (persamaan/pertidaksamaan). 4. Validasi Model (<img src=\"//:0\" height=\"22\" width=\"39\">).</p>', NULL, '<p>Yaitu dengan melihat bahwa <strong>SPLDV:</strong> Campuran. <strong>SPLTV:</strong> Eliminasi-Substitusi Bertingkat. <strong>SPtL:</strong> Grafik &amp; Uji Titik. <strong>Optimasi:</strong> Uji Titik Pojok.</p>', NULL, '2025-12-13 05:22:30', '2025-12-13 05:25:51'),
(272, 3, 344, '<p>dapat mengetehui apa itu trigonometri dan sifat\" nya</p>', NULL, '<p>dengan mengamati dan menganalisis soal tersebut</p>', NULL, '<p>ketika kita mendaptkan soal yang cukup menantang dan coba menyelesaikanya</p>', NULL, '2025-12-13 05:23:18', '2025-12-13 05:25:33'),
(273, 5, 211, '<p><span style=\"color: rgb(51, 65, 85);\">&nbsp;Fungsi eksponen merupakan fungsi matematika yang bentuk umumnya adalah f(x) = a^x, di mana a adalah bilangan riil positif yang disebut sebagai basis eksponen.&nbsp;</span></p>', NULL, '<p>Langkah-langkahnya yaitu membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, menyusun model matematika sesuai konteks soal, lalu memilih metode penyelesaian sebelum melakukan perhitungan.</p>', NULL, '<p>Langkah-langkah tersebut sudah tepat karena membantu memahami soal, menyusun model, dan memilih metode yang sesuai sebelum menghitung.</p>', NULL, '2025-12-13 05:24:51', '2025-12-13 05:27:34'),
(274, 5, 320, '<p>Yang sudah saya ketahui yaitu tentang konsep eksponen dan penerapannya dalam persamaan serta fungsi eksponensial. Saya juga memahami bentuk grafik eksponensial dan maknanya. Materi ini membantu memahami masalah pertumbuhan dan peluruhan</p>', NULL, '<p>Langkah awal adalah memahami isi soal secara menyeluruh. Kemudian menentukan apa yang diketahui dan yang ditanyakan. Setelah itu, soal diubah ke bentuk matematika sebelum dihitung.</p>', NULL, '<p>Strategi dibuat setelah memahami tujuan soal. Strategi disesuaikan dengan jenis permasalahan yang diberikan. Hal ini membantu penyelesaian menjadi lebih tepat dan terarah.</p>', NULL, '2025-12-13 05:26:46', '2025-12-13 05:27:39'),
(275, 3, 330, '<p>Saya telah mempelajari perbandingan trigonometri, relasi sudut kuadran, sudut istimewa, Aturan Sinus, dan Aturan Cosinus untuk memecahkan masalah segitiga</p>', NULL, '<p>Untuk menyelesaikan soal cerita trigonometri, langkah-langkahnya adalah:Identifikasi segitiga siku-siku dan sudut yang diketahui,Tentukan sisi depan, samping, dan miring, serta Pilih perbandingan trigonometri (sin, cos, tan) yang sesuai</p><p><br></p>', NULL, '<p>Saya akan menggunakan strategi spesifik ketika masalah tersebut melibatkan hubungan sudut dan sisi segitiga , seperti untuk mengukur tinggi atau jarak.</p>', NULL, '2025-12-13 05:27:20', '2025-12-13 05:30:15'),
(276, 3, 194, '<p>perbandingan trigonometri (sin, cos, dan tan) menjelaskan hubungan antara sudut dan panjang sisi pada segitiga siku-siku serta dapat digunakan untuk menentukan sudut atau panjang sisi dalam berbagai masalah nyata.</p>', NULL, '<p>Langkah-langkahnya yaitu memahami masalah, menggambar sketsa segitiga, menentukan sisi yang diketahui dan ditanya, memilih perbandingan trigonometri yang sesuai, lalu melakukan perhitungan.</p><p>.</p>', NULL, '<p>Strategi digunakan ketika soal melibatkan sudut dan jarak atau tinggi, dengan menyesuaikan perbandingan trigonometri yang tepat berdasarkan informasi yang diketahui dalam konteks masalah</p>', NULL, '2025-12-13 05:35:30', '2025-12-13 05:36:12'),
(277, 2, 216, '<p>konsep dasar sistem persamaan linear dan pertidaksamaan linear</p>', NULL, '<p>langkah-langkah</p><ol><li>memahami dengan baik informasi yang diberikan soal</li><li>merumuskan persamaan atau pertidaksamaan berdasarkan informasi yang diberikan soal</li><li>menyelesaikan sistem persamaan atau pertidaksamaan tersebut</li></ol>', NULL, '<p>Untuk menyelesaikan soal pertama tama kita harus memahami konsep dasarnya, lalu mengidentifikasi sistem persamaan atau pertidaksamaan yang ada, kemudian gunakan metode eliminasi atau substitusi untuk mencari solusinya</p>', NULL, '2025-12-13 05:36:43', '2025-12-13 06:56:58'),
(278, 3, 280, '<p>Perbandingan trigonometri adalah perbandingan antara panjang sisi-sisi pada segitiga siku-siku yang dihubungkan dengan besar sudutnya. perbandingan ini menghasilan enam fungsi dasar yaitu sinus, kosinus, tangen, cosecan, secan, dan kotangen.</p>', NULL, '<ol><li>Visualisasikan Soal dengan Gambar &nbsp;</li><li>Identifikasi Variabel yang Diketahui dan Ditanyakan</li><li>Pilih Rumus Trigonometri yang Tepat</li><li>Lakukan Perhitungan Matematis</li><li>Cek Kembali Jawaban</li></ol>', NULL, '<p>Strategi untuk menyelesaikan masalah matematika, khususnya trigonometri, harus disusun berdasarkan identifikasi tipe masalah dan pemanfaatan alat bantu visual.</p>', NULL, '2025-12-13 05:38:04', '2025-12-13 05:46:11'),
(279, 1, 247, '<p>Materi ini membahas perkalian berulang atau bilangan berpangkat, yaitu cara menuliskan perkalian dengan faktor yang sama dalam bentuk pangkat untuk mempermudah perhitungan.</p>', NULL, '<p>Langkah-langkahnya adalah membaca dan memahami soal, menentukan diketahui dan ditanyakan, mengubah perkalian berulang ke bentuk pangkat, lalu menyelesaikan perhitungan.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, lalu mengubah perkalian berulang ke bentuk pangkat agar perhitungan lebih mudah dan hasilnya tepat.</p>', NULL, '2025-12-13 05:38:51', '2025-12-13 05:40:38'),
(280, 1, 309, '<p>Saya mengetahui bahwa bilangan berpangkat adalah bentuk perkalian berulang yang ditulis aⁿ, dengan a sebagai bilangan pokok dan n sebagai pangkat, serta memiliki sifat-sifat eksponen.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, mengubah ke bentuk eksponen, lalu menggunakan sifat eksponen yang sesuai.</p>', NULL, '<p>Menentukan pola masalah, memodelkannya ke bentuk eksponen, dan menyelesaikannya dengan sifat-sifat eksponen.</p>', NULL, '2025-12-13 05:43:02', '2025-12-13 19:05:54'),
(281, 1, 243, '<p><span style=\"color: rgb(51, 65, 85);\">kita belajar mengenai cara menyatakan suatu bilangan atau variabel yang dipangkatkan dengan bilangan eksponen tertentu</span></p>', NULL, '<p>memahami permasalahan dalam cerita, melihat sifat apa yang cocok dengan soal, mengerjakan sesuai dengan langkah langkahnya, menghitung hasil akhirnya.</p><p><br></p>', NULL, '<p>strategi yang saya lakukan adalah mengetahui dan memahami soal yang diberikan kemudian mencari cara paling cepat dan mudah dengan sifat-sifat yang ada untuk menyelesaikan permasalahan tersebut.</p>', NULL, '2025-12-13 05:44:32', '2025-12-13 20:41:30'),
(282, 5, 199, '<p>Mengetahui bahwa eksponen adalah bilangan yang dikalikan dengan bilangan yang sama dan dilakukan secara berulang-ulang tergantung dari nilainya pangkatnya. </p>', NULL, '<p>Membuat perencanaan terlebih dahulu dengan memahami konsep dan rumus yang sesuai dengan model soal, mensubtitusi nilai ke rumus dan tarik kesimpulan pada hasil akhir </p>', NULL, '<p>Strategi eksponensial diterapkan ketika laju perubahan suatu kuantitas proporsional terhadap kuantitas itu sendiri atau ketika perubahan terjadi secara berlipat ganda (multiplikatif) per periode waktu, bukan secara tetap (aditif).</p>', NULL, '2025-12-13 05:45:22', '2025-12-13 05:49:40'),
(283, 5, 191, '<p>Fungsi eksponen&nbsp;menggambarkan suatu proses perubahan yang terjadi secara sangat cepat, baik meningkat maupun menurun. Dalam fungsi ini, suatu nilai bertambah atau berkurang dengan kecepatan yang semakin lama semakin besar</p>', NULL, '<p>Baca soal dengan teliti, Tentukan angka atau variabel, lalu buat persamaan eksponennya.</p><p>Pikirkan cara menghitungnya sebelum langsung menjawab.</p>', NULL, '<p>Strategi muncul saat saya memahami soal, memilih metode yang sesuai, lalu menyusun langkah-langkah hitung secara sistematis hingga hasilnya masuk akal.</p>', NULL, '2025-12-13 05:46:27', '2025-12-13 05:49:32'),
(284, 1, 210, '<p>Saya mengetahui bahwa eksponen adalah bentuk perkalian berulang. Saya juga memahami sifat-sifat eksponen yang digunakan untuk menyederhanakan perhitungan.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, mengubah ke bentuk eksponen, lalu menghitung sesuai sifat eksponen.</p>', NULL, '<p>Saya menyelesaikan soal dengan memahami konteks masalah, menentukan model matematika yang sesuai (eksponen), lalu menggunakan sifat eksponen yang tepat untuk mendapatkan hasilnya.</p>', NULL, '2025-12-13 05:50:10', '2025-12-13 05:53:29'),
(285, 5, 262, '<p>Fungsi Eksponen adalah perpangkatan dengan variabel di pangkatnya. Fungsinya untuk memodelkan pertumbuhan dan peluruhan. Grafiknya selalu di atas sumbu horizontal dan melewati titik nol koma satu.</p>', NULL, '<p>Pahami masalah dan tentukan apa yang dicari. Pilih model eksponen yang tepat apakah pertumbuhan atau peluruhan. Tuliskan nilai-nilai yang diketahui seperti nilai awal, laju, dan waktu. Susun persamaannya lalu mulai hitung</p>', NULL, '<p>Strategi muncul saat mengidentifikasi konteks masalah. Misalnya pertumbuhan penduduk butuh model pertumbuhan. Peluruhan radioaktif butuh model peluruhan dengan waktu paruh. Strategi ini membantu memilih rumus dan variabel yang benar untuk dihitung.</p>', NULL, '2025-12-13 05:50:32', '2025-12-13 05:50:57'),
(286, 1, 215, '<p>	Berdasarkan materi aljabar dan fungsi pada topik eksponen, saya dapat mengetahui dasar-dasarnya seperti perkalian berulang menjadi bentuk pangkat dan sifat-sifat eksponen.</p>', NULL, '<ol><li>melihat pola datanya</li><li>menuliskan dalam bentuk eksponen menggunakan sifat-sifat eksponen yang sesuai</li><li>sebelum mendapatkan jawaban akhir, kita dapat mengecek ulang dengan menghitung manual atau menggunakan tabel </li></ol>', NULL, '<p>menghubungkan langsung pada konteks masalahnya menggunakan pendekatan kontekstual dengan mangamati data nyata, lalu kita dapat terapkan sifat eksponen.</p>', NULL, '2025-12-13 05:52:59', '2025-12-13 06:14:17'),
(287, 5, 257, '<p>Fungsi eksponensial adalah fungsi yang variabelnya berada pada pangkat. Ada dua jenis utama, yaitu pertumbuhan eksponensial dan peluruhan eksponensial.</p>', NULL, '<p>Membaca soal dengan cermat, menentukan besaran awal, mengidentifikasi rasio perubahan pada setiap periode waktu, menyusun satuan waktu atau fase, dan kemudian menyusun model matematika dalam bentuk fungsi eksponensial yang sesuai.</p>', NULL, '<p>Sesuaikan model fungsi dengan situasi nyata, kaitkan makna variabel x dengan konteks, kemudian cek kembali hasil perhitungan.</p>', NULL, '2025-12-13 05:53:39', '2025-12-13 06:07:54'),
(288, 6, 211, '<p><span style=\"color: rgb(51, 65, 85);\">Vektor memiliki sifat-sifat seperti penjumlahan vektor, pengurangan vektor, dan perkalian skalar.</span></p>', NULL, '<p>Langkah-langkahnya yaitu membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, menyusun model matematika sesuai konteks soal, lalu memilih metode penyelesaian sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi ditentukan sejak memahami soal, dengan mengidentifikasi informasi penting, memilih konsep yang sesuai, lalu menyusun langkah penyelesaian yang tepat.</p>', NULL, '2025-12-13 05:58:09', '2025-12-13 06:01:12'),
(289, 1, 241, '<p>Yang saya ketahui dari topik ini ialah</p><ol><li>Definisi bilangan Eksponen</li><li>Sifat-sifat bilangan Eksponen</li><li>Cara menyederhanakan bilangan Eksponen</li></ol>', NULL, '<p>identifikasi bentuk eksponen yang muncul dalam cerita, catat angka dan variabel tentukan sifat eksponen, buat persamaan matematika, gunakan sifat eksponen untuk menyederhanakan, periksa kembali hasil penyederhanaan, hitung hasil akhir</p><p><br></p>', NULL, '<p>Strategi yang saya lakukan adalah mengetahui dan memahami soal yang diberikan kemudian mencari cara paling cepat dan mudah dengan sifat-sifat yang ada untuk menyelesaikan permasalahan tersebut.</p>', NULL, '2025-12-13 06:07:33', '2025-12-13 06:32:55'),
(290, 1, 202, '<p>yang saya ketahui dari topik ini ialah :</p><ol><li>Definisi bilangan eksponen </li><li>Sifat sifat eksponen </li><li>cara menyederhanakan bilangan eksponen</li></ol>', NULL, '<ol><li>Identifikasi bentuk eksponen</li><li>Tentukan sifat eksponen yang sesuai</li><li>Sederhanakan pangkat terlebih dahulu</li><li>Ubah ke bentuk eksponen positif&nbsp;</li><li>Hitung nilai akhir (jika diminta)</li></ol>', NULL, '<ol><li>Pahami konteks soal</li><li>Ubah ke model eksponen</li><li>Kenali pola eksponen</li><li>Pilih sifat eksponen yang tepat</li><li>Sederhanakan pangkatnya</li><li>Sesuaikan dengan konteks</li><li>Hitung &amp; simpulkan</li></ol>', NULL, '2025-12-13 06:09:42', '2025-12-13 06:32:44'),
(291, 3, 196, '<p>Perbandingan trigonometri meliputi sin, cos, tan pada segitiga siku-siku, Trigonometri digunakan untuk mencari sudut atau sisi pada segitiga, serta aplikasi praktis seperti tinggi bangunan, jarak, dan navigasi.</p>', NULL, '<p>Gambar sketsa segitiga siku-siku, identifikasi sudut yang diketahui dan ditanya, tentukan sisi depan/samping/miring relatif terhadap sudut tersebut. Pilih rumus trigonometri yang tepat (sin/cos/tan), baru kemudian substitusi nilai.</p>', NULL, '<p>Gunakan sin/cos saat melibatkan sisi miring, gunakan tan saat hanya ada sisi tegak dan mendatar. Untuk soal ketinggian/jarak: buat sketsa, tentukan sudut elevasi/depresi, lalu pilih perbandingan yang sesuai dengan data yang ada.</p>', NULL, '2025-12-13 06:12:24', '2025-12-13 06:14:47'),
(292, 4, 240, '<p>Fungsi kuadrat digunakan untuk memodelkan berbagai fenomena alam seperti lintasan peluru, bentuk jembatan, atau masalah optimalisasi.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '<p><strong>Pahami soal, Buat model matematika. </strong>Setelah kedua langkah ini selesai, baru lakukan perhitungan untuk menemukan hasil akhir.</p>', NULL, '<p>Identifikasi jenis masalah dan pilih metode yang tepat.</p>', NULL, '2025-12-13 06:16:33', '2025-12-13 06:29:24'),
(293, 6, 262, '<p>Materi vektor meliputi definisi, komponen, panjang, dan operasi dasarnya: penjumlahan, pengurangan, perkalian skalar, dan perkalian titik atau silang . Vektor dipakai untuk menyatakan besaran berarah seperti posisi dan gaya.</p>', NULL, '<p>Langkah awal adalah mengubah soal cerita menjadi model vektor, menentukan komponen yang diketahui. Pilih operasi vektor yang tepat (tambah, kurang, kali titik, kali silang) untuk menyusun persamaan, lalu hitung.</p>', NULL, '<p>Strategi dipilih setelah memahami konteks masalah. Jika mencari perpindahan total, gunakan penjumlahan vektor. Jika mencari sudut atau proyeksi, gunakan perkalian titik. </p>', NULL, '2025-12-13 06:17:13', '2025-12-13 06:18:57'),
(294, 2, 272, '<p>Materi ini membahas hubungan beberapa persamaan atau pertidaksamaan untuk menentukan nilai atau himpunan penyelesaian variabel, yang dapat diselesaikan dengan metode substitusi, eliminasi, atau grafik dan digunakan dalam masalah sehari-hari.</p>', NULL, '<p>Langkah-langkahnya adalah membaca soal dengan cermat, menentukan variabel, menuliskan persamaan atau pertidaksamaan sesuai cerita, memilih metode penyelesaian yang tepat, lalu menyusun langkah perhitungan sebelum mencari hasil akhir.</p>', NULL, '<p>Memahami konteks soal, menentukan variabel yang tepat, memodelkan masalah ke dalam sistem persamaan atau pertidaksamaan linear, memilih metode penyelesaian yang sesuai, lalu menafsirkan hasil sesuai dengan situasi pada soal.</p>', NULL, '2025-12-13 06:18:49', '2025-12-13 06:20:23'),
(295, 5, 324, '<p>materi fungsi eksponen berbentuk f(x)=n*a^x dengan a&gt;0, a tidak sam dengan nol. ada dua jenis pertumbuhan eksponen (nilai meningkat, contoh pertumbuhan bakteri) dan peluruhan eksponen (nilai menurun)</p>', NULL, '<p>membaca soal dan mengidentifikasi jenis masalah (pertumbuhan/peluruhan), menentukan nilai awal (n), menentukan rasio perubahan (a), membuat model fungsi eksponen f(x)=n *a^x, menentukan variabel x (waktu/fase)</p>', NULL, '<p>untuk masalah pertumbuhan (bakteri, investasi) gunakan a&gt;1, untuk peluruhan (obat, radioakti) gunakan 0&lt;a&lt;1, buat tabelpola perubahan beberapa fase awal untuk menemukan model, gambar grafik</p>', NULL, '2025-12-13 06:19:39', '2025-12-13 06:26:39'),
(296, 1, 318, '<p>1.Pengertian eksponen (bilangan berpangkat)</p><p>2.Bentuk-bentuk eksponen</p><p>3.Sifat-sifat eksponen</p><p>4.Penerapan eksponen dalam masalah kontekstual</p>', NULL, '<p><br></p><p>Mengidentifikasi pola eksponen pada soal.</p><p>Mengubah soal cerita ke model matematika.</p><p>Memastikan model sudah sesuai dengan soal.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, menentukan konsep yang digunakan, memodelkan masalah ke bentuk matematika, lalu menyelesaikannya sesuai aturan yang tepat dan menafsirkan hasilnya.</p>', NULL, '2025-12-13 06:21:40', '2025-12-13 22:46:51'),
(297, 3, 253, '<p>Yang saya sudah ketahui dari materi yang telah dipelajari pada topik ini yaitu konsep dari perbandingan trigonomteri dan juga penerapannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah-langkah yang saya lakukan yaitu, visualisasikan, pilih rumus, substitusi, sederhanakan dan menyelesaikan persamaan dengan baik dan benar.</p><p><br></p>', NULL, '<p>Saya punya strategi ketika bisa mengidentifikasi jenis segitiganya. Bagaimana caranya tergantung jenis soalnya, tapi intinya adalah pilih rumus yang tepat.</p>', NULL, '2025-12-13 06:26:20', '2025-12-13 06:37:44'),
(298, 6, 286, '<p>definisi vektor dan penerapannya dalam kehidupan sehari - hari</p>', NULL, '<p>Langkahnya adalah memahami konteks soal, menentukan besaran dan arah vektor yang diketahui serta ditanyakan, memodelkannya dalam bentuk vektor atau gambar, lalu menyusun rencana penyelesaian sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Strategi mulai ditentukan sejak membaca soal dengan memahami konteks masalah, lalu memilih konsep matematika yang sesuai dan menyusun langkah penyelesaian secara logis.</p><p><br></p>', NULL, '2025-12-13 06:27:00', '2025-12-13 21:39:51'),
(299, 4, 272, '<p>Dari topik ini diketahui cara menentukan arah buka parabola, titik puncak, sumbu simetri, serta titik potong dengan sumbu-sumbu koordinat. Fungsi kuadrat juga digunakan untuk memodelkan berbagai masalah dalam kehidupan sehari-hari.</p>', NULL, '<p>Membaca soal dengan teliti, memahami konteks masalah, menentukan variabel yang sesuai, memodelkan soal ke dalam bentuk fungsi kuadrat,lalu menyusun rencana penyelesaian sebelum melakukan perhitungan hasil akhir.</p>', NULL, '<p>Memahami konteks masalah, menentukan variabel yang tepat, memodelkan situasi ke dalam bentuk fungsi kuadrat, menganalisis grafik atau unsur fungsi seperti titik puncak dan akar, lalu menafsirkan hasil sesuai dengan permasalahan yang diberikan.</p>', NULL, '2025-12-13 06:27:05', '2025-12-13 06:30:18'),
(300, 2, 270, '<p><span style=\"color: rgb(51, 65, 85);\">adalah kumpulan dua atau lebih persamaan linear yang memiliki variabel yang sama. Tujuan utamanya adalah mencari nilai variabel yang memenuhi semua persamaan secara bersamaan.&nbsp;</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Yang baik untuk dilakukan adalah memahami masalah secara keseluruhan. Identifikasi informasi yang diberikan dalam soal cerita dan apa yang diminta atau ditanyakan.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">identifikasi metode yang tepat untuk menyelesaikan masalah tersebut.</span></p>', NULL, '2025-12-13 06:29:40', '2025-12-13 06:51:35'),
(301, 2, 279, '<p>yang dapat saya ketahui dari topik ini adalah, apa itu SPLDV, bagaimana bentuk yang membedakan persamaan dan pertidaksamaan, serta bagaiaman untuk menyelesaikannya.</p>', NULL, '<p>analisis soal, bentuk soalnya, apa yang diketahui dan ditanyakan, kerjakan sesuai prosedur untuk bentuk soal yang ditanyakan, tentukan nilai akhir.</p>', NULL, '<p>strategi yang bisa saya berikan yaitu ketika mengerjakan soal kalau bisa kerja bersama teman-teman, karena bisa saja ada teman yang lebih paham tentang topik ini, kalau masih kesulitan bisa bertanya kepada guru.</p>', NULL, '2025-12-13 06:32:33', '2025-12-13 06:42:25'),
(302, 2, 198, '<p>Definisinya, penerapannya dalam kehidupan sehari-hari serta contoh soalnya </p>', NULL, '<p>Membaca dan memahami soal, identifikasi informasi diketahui dan ditanyakan, tetapkan variabel, kenali jenis masalah (persamaan atau pertidaksamaan), buat model matematika, lalu hitung dan maknai hasilnya sesuai konteks soal.​​​​​​​​​​​​​​​​</p>', NULL, '<p>Mengenali pola dan konteks masalah terlebih dahulu, kemudian memilih strategi pemodelan yang tepat sesuai soal.​​​​​​​​​​​​​​​​</p>', NULL, '2025-12-13 06:32:33', '2025-12-13 06:41:50'),
(303, 6, 191, '<p>Vektor&nbsp;adalah konsep matematika yang menggambarkan besaran yang memiliki&nbsp;arah dan besar (magnitude). Artinya, vektor tidak hanya menunjukkan seberapa banyak sesuatu berubah, tetapi juga ke mana arah perubahannya.</p>', NULL, '<p>Baca dan pahami soal ,Tentukan representasi vektor ,Gambar vektor jika perlu, dan tuliskan dalam bentuk koordinat atau panah. Pilih operasi yang tepat, tentukan apakah harus menjumlahkan, mengurangkan, atau mengalikan . lalu selesaikan perhitungan</p>', NULL, '<p>Strategi dibuat setelah memahami soal, dengan menganalisis informasi, memilih representasi yang tepat, dan menentukan langkah penyelesaian agar perhitungan terarah dan hasil logis.</p><p><br></p>', NULL, '2025-12-13 06:33:03', '2025-12-13 06:37:36'),
(304, 2, 204, '<p>Yaitu persamaan dan pertidaksamaan linear serta SPLDV, cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah atau soal cerita.</p>', NULL, '<p>Yaitu dengan membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, lalu mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Yaitu dengan memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar.</p>', NULL, '2025-12-13 06:36:01', '2025-12-13 06:39:39'),
(305, 4, 209, '<p>Saya tahu bahwa fungsi kuadrat berbentuk y=ax²+bx+c dengan grafiknya beruoa parabola dan memiliki titik puncak, sumbu simetri, serta nilai maksimum atau minimum yang sering digunakan dalam kehidupan sehari-hari untuk menyelesaikan masalah </p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, mencatat informasi yang diketahui, menentukan apa yang ditanyakan, memisalkan variabel, lalu mengubah soal cerita ke dalam bentuk fungsi kuadrat.</p>', NULL, '<p>Dengan memahami bentuk grafik fungsi kuadrat, menentukan rumus yang sesuai, memilih cara penyelesaian yang tepat seperti faktorisasi, melengkapkan kuadrat, atau rumus ABC. Setelah itu, saya menyesuaikan hasilnya dengan konteks soal.</p>', NULL, '2025-12-13 06:40:29', '2025-12-13 06:46:28'),
(306, 3, 193, '<p>konsep triginometri sering kali ditemukan dalam menyel;esaikan permasalahan dalam segi tiga </p><p>dalam konsep ini rumus utamanya yaitu a^2 + b^2 = C^2</p>', NULL, '<p>menganalisis soal dengan mengetahui besaran sisi masing-masing segitiga jika bagian yang tidak diketahui dapat diselesaikan dengan rumus dari triginometri</p><p><br></p>', NULL, '<p>ketika komponen utamanya yaitu besaran sudut dan besaran sisinya telah diketahui maka dengan mudah dinotasikan dalam konsep matematika</p>', NULL, '2025-12-13 06:44:36', '2025-12-13 06:48:56'),
(307, 2, 254, '<p>Definisi sistem persamaan linear adalah himpunan persamaan linear yang saling terkait dengan koefisien bilangan real.</p><p><br></p>', NULL, '<p>Untuk menyelesaikan soal, saya membaca soal dengan teliti, menentukan variabel dan membuat model matematika, lalu menyelesaikannya dengan metode yang sesuai. Setelah itu, saya mengecek kembali hasilnya untuk memastikan jawaban sudah benar </p>', NULL, '<p>Saya menentukan strategi dengan memahami konteks soal terlebih dahulu, lalu memilih metode penyelesaian yang sesuai agar langkah pengerjaannya lebih terarah dan tepat.</p>', NULL, '2025-12-13 06:44:48', '2025-12-13 06:57:40'),
(308, 5, 273, '<p>saya dapat mempelajari tentang pengertian dasar eksponen, bentuk umum fungsi eksponen,sifat-sifat operasinya, cara menggambar grafik,dan aplikasinya dalam kehidupan nyata.</p>', NULL, '<p>yaitu membaca soal dengan teliti,menemukan kata kunci dan data penting, membuat model, dan menentukan apa yang di tanyakan.</p>', NULL, '<p>yaitu dengan pahami masalah yang ada di dalam soal, lalu pilih model yang tepat, subsitusi nilai yang diketahui, selesaikan persamaan,dan interpretasikan hasil.</p>', NULL, '2025-12-13 06:49:17', '2025-12-13 06:56:31'),
(309, 4, 208, '<p>Yang saya ketahui adalah mengenai konsep fungsi kuadrat</p>', NULL, '<p>Pertama memahami konsep dalam topik ini, kemudian mengidentifikasi soal matematikanya dan lakukan metode penyelesaiannya sampai hasil akhir.</p>', NULL, '<p>1.&nbsp;&nbsp;&nbsp;Mengidentifikasi masalah yang diberikan</p><p>2.&nbsp;&nbsp;&nbsp;menganalisis sifat fungsi kuadrat</p><p>3.&nbsp;&nbsp;&nbsp;melakukan langkah penyelesaian</p><p>4.&nbsp;&nbsp;&nbsp;Menyajikan hasil</p>', NULL, '2025-12-13 06:51:05', '2025-12-13 06:55:04'),
(310, 2, 259, '<p>Materi Sistem Persamaan dan Pertidaksamaan Linear adalah konsep yang digunakan untuk memecahkan masalah yang melibatkan lebih dari satu variabel atau kondisi. </p>', NULL, '<p>Pahami masalah (data/tujuan), definisikan variabel ($x, y$), lalu buat model matematika (Persamaan/Pertidaksamaan).</p>', NULL, '<p>Jika mencari nilai pasti, gunakan Eliminasi/Substitusi. Jika mencari optimasi (maksimal/minimal), gunakan Metode Grafik.</p>', NULL, '2025-12-13 06:57:09', '2025-12-13 07:29:56'),
(311, 4, 206, '<p>Konsep Fungsi Kuadrat dan penerapannya dalam kehidupan</p>', NULL, '<p>Langkah-langkah singkat sebelum menghitung soal cerita fungsi kuadrat:</p><ol><li>Pahami soal</li><li>Tentukan variabel</li><li>Buat model matematika</li><li>Identifikasi bagian pentinga</li><li>Rencanakan metode penyelesaian</li></ol>', NULL, '<p>Strateginya dengan memahami soal, buat fungsi kuadrat dari informasi yang diberikan, tentukan metode yang sesuai (titik puncak, pemfaktoran, atau melengkapkan kuadrat), lalu periksa hasil agar sesuai konteks</p>', NULL, '2025-12-13 06:57:58', '2025-12-13 07:13:37'),
(312, 4, 329, '<p>yang saya ketahui yaitu Karakteristik Fungsi Kuadrat, Menentukan Akar-Akar Persamaan Kuadrat serta contoh soal dan penyelesaiannya</p>', NULL, '<p>Langkah-langkahnya yaitu menganalisis soal secara cermat, kemudian tetapkan variabel lalu terjemahkan seluruh hubungan atau kondisi dalam soal Setelah model persamaan kuadrat berhasil dibentuk selanjutnya memilih metode penyelesaian</p>', NULL, '<p>Strategi yang digunakan yaitu Pemodelan Konteks, setelah model terbentuk, fokus strategi beralih ke Analisis Karakteristik Fungsi. Terakhir, solusi yang diperoleh harus selalu diinterpretasikan kembali dalam konteks masalah</p>', NULL, '2025-12-13 07:01:32', '2025-12-13 07:10:41'),
(313, 1, 259, '<p>Saya sudah mengetahui konsep dasar bilangan eksponen, seperti arti basis dan pangkat serta cara menyederhanakan bentuk eksponen menggunakan sifat-sifatnya.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, memahami konteksnya, menuliskan yang diketahui dan ditanyakan, lalu menentukan model dan rumus matematika sebelum menghitung hasil akhir.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, menentukan yang diketahui dan ditanyakan, memilih rumus yang sesuai, lalu menyelesaikannya secara bertahap dan mengecek kembali hasilnya.</p>', NULL, '2025-12-13 07:04:20', '2025-12-13 07:06:09'),
(314, 3, 262, '<p>Materi perbandingan trigonometri mencakup konsep dasar sinus, kosinus, dan tangen sebagai perbandingan sisi-sisi pada segitiga siku-siku, serta nilai-nilai khusus untuk sudut istimewa.</p><p><br></p>', NULL, '<p>Langkah awal adalah membuat sketsa masalah dan menandai sisi serta sudut yang diketahui&nbsp;Pilih perbandingan trigonometri (sinus, kosinus, atau tangen) yang menghubungkan data yang ada dengan nilai yang dicari, lalu hitung.</p>', NULL, '<p>Strategi dipilih berdasarkan hubungan sudut dan sisi yang dicari. Jika sisi miring diketahui, gunakan sinus atau kosinus. Jika sisi depan dan samping diketahui, gunakan tangen. </p>', NULL, '2025-12-13 07:04:28', '2025-12-13 07:05:37'),
(315, 3, 211, '<p>Perbandingan trigonometri merupakan konsep penting dalam matematika yang menjelaskan hubungan antara besar sudut dan panjang sisi pada sebuah segitiga yang memiliki satu sudut siku-siku.&nbsp;</p>', NULL, '<p>Baca soal, tentukan diketahui dan ditanyakan, buat model matematika, lalu pilih metode penyelesaian.</p>', NULL, '<p>Strategi ditentukan sejak membaca dan memahami soal, dengan mengidentifikasi informasi penting, memilih konsep yang sesuai, lalu menyusun langkah penyelesaian berdasarkan konteks masalah.</p><p><br></p>', NULL, '2025-12-13 07:13:03', '2025-12-13 07:16:30'),
(316, 1, 204, '<p>Definis eksponen, sifat-sifat eksponen, jenis-jenis eksponen dan maknanya dalam kehidupan sehari-hari.</p>', NULL, '<p>Yaitu memahami konteks soal, kemudian menentukan apa yang diketahui dan ditanyakan soal. Selanjutnya, mengubah cerita ke bentuk matematika dan menentukan aturan eksponen apa yang sesuai. Terakhir, menyusun langkah operasi eksponen secara urut.</p>', NULL, '<p>Yaitu dengan menemukan pola atau struktur eksponen, kemudian menggunakan sifat-sifat eksponen secara tepat, lalu mengecek dengan cara menyederhanakan bentuk aljabarnya.</p>', NULL, '2025-12-13 07:18:20', '2025-12-13 07:28:56'),
(317, 4, 254, '<p>yang saya ketahui adalah tentang Karakteristik Fungsi Kuadrat</p><p><br></p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, lalu menyusun model matematika sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks soal, mengidentifikasi informasi yang diketahui dan ditanyakan, kemudian memilih konsep atau rumus yang sesuai dengan materi agar penyelesaian masalah tepat dan sistematis.</p>', NULL, '2025-12-13 07:18:37', '2025-12-13 07:22:30'),
(318, 3, 199, '<p>Dengan mempelajari trigonometri kita dapat mengetahui sudut sudut istimewa yang ada pada segitiga dan kapan kita menggunakan rumus Teorema phytagoras </p>', NULL, '<p>Kita harus memahami konsep pertanyaan pada soal yang akan diselesaikan, setelah memahami konsep-konsepnya maka tentukan rumus apa yang akan digunakan untuk menyelesaikan permasalahan-permasalahan yang ada pada soal</p>', NULL, '<p>Strategi yang bisa digunakan adalah pahami dulu soal yang akan dikerjakan dan akan menggunakan rumus apa untuk menyelesaikan soal tersebut </p><p>Setelah mengetahuinya maka tariklah kesimpulannya </p>', NULL, '2025-12-13 07:19:30', '2025-12-13 07:21:34'),
(319, 2, 210, '<p>Dari materi pada topik ini, saya mengetahui bahwa soal cerita matematika harus dipahami terlebih dahulu lalu diubah ke dalam bentuk model atau kalimat matematika sebelum diselesaikan.</p><p><br></p>', NULL, '<p>Langkah yang dilakukan sebelum menghitung adalah membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, serta memilih rumus atau metode yang sesuai.</p><p><br></p>', NULL, '<p>Strategi yang digunakan adalah menyelesaikan soal secara sistematis sesuai konteks masalah dan mengecek kembali hasil agar jawabannya masuk akal.</p><p><br></p>', NULL, '2025-12-13 07:20:15', '2025-12-13 07:22:52'),
(320, 5, 240, '<p>Fungsi eksponen f(x) = a·bˣ adalah fungsi dengan variabel di pangkat, grafiknya kurva yang terus naik (b &gt; 1) atau turun (0 &lt; b &lt; 1), dan digunakan untuk memodelkan pertumbuhan populasi, peluruhan radioaktif, atau bunga majemuk.</p>', NULL, '<p>Pahami soal dan identifikasi nilai awal (a), laju perubahan (b), dan variabel waktu (x). Kemudian ubah informasi menjadi bentuk fungsi f(x) = a·bˣ, substitusikan nilai yang diketahui, dan hitung hasilnya.</p>', NULL, '<p>Pilih bentuk fungsi berdasarkan jenis: pertumbuhan gunakan f(x) = a(1 + r)ˣ, peluruhan gunakan f(x) = a(1 - r)ˣ, dan bunga majemuk gunakan A = P(1 + r/n)ⁿᵗ. Verifikasi jawaban apakah logis dan sesuai konteks.</p>', NULL, '2025-12-13 07:21:04', '2025-12-13 07:22:22'),
(321, 4, 261, '<p>yang sudah saya  pahami yaitu definisi persamaan kuadrat , metode penyelesaian persamaan kuadrat  dan fungsi kuadrat</p>', NULL, '<p>yang saya lakukan adalah pahami soal dengan cermat ,mengecek kembali  jawaban nya apakah sesuai dengan konsep fungsi kuadrat</p>', NULL, '<p>strategi saya yaitu memahami konsep dari funsi kuadrat dengan baik benar, dan saya harus memliki pemahaman yang bagus untuk bisa menjawab soal tersebut </p>', NULL, '2025-12-13 07:21:47', '2025-12-13 07:28:43'),
(322, 1, 203, '<p>yang saya ketahui adalah eksponen dan sifat sifatya</p>', NULL, '<p>baca soal dengan teliti,tentukan apa yang diketahui dan ditanyakan,ubah kalimat cerita ke dalam bentuk matematika</p>', NULL, '<p>memahami konteks masalah terlebih dahulu dan menentukan eksponen yang tepat memilih aturan eksponen yang relavan</p>', NULL, '2025-12-13 07:25:24', '2025-12-13 07:29:57'),
(323, 4, 279, '<p>saya jadi tahu apa itu fungsi kuadrat, bentuk persamaannya, dan bagaimana mengerjakannya.</p>', NULL, '<p>analisis soal, tentukan yang diketahui dan yang ditanyakan, tentukan bentuk persamaannya, tentukan nilai akhirnya.</p>', NULL, '<p>strategi yang bisa saya berikan yaitu ketika mengerjakan soal kalau bisa kerja bersama teman-teman, karena bisa saja ada teman yang lebih paham tentang topik ini, kalau masih kesulitan bisa bertanya kepada guru.</p>', NULL, '2025-12-13 07:29:37', '2025-12-13 07:31:39'),
(324, 6, 324, '<p>vektor adalah besaran yang memiliki besar dan arah, dinotasikan sebagai AB atau huruf tebal. operasi vektor meliputi penjumlahan (metode sgitiga, jajargenjang, poligon, dan komponen)</p>', NULL, '<p>membaca soal dan mengidentifikasi besaran vektor (perpindahan gaya kecepatan), menentukan besar dan arah setiap vektor, memeilih metode operasi yang sesuai</p>', NULL, '<p>untuk masalah perpindahan gunakan penjumlahan vekltor metode sgitiga/poligon, untuk mencari selisih posisi gunakan pengurangan vektor, untuk mencari masalah kelipatan/perubahan skala gunakan perkalian skalar</p>', NULL, '2025-12-13 07:30:00', '2025-12-13 07:32:33'),
(325, 4, 270, '<p><span style=\"color: rgb(51, 65, 85);\">Saya senang mendengar Anda tertarik dengan topik Fungsi Kuadrat dalam matematika. Untuk memulai, mari kita eksplorasi konsep dasar dari fungsi kuadrat.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Identifikasi data-data yang diberikan seperti nilai-nilai variabel, hubungan antar variabel, dan pertanyaan yang diajukan.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">coba identifikasi informasi yang diberikan dalam soal cerita tersebut. Pahami dengan baik apa yang diminta dalam soal dan informasi apa yang sudah diberikan</span></p>', NULL, '2025-12-13 07:30:26', '2025-12-13 07:35:40'),
(326, 4, 345, '<p>Bentuk umu fungsi kuadrat,grafik:Parabola.Arah a&gt;0(minimum), a&lt;0(maksimum). Titik puncak <img src=\"//:0\" height=\"29\" width=\"64\">, Diskriminan <img src=\"//:0\" height=\"20\" width=\"11\"></p>', NULL, '<p>1)<strong>Pahami Konteks</strong> dan <strong>Identifikasi Variabel, </strong>2)<strong>Formulasikan Fungsi</strong>&nbsp;<img src=\"//:0\" height=\"38\" width=\"142\">, dan 3)<strong>Tentukan Tujuan</strong> (maksimum/minimum atau akar-akar).</p>', NULL, '<p>1) untuk maks/min : cari titik puncak, 2) untuk titik nol : cari akar f(x)=0, dan 3) untuk konteks : analisis alfa untuk jenis ekstrem.</p>', NULL, '2025-12-13 07:36:43', '2025-12-13 07:42:21'),
(327, 6, 240, '<p>Vektor adalah besaran dengan besar dan arah, ditulis sebagai komponen (x, y) atau (x, y, z). Operasi: penjumlahan, pengurangan, perkalian skalar, dot product, cross product. Digunakan dalam fisika, navigasi, dan grafika.</p>', NULL, '<p>Pahami soal, tentukan sistem koordinat, ubah ke bentuk komponen vektor, identifikasi operasi yang diperlukan, sketsa diagram, hitung, dan interpretasikan hasil.</p>', NULL, '<p><strong>Soal gerak/gaya:</strong> Gunakan penjumlahan vektor untuk resultan. </p><p><br></p>', NULL, '2025-12-13 07:59:30', '2025-12-13 08:03:08'),
(328, 5, 329, '<p>yang saya ketahui yaitu Definisi fungsi eksponen,Sifat-Sifat Grafik Fungsi Eksponen serta contoh soal dan penyelesaiannya</p>', NULL, '<p>langkah langkahnya yaitu Memahami dan Mengidentifikasi Masalah, Memformulasikan Model Matematika kemudian Menyusun Rencana Perhitungan</p>', NULL, '<p>saya memilih dan memiliki strategi pada tahap awal pemecahan masalah dengan cara menganalisis masalah untuk menentukan jenis strategi mana  yang akan paling efektif dalam menerjemahkan soal cerita menjadi model matematika yang dapat dipecahkan.</p>', NULL, '2025-12-13 08:02:41', '2025-12-13 08:08:17'),
(329, 5, 270, '<p><span style=\"color: rgb(51, 65, 85);\">Fungsi eksponen merupakan fungsi matematika yang bentuk umumnya adalah f(x) = a^x, di mana a adalah konstanta positif yang disebut basis, dan x adalah variabel eksponen.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Identifikasi informasi penting seperti nilai-nilai yang diketahui, variabel yang digunakan, dan pertanyaan yang diajukan.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Salah satu strategi yang bisa digunakan adalah dengan memahami properti dasar dari fungsi eksponensial, seperti aturan perkalian, pembagian, dan pemangkatan. </span></p>', NULL, '2025-12-13 08:03:41', '2025-12-13 08:07:47'),
(330, 2, 203, '<p>mengetahui bagaimana cara kita belajar, strategi apa yang efektif, serta memahami kekuatan dan kelemahan diri.</p>', NULL, '<p><strong>Perencanaan</strong>: memahami soal, menentukan konsep dan strategi yang tepat.</p><p><strong>Pemantauan</strong>: mengecek langkah dan perhitungan saat mengerjakan.</p>', NULL, '<p><strong>Perencanaan</strong>: memahami soal, menentukan konsep dan strategi yang tepat.</p><p><strong>Pemantauan</strong>: mengecek langkah dan perhitungan saat mengerjakan.</p>', NULL, '2025-12-13 08:03:58', '2025-12-13 08:08:55'),
(331, 5, 209, '<p>Saya mengetahui bahwa fungsi eksponen adalah fungsi yang variabelnya berada pada pangkat, misalnya <em>y</em>=𝑎^x. Fungsi ini sering digunakan untuk menggambarkan pertumbuhan atau peluruhan, seperti pertumbuhan penduduk dan bunga majemuk.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, memisalkan variabel, lalu mengubah soal cerita ke dalam bentuk fungsi eksponen yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Dengan memahami konteks soal terlebih dahulu, menentukan apakah masalah tersebut termasuk pertumbuhan/peluruhan, lalu memilih rumus fungsi eksponen yang tepat. Setelah itu, hasilnya dicek kembali agar sesuai dengan konteks soal.</p>', NULL, '2025-12-13 08:12:04', '2025-12-13 08:14:10'),
(332, 3, 279, '<p>saya jadi tahu apa itu trigonometri, perbandingan trigonometri, rumus-rumusnya dan cara menyelesaikannya.</p>', NULL, '<p>analisis soal, tentukan apa yang diketahui dan ditanyakan, masukkan dalam rumus yang berkaitan dengan soal lalu selesaikan.</p>', NULL, '<p>Strategi untuk menyelesaikan soal perbandingan trigonometri, seperti sinus, kosinus, atau tangen, diterapkan ketika konteks masalah melibatkan sudut dan panjang sisi dalam segitiga siku-siku.&nbsp;</p>', NULL, '2025-12-13 08:16:07', '2025-12-13 08:21:40'),
(333, 3, 272, '<p>Perbandingan trigonometri menjelaskan hubungan antara besar sudut dan panjang sisi pada segitiga siku-siku, di mana nilainya berubah sesuai besar sudut yang digunakan.</p>', NULL, '<p>Membaca soal dengan cermat, memahami konteks masalah, menentukan sudut dan sisi yang diketahui, memilih perbandingan trigonometri yang tepat, lalu menyusun rencana penyelesaian sebelum melakukan perhitungan hasil akhir.</p>', NULL, '<p>Menganalisis informasi dan konteks masalah, memilih konsep atau rumus yang sesuai, lalu menyusun langkah penyelesaian secara runtut agar hasil yang diperoleh tepat dan sesuai dengan permasalahan.</p>', NULL, '2025-12-13 08:19:50', '2025-12-13 08:22:17'),
(334, 5, 254, '<p>yang saya ketahui adalah tentang Definisi Grafik Eksponen dan Sifat-sifat Grafik Fungsi Eksponen</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, lalu menyusun model matematika sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks soal, mengidentifikasi informasi yang diketahui dan ditanyakan, kemudian memilih konsep atau rumus yang sesuai dengan materi agar penyelesaian masalah tepat dan sistematis.</p>', NULL, '2025-12-13 08:21:52', '2025-12-13 08:22:43'),
(335, 4, 210, '<p>Dari materi pada topik ini, saya mengetahui bahwa soal cerita matematika perlu dipahami konteksnya lalu diubah ke dalam model atau persamaan matematika sebelum diselesaikan.</p><p><br></p>', NULL, '<p>Langkah yang saya lakukan sebelum menghitung adalah membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, serta memilih rumus atau metode yang sesuai.</p><p><br></p>', NULL, '<p>Strategi saya adalah menyelesaikan soal secara bertahap dan sistematis sesuai konteks masalah, kemudian mengecek kembali hasil agar jawabannya masuk akal.</p><p><br></p>', NULL, '2025-12-13 08:22:23', '2025-12-13 08:23:17'),
(336, 6, 270, '<p><span style=\"color: rgb(51, 65, 85);\">Vektor merupakan besaran yang memiliki besar (magnitude) dan arah. Dalam konteks aljabar, vektor direpresentasikan dengan koordinat dalam ruang.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Perhatikan apakah Anda perlu menggunakan hukum-hukum vektor seperti hukum komutatif, asosiatif, distributif, atau pun hukum-hukum lainnya.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">terutama yang berkaitan dengan konsep vektor, melibatkan pemahaman yang mendalam tentang konsep tersebut. </span></p>', NULL, '2025-12-13 08:28:03', '2025-12-13 08:42:21'),
(337, 5, 206, '<p>Konsep fungsi eksponen dan penerapannya dalam kehidupan sehari-hari. Serta cara penyelesaiannya.</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, lalu membuat model fungsi eksponen yang sesuai sebelum menghitung.</p><p><br></p>', NULL, '<p>Saya menentukan strategi setelah memahami soal, dengan menyesuaikannya pada konteks dan konsep matematika yang digunakan.</p>', NULL, '2025-12-13 08:30:18', '2025-12-13 08:34:46'),
(338, 1, 205, '<p>Materi ini membahas bilangan berpangkat sebagai bentuk perkalian berulang, bentuk (a^n) memudahkan penulisan dan perhitungan, dan eksponen juga digunakan untuk memodelkan berbagai masalah.</p>', NULL, '<ol><li>Membaca dan memahami isi soal cerita dengan cermat.</li><li>Menentukan model matematika yang sesuai dengan bilangan berpangkat.</li><li>Menentukan sifat eksponen yang digunakan sebelum menghitung.</li></ol><p><br></p>', NULL, '<p>Strategi yang saya lakukan adalah memahami konteks dan pola pada masalah, kemudian mengubahnya ke dalam bentuk matematika yang sesuai seperti eksponen, lalu menerapkan sifat-sifat eksponen yang tepat untuk memperoleh hasil yang benar.</p>', NULL, '2025-12-13 08:38:05', '2025-12-13 08:44:38'),
(339, 6, 242, '<p>Saya memahami bahwa vektor adalah besaran yang memiliki besar dan arah, notasi vektor, jenis-jenis vektor, serta operasi dasar vektor seperti penjumlahan, pengurangan, dan perkalian skalar yang dapat dilakukan secara aljabar maupun grafis.</p>', NULL, '<p>Langkah yang dilakukan adalah mengidentifikasi besaran vektor dalam soal, menuliskannya dalam bentuk vektor, lalu menentukan operasi vektor yang sesuai dengan konteks masalah.</p><p><br></p>', NULL, '<p>Strategi saya adalah mengaitkan konteks soal dengan sifat-sifat vektor dan memilih metode penyelesaian yang tepat, baik secara perhitungan komponen maupun visualisasi grafis, agar hasilnya sesuai arah dan besar vektor.</p>', NULL, '2025-12-13 08:38:25', '2025-12-13 08:39:07'),
(340, 4, 327, '<p>Karakteristik fungsi kuadrat dan cara menentukan akar-akar persamaan kuadrat</p>', NULL, '<p>membaca soal cerita fungsi kuadrat dengan cermat , menentukan informasi yang diketahui dan yang ditanyakan, menetapkan variabel yang sesuai dengan konteks soal dan mengubah cerita ke dalam bentuk model matematika berupa fungsi kuadrat </p>', NULL, '<p>memahami konteks masalah , menentukan variabel dan membentuk model fungsi kuadrat ,memilih  metode penyelesaian,menafsirkan hasil perhitungan kembali ke konteks masalah.</p>', NULL, '2025-12-13 08:39:15', '2025-12-13 08:47:55');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(341, 5, 204, '<p>Fungsi eksponensial adalah fungsi yang variabelnya berada pada pangkat dengan dua jenis utama, yaitu pertumbuhan eksponensial dan peluruhan eksponensial.</p>', NULL, '<p>Yaitu dengan membaca soal dengan cermat, menentukan besaran awal, mengidentifikasi rasio perubahan pada setiap periode waktu, menyusun satuan waktu atau fase, dan kemudian menyusun model matematika dalam bentuk fungsi eksponensial yang sesuai.</p>', NULL, '<p>Yaitu segera setelah masalah diidentifikasi melibatkan hitungan yang bertambah atau berkurang secara persentase seiring waktu (seperti pertumbuhan cepat atau penyusutan). Caranya dengan mengubah cerita menjadi rumus f(x) = A * B^x.</p>', NULL, '2025-12-13 08:40:25', '2025-12-13 08:53:35'),
(342, 2, 202, '<ol><li>definisi persamaan linear</li><li>menyelesaikan persamaan linear dengan 2 variabel : menggunakan metode subtitusi,eliminasi dan campuran.</li><li>menyelesaikan persamaan linear dengan 3 variabel</li></ol>', NULL, '<p>Baca soal dengan teliti, Tentukan yang diketahui dan yang ditanyakan, Misalkan variabel, Ubah cerita menjadi model matematika, Periksa tanda dan kondisi, Pilih strategi penyelesaian dan Hitung hasil akhir dan tuliskan jawaban sesuai konteks</p>', NULL, '<p>Pahami konteks masalah,Tentukan variabel, Ubah kalimat soal menjadi model matematika, Selesaikan persamaan atau pertidaksamaan, Tulis himpunan solusi</p><p>dan Periksa jawaban sesuai konteks.</p>', NULL, '2025-12-13 08:45:12', '2025-12-13 09:01:50'),
(343, 2, 241, '<ol><li>Definisi persamaan linear</li><li>Menyelesaikan persamaan linear dengan 2 variabel : menggunakan metode subtitusi,eliminasi dan campuran.</li><li>Menyelesaikan persamaan linear dengan 3 variabel</li></ol>', NULL, '<p>Baca soal dengan teliti, Tentukan yang diketahui dan yang ditanyakan, Misalkan variabel, Ubah cerita menjadi model matematika, Periksa tanda dan kondisi, Pilih strategi penyelesaian dan Hitung hasil akhir dan tuliskan jawaban sesuai konteks</p>', NULL, '<p>Pahami konteks masalah,Tentukan variabel, Ubah kalimat soal menjadi model matematika, Selesaikan persamaan atau pertidaksamaan, Tulis himpunan solusi dan Periksa jawaban sesuai konteks.</p>', NULL, '2025-12-13 08:45:20', '2025-12-13 09:04:43'),
(344, 3, 324, '<p>Saya telah memahami: perbandingan trigonometri (sin, cos, tan) pada segitiga siku-siku, hubungan sudut dan sisi segitiga, aturan sinus dan cosinus, nilai sudut istimewa (30°, 45°, 60°, 90°), teorema Pythagoras, dan penerapan trigonometri</p><p><br></p>', NULL, '<p>Baca dan pahami masalah dengan teliti Gambar sketsa/diagram segitiga siku-siku dari situasi soal Identifikasi dan beri label: sudut yang diketahui, sisi depan, sisi samping, sisi miring</p>', NULL, '<p>Strategi muncul saat: (1) memahami pola soal yang serupa, (2) mengenali kata kunci (tinggi, jarak, sudut elevasi), (3) mengidentifikasi elemen segitiga siku-siku dalam konteks. Caranya: latihan soal variatif, membuat visualisasi, </p>', NULL, '2025-12-13 08:49:42', '2025-12-13 08:51:50'),
(345, 1, 212, '<p>Eksponen digunakan untuk menyatakan perkalian berulang dan perubahan yang terjadi secara berlipat dalam kehidupan sehari-hari.</p><p><br></p>', NULL, '<p>Membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, menuliskan model matematika, lalu memilih konsep eksponen yang tepat sebelum menghitung.</p>', NULL, '<p>Strategi yang saya gunakan adalah memahami konteks soal terlebih dahulu, mengidentifikasi bentuk perkalian berulang atau eksponen yang sesuai, menyusun model matematika, lalu menerapkan aturan eksponen yang tepat untuk memperoleh jawaban.</p>', NULL, '2025-12-13 08:56:33', '2025-12-13 08:59:19'),
(346, 2, 339, '<p>Materi ini membahas Sistem Persamaan Linear (SPL) yang mencari nilai tunggal variabel, dan Sistem Pertidaksamaan Linear (SPtL) yang solusinya berupa Daerah Penyelesaian (DP) pada grafik.</p>', NULL, '<p>Langkah kuncinya adalah membuat model matematika<strong> </strong>: tetapkan variabel, lalu terjemahkan batasan cerita menjadi persamaan<strong> </strong> atau pertidaksamaan<strong> </strong>untuk membentuk sistem yang relevan.</p>', NULL, '<p>Strateginya disesuaikan konteks: gunakan eliminasi/substitusi untuk SPL (mencari nilai), atau metode grafik (menggambar garis batas dan uji titik) untuk SPtLDV (mencari daerah penyelesaian).</p>', NULL, '2025-12-13 09:00:12', '2025-12-13 09:02:02'),
(347, 6, 329, '<p>yang saya ketahui yaitu Definisi Vektor, Operasi Vektor serta contoh soal dan penyelesaiannya</p>', NULL, '<p>yaitu identifikasi besaran vektor dan skalar yang ada dalam soal kemudian tetapkan sistem koordinat lalu merepresentasikan setiap besaran vektor kemudian tentukan operasi vektor</p>', NULL, '<p>Strategi untuk menyelesaikan soal matematika dibentuk segera setelah memahami konteks masalah dan sebelum memulai perhitungan</p>', NULL, '2025-12-13 09:03:27', '2025-12-13 09:06:11'),
(348, 6, 206, '<p>Konsep Vektor, penerapan vektor dalam kehidupan sehari-hari, dan langkah-langkah penyelesaian soal terkait vektor</p>', NULL, '<p>Saya memahami soal, menentukan vektor yang diketahui dan ditanyakan, menetapkan arah/sistem koordinat, lalu memodelkannya sebelum menghitung.</p>', NULL, '<p>Saya menentukan strategi setelah memahami konteks soalnya dengan mengidentifikasi arah dan besar vektor serta metode yang sesuai.</p>', NULL, '2025-12-13 09:08:55', '2025-12-13 09:13:36'),
(349, 4, 268, '<p>Persamaan kuadrat adalah persamaan satu variabel dengan pangkat tertinggi dua, yang dapat diselesaikan dengan faktorisasi, melengkapkan kuadrat sempurna, atau rumus kuadrat.</p>', NULL, '<p>Memahami soal, menentukan variabel, menyusun persamaan kuadrat dari informasi yang diberikan, lalu menyelesaikannya dengan metode yang sesuai.</p>', NULL, '<p>Strategi penyelesaian dipilih dengan menyesuaikan bentuk persamaan kuadrat dan konteks masalah agar metode yang digunakan paling efisien dan sesuai.</p>', NULL, '2025-12-13 09:15:33', '2025-12-13 09:17:50'),
(350, 3, 270, '<p><span style=\"color: rgb(51, 65, 85);\">Dalam trigonometri, terdapat tiga fungsi trigonometri utama: sinus (sin), kosinus (cos), dan tangen (tan).</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Pastikan untuk mengidentifikasi sudut atau panjang sisi yang terlibat dalam perbandingan trigonometri tersebut.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Saat menghadapi soal matematika yang melibatkan perbandingan trigonometri, penting untuk memiliki strategi yang terorganisir.&nbsp;</span></p>', NULL, '2025-12-13 09:16:41', '2025-12-13 09:19:25'),
(351, 5, 345, '<p>Fungsi eksponen: <img src=\"//:0\" height=\"20\" width=\"179\">. Ada dua jenis: <strong>pertumbuhan</strong> (<img src=\"//:0\" height=\"20\" width=\"36\">) dan <strong>peluruhan</strong> (<img src=\"//:0\" height=\"20\" width=\"63\">).</p>', NULL, '<p>1)Tentukan <strong>Jenis</strong> (Pertumbuhan/Peluruhan), 2)Identifikasi <em>n</em>, <em>a</em>, dan <em>x, 3)</em>Tuliskan <strong>Model Fungsi</strong> (<img src=\"//:0\" height=\"37\" width=\"98\">), 4)<strong>Substitusi</strong> nilai <em>x</em>.</p>', NULL, '<p>(1)<strong>Pertumbuhan:</strong> Gunakan alfa&gt;1, (2)<strong>Peluruhan:</strong> Gunakan 0&lt;alfa&lt;1, (3)<strong>Grafik:</strong> Pastikan kurva melalui (0, <em>n</em>) dan mendekati asimtot y=0.</p>', NULL, '2025-12-13 09:18:20', '2025-12-13 09:33:03'),
(352, 2, 205, '<p>Materi ini membahas sistem persamaan dan pertidaksamaan linear beserta metode penyelesaiannya untuk memodelkan dan menyelesaikan masalah matematika dan kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang sebaiknya saya lakukan adalah memahami soal, menentukan variabel, membuat model matematika, dan memilih metode penyelesaian yang tepat sebelum menghitung.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, memodelkannya ke dalam sistem persamaan atau pertidaksamaan linear, lalu menyelesaikannya dengan metode yang sesuai.</p>', NULL, '2025-12-13 09:24:17', '2025-12-13 09:27:47'),
(353, 6, 204, '<p>Yaitu tentang vektor (besaran yang memiliki besar dan arah), jenis-jenis vektor (negatif, nol, ekuivalen), serta operasi vektor dasar seperti penjumlahan dan perkalian skalar.</p>', NULL, '<p>Yaitu dengan mengidentifikasi besaran vektor yang terlibat (seperti perpindahan atau kecepatan) dan juga menentukan operasi vektor apa yang diperlukan (tambah, kurang, atau kali skalar) sesuai konteks masalah.</p>', NULL, '<p>Yaitu saat konteks masalah diketahui. Caranya, jika melibatkan penentuan resultan total, maka menggunakan penjumlahan (metode poligon/aljabar) atau jika mencari perbedaan posisi/jarak, maka menggunakan pengurangan vektor.</p>', NULL, '2025-12-13 09:30:08', '2025-12-13 09:33:59'),
(354, 3, 240, '<p>Saya mengetahui sin = depan/miring, cos = samping/miring, tan = depan/samping, dan cara menghitung tinggi/jarak menggunakan sudut.</p>', NULL, '<p>Pahami soal → Gambar segitiga → Tandai yang diketahui → Pilih rumus (sin/cos/tan) → Hitung.</p>', NULL, '<p>Strategi muncul saat mengenali pola soal. Selalu gambar diagram dan gunakan SOH-CAH-TOA untuk memilih rumus yang tepat.</p>', NULL, '2025-12-13 09:34:46', '2025-12-13 09:35:28'),
(355, 2, 212, '<p>Sistem persamaan dan pertidaksamaan linear digunakan untuk menyelesaikan masalah dengan lebih dari satu variabel dan membantu pengambilan keputusan dalam kehidupan sehari-hari.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, serta memilih model atau rumus yang sesuai sebelum menghitung.</p>', NULL, '<p>Memahami konteks soal, menentukan model persamaan atau pertidaksamaan yang sesuai, lalu menyelesaikannya dengan metode yang tepat.</p>', NULL, '2025-12-13 09:47:40', '2025-12-13 09:49:22'),
(356, 1, 317, '<p>definisi eksponen dan sifat sifat eksponen</p>', NULL, '<p>langkah langkahnya adalah</p><ol><li>Memahami dan Menganalisis Masalah</li><li>Memodelkan Masalah ke dalam Bentuk Matematika</li><li>merencanakan solusi</li></ol>', NULL, '<p>Strategi saya untuk menyelesaikan soal cerita pada topik Aljabar dan Fungsi adalah dengan fokus pada<strong> pemodelan </strong>dan <strong>pemilihan teknik penyelesaian </strong>berdasarkan jenis hubungan matematis dalam masalah tersebut</p>', NULL, '2025-12-13 09:50:15', '2025-12-13 09:56:59'),
(357, 4, 205, '<p>Yang saya ketahui dari materi ini adalah persamaan dan fungsi kuadrat memiliki bentuk umum, sifat grafik (titik puncak, sumbu simetri, dan arah buka), serta cara menentukan akar-akar dan penerapannya dalam berbagai konteks kehidupan sehari-hari.</p>', NULL, '<p>Langkahnya adalah memahami soal, menentukan variabel, membuat model matematika, lalu mengecek model sebelum menghitung.</p>', NULL, '<p>Strategi saya adalah memahami konteks masalah terlebih dahulu, menentukan variabel yang tepat, membentuk persamaan atau fungsi kuadrat yang sesuai, lalu memilih metode penyelesaian yang paling efektif.</p>', NULL, '2025-12-13 09:56:11', '2025-12-13 09:58:05'),
(358, 5, 274, '<p><span style=\"color: rgb(51, 65, 85);\">Dalam fungsi eksponen, nilai pangkatnya merupakan eksponen yang menentukan pertumbuhan atau penyusutan nilai fungsi tersebut.&nbsp;</span></p>', NULL, '<p>Baca soal dengan teliti, catat data yang diketahui (nilai awal, faktor pertumbuhan/peluruhan, waktu), lalu tentukan model fungsi eksponen f(x) = a · bˣ. Substitusikan nilai-nilai tersebut, hitung hasilnya, dan periksa apakah jawabannya sesuai</p>', NULL, '<p><strong>Kapan:</strong> Setelah memahami konteks dan mengenali pola masalah dalam soal.</p><p><strong>Bagaimana:</strong> Perhatikan kata kunci, identifikasi data, lalu pilih model fungsi eksponen yang sesuai dan hitung hasilnya.</p>', NULL, '2025-12-13 10:09:55', '2025-12-13 10:25:20'),
(359, 3, 195, '<p>Saya dapat memahami konsep-konsep dasar trigonometri dan mengaplikasikannya dalam menyelesaikan berbagai permasalahan.</p>', NULL, '<p>dengan cara membaca dan memahami soal dan apa perinah dari soal tersubut dan melakukan pengoperasian</p>', NULL, '<p>satrategi penyelesaian soal matematika dimiliki <strong>sejak awal memahami soal</strong> dan masalah, memodelkan secara matematis, memilih metode yang tepat, menyelesaikan secara sistematis, dan melakukan pengecekan hasil.</p>', NULL, '2025-12-13 10:14:33', '2025-12-13 10:17:11'),
(360, 4, 212, '<p>Fungsi kuadrat membentuk grafik parabola dan digunakan untuk menentukan nilai maksimum atau minimum dalam berbagai masalah kehidupan sehari-hari.</p>', NULL, '<p>Memahami soal, menentukan data dan yang ditanyakan, lalu menyusun model fungsi kuadrat sebelum menghitung.</p>', NULL, '<p>Memahami konteks soal, menentukan bentuk fungsi kuadrat yang sesuai, lalu menyelesaikannya dengan metode yang tepat.</p>', NULL, '2025-12-13 10:22:45', '2025-12-13 10:24:06'),
(361, 6, 320, '<p>Dari materi ini saya memahami bahwa  pengertian vektor beserta besar dan arahnya. Selain itu, saya mempelajari cara menyatakan vektor dan melakukan operasinya. Vektor digunakan untuk menggambarkan perpindahan dan arah.</p>', NULL, '<p>Langkah awal adalah memahami soal dan menentukan vektor yang diketahui. Selanjutnya memilih operasi vektor yang sesuai. Setelah itu barulah dilakukan perhitungan.</p>', NULL, '<p>Strategi dibuat setelah memahami tujuan soal. Strategi disesuaikan dengan jenis operasi vektor yang digunakan. Dengan strategi yang tepat, soal lebih mudah diselesaikan.</p>', NULL, '2025-12-13 10:23:43', '2025-12-13 10:26:48'),
(362, 6, 345, '<p>Vektor adalah besaran <strong>besar</strong> + <strong>arah</strong>. Meliputi notasi (vec{A}), vektor lawan/ekuivalen, dan operasi <strong>penjumlahan</strong>, <strong>pengurangan</strong>, dan <strong>perkalian skalar</strong>.</p>', NULL, '<p><strong>1) Identifikasi</strong> (vektor/skalar), 2)<strong>Representasi</strong> (notasi vektor), 3)<strong>Tentukan</strong> operasi, 4)<strong>Pilih metode</strong> (Aljabar/Komponen vs Grafis), dan 5)<strong>Cek Satuan</strong>.</p><p><br></p>', NULL, '<p>1)Pilih <strong>Aljabar/Komponen</strong> jika ada <strong>koordinat</strong> (akurat). 2)Pilih <strong>Grafis</strong> jika ada <strong>besar dan arah</strong> (visualisasi, lalu pakai trigonometri). Strategi bergantung pada data yang diberikan.</p>', NULL, '2025-12-13 10:30:36', '2025-12-13 10:36:29'),
(363, 5, 212, '<p>Fungsi eksponen menunjukkan perubahan cepat, baik naik maupun turun, seperti pertumbuhan populasi, investasi, teknologi, dan peluruhan zat radioaktif.</p>', NULL, '<p><br></p><ol><li>Pahami soal dan tentukan yang ditanya.</li><li>Tandai data penting.</li><li>Buat model matematika.</li><li>Pilih strategi atau rumus yang sesuai.</li><li>Periksa kembali model dan langkah.</li></ol><p><br></p>', NULL, '<p>Strategi digunakan saat memahami soal dan menentukan metode yang sesuai dengan konteks, misalnya menggunakan persamaan, fungsi, atau diagram untuk mempermudah penyelesaian.</p><p><br></p>', NULL, '2025-12-13 10:58:20', '2025-12-13 11:00:47'),
(364, 6, 274, '<p><span style=\"color: rgb(51, 65, 85);\">Vektor merupakan besaran yang memiliki besar dan arah.</span></p>', NULL, '<p>Pahami soal, identifikasi besaran vektor dan gambarkan diagramnya, lalu tentukan metode penyelesaian yang sesuai. Representasikan vektor dalam komponen, lakukan operasi vektor, dan periksa kesesuaian hasil dengan konteks soal.</p>', NULL, '<p><strong>Kapan:</strong> Setelah mengidentifikasi jenis masalah vektor.</p><p><strong>Bagaimana:</strong> Pilih metode sesuai bentuk data yang diberikan dan apa yang ditanyakan.</p>', NULL, '2025-12-13 11:02:24', '2025-12-13 11:06:24'),
(365, 6, 212, '<p>punya besar dan arah, bisa dioperasikan, digunakan untuk gerak dan gaya.</p>', NULL, '<p><br></p><ul><li>Pahami soal dan tentukan yang ditanya.</li><li>Tandai vektor dan besarnya.</li><li>Buat diagram/model vektor.</li><li>Pilih operasi vektor yang sesuai.</li><li>Periksa kembali sebelum menghitung.</li></ul><p><br></p>', NULL, '<p>Strategi penyelesaian:</p><ul><li>Digunakan setelah memahami soal.</li><li>Tentukan metode atau diagram yang tepat.</li><li>Mempermudah perhitungan dan memastikan jawaban logis.</li></ul><p><br></p>', NULL, '2025-12-13 11:33:45', '2025-12-13 11:34:44'),
(366, 4, 214, '<p>Fungsi kuadrat, cara menyelesaikan soal fungsi kuadrat dan grafik persamaan kuadrat</p>', NULL, '<p>mengidentifikasi terlebih dahulu tujuan dari soal cerita, kemudian mencari model, lalu mencari nilai x nya</p>', NULL, '<p>Periksa angka depannya untuk menentukan arah lengkungan grafik. Gunakan cara pemfaktoran jika ingin mencari titik potong, atau cari garis tengahnya terlebih dahulu jika tujuan Anda adalah menemukan nilai tertinggi atau terendah.</p>', NULL, '2025-12-13 12:04:45', '2025-12-13 12:32:28'),
(367, 3, 320, '<p>Dari materi yang dipelajari, saya memahami bahwa trigonometri membahas hubungan sudut dan sisi pada segitiga siku-siku. Serta sin, cos, dan tan serta cara menggunakannya. Materi ini banyak digunakan untuk menghitung tinggi dan jarak.</p>', NULL, '<p>Langkah awal yang saya lakukan adalah membaca soal dengan teliti dan memahaminya. Setelah itu saya membuat gambar segitiga dan menentukan sudut serta sisi yang terlibat. Jika sudah jelas, barulah memilih rumus yang sesuai dan menghitung hasilnya.</p>', NULL, '<p>Saya menggunakan strategi membuat sketsa, menandai data yang diketahui, lalu memilih perbandingan trigonometri yang tepat. Dengan cara ini, penyelesaian soal menjadi lebih mudah dan terarah.</p>', NULL, '2025-12-13 12:11:39', '2025-12-13 12:13:57'),
(368, 3, 274, '<p><strong>Perbandingan trigonometri</strong> adalah perbandingan antara sisi-sisi dalam segitiga siku-siku.&nbsp;</p>', NULL, '<p> 1. Baca soal, buat sketsa segitiga, tandai yang diketahui dan ditanyakan.</p><p>2. Pilih rumus trigonometri yang tepat, hitung, dan periksa jawaban.</p>', NULL, '<p><strong>Kapan:</strong> Saat memahami soal dan membuat sketsa segitiga.</p><p><strong>Bagaimana:</strong> Pilih rumus sesuai posisi sisi terhadap sudut yang diketahui.</p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p><p><br></p>', NULL, '2025-12-13 12:57:26', '2025-12-13 13:06:50'),
(369, 2, 207, '<p>Sistem Persamaan linear adalah kumpulan beberapa persamaan linear yang saling terkait. Kita dapat menyelesaikan soal persamaan linear dengan menggunakan substitusi, eliminasi, campuran, dan metode grafik.</p>', NULL, '<p>Saya akan memahami masalah pada soal, membuat model matematikanya, menyelesaikan persamaan yang ada, memastikan jawaban saya sudah benar dan membuat kesimpulan.</p>', NULL, '<p>Mengidentifikasi variabel, membuat persamaannya, memilih metode penyelesaian yang paling efektif, menyelesaikan sistem persamaannya, memeriksa solusi yang di dapat kemudian menerjemahkan kembali nilai variabel ke dalam konteks soal cerita.</p>', NULL, '2025-12-13 13:06:28', '2025-12-13 13:23:12'),
(370, 4, 207, '<p>Persamaan kuadrat: ax² + bx + c = 0. Fungsi kuadrat: f(x) = ax² + bx + c. Solusi persamaan kuadrat: memfaktorkan, kuadrat sempurna, rumus ABC. Karakteristik fungsi kuadrat: keterbukaan, titik potong sumbu x/y, sumbu simetri.</p>', NULL, '<p>Memahami soal cerita, mengidentifikasi informasi, menentukan pertanyaan soal, buat model matematika (fungsi kuadrat), selesaikan model, periksa kembali jawaban.</p>', NULL, '<p>Gunakan informasi soal untuk menentukan koefisien fungsi kuadrat, gunakan karakteristik fungsi kuadrat (titik puncak, sumbu simetri), visualisasikan grafik untuk memahami konteks.</p>', NULL, '2025-12-13 14:40:15', '2025-12-13 14:44:24'),
(371, 2, 258, '<p>Materi ini membahas persamaan dan pertidaksamaan linear serta SPLDV, yaitu cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah, termasuk soal cerita.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel (misalnya xxx dan yyy), mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Strategi saya adalah memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar.</p>', NULL, '2025-12-13 15:01:09', '2025-12-13 15:02:14'),
(372, 4, 247, '<blockquote>Saya mengetahui bahwa persamaan kuadrat adalah persamaan dengan satu variabel berpangkat dua dan dapat diselesaikan dengan faktorisasi, melengkapkan kuadrat sempurna, atau rumus ABC.</blockquote><p><br></p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, lalu menyusun persamaan kuadrat sebelum menghitung hasilnya.</p>', NULL, '<p>Saya menggunakan strategi memahami konteks soal, menentukan variabel yang tepat, menyusun persamaan kuadrat sesuai masalah, lalu memilih metode penyelesaian yang paling sesuai.</p>', NULL, '2025-12-13 15:23:37', '2025-12-13 15:26:24'),
(373, 5, 279, '<p>saya jadi tahu apa itu fungsi eksponen, bentuk persamaan sederhananya, dan contoh penerapannya pada kehidupan sehari-hari.</p>', NULL, '<p>analisis soal, tentukan apa yang diketahui dan ditanyakan, masukkan dalam rumus yang berkaitan dengan soal lalu selesaikan.</p>', NULL, '<p>saya akan menggunakan strategi dengan mengubah basis agar sama (untuk persamaan), atau menggunakan logaritma untuk mengisolasi variabel dalam eksponen, sesuai dengan konteks masalah yang disajikan.</p>', NULL, '2025-12-13 15:27:13', '2025-12-13 15:33:39'),
(374, 3, 345, '<p>Konsep <strong>perbandingan trigonometri</strong> (Sin, Cos, Tan) menjelaskan hubungan sudut dan sisi pada segitiga siku-siku, berguna untuk mengukur tinggi, jarak, dan navigasi.</p>', NULL, '<p><strong>1)Visualisasikan</strong> masalah ke segitiga siku-siku. 2)<strong>Labeli Sisi</strong> (Depan, Samping, Miring). 3)<strong>Pilih Perbandingan</strong> (Sin, Cos, atau Tan) yang menghubungkan data.</p><p><br></p>', NULL, '<p>Pilih perbandingan berdasarkan pasangan sisi yang diketahui/dicari: <strong>Sin</strong> (Depan/Miring), <strong>Cos</strong> (Samping/Miring), atau <strong>Tan</strong> (Depan/Samping).</p>', NULL, '2025-12-13 15:28:14', '2025-12-13 15:32:31'),
(375, 5, 207, '<p>Fungsi Eksponen memilik bentuk: f(x) = a^x dengan a = basis (a &gt; 0, a ≠ 1) dan x = variabel.&nbsp;</p><p>Grafik Eksponen meliputi Domain, Range, Intersep,&nbsp;​Asimtot.</p>', NULL, '<p>Baca soal cermat, kenali konsep eksponen (pertumbuhan/peluruhan), ubah jadi persamaan, gunakan sifatnya untuk selesaikan, lalu cek jawaban apakah logis dan sesuai.</p>', NULL, '<p>Gunakan saat soal kompleks/baru. Analisis konteks dan variabel, pilih metode tepat (substitusi, grafik dll), terapkan langkah demi langkah, lalu evaluasi efektifitasnya.</p>', NULL, '2025-12-13 15:34:19', '2025-12-13 15:38:25'),
(376, 5, 261, '<p>yang saya ketahui dari video tadi yaitu fungsi eksponen , yang termasuk dalam elemen aljabar dan fungsi kuadrat</p>', NULL, '<p>langkah langkah nya yaitu baca soal dengan  seksama harus teliti, gunakan konsep dan sifat fungsi eksponen dengan metode yang umum di gunakan lalu tulis hasil nya </p><p><br></p>', NULL, '<p>yaitu setelah saya memahami soal saya akan menyusun rencana  penyelesaian  dan gunakan informasi yang diketahui untuk menulis kan jawaban nya </p>', NULL, '2025-12-13 15:40:03', '2025-12-13 15:46:47'),
(377, 5, 247, '<p>Saya mengetahui bahwa eksponen adalah bentuk perkalian berulang dari suatu bilangan yang sama, serta memahami bentuk dan sifat-sifat dasar eksponen untuk mempermudah perhitungan matematika.</p>', NULL, '<p>Langkah-langkahnya adalah membaca soal dengan teliti, memahami informasi yang diketahui dan ditanyakan, menentukan konsep atau sifat eksponen yang digunakan, lalu menyusun model matematika sebelum melakukan perhitungan.</p>', NULL, '<p>Saya mulai memiliki strategi saat memahami konteks soal, kemudian menentukan konsep matematika yang sesuai, memisalkan variabel jika diperlukan, dan memilih langkah penyelesaian yang paling tepat agar hasilnya sesuai dengan masalah yang diberikan.</p>', NULL, '2025-12-13 15:50:24', '2025-12-13 15:51:40'),
(378, 3, 206, '<p>Konsep trigonometri, penerapan trigonometri dalam kehidupan sehari-hari, dan cara memecahkan masalah terkait persoalan trigonometri</p>', NULL, '<p>Pahami soal dan gambarkan segitiganya, tentukan sisi dan sudut yang diketahui, pilih rumus trigonometri yang tepat, lalu hitung hasilnya.</p>', NULL, '<p>Strategi yang saya gunakan setelah memahami soal: buat gambar, tentukan sisi dan sudut, pilih rumus trigonometri yang sesuai, lalu hitung.</p>', NULL, '2025-12-13 15:52:09', '2025-12-13 15:58:03'),
(379, 1, 294, '<p>pengertian eksponen,jenis-jenis pangkat,sifat-sifat eksponen,penyederhanaan bentuk aljabar eksponen.penerapan eksponen dalam kehidupan nyata</p>', NULL, '<p>membaca soal dengan cermat,menentukan apa yang diketahui dan ditanyakan, mengindentifikasi bentuk eksponen yang sesuai, menentukan variabel dan model matematika, menentukan sifat eksponen yang akan digunakan, memeriksa kembali model yang dbuat</p>', NULL, '<p>saya menyelesaikan soal dengan memahami konteks masalah, menentukan diketahui dan ditanyakan,lalu meyelesaikan dengan sifat-sifat ekponen yang tepat, periksa ulang hasil akhir</p>', NULL, '2025-12-13 16:02:44', '2025-12-13 16:29:42'),
(380, 6, 247, '<blockquote>Saya mengetahui bahwa vektor memiliki besar dan arah serta dapat direpresentasikan dan dioperasikan dengan aturan tertentu.</blockquote><p><br></p>', NULL, '<blockquote>Membaca soal dengan teliti, menentukan vektor yang terlibat, memilih operasi vektor yang sesuai, lalu menyelesaikannya secara sistematis.</blockquote><p><br></p>', NULL, '<p>Saya mulai memiliki strategi setelah memahami konteks soal, kemudian menentukan konsep atau operasi matematika yang sesuai, dan menyelesaikannya secara sistematis agar jawabannya tepat.</p>', NULL, '2025-12-13 16:11:59', '2025-12-13 16:14:39'),
(381, 3, 346, '<p>yang telah saya ketahui adalah terkait perbandingan sudut segitiga siku-siku, perbandingan trigonometri dan teorema Phytagoras</p>', NULL, '<p>mencermati soal dan menganalisisnya untuk dibuatkan model matematika sesuai konteks trigonometri lalu menyelesaikannya</p>', NULL, '<p>ketika mengerti soalnya lalu  mencermati soal dan menganalisisnya untuk dibuatkan model matematika sesuai konteks trigonometri lalu menyelesaikannya</p>', NULL, '2025-12-13 16:12:47', '2025-12-13 16:14:15'),
(382, 6, 273, '<p>saya dapat memahami dengan baik cara pengerjaan operasi vektor</p>', NULL, '<p>yaitu dengan memaahami soal cerita, memodelkan masalah, dan merencanakan penyelesaian masalah tersebut.</p>', NULL, '<p>memahami maslah, merencanakan cara menyelesaian, melaksakan rencana, dan menafsirkan hasil.</p>', NULL, '2025-12-13 16:21:22', '2025-12-13 16:27:15'),
(383, 1, 347, '<p>topik ini membantu memahami pola pertumbuhan, penyederhanaan bentuk aljabar, serta penerapan matematika dalam kehidupan sehari-hari.</p>', NULL, '<p>Membaca soal, memahami soal, lalu menengukan konsep eksponen yang sesuai untuk menyelesaikan soal tersebut</p>', NULL, '<p>memahami konteks → menentukan konsep → memodelkan secara matematika → menyelesaikan dengan sifat eksponen → menafsirkan hasil.</p>', NULL, '2025-12-13 16:23:26', '2025-12-13 16:29:55'),
(384, 6, 279, '<p>saya jadi tahu apa itu vektor, operasi apa saja yang ada dalam vektor, cara penyelesainnya dan juga penggunaannya dalam kehidupan sehari-hari.</p>', NULL, '<p>analisis soal, tentukan apa yang diketahui dan ditanyakan, masukkan dalam rumus yang berkaitan dengan soal lalu selesaikan.</p>', NULL, '<p>ketika bertemu dengan soal yang kira-kira berkaitan dengan vektor, bekerja secara berkelompok dengan teman, berdiskusi dengan guru dan memanfaatkan teknologi digital.</p>', NULL, '2025-12-13 16:29:44', '2025-12-13 16:32:08'),
(385, 1, 255, '<p>Eksponen adalah bentuk aⁿ yang menunjukkan perkalian berulang dan memiliki sifat-sifat seperti a⁰ = 1, aᵐ × aⁿ = aᵐ⁺ⁿ, dan (aᵐ)ⁿ = aᵐⁿ.</p><p><br></p><p><br></p>', NULL, '<p>Pengetahuan Prosedural</p><p><br></p><p>1. Baca soal.</p><p>2. Ubah informasi ke bentuk eksponen.</p><p>3. Pakai sifat-sifat eksponen untuk menyederhanakan.</p><p>4. Hitung hasil akhirnya.</p>', NULL, '<p>Saya menggunakan strategi eksponen ketika soal melibatkan perubahan berulang, pertumbuhan, atau pengurangan bertingkat. Dalam situasi seperti itu, model pangkat lebih tepat sehingga perhitungan bisa dilakukan dengan cepat dan sesuai konteks soal.</p>', NULL, '2025-12-13 16:41:07', '2025-12-13 16:45:03'),
(386, 6, 207, '<p>Vektor didefinisikan sebagai ruas garis yang memiliki panjang dan arah. Secara geometri menggunakan panah sedangkan secara aljabar menggunakan (a, b) /(a, b, c). Operasi pada vektor yaitu penjumlahan, pengurangan dan perkalian.</p>', NULL, '<p>Pahami soal, visualisasi vektornya, pilih metode (penjumlahan, perkalian, dll.), ubah ke bentuk aljabar, tulis persamaan, sederhanakan, hitung, terus periksa jawaban.</p>', NULL, '<p>Strategi tergantung konteks soal. Resultan gaya pakai penjumlahan, usaha pakai perkalian titik, momen gaya pakai perkalian silang, gerak proyektil pakai uraian komponen. Pilih strategi berdasarkan kata kunci dan visualisasi.</p>', NULL, '2025-12-13 16:42:13', '2025-12-13 16:43:58'),
(387, 4, 259, '<p>Fungsi kuadrat adalah persamaan f(x)= ax²+bx+c  yang grafiknya selalu berupa parabola, dan kita mempelajari cara menentukan titik potong, sumbu simetri, dan titik puncaknya (maksimum/minimum).</p>', NULL, '<p>Langkah sebelum menghitung adalah mendefinisikan variabel, menerjemahkan cerita ke dalam bentuk fungsi f(x) = ax² + bx + c, dan mengidentifikasi apakah yang dicari adalah x (input optimum) atau f(x) (nilai output optimum).</p>', NULL, '<p>Strategi utama adalah selalu mencari titik puncak.</p>', NULL, '2025-12-13 16:49:29', '2025-12-13 16:52:13'),
(388, 1, 257, '<p>Definisi eksponen adalah cara untuk menulis perkalian berulang dari suatu bilangan dengan dirinya sendiri, sifat-sifat eksponen, jenis-jenis eksponen dan maknanya dalam kehidupan nyata.</p>', NULL, '<p>Pahami konteks cerita, tentukan apa yang diketahui dan ditanya, ubah cerita ke bentuk matematika, tentukan aturan eksponen yang sesuai, susun langkah operasi eksponen, lakukan perhitungan, dan interpretasi kembali jawaban.</p>', NULL, '<p>Tentukan pola pertumbuhan atau struktur eksponen, gunakan sifat eksponen secara tepat, visualisasi/pemetaan per fase, cek kembali dengan contoh kecil, dan sederhanakan dulu bentuk aljabarnya.</p>', NULL, '2025-12-13 16:54:38', '2025-12-13 16:57:51'),
(389, 6, 261, '<p>definisi dari vektor , vektor posisi dan panjang vektor</p>', NULL, '<p>pahami soal dengan seksama  , identifikasi konsep matematika yang relevan , rumuskan model matematika dan lakukan langkah langkah penyelsaian</p>', NULL, '<p>menganilisi soal pemilihan konsep yang sesuai , penyusunan rencana penyelsaian</p>', NULL, '2025-12-13 16:55:22', '2025-12-13 16:58:40'),
(390, 2, 257, '<p>Materi ini membahas persamaan dan pertidaksamaan linear serta SPLDV, yaitu cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah, termasuk soal cerita.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel (misalnya xxx dan yyy), mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Strategi saya adalah memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar.</p>', NULL, '2025-12-13 17:03:44', '2025-12-13 17:04:45'),
(391, 4, 257, '<p>Definisi persamaan kuadrat, tiga cara untuk menentukan akar-akar (penyelesaian) persamaan kuadrat, fungsi kuadrat dalam x berbentuk f(x)=ax^2+bx+c, dan diskriminan (D): Nilai D=b^2-4ac.</p>', NULL, '<p>Yaitu dengan memahami konteks masalah, identifikasi variabel-variabel yang ada, tentukan apa yang ditanyakan oleh soal, lalu memilih cara penyelesaian yang paling efektif.</p>', NULL, '<p>Dengan cara mengidentifikasi serta memodelkan apa yang dminta soal.</p>', NULL, '2025-12-13 17:12:09', '2025-12-13 17:12:55'),
(392, 5, 272, '<p>Fungsi eksponen&nbsp;menggambarkan suatu proses perubahan yang terjadi secara sangat cepat, baik meningkat maupun menurun. Dalam fungsi ini, suatu nilai bertambah atau berkurang dengan kecepatan yang semakin lama semakin besar.</p>', NULL, '<p>Membaca soal dengan cermat, mengidentifikasi informasi yang diketahui, menentukan apa yang ditanyakan, menentukan jenis permasalahan eksponen, menuliskan model atau bentuk fungsi eksponen yang sesuai, menyesuaikan variabel dan satuan </p>', NULL, '<p>Membaca soal secara menyeluruh, lalu mengidentifikasi informasi yang diketahui dan yang ditanyakan, menentukan model matematika yang sesuai dengan konteks soal, memilih rumus yang tepat, dan menyusun langkah penyelesaian secara sistematis. </p>', NULL, '2025-12-13 17:25:59', '2025-12-13 17:29:55'),
(393, 1, 267, '<p>Eksponen digunakan dalam berbagai konteks, seperti pertumbuhan dan peluruhan (misalnya bunga majemuk), notasi ilmiah, serta dalam penyederhanaan bentuk aljabar.</p>', NULL, '<p>langkah yang sebaiknya dilakukan adalah membaca soal dengan cermat agar memahami konteks permasalahan</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks masalah secara menyeluruh, mengidentifikasi informasi yang diketahui dan yang ditanyakan</p>', NULL, '2025-12-13 17:32:12', '2025-12-13 17:40:13'),
(394, 4, 203, '<p>Grafik fungsi kuadrat berbentuk parabola yang dapat terbuka ke atas atau ke bawah tergantung pada nilaia</p><p>a.&nbsp;</p>', NULL, '<p>Membaca soal dengan teliti,Menentukan informasi yang diketahui,Menentukan apa yang ditanyakan,Menentukan variabel,Membuat model matematika,Menentukan jenis penyelesaian yang dibutuhkan</p>', NULL, '<p>Strategi menyelesaikan soal cerita fungsi kuadrat adalah <strong>memahami konteks soal, menentukan data yang diketahui dan ditanyakan, memisalkan variabel, membentuk model fungsi kuadrat,&nbsp;</strong></p>', NULL, '2025-12-13 17:34:44', '2025-12-13 18:59:52'),
(395, 1, 192, '<p>Eksponen merupakan konsep dalam matematika yang digunakan untuk menggambarkan perkalian berulang serta memodelkan pertumbuhan eksponensial, dengan aplikasi luas di berbagai bidang dan memudahkan proses kalkulasi matematis.</p>', NULL, '<p>Cermati dengan teliti informasi yang tersaji dalam soal cerita, ubah data yang ada di dalam soal, terapkan aturan eksponen, kemudian nilai dan kerjakan perhitungan soal tersebut.</p>', NULL, '<p>Dengan mencermati konteks soal, mengenali informasi yang tersedia dan pertanyaan yang diajukan, mentransformasikannya ke dalam bentuk bilangan berpangkat, menentukan sifat eksponen yang sesuai, kemudian menyelesaikannya secara sistematis dan logis.</p>', NULL, '2025-12-13 17:46:11', '2025-12-13 17:47:43'),
(396, 2, 255, '<p><span style=\"color: rgb(17, 24, 39);\">Persamaan Linear</span>: Suatu kalimat terbuka yang melibatkan hubungan kesetaraan (=) dengan variabel yang berpangkat satu.</p><p><br></p>', NULL, '<p>Baca soal dan tentukan apa yang dicari.Tetapkan x dan y untuk besaran yang tidak diketahui.Terjemahkan soal cerita menjadi sistem persamaan atau sistem pertidaksamaan yang relevan.</p>', NULL, '<p>Identifikasi jenis masalah (persamaan dan . pertidaksamaan), lalu pilih metode penyelesaian yang paling efisien.</p>', NULL, '2025-12-13 17:47:30', '2025-12-13 17:51:13'),
(397, 5, 259, '<p>Fungsi eksponen adalah fungsi yang melibatkan perkalian berulang dan digunakan untuk menggambarkan pertumbuhan atau penurunan suatu nilai.</p>', NULL, '<p>Langkah penyelesaian dilakukan dengan memahami soal, menentukan nilai awal dan perubahan, menyusun model fungsi eksponen, lalu menghitung hasilnya.</p>', NULL, '<p>Strategi dipilih sesuai konteks masalah, yaitu menggunakan pertumbuhan jika nilainya bertambah dan peluruhan jika nilainya berkurang.</p>', NULL, '2025-12-13 17:50:32', '2025-12-13 17:51:26'),
(398, 3, 247, '<p>:Saya mengetahui bahwa trigonometri mempelajari hubungan sudut dan sisi pada segitiga siku-siku menggunakan perbandingan sinus, cosinus, dan tangen.</p><p><br></p>', NULL, '<p>Membaca soal dengan teliti, menggambar sketsa segitiga, menentukan sudut dan sisi yang diketahui, memilih perbandingan trigonometri yang sesuai, lalu menyusun perhitungan sebelum menghitung hasil akhirnya.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal, dengan mengidentifikasi informasi yang diketahui dan ditanya, lalu memilih rumus atau konsep matematika yang paling sesuai untuk menyelesaikannya.</p>', NULL, '2025-12-13 17:54:49', '2025-12-13 17:57:13'),
(399, 4, 258, '<p>Definisi persamaan kuadrat, tiga cara untuk menentukan akar-akar (penyelesaian) persamaan kuadrat, fungsi kuadrat dalam x berbentuk f(x)=ax^2+bx+c, dan diskriminan (D): Nilai D=b^2-4ac.</p>', NULL, '<p>Yaitu dengan memahami konteks masalah, identifikasi variabel-variabel yang ada, tentukan apa yang ditanyakan oleh soal, lalu memilih cara penyelesaian yang paling efektif.</p>', NULL, '<p>denga cara mengidentifikasi serta memodelkan apa yang diminta soal</p>', NULL, '2025-12-13 17:55:29', '2025-12-13 18:02:31'),
(400, 4, 216, '<p>Karakteristik fungsi kuadrat, menyelesaikan soal fungsi kuadrat</p>', NULL, '<ol><li>pahami soal dengan baik</li><li>pahami informasi dasar dalam soal</li><li>identifikasi pola atau hubungan anatara variabel variabel yang terlibat</li><li>gunakan pengetauhuan tentang sifat siafat kuadrat</li></ol>', NULL, '<p>Untuk menyelesaikan soal terkait fungsi kuadrat pertama tama pahami konsep dasarnya stelah memahami konsep dasar, gunakan berbagai metode seperti faktorisasi, melengkapkan kuadrat sempurna, gunakan rumus abac</p>', NULL, '2025-12-13 17:58:30', '2025-12-13 18:23:34'),
(401, 1, 336, '<p>yang saya ketahui dari materi pokok di atas bahwa eksponen ialah bilangan berpangkat dari suatu bilangan</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-13 17:59:39', '2025-12-13 17:59:39'),
(402, 6, 272, '<p>Vektor&nbsp;adalah konsep matematika yang menggambarkan besaran yang memiliki&nbsp;arah dan besar (magnitude). Artinya, vektor tidak hanya menunjukkan seberapa banyak sesuatu berubah, tetapi juga ke mana arah perubahannya. </p>', NULL, '<p>Baca soal dengan teliti, tentukan vektor yang terlibat, pisahkan vektor menjadi komponen, tentukan operasi yang diperlukan, gambar diagram vektor, tuliskan persamaan atau formula, periksa satuan dan arah, mulai perhitungan. </p><p><br></p>', NULL, '<p>Saat membaca soal. Identifikasi informasi penting, tentukan operasi yang dibutuhkan, pecah menjadi komponen, susun langkah perhitungan</p><p><br></p>', NULL, '2025-12-13 18:00:13', '2025-12-13 18:07:14'),
(403, 2, 267, '<p> saya sudah mengetahui bahwa persamaan linear adalah kalimat matematika yang memuat tanda sama dengan dan memiliki satu variabel berpangkat satu, dengan tujuan mencari nilai variabel yang memenuhi persamaan tersebut. </p>', NULL, '<p>langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti untuk memahami situasi masalah, menentukan informasi yang diketahui dan apa yang ditanyakan, menetapkan variabel yang mewakili besaran yang belum diketahui</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks masalah secara menyeluruh, kemudian menentukan variabel yang tepat untuk mewakili besaran yang belum diketahui</p>', NULL, '2025-12-13 18:02:06', '2025-12-13 18:04:22'),
(404, 5, 214, '<p>saya mengetahui fungsi eksponen, dan grafiknya dapat naik berdasarkan ketentuan tertentu dan sebaliknya</p><p><br></p>', NULL, '<p>meninjau soal cerita, lalu membentuk model fungsi eksponennya.</p>', NULL, '<p>Saya menguraikan informasi yang <strong>diketahui</strong> dan yang <strong>ditanyakan</strong> dari soal<span class=\"ql-cursor\">﻿﻿, lalu memilih rumus, setelah itu menggunakannya untuk mandapatkan solusi.</span></p>', NULL, '2025-12-13 18:12:24', '2025-12-13 18:18:06'),
(405, 6, 257, '<p>Yaitu tentang vektor, jenis-jenis vektor (negatif, nol, ekuivalen), serta operasi vektor dasar seperti penjumlahan dan perkalian skalar.</p>', NULL, '<p>Sebelum menghitung, langkah pertama adalah mengidentifikasi besaran vektor yang terlibat (seperti perpindahan atau kecepatan) dan menentukan operasi vektor apa yang diperlukan (tambah, kurang, atau kali skalar) sesuai konteks masalah.</p>', NULL, '<p>Strategi muncul saat konteks masalah diketahui; jika melibatkan penentuan resultan total, gunakan penjumlahan (metode poligon/aljabar). Jika mencari perbedaan posisi/jarak, gunakan pengurangan vektor.</p>', NULL, '2025-12-13 18:14:11', '2025-12-13 18:15:00'),
(406, 3, 305, '<p>saya mempelajari serta memahami bagaimana hubungan sudut dan&nbsp;sisi pada segitiga siku-siku.</p>', NULL, '<p>saya mengidentifikasi hal-hal yang diketahui seperti besar sudut yang diketahui, kemudian saya menganalisis rumus yang akan saya gunakan, dan mulau menyelesaikan soal</p>', NULL, '<p>saya menggunakan strategi dalam menyelesaikan soal dengan memahami soal dengan cara menentukan informasi yang diketahui, memilih rumus yang tepat, dan melakukan perhitungan secara teliti sehingga diperoleh jawaban yang benar.</p>', NULL, '2025-12-13 18:15:20', '2025-12-13 18:32:55'),
(407, 4, 267, '<p>saya sudah mengetahui bahwa fungsi kuadrat adalah fungsi berbentuk f(x)=ax2+bx+cf(x)=ax^2+bx+cf(x)=ax2+bx+c dengan a≠0a, dan grafiknya berupa parabola yang dapat terbuka ke atas atau ke bawah tergantung tanda koefisien a.</p>', NULL, '<p> langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti untuk memahami konteks permasalahan, menentukan apa saja informasi yang diketahui dan apa yang ditanyakan, menetapkan variabel yang sesuai</p>', NULL, '<p>Saya memiliki strategi dengan memahami terlebih dahulu konteks masalah secara menyeluruh, kemudian menentukan variabel dan membentuk model fungsi kuadrat yang sesuai dengan situasi pada soal. </p>', NULL, '2025-12-13 18:16:10', '2025-12-13 18:17:34'),
(408, 6, 259, '<p>Vektor adalah besaran yang dicirikan oleh nilai (besar) dan arah, yang operasi dasarnya meliputi penjumlahan, pengurangan, perkalian dengan skalar, perkalian titik (dot product), dan perkalian silang (cross product) .</p>', NULL, '<p>Langkah-langkahnya adalah memahami soal, mengidentifikasi, merepresentasikan vektor dalam komponen, menentukan operasi yang sesuai, dan merumuskan persamaan sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi dipilih berdasarkan tujuan soal: menggunakan penjumlahan untuk resultan, perkalian titik untuk sudut/proyeksi, dan perkalian silang untuk vektor tegak lurus, dengan menerapkan rumus operasi yang relevan.</p>', NULL, '2025-12-13 18:16:12', '2025-12-13 18:19:31'),
(409, 1, 308, '<p>Materi ini mendefinisikan eksponen sebagai bentuk ringkas perkalian berulang dengan aturan operasi khusus yang digunakan untuk memodelkan fenomena pertumbuhan cepat, seperti penyebaran virus.</p>', NULL, '<p>Identifikasi pola perkalian berulang dari cerita, susun datanya dalam tabel, lalu ubah menjadi bentuk pangkat untuk menentukan apa yang dicari .</p>', NULL, '<p>Ubah cerita menjadi tabel untuk melihat pola perkalian, lalu modelkan ke dalam bentuk pangkat (a^n) untuk menemukan solusinya.</p>', NULL, '2025-12-13 18:21:01', '2025-12-13 18:24:48'),
(410, 4, 202, '<ol><li>definisi fungsi kuadrat</li><li>karakteristik fungsi kuadrat</li><li>bentuk umum persamaan kuadrat</li><li>menyelesaikan persamaan kuadrat</li></ol>', NULL, '<p>Memahami soal</p><p>Menentukan data yang diketahui</p><p>Menentukan apa yang ditanyakan</p><p>Menetapkan variabel</p><p>Membuat model fungsi kuadrat</p><p>Menentukan metode penyelesaian</p><p>Menafsirkan hasil sesuai konteks soal</p><p><br></p>', NULL, '<p>Memahami konteks masalah, Mengidentifikasi informasi yang diketahui dan ditanyakan, Menetapkan variabel, Membuat model fungsi kuadrat, Memilih metode penyelesaian dan Menafsirkan dan memeriksa hasil,</p>', NULL, '2025-12-13 18:22:40', '2025-12-13 18:30:45'),
(411, 4, 241, '<ol><li>Definisi fungsi kuadrat</li><li>Karakteristik fungsi kuadrat</li><li>Bentuk umum persamaan kuadrat</li><li>Menyelesaikan persamaan kuadrat</li></ol>', NULL, '<p>Memahami soal, Menentukan data yang diketahui, Menentukan apa yang ditanyakan, Menetapkan variabel, Membuat model fungsi kuadrat, Menentukan metode penyelesaian, Dan menafsirkan hasil sesuai konteks soal</p><p><br></p>', NULL, '<p>Memahami konteks masalah, Mengidentifikasi informasi yang diketahui dan ditanyakan, Menetapkan variabel, Membuat model fungsi kuadrat, Memilih metode penyelesaian dan Menafsirkan dan memeriksa hasil</p>', NULL, '2025-12-13 18:22:45', '2025-12-13 18:31:30'),
(412, 1, 245, '<p>Materi ini adalah tentang Perkalian Berulang atau Eksponen. Perkalian berulang adalah perkalian yang dilakukan secara berulang dengan faktor yang sama</p>', NULL, '<p>Pahami soal untuk mengidentifikasi bilangan pokok (basis) dan jumlah pengulangan (pangkat).</p><p>​Tuliskan model matematikanya dalam bentuk bilangan berpangkat (a^n).</p><p>​Hitung hasil perkalian berulang untuk mendapatkan nilai akhir.</p>', NULL, '<p>Strateginya adalah menerapkan sifat-sifat eksponen (seperti penjumlahan pangkat saat perkalian, atau perkalian pangkat saat dipangkatkan) untuk menyederhanakan perhitungan sebelum mencari nilai akhirnya.</p>', NULL, '2025-12-13 18:24:57', '2025-12-13 18:29:48'),
(413, 4, 255, '<p>Fungsi Kuadrat merupakan fungsi yang berpangkat tertinggi dua, dan representasi visualnya adalah parabola .Elemen penting yang membentuk fungsi ini adalah titik-titik potong dengan sumbu koordinat, garis sumbu simetri, dan titik puncak</p>', NULL, '<p>Langkah awal penyelesaian soal cerita adalah pemodelan, yaitu mengubah narasi masalah menjadi bentuk fungsi kuadrat yang benar</p>', NULL, '<p>Strategi utama saya adalah menyesuaikan metode berdasarkan kebutuhan soal</p>', NULL, '2025-12-13 18:25:25', '2025-12-13 18:27:47'),
(414, 3, 273, '<p>saya dapat memahami mengenai perbandingan trigonometri dan cara penyelesaiannya.</p>', NULL, '<p>yaitu pahami dan analisis soaal cerita, rumuskan ke model matematika, selesaikan persamaan fungsi, dan interpretasikan hasil akhir.</p>', NULL, '<p>yaitu dengan memahami masalah dari soal tersebut, memformulasikan model matematika, menyelesaikan model matematika, lalu tafsirkan hasilnya.</p>', NULL, '2025-12-13 18:26:04', '2025-12-13 18:33:06'),
(415, 6, 258, '<p>Yaitu tentang vektor, jenis-jenis vektor (negatif, nol, ekuivalen), serta operasi vektor dasar seperti penjumlahan dan perkalian skalar.</p>', NULL, '<p>Sebelum menghitung, langkah pertama adalah mengidentifikasi besaran vektor yang terlibat (seperti perpindahan atau kecepatan) dan menentukan operasi vektor apa yang diperlukan (tambah, kurang, atau kali skalar) sesuai konteks masalah.</p>', NULL, '<p>Strategi muncul saat konteks masalah diketahui; jika melibatkan penentuan resultan total, gunakan penjumlahan (metode poligon/aljabar). Jika mencari perbedaan posisi/jarak, gunakan pengurangan vektor.</p>', NULL, '2025-12-13 18:31:04', '2025-12-13 18:32:13'),
(416, 1, 244, '<p>Materi ini adalah tentang Perkalian Berulang atau Eksponen. Perkalian berulang adalah perkalian yang dilakukan secara berulang dengan faktor yang sama.</p>', NULL, '<p>Pahami soal untuk mengidentifikasi bilangan pokok (basis) dan jumlah pengulangan (pangkat).</p><p>​Tuliskan model matematikanya dalam bentuk bilangan berpangkat (a^n).</p><p>​Hitung hasil perkalian berulang untuk mendapatkan nilai akhir.</p>', NULL, '<p>Strateginya adalah menerapkan sifat-sifat eksponen (seperti penjumlahan pangkat saat perkalian, atau perkalian pangkat saat dipangkatkan) untuk menyederhanakan perhitungan sebelum mencari nilai akhirnya.</p>', NULL, '2025-12-13 18:37:22', '2025-12-13 18:39:50'),
(417, 3, 329, '<p>yang saya ketahui yaitu Hubungan Sudut dan Sisi Dari Segitiga Siku-Siku, Perbandingan Trigonometri Untuk Sudut Lancip, Hubungan Antara Sinus dan Cosinus Untuk Sudut Penyiku, Perbandingan Trignometri dan Teorema Phytagoras</p>', NULL, '<p>langkah langkahnya yaitu memahami dan menganalisis soal cerita, selanjutnya membuat representasi visual lalu menentukan konsep dan rumus trigonometri terakhir menyusun persamaan matematika</p>', NULL, '<p>Saya memiliki strategi penyelesaian soal matematika setiap kali saya menerima pertanyaan yang menyajikan suatu konteks masalah (soal cerita) atau memerlukan penerapan konsep matematika tertentu, seperti aljabar, kalkulus, atau trigonometri.</p>', NULL, '2025-12-13 18:42:34', '2025-12-13 18:47:35'),
(418, 5, 267, '<p>Dari materi fungsi eksponen, saya mengetahui bahwa fungsi eksponen adalah fungsi yang variabelnya berada pada pangkat, biasanya berbentuk f(x)=axf(x) = a^xf(x)=ax dengan a&gt;0a &gt; 0a&gt;0 dan a≠1a</p>', NULL, '<p>sebelum mulai menghitung adalah membaca soal dengan cermat untuk memahami konteks permasalahan, menentukan informasi yang diketahui dan apa yang ditanyakan,</p>', NULL, '<p>Saya memiliki strategi untuk menyelesaikan soal sesuai konteks masalah matematika setelah memahami isi soal dengan baik, yaitu ketika saya sudah mengetahui apa yang diketahui, apa yang ditanyakan, serta konsep matematika yang berkaitan.</p>', NULL, '2025-12-13 18:44:03', '2025-12-13 18:45:27'),
(419, 5, 327, '<p>definisi fungsi eksponen dan sifat sifat grafik fungsi eksponen </p>', NULL, '<p>membaca soal cerita dengan teliti,mengenali besaran yang berubah secara eksponensial, menentukan yang diketahui dan ditanyakan,memodelkan masalah ke bentuk fungsi eksponen,dan  perhitungan dilakukan sesuai konteks soal.</p>', NULL, '<p>memahami konteks masalah dan tujuan yang ingin dicapai. mengidentifikasi informasi penting, memilih konsep matematika yang sesuai,  merencanakan langkah penyelesaian sebelum melakukan perhitungan. </p>', NULL, '2025-12-13 18:44:37', '2025-12-13 18:49:40');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(420, 5, 258, '<p> Fungsi eksponensial adalah fungsi yang variabelnya berada pada pangkat. Ada dua jenis utama, yaitu pertumbuhan eksponensial dan peluruhan eksponensial.</p>', NULL, '<p>Membaca soal dengan cermat, menentukan besaran awal, mengidentifikasi rasio perubahan pada setiap periode waktu, menyusun satuan waktu atau fase, dan kemudian menyusun model matematika dalam bentuk fungsi eksponensial yang sesuai.</p>', NULL, '<p>Sesuaikan model fungsi dengan situasi nyata, kaitkan makna variabel x dengan konteks, kemudian cek kembali hasil perhitungan.</p>', NULL, '2025-12-13 18:49:09', '2025-12-13 18:51:07'),
(421, 6, 214, '<p>Vektor  memiliki besar dan arah, dan dapat dioperasikan secara geometris dan aljabar, serta digunakan untuk menentukan hasil kali skalar dan sudut antara dua vektor.</p>', NULL, '<p>Mengidentifikasi besaran vektor yang diketahui dan ditanyakan, menentukan model atau operasi vektor yang tepat, lalu menyiapkan representasi vektor seblum melakukan perhitungan.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks dan tujuan soal, dengan menyesuaikan konsep serta metode matematika yang paling relevan agar penyelesaian berjalan efektif dan tepat.</p>', NULL, '2025-12-13 18:50:30', '2025-12-13 19:05:06'),
(422, 6, 267, '<p>Dari materi vektor, saya mengetahui bahwa vektor adalah besaran yang memiliki <strong>nilai (besar)</strong> dan <strong>arah</strong>, yang dapat dinyatakan dalam bentuk panah, pasangan koordinat, atau komponen. </p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan untuk menyelesaikan soal cerita matematika pada topik vektor sebelum mulai menghitung hasil akhirnya adalah membaca soal dengan cermat untuk memahami situasi dan arah yang terlibat</p>', NULL, '<p>Saya memiliki strategi untuk menyelesaikan soal sesuai konteks masalah matematika setelah memahami isi soal secara menyeluruh, yaitu ketika saya sudah mengetahui informasi yang diberikan, apa yang ditanyakan</p>', NULL, '2025-12-13 19:00:54', '2025-12-13 19:01:59'),
(423, 5, 255, '<p>Fungsi eksponen adalah fungsi dengan variabel sebagai pangkat, di mana grafiknya selalu melewati titik nol koma satu dan memiliki sifat monoton (selalu naik atau turun) serta mendekati sumbu horizontal.</p>', NULL, '<p>Sebelum menghitung, pahami konteks soal (pertumbuhan atau peluruhan), identifikasi nilai awal dan laju perubahan untuk menyusun model fungsi eksponen yang benar, kemudian tentukan tujuan akhir perhitungan.</p>', NULL, '<p>Strategi penyelesaian digunakan ketika masalah melibatkan perubahan nilai yang berlipat ganda atau berkurang secara proporsional, di mana model pertumbuhan dipilih untuk peningkatan dan model peluruhan dipilih untuk penurunan nilai.</p>', NULL, '2025-12-13 19:04:17', '2025-12-13 19:05:14'),
(424, 3, 259, '<p>Perbandingan trigonometri adalah perbandingan sisi-sisi pada segitiga siku-siku yang meliputi sinus, cosinus, dan tangen, yang digunakan untuk menentukan panjang sisi atau besar sudut.</p>', NULL, '<p>Memahami masalah, membuat sketsa segitiga, menentukan sudut dan sisi yang diketahui, memilih perbandingan trigonometri yang tepat, lalu melakukan perhitungan.</p>', NULL, '<p>Strategi dipilih sesuai dengan informasi yang diketahui dalam soal, misalnya menggunakan sinus jika yang diketahui sisi depan sudut, cosinus untuk sisi samping, dan tangen untuk perbandingan sisi depan dan samping.</p>', NULL, '2025-12-13 19:05:03', '2025-12-13 19:08:56'),
(425, 1, 306, '<p>Eksponen adalah bilangan berpangkat yang menyatakan perkalian berulang suatu bilangan. Konsep ini memiliki aturan dan sifat tertentu untuk menyederhanakan bentuk aljabar.</p>', NULL, '<p>Langkah yang dilakukan adalah memahami isi soal, menentukan informasi yang diketahui dan ditanyakan, memilih sifat eksponen yang sesuai, mengubah soal ke dalam model matematika, lalu menyederhanakan bentuk aljabar sebelum menghitung hasil akhirnya.</p>', NULL, '<p>Strategi yang digunakan adalah menyesuaikan sifat eksponen dengan konteks masalah agar penyelesaian tepat dan sesuai tujuan soal.</p>', NULL, '2025-12-13 19:05:40', '2025-12-13 19:19:24'),
(426, 6, 209, '<p>Saya memahami bahwa vektor adalah besaran yang memiliki nilai dan arah, dan dapat dinyatakan dalam bentuk komponen, digambar secara geometris, dioperasikan melalui penjumlahan, pengurangan, dan perkalian dengan skalar untuk memecahkan masalah.</p>', NULL, '<p>Yaitu membaca soal dengan cermat, mengidentifikasi informasi yang diketahui, memodelkan masalah ke dalam bentuk vektor (arah dan komponennya), lalu menentukan rumus atau operasi vektor yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Yaitu dengan melihat hubungan antar vektor dan tujuan yang ingin dicari. Strategi diterapkan dengan memilih metode yang paling sederhana, misalnya menggunakan komponen vektor atau diagram, agar penyelesaian lebih efektif dan tepat.</p>', NULL, '2025-12-13 19:05:48', '2025-12-13 19:09:55'),
(427, 4, 339, '<p>Fungsi kuadrat (f(x) = ax^2 + bx + c) menghasilkan grafik parabola, di mana titik puncak (-b/2a}, -D/4a) menentukan nilai maksimum atau minimum fungsi tersebut.</p>', NULL, '<p>Langkah utamanya adalah membuat model matematika yang benar (f(x) = ax^2 + bx + c), dengan mengidentifikasi variabel dan batasan dari soal cerita, sebelum menentukan perhitungan yang relevan (titik puncak atau akar).</p>', NULL, '<p>Strateginya yaitu, mencari nilai optimal (maks/min) : Hitung y titik puncak (-D/4a), mencari input x optimal (misal: waktu) : Hitung sumbu simetri (x = -b/2a), dan mencari titik nol :  Gunakan pemfaktoran atau Rumus ABC.</p><p><br></p>', NULL, '2025-12-13 19:08:51', '2025-12-13 19:12:41'),
(428, 3, 286, '<p>Definisi trigonometri dan manfaatnya dalam kehidupan sehari- hari</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-13 19:09:56', '2025-12-13 19:09:56'),
(429, 3, 207, '<p>Segitiga siku-siku punya sudut 90°. Ada 3 sisi: dua kaki dan sisi miring (terpanjang). Teorema Pythagoras (a²+b²=c²) buat cari sisi. Dua sudut lain lancip, jumlah 90°. Ada sin, cos, tan untuk hubungkan sudut dan sisi.</p>', NULL, '<p>Baca soal dengan teliti, catat yang diketahui &amp; ditanyakan. Pilih rumus yang pas (Pythagoras atau sin/cos/tan), masukkan angka, hitung, lalu cek apakah jawaban masuk akal.</p>', NULL, '<p>Saya memilih strategi sesuai jenis soal dan info yang ada. Cari sisi pakai Pythagoras, cari sudut/sisi pakai sin/cos/tan. Kadang perlu gambar, kalau soal sulit saya akan memecahnya menjadi langkah kecil.</p>', NULL, '2025-12-13 19:11:44', '2025-12-13 19:18:35'),
(430, 5, 203, '<p>Fungsi eksponen adalah <strong>fungsi berbentuk f(x)=axf(x)=a^xf(x)=ax</strong> yang menunjukkan <strong>pertumbuhan atau peluruhan</strong>, grafiknya selalu positif, dan banyak digunakan dalam masalah kehidupan sehari-hari.</p>', NULL, '<p><strong>memahami konteks soal, menentukan data yang diketahui dan ditanyakan, memisalkan variabel, membentuk model fungsi eksponen yang sesuai, lalu menentukan metode penyelesaian sebelum melakukan perhitungan</strong>.</p>', NULL, '<p>Strategi ditentukan <strong>sejak awal setelah memahami konteks soal</strong>, dengan cara <strong>mengidentifikasi konsep yang digunakan, menentukan variabel, dan menyusun model matematika yang sesuai dengan masalah</strong>.</p><p><br></p>', NULL, '2025-12-13 19:14:39', '2025-12-13 19:16:24'),
(431, 3, 303, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan panjang sisi pada segitiga siku-siku melalui perbandingan sinus, cosinus, dan tangen, yang dapat digunakan untuk menyelesaikan berbagai masalah dalam kehidupan sehari-hari.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanyakan, membuat sketsa, menentukan sisi dan sudut, lalu memilih perbandingan trigonometri yang sesuai.</p><p><br></p>', NULL, '<p>Saya memiliki strategi penyelesaian setelah memahami konteks soal, dengan menentukan apa yang diketahui dan ditanyakan, membuat sketsa, lalu memilih rumus atau konsep matematika yang sesuai dengan masalah tersebut.</p>', NULL, '2025-12-13 19:17:15', '2025-12-13 19:21:18'),
(432, 5, 205, '<p>Saya memahami bahwa eksponen adalah perkalian berulang yang digunakan untuk memodelkan pertumbuhan dan peluruhan melalui fungsi eksponensial.</p>', NULL, '<p>Sebaiknya saya membaca soal dengan teliti, memahami apa yang diketahui dan ditanyakan, lalu menentukan model matematika yang tepat sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi setelah memahami konteks soal, dengan cara menentukan konsep atau rumus yang sesuai dengan masalah, lalu menyusun langkah penyelesaian secara runtut sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 19:23:24', '2025-12-13 19:25:09'),
(433, 1, 246, '<ol><li>Eksponen menyederhanakan perkalian berulang</li><li>Pertumbuhan eksponen berlangsung sangat cepat</li><li>Banyak masalah nyata dapat dimodelkan dengan eksponen</li><li>Sifat-sifat eksponen mempermudah perhitungan matematika yang kompleks</li></ol>', NULL, '<ol><li>Membaca soal dengan cermat</li><li>Menentukan apa yang diketahui</li><li>Menentukan apa yang ditanyakan</li><li>Mengidentifikasi pola matematika</li><li>Menyusun model matematika</li><li>Memeriksa kembali model yang dibuat</li></ol><p><br></p>', NULL, '<p>strateginya adalah memahami konteks soal, menentukan pola, memodelkannya dalam bentuk eksponen, lalu menafsirkan hasil sesuai dengan konteks</p>', NULL, '2025-12-13 19:27:26', '2025-12-13 19:44:58'),
(434, 3, 267, '<p>. Perbandingan tersebut meliputi sinus (sin), cosinus (cos), dan tangen (tan), yang masing-masing merupakan perbandingan sisi depan terhadap sisi miring, sisi samping terhadap sisi miring, dan sisi depan terhadap sisi samping. </p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan untuk menyelesaikan soal cerita matematika pada topik perbandingan trigonometri sebelum mulai menghitung hasil akhirnya adalah membaca soal dengan cermat untuk memahami situasi dan sudut yang terlibat.</p>', NULL, '<p>Saya memiliki strategi untuk menyelesaikan soal sesuai konteks masalah matematika setelah memahami soal secara menyeluruh, yaitu ketika saya sudah mengetahui informasi yang diberikan, apa yang ditanyakan, serta konsep matematika yang berkaitan,</p>', NULL, '2025-12-13 19:27:30', '2025-12-13 19:28:46'),
(435, 6, 203, '<p>dapat dinyatakan dalam komponen, dioperasikan dengan penjumlahan, pengurangan, dan perkalian skalar, serta digunakan untuk menyelesaikan masalah posisi, perpindahan, dan gaya.</p><p><br></p>', NULL, '<p><strong>memahami konteks soal vektor, menentukan besaran dan arah yang diketahui serta ditanyakan, memisalkan vektor dengan tepat, memilih model atau operasi vektor yang sesuai, lalu merencanakan perhitungan sebelum menghitung hasil akhir</strong>.</p>', NULL, '<p>Strategi ditentukan <strong>sejak awal setelah memahami konteks soal</strong>, dengan cara <strong>mengidentifikasi konsep yang digunakan dan memilih model atau operasi matematika yang sesuai</strong>.</p><p><br></p>', NULL, '2025-12-13 19:28:38', '2025-12-13 19:30:29'),
(436, 1, 252, '<p>ekspresi eksponen</p>', NULL, '<p>1.Membaca dan memahami soal</p><p>2.Menentukan informasi yang diketahui dan yang ditanyakan</p><p>3.Mengubah soal cerita ke model matematika</p><p>4.Menentukan konsep atau rumus yang digunakan</p><p>5.Menyusun langkah penyelesaian</p>', NULL, '<ol><li>Memahami masalah dan konteks soal</li><li>Mengidentifikasi informasi yang diketahui dan ditanyakan</li><li>Menentukan konsep, rumus, atau strategi yang sesuai</li><li>Melakukan perhitungan dengan teliti</li></ol><p><br></p><p><br></p>', NULL, '2025-12-13 19:29:14', '2025-12-14 00:41:11'),
(437, 2, 244, '<p>menguasai SPL (SPLDV, SPLTV), metode penyelesaiannya (Eliminasi, Substitusi, Sarrus), dan SPtLDV serta penentuan Daerah Penyelesaian (DP) melalui grafik dan uji titik.</p>', NULL, '<p>Proses penyelesaian soal dilakukan dengan menentukan variabel, menyusun model matematika (SPL/SPtL), lalu memilih metode penyelesaian yang paling efisien (substitusi, eliminasi, Sarrus, atau grafik).</p>', NULL, '<p>​Untuk SPL, Anda menggunakan Eliminasi dan Substitusi (atau Metode Sarrus untuk SPLTV) guna menemukan nilai variabel. Sedangkan untuk SPtLDV, Anda mengandalkan Metode Grafik dan Uji Titik untuk mengidentifikasi Daerah Penyelesaian (DP).</p>', NULL, '2025-12-13 19:34:31', '2025-12-13 19:36:52'),
(438, 6, 255, '<p>Vektor adalah besaran yang memiliki besar dan arah serta dapat dinyatakan dalam bentuk panah atau komponen.</p>', NULL, '<p>Membaca soal, menuliskan vektor dalam bentuk komponen, memilih operasi yang sesuai, lalu menghitung hasilnya.</p>', NULL, '<p>Strategi dipilih sesuai jenis soal, misalnya diagram vektor untuk perpindahan dan metode komponen untuk soal koordinat.</p>', NULL, '2025-12-13 19:35:33', '2025-12-13 19:36:29'),
(439, 2, 245, '<p>yang saya ketahui adalah cara menguasai SPL (SPLDV, SPLTV), metode penyelesaiannya (Eliminasi, Substitusi, Sarrus), dan SPtLDV serta penentuan Daerah Penyelesaian (DP) melalui grafik dan uji titik.</p>', NULL, '<p>Proses penyelesaian soal dilakukan dengan menentukan variabel, menyusun model matematika (SPL/SPtL), lalu memilih metode penyelesaian yang paling efisien (substitusi, eliminasi, Sarrus, atau grafik).</p>', NULL, '<p>Untuk SPL, Anda menggunakan Eliminasi dan Substitusi (atau Metode Sarrus untuk SPLTV) guna menemukan nilai variabel. Sedangkan untuk SPtLDV, Anda mengandalkan Metode Grafik dan Uji Titik untuk mengidentifikasi Daerah Penyelesaian (DP).</p>', NULL, '2025-12-13 19:35:42', '2025-12-13 19:36:48'),
(440, 5, 339, '<p>Modelkan masalah ke f(x) = ax^2 + bx + c. Hitung Titik Puncak (optimal) atau Akar-akar (titik nol).</p>', NULL, '<p>Pastikan Model benar dan Rumus yang dipakai tepat (-b/2a untuk input optimal, -D/4a untuk nilai optimal).</p>', NULL, '<p>Lakukan Verifikasi (substitusi balik) dan Validasi Logis (hasil harus positif dan masuk akal sesuai konteks).</p>', NULL, '2025-12-13 19:37:19', '2025-12-13 19:38:52'),
(441, 3, 214, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi segitiga, khususnya segitiga siku-siku, dan digunakan untuk menentukan panjang sisi atau besar sudut dalam berbagai permasalahan sehari-hari.</p>', NULL, '<p>Langkah yang sebaiknya dilakukan adalah memahami cerita soal, menuliskan informasi yang diketahui dan ditanya, menggambar sketsa jika perlu, menentukan perbandingan trigonometri yang sesuai, lalu baru melakukan perhitungan.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal, dengan mengidentifikasi apa yang diketahui dan ditanya, lalu memilih konsep atau rumus yang paling sesuai sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 19:45:17', '2025-12-13 19:47:00'),
(442, 3, 304, '<p>Konsep utama dalam materi perbandingan trigonometri adalah hubungan antara panjang sisi-sisi segitiga dengan besarnya sudut-sudut dalam segitiga tersebut.</p>', NULL, '<p>pertama saya akan menentukan data yang diketahui dan ditanyakan, serta membuat sketsa untuk melihat hubungan sudut dan sisi. kemudian saya memilih perbandingan trigonometri yang sesuai, kemudian melakukan perhitungan untuk memperoleh jawaban.</p>', NULL, '<p>saya menggunakan strategi dalam menyelesaikan soal dengan memahami soal dengan cara menentukan informasi yang diketahui, memilih rumus yang tepat, dan melakukan perhitungan secara teliti sehingga diperoleh jawaban yang benar.</p>', NULL, '2025-12-13 19:45:54', '2025-12-13 19:53:02'),
(443, 3, 203, '<p>saya mengetahui bahwa <strong>sin, cos, dan tan adalah perbandingan sisi-sisi segitiga siku-siku terhadap sudut tertentu</strong></p>', NULL, '<p>Langkah-langkahnya adalah <strong>memahami konteks soal, menggambar atau memodelkan segitiga, menentukan sudut dan sisi yang diketahui serta ditanyakan,&nbsp;</strong></p>', NULL, '<p>Strategi ditentukan <strong>sejak awal setelah memahami konteks soal</strong>, dengan cara <strong>mengidentifikasi besaran yang diketahui,&nbsp;</strong></p>', NULL, '2025-12-13 19:51:57', '2025-12-13 19:54:07'),
(444, 6, 205, '<p>Saya memahami bahwa vektor memiliki besar dan arah, dapat direpresentasikan dalam bentuk komponen, serta dapat dioperasikan dan digunakan untuk menggambarkan perpindahan dan arah dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang sebaiknya saya lakukan adalah membaca soal dengan teliti, memahami konteks dan informasi yang diberikan, menentukan konsep atau rumus vektor yang sesuai, lalu menyusun rencana penyelesaian sebelum melakukan perhitungan.</p>', NULL, '<p>Saya memiliki strategi setelah memahami konteks soal, dengan cara mengidentifikasi konsep matematika yang tepat lalu menyusun langkah penyelesaian secara runtut sebelum menghitung.</p>', NULL, '2025-12-13 19:52:52', '2025-12-13 19:53:55'),
(445, 5, 216, '<p>sifat sifat grafik fungsi eksponen</p>', NULL, '<ol><li>pahami soal dengan baik</li><li>identifikasi konsep fungsi eksponen yang relevan</li><li>rumuskan persamaan matematka yang tepat</li></ol>', NULL, '<p>Ketika dihadapkan pada soal matematika yang melibatkan fungsi eksponen. strategi yang bisa di terapkan pertama pahami dahulu konsep dasar dari fungsi eksponen, kembangkan strategi yang tepat untuk menyelesaikan soal soal matematika tersebut</p>', NULL, '2025-12-13 19:56:47', '2025-12-13 20:02:27'),
(446, 3, 309, '<p>Saya mengetahui bahwa <strong>trigonometri mempelajari hubungan sudut dan sisi segitiga siku-siku melalui sin, cos, dan tan untuk menghitung jarak dan tinggi</strong>.</p><p><br></p>', NULL, '<p>Memahami soal, menentukan sudut dan sisi yang diketahui, memilih perbandingan trigonometri yang sesuai, lalu menyusun model perhitungan sebelum menghitung hasil akhir.</p>', NULL, '<p>Saya memiliki strategi <strong>setelah memahami konteks soal</strong>, dengan <strong>menentukan informasi yang diketahui, tujuan yang dicari, lalu memilih metode matematika yang paling sesuai</strong> dengan permasalahan.</p>', NULL, '2025-12-13 19:58:45', '2025-12-13 20:00:38'),
(447, 1, 266, '<p>Saya telah memahami bahwa eksponen merupakan cara penulisan bilangan berpangkat yang menunjukkan perkalian berulang.</p>', NULL, '<p>1. Membaca soal dengan teliti dan mengidentifikasi bentuk eksponen yang digunakan.</p><p>2. Menentukan sifat-sifat eksponen yang sesuai, lalu menghitung hingga diperoleh hasil akhir.</p>', NULL, '<p>saya akan menyederhanakan bilangan ke bentuk pangkat yang sama, kemudian menerapkan sifat-sifat eksponen agar perhitungan lebih mudah dan cepat.</p>', NULL, '2025-12-13 20:05:35', '2025-12-13 20:11:12'),
(448, 1, 303, '<p>Materi ini membahas eksponen (bilangan berpangkat) sebagai cara menyederhanakan perkalian berulang serta penerapannya untuk memodelkan pertumbuhan dan peluruhan dalam kehidupan sehari-hari.</p>', NULL, '<p>Baca soal → tentukan yang diketahui &amp; ditanya → buat model eksponen → gunakan sifat eksponen → hitung hasil.</p><p><br></p><p><br></p>', NULL, '<p>Menentukan informasi yang diketahui, memodelkannya ke bentuk eksponen yang sesuai, lalu menerapkan sifat-sifat eksponen untuk menyelesaikan masalah sesuai konteks.</p>', NULL, '2025-12-13 20:07:16', '2025-12-13 20:09:56'),
(449, 1, 305, '<p>Materi ini membahas eksponen (bilangan berpangkat) sebagai cara menyederhanakan perkalian berulang serta penerapannya untuk memodelkan pertumbuhan dan peluruhan dalam kehidupan sehari-hari.</p>', NULL, '<p>Baca soal → tentukan yang diketahui &amp; ditanya → buat model eksponen → gunakan sifat eksponen → hitung hasil.</p>', NULL, '<p>Menentukan informasi yang diketahui, memodelkannya ke bentuk eksponen yang sesuai, lalu menerapkan sifat-sifat eksponen untuk menyelesaikan masalah sesuai konteks.</p>', NULL, '2025-12-13 20:14:43', '2025-12-13 20:15:30'),
(450, 1, 304, '<p>Materi ini membahas eksponen (bilangan berpangkat) sebagai cara menyederhanakan perkalian berulang serta penerapannya untuk memodelkan pertumbuhan dan peluruhan dalam kehidupan sehari-hari.</p>', NULL, '<p>Baca soal → tentukan yang diketahui &amp; ditanya → buat model eksponen → gunakan sifat eksponen → hitung hasil.</p>', NULL, '<p>Menentukan informasi yang diketahui, memodelkannya ke bentuk eksponen yang sesuai, lalu menerapkan sifat-sifat eksponen untuk menyelesaikan masalah sesuai konteks.</p>', NULL, '2025-12-13 20:14:44', '2025-12-13 20:15:30'),
(451, 6, 327, '<p>Dfinisi vektor,notasi vektor dan operasi vektor</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, lalu merepresentasikan vektor dengan gambar atau komponen. Setelah itu, saya memilih operasi vektor yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Saya mulai memiliki strategi sejak pertama membaca soal dengan memahami konteks dan tujuan masalah. Strategi tersebut dibentuk dengan menentukan konsep yang tepat dan merencanakan langkah penyelesaian sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 20:14:54', '2025-12-13 20:19:21'),
(452, 4, 249, '<p>memiliki sumbu simetri, titik puncak (maksimum atau minimum), serta akar-akar yang dapat ditentukan dengan metode tertentu dan sering digunakan untuk menyelesaikan masalah dalam kehidupan sehari-hari.</p><p><br></p>', NULL, '<p><strong>Baca dan pahami soal</strong>.</p><p><strong>Tentukan variabel</strong> yang sesuai.</p><p><strong>Buat persamaan kuadrat</strong> dari informasi soal.</p><p><strong>Pilih metode penyelesaian</strong> </p>', NULL, '<p>memahami masalah, tentukan variabel, buat persamaan kuadrat sesuai konteks, selesaikan dengan metode yang tepat, dan periksa jawaban agar sesuai situasi soal.</p><p><br></p>', NULL, '2025-12-13 20:17:30', '2025-12-13 20:19:52'),
(453, 1, 217, '<p>Yang sudah saya ketahui pada materi eksponen adalah pengertian eksponen serta sifat-sifatnya, seperti perkalian dan pembagian bilangan berpangkat ,pangkat nol dan lainnya serta cara menyederhanakan eksponen</p>', NULL, '<p>Langkah-langkah yang saya lakukan dalam menyelesaikan soal pada topik ini adalah membaca soal dengan teliti, mengidentifikasi bentuk eksponen yang digunakan, menentukan sifat eksponen yang sesuai, dan menyederhanakan bentuk eksponen secara bertahap</p>', NULL, '<p>Saya memahami konteks soal terlebih dahulu, kemudian memilih sifat eksponen yang sesuai. Selanjutnya, saya menyederhanakan bentuk matematika, melakukan perhitungan, dan memeriksa kembali hasilnya agar sesuai dengan soal.</p>', NULL, '2025-12-13 20:21:40', '2025-12-13 20:28:31'),
(454, 1, 278, '<p>Eksponen adalah perkalian secara berulang ,lalu Sifat sifat eksponen, operasi eksponen dan cara menyelesaikan masalah eksponensial</p>', NULL, '<p>Bacalah soal dengan teliti untuk mengetahui informasi yang diberikan dan yang ditanyakan, lalu ubah ke dalam bentuk model eksponen.</p><p> Gunakan sifat-sifat eksponen yang sesuai untuk menghitung dan menuliskan jawabannya.</p><p><br></p>', NULL, '<p>Identifikasi informasi yang diketahui dan yang ditanyakan, lalu nyatakan masalah dalam bentuk eksponen.</p><p> Gunakan sifat-sifat eksponen yang tepat untuk menyelesaikan dan menafsirkan hasilnya.</p><p><br></p>', NULL, '2025-12-13 20:22:58', '2025-12-13 20:35:39'),
(455, 1, 238, '<ol><li> Defenisi eksponen adalah cara untuk menulis perkalian berulang dari suatu bilangan dengan dirinya sendiri contoh: 2^3 = 2x2x2</li><li>Sifat-sifat eksponen</li><li>Makna dalam kehidupan nyata</li><li>Jenis-jenis eksponen</li></ol>', NULL, '<p>Pahami konteks soal cerita, tentukan apa yang diketahui dan ditanya, ubah cerita ke bentuk matematika, tentukan aturan-aturan yang sesuai, susunlah langkah operasi eksponen, lakukan perhitungan, dan interpretasi kembali jawaban.</p>', NULL, '<p>Tentukan pola pertumbuhan atau struktur eksponen gunakan sifat eksponen secara tepat visualisasi atau pemetaan per fase cek kembali dengan contoh kecil dan sederhanakan dulu bentuk aljabarnya</p>', NULL, '2025-12-13 20:25:11', '2025-12-13 20:37:48'),
(456, 5, 202, '<ol><li>definisi fungsi eksponen</li><li>sifat sifat grafik fungsi eksponen</li><li>mengerjakan fungsi ekspoen</li><li>menyajikan grafik fungsi eksponen/ eksponensial</li></ol>', NULL, '<p>Baca soal dan pahami konteks, Identifikasi informasi, Tentukan apa yang ditanyakan, Tetapkan variabel, Buat model fungsi eksponen, Tentukan metode perhitungan sebelum menghitung.dan  Periksa hubungan hasil dengan konteks soal.</p>', NULL, '<p>Gunakan saat soal cerita melibatkan *pertumbuhan atau peluruhan eksponensial.</p><p>Buat persamaan fungsi, hitung dengan sifat eksponen/logaritma, dan pastikan hasil masuk akal sesuai konteks.</p>', NULL, '2025-12-13 20:26:07', '2025-12-13 20:30:42'),
(457, 5, 241, '<ol><li>Definisi fungsi eksponen</li><li>Sifat-sifat grafik fungsi eksponen</li><li>Mengerjakan fungsi eksponen</li><li>Menyajikan grafik fungsi eksponen/eksponensial</li></ol>', NULL, '<p>Baca soal dan pahami konteks, identifikasi informasi, tentukan apa yang ditanyakan, tetapkan variabel jika perlu, buat model fungsi eksponen, tentukan metode perhitungan sebelum menghitung, periksa hubungan hasil dengan konteks soal.</p><p><br></p>', NULL, '<p>Gunakan saat soal cerita melibatkan pertumbuhan atau peluruhan eksponensial.</p><p>Buat persamaan fungsi, hitung dengan sifat eksponen/logaritma, dan pastikan hasil masuk akal sesuai konteks.</p>', NULL, '2025-12-13 20:26:07', '2025-12-13 20:31:02'),
(458, 1, 293, '<ol><li>definisi eksponen</li><li>sifat-sifat eksponen</li></ol>', NULL, '<p>langkah-langkah yang saya gunakan yaitu : membaca soal dengan cermat, menentukan apa yang ditanyakan, mengubah soal cerita kedalam model matematika, menentukan konsep atau sifat eksponen yang tepat, dan menyusun rencana penyelesaian.</p>', NULL, '<p>Strategi menyelesaikan soal eksponen dilakukan dengan memahami konteks masalah, mengidentifikasi pola, mengubahnya ke bentuk eksponen, memilih sifat eksponen yang tepat, dan memastikan hasil sesuai dengan konteks soal.</p>', NULL, '2025-12-13 20:28:40', '2025-12-13 20:39:39'),
(459, 5, 208, '<p>yang telah saya ketahui mengenai topik ini adalah konsep/defenisi fungsi eksponen, bentuk, dan sifat sifat grafik fungsi eksponen</p>', NULL, '<ol><li>Tentu saja paham konsep soal matematika</li><li>menganalisis soal tersebut</li><li>melakukan langkah penyelesaian</li><li>dan menghitung hasil akhirnya</li></ol>', NULL, '<p>menyelesaikan soal setiap kali mendapatkan masalah matematika, strateginya</p><ol><li>Memahami konteks masalah</li><li>menganalisis masalahnya dan melakukan penyelesaian</li></ol>', NULL, '2025-12-13 20:30:05', '2025-12-13 20:35:40'),
(460, 6, 216, '<p>penerapan vektor dalam kehidupan sehari hari</p>', NULL, '<ol><li>pahami soal dengan baik</li><li>identifikasi masalah</li><li>tentukan strategi</li><li>hitung solusi</li><li>periksa kembali</li></ol>', NULL, '<p>Strategi penyelesaian soal diperlukan ketika menghadapi soal cerita atau soal kontekstual<strong> </strong>yang tidak bisa langsung diselesaikan dengan satu rumus</p>', NULL, '2025-12-13 20:30:35', '2025-12-13 20:34:07'),
(461, 6, 254, '<p>yang saya ketahui dari materi ini adalah tentang Definisi Vektor dan Operasi Vektor</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, lalu menyusun model matematika sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks soal, mengidentifikasi informasi yang diketahui dan ditanyakan, kemudian memilih konsep atau rumus yang sesuai dengan materi agar penyelesaian masalah tepat dan sistematis.</p>', NULL, '2025-12-13 20:30:58', '2025-12-13 20:31:47'),
(462, 5, 210, '<p><strong>Fungsi eksponensial</strong> adalah fungsi berpangkat di mana variabel berada di posisi pangkat. Materinya mencakup sifat dasar bilangan berpangkat dan penerapannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah-langkah utamanya adalah memahami masalah, merencanakan model (merumuskan rumus), lalu melaksanakan perhitungan untuk hasil akhir.&nbsp;</p>', NULL, '<p>Strategi dimiliki saat konteks masalah diidentifikasi, dan diimplementasikan dengan menyesuaikan model matematika yang tepat (misalnya, untuk pertumbuhan, persamaan, atau grafik).</p>', NULL, '2025-12-13 20:32:41', '2025-12-13 20:34:42'),
(463, 1, 275, '<p>Pada topik ini yang saya sudah ketahui adalah cara menyerhanakan  bentuk eksponen agar perhitungannya lebih mudah. kemudian Sifat-sifat eksponen serta definisi bentuk eksponen.</p>', NULL, '<p>Langkah yang pertama Ialah baca dan pahami soal cerita terlebih dahulu, kemudian saya tentukan sifat eksponen mana yang digunakan dan langkah terakhir yaitu menyederhanakan.</p>', NULL, '<p>Strategi saya ialah memahami soal dan menentukan apa yang diketahui dan yang ditanyakan terkebih dahulu. setelah itu memilih sifat eksponen yang sesuai dan menyederhanakan.</p>', NULL, '2025-12-13 20:40:25', '2025-12-13 20:55:21'),
(464, 2, 305, '<p>Materi ini membahas cara menentukan solusi persamaan dan pertidaksamaan linear, termasuk sistemnya dengan metode substitusi, eliminasi, dan grafik.</p>', NULL, '<p>Langkahnya adalah memahami soal, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat sebelum menghitung.</p>', NULL, '<p>Saya menyelesaikan soal dengan memahami konteks, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode yang tepat.</p><p><br></p>', NULL, '2025-12-13 20:40:50', '2025-12-13 20:44:10'),
(465, 3, 255, '<p>trigonometri sebagai hubungan antara sudut dan sisi segitiga siku-siku. Saya mengetahui perbandingan trigonometri seperti sinus, cosinus, dan tangen, serta cara menentukan nilai sudut atau panjang sisi segitiga</p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan dalam menyelesaikan soal cerita trigonometri adalah memahami permasalahan, menentukan informasi yang diketahui dan yang ditanyakan, kemudian membuat gambar atau sketsa segitiga.&nbsp;</p>', NULL, '<p>ketika permasalahan melibatkan sudut dan panjang sisi segitiga, terutama segitiga siku-siku. Strategi dipilih dengan menyesuaikan posisi sudut dan sisi yang diketahui, sehingga perbandingan trigonometri yang digunakan tepat.&nbsp;</p>', NULL, '2025-12-13 20:47:57', '2025-12-13 20:50:39'),
(466, 6, 339, '<p>Vektor adalah besaran yang memiliki besar (nilai) dan arah. Contohnya adalah perpindahan dan kecepatan, berbeda dengan besaran skalar (hanya punya besar, seperti massa). Vektor AB memiliki titik pangkal A dan titik ujung B.</p>', NULL, '<p>Strategi penyelesaian soal cerita vektor adalah: identifikasi besaran; representasikan secara aljabar/visual, tentukan operasi, dan formulasikan persamaan menggunakan metode perhitungan yang paling efisien.</p>', NULL, '<p>Strategi utama penyelesaian masalah vektor adalah: identifikasi besaran, representasikan (aljabar/visual), tentukan operasi (penjumlahan/pengurangan/skalar), dan formulasikan persamaan menggunakan metode efisien yang sesuai konteks.</p>', NULL, '2025-12-13 20:48:19', '2025-12-13 20:56:18'),
(467, 4, 198, '<p>Pengertiannya, contoh penerapannya dalam kehidupan sehari-hari serta contoh soal dan cara penyelesaiannya.</p>', NULL, '<p>Sebelum menghitung, pahami soal dan tentukan yang diketahui serta ditanyakan. Lalu definisikan variabel dan buat model fungsi kuadrat y = ax² + bx + c. Kemudian pilih metode penyelesaian yang tepat.</p>', NULL, '<p>Strategi yang saya gunakan adalah menyesuaikan metode dengan jenis pertanyaan dan konteks masalah.&nbsp;</p>', NULL, '2025-12-13 20:49:45', '2025-12-13 20:54:51'),
(468, 4, 244, '<p>Topik ini meliputi definisi dan bentuk umum Fungsi Kuadrat f(x)=ax^2+bx+c, serta tiga cara dasar untuk mencari akar-akar Persamaan Kuadrat (Pemfaktoran, Melengkapi Kuadrat Sempurna, dan Rumus abc).</p>', NULL, '<p>Langkah penyelesaian soal cerita fungsi kuadrat dimulai dari memodelkan masalah ke dalam bentuk f(x)=ax^{2}+bx+c, kemudian menentukan apakah yang dicari adalah akar-akar </p>', NULL, '<p>Strategi penyelesaian harus disesuaikan dengan konteks masalah; yaitu dengan menganalisis koefisien a (menentukan titik balik maksimum/minimum) dan nilai Diskriminan D.</p>', NULL, '2025-12-13 20:53:44', '2025-12-13 21:51:53'),
(469, 3, 204, '<p>Saya mengetahui trigonometri adalah studi hubungan sudut dan sisi segitiga siku-siku, perbandingan dasar (Sin, Cos, Tan, dll), sudut istimewa, kuadran, hingga persamaan trigonometri.</p>', NULL, '<p>Yaitu dengan memvisualisasikan soal sebagai segitiga siku-siku, mengidentifikasi sudut acuan, menententukan posisi sisi (depan/samping/miring), lalu memilih perbandingan trigonometri yang tepat untuk perhitungan.</p>', NULL, '<p>Yaitu saat masalah melibatkan segitiga siku-siku, seperti menghitung tinggi atau jarak. Pemilihan rasio (Sin, Cos, Tan) didasarkan pada hubungan sisi yang diketahui dengan sudut acuan.</p>', NULL, '2025-12-13 20:55:44', '2025-12-13 20:57:50'),
(470, 2, 246, '<p>persamaan linear menggunakan simbol =, sedangkan pertidaksamaan linear menggunakan &lt;, &gt;, ≤ atau ≥.</p>', NULL, '<ol><li>Pahami soal</li><li>Tentukan variabel</li><li>buat model matematis</li><li>pilih metode penyelesaian yang sesuai</li><li>cek dan interpertasikan hasilnya</li></ol>', NULL, '<p>memahami konteks masalah, menetukan variabel yang sesuai, membentuk persamaan atau pertidaksamaan linear, memilih metode penyelesaian, kemudian memeriksa hasil agar sesuai dengan soal</p>', NULL, '2025-12-13 21:01:46', '2025-12-13 21:07:44'),
(471, 2, 303, '<p>Materi ini membahas cara menentukan solusi persamaan dan pertidaksamaan linear, termasuk sistemnya dengan metode substitusi, eliminasi, dan grafik.</p>', NULL, '<p>Langkahnya adalah memahami soal, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat sebelum menghitung.</p>', NULL, '<p>Saya menyelesaikan soal dengan memahami konteks, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode yang tepat.</p>', NULL, '2025-12-13 21:03:28', '2025-12-13 21:04:28'),
(472, 2, 243, '<p>Sistem Persamaan linear adalah kumpulan beberapa persamaan linear yang saling terkait. Kita dapat menyelesaikan soal persamaan linear dengan menggunakan substitusi, eliminasi, campuran, dan metode grafik.</p>', NULL, '<p>Saya akan memahami masalah pada soal, membuat model matematikanya, menyelesaikan persamaan yang ada, memastikan jawaban saya sudah benar dan membuat kesimpulan.</p>', NULL, '<p>Mengidentifikasi variabel, membuat persamaannya, memilih metode penyelesaian yang paling efektif, menyelesaikan sistem persamaannya, memeriksa solusi yang di dapat kemudian menerjemahkan kembali nilai variabel ke dalam konteks soal cerita.</p>', NULL, '2025-12-13 21:09:04', '2025-12-13 21:10:35'),
(473, 2, 304, '<p>Materi ini membahas cara menentukan solusi persamaan dan pertidaksamaan linear, termasuk sistemnya dengan metode substitusi, eliminasi, dan grafik.</p>', NULL, '<p>Langkahnya adalah memahami soal, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat sebelum menghitung.</p>', NULL, '<p>Saya menyelesaikan soal dengan memahami konteks, menentukan variabel, menyusun persamaan atau pertidaksamaan, lalu memilih metode yang tepat.</p>', NULL, '2025-12-13 21:09:32', '2025-12-13 21:10:04'),
(474, 3, 205, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan sudut dan sisi pada segitiga siku-siku melalui perbandingan sinus, cosinus, dan tangen serta penerapannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang sebaiknya saya lakukan adalah membaca soal dengan teliti, menentukan informasi sudut dan sisi, memilih perbandingan trigonometri yang sesuai, lalu menyusun langkah penyelesaian sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi setelah memahami konteks soal, dengan cara mengidentifikasi informasi yang diketahui dan menentukan konsep trigonometri yang sesuai sebelum melakukan perhitungan.</p>', NULL, '2025-12-13 21:13:15', '2025-12-13 21:17:14'),
(475, 2, 293, '<p>Persamaan dan pertidaksamaan digunakan untuk menentukan nilai variabel yang memenuhi hubungan tertentu dengan operasi aljabar yang setara.</p>', NULL, '<p>Memahami soal, menentukan diketahui dan ditanyakan, serta mengubahnya ke bentuk persamaan atau pertidaksamaan sebelum menghitung.</p>', NULL, '<p>Strategi yang digunakan adalah memahami konteks masalah, memodelkannya ke dalam persamaan atau pertidaksamaan yang sesuai, lalu menyelesaikannya secara sistematis dan mengecek kembali hasilnya.</p>', NULL, '2025-12-13 21:19:07', '2025-12-13 21:20:53'),
(476, 1, 312, '<p>Materi ini membahas Eksponen</p>', NULL, '<p>Identifikasi Variabel, Modelkan Masalah, Substitusikan dan Sederhanakan</p>', NULL, '<p>Analisis konteks masalah, pilih sifat eksponen, tentukan tujuan perhitungan</p>', NULL, '2025-12-13 21:25:06', '2025-12-13 21:29:22'),
(477, 2, 291, '<p>Sistem Persamaan Linear Dua Variabel (SPLDV) mencari titik solusi (nilai x dan y). Ini diselesaikan dengan metode substitusi atau eliminasi. Sistem Pertidaksamaan Linear Dua Variabel (SPtLDV) mencari daerah penyelesaian (daerah yang diarsir).</p>', NULL, '<p>Memahami soal, mengidentifikasi yang diketahui/ditanyakan, memodelkan cerita menjadi persamaan/pertidaksamaan, lalu memverifikasi model tersebut.</p>', NULL, '<p>Modelkan masalah menjadi persamaan (untuk nilai tunggal) atau pertidaksamaan (untuk daerah), lalu selesaikan dan verifikasi hasilnya sesuai konteks cerita.</p>', NULL, '2025-12-13 21:25:25', '2025-12-13 21:28:59'),
(478, 5, 249, '<p>Saya mengetahui bahwa fungsi eksponen adalah fungsi dengan bentuk f(x)=axf(x) = a^xf(x)=ax di mana a&gt;0a &gt; 0a&gt;0 dan a≠1a \\neq 1a=1, dan memiliki sifat pertumbuhan atau peluruhan tergantung nilai basisnya.</p><p><br></p>', NULL, '<p>Langkah-langkahnya: pahami soal, tentukan variabel, tulis persamaan eksponensial sesuai informasi, lalu rencanakan metode penyelesaian sebelum menghitung.</p><p><br></p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis informasi yang diberikan, memilih metode atau rumus yang tepat, dan menyesuaikan langkah penyelesaian dengan tipe soal.</p><p><br></p>', NULL, '2025-12-13 21:32:37', '2025-12-14 00:58:38'),
(479, 6, 249, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki besar dan arah, dapat direpresentasikan dalam bentuk komponen, dan dapat dijumlahkan atau dikalikan dengan skalar.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan vektor dan komponennya → buat diagram jika perlu → susun persamaan vektor → rencanakan perhitungan sebelum menyelesaikan.</p><p><br></p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis arah dan besar vektor, memilih operasi vektor yang sesuai, dan menyusun langkah penyelesaian sistematis.</p><p><br></p>', NULL, '2025-12-13 21:40:32', '2025-12-14 00:33:06'),
(480, 4, 243, '<p>Dari materi fungsi kuadrat, saya mengetahui bahwa fungsi kuadrat berbentuk f(x)=ax2+bx+cf(x)=ax^2+bx+cf(x)=ax2+bx+c dengan a≠0a dan grafiknya berupa parabola. </p>', NULL, '<p>Langkah yang sebaiknya dilakukan adalah memahami cerita soal, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, menuliskan fungsi kuadrat yang sesuai, lalu menyiapkan strategi penyelesaian sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Strategi yang saya gunakan adalah memahami konteks masalah terlebih dahulu, mengubah permasalahan ke dalam bentuk fungsi kuadrat, menentukan informasi penting seperti titik puncak atau akar fungsi sesuai yang ditanyakan</p>', NULL, '2025-12-13 21:48:35', '2025-12-13 21:52:02'),
(481, 6, 208, '<p>yang telah saya ketahui tentang materi ini adalah defenisi vektor, operasi vektor dan lain lain</p>', NULL, '<ol><li>memahami isi soal</li><li>menentukan metode penyelesaiannya</li><li>memastikan langkah penyelesaian benar</li><li>dan memastikan kesesuaian satuan vektor</li></ol>', NULL, '<p>membentuk strategi ketika ada soal yang konteksnya spesifik. strateginya :</p><ol><li>mengidentifikasi konteks masalah</li><li>memeriksa karakteristik masalah</li><li>melakukan penyelesaian</li></ol>', NULL, '2025-12-13 21:49:43', '2025-12-13 21:58:24'),
(482, 4, 245, '<p>Topik ini meliputi definisi dan bentuk umum Fungsi Kuadrat f(x)=ax^2+bx+c, serta tiga cara dasar untuk mencari akar-akar Persamaan Kuadrat (Pemfaktoran, Melengkapi Kuadrat Sempurna, dan Rumus abc).</p>', NULL, '<p>Langkah penyelesaian soal cerita fungsi kuadrat dimulai dari memodelkan masalah ke dalam bentuk f(x)=ax^2+bx+c, kemudian menentukan apakah yang dicari adalah akar-akar</p>', NULL, '<p>Strategi penyelesaian harus disesuaikan dengan konteks masalah; yaitu dengan menganalisis koefisien a (menentukan titik balik maksimum/minimum) dan nilai Diskriminan D.</p>', NULL, '2025-12-13 21:51:11', '2025-12-13 21:53:24'),
(483, 3, 258, '<p>Topik ini membahas perbandingan trigonometri pada segitiga siku-siku, meliputi pengertian sudut dan sisi-sisi segitiga serta konsep sinus, cosinus, dan tangen, yang digunakan untuk menentukan panjang sisi atau besar sudut dalam soal kontekstual.</p>', NULL, '<p>Pahami soal, tentukan data yang diketahui dan ditanya, buat sketsa segitiga, pilih perbandingan trigonometri yang tepat, lalu hitung.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal dengan menyesuaikan data yang ada dan tujuan soal pada konsep trigonometri yang sesuai.</p>', NULL, '2025-12-13 21:51:51', '2025-12-13 21:59:40'),
(484, 3, 249, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi pada segitiga, termasuk fungsi sinus, cosinus, dan tangen serta penerapannya dalam masalah sudut dan panjang.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan sudut dan sisi yang diketahui → pilih fungsi trigonometri yang sesuai → susun persamaan → rencanakan perhitungan sebelum menyelesaikan.</p><p><br></p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal dengan menganalisis informasi sudut dan sisi, lalu memilih fungsi trigonometri dan langkah perhitungan yang tepat.</p><p><br></p>', NULL, '2025-12-13 21:54:53', '2025-12-14 02:08:44'),
(485, 4, 293, '<p>persamaan kuadrat adalah  persamaanyang memiliki bentuk umum ax^2+bx+c=0 dan dapat memiliki dua, satu, atau tidak ada solusi real, yang dapat ditentukan dengan faktorisasi, melengkapi kuadrat, atau rumus kuadrat.</p>', NULL, '<p>Langkah-langkah sebelum menghitung dalam menyelesaikan soal cerita adalah memahami konteks soal, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, serta mengubah masalah ke dalam model persamaan kuadrat yang sesuai.</p>', NULL, '<p>Strategi penyelesaian yang digunakan adalah memilih metode penyelesaian yang paling tepat sesuai bentuk persamaan dan konteks masalah, menyelesaikannya secara sistematis, lalu memeriksa kembali hasil agar sesuai dan masuk akal dengan permasalahan.</p>', NULL, '2025-12-13 21:54:58', '2025-12-13 21:56:06'),
(486, 3, 339, '<p>Materi yang diketahui adalah perbandingan dasar Sin/Cos/Tan pada segitiga siku-siku, kaitannya dengan Pythagoras, dan penggunaan nilai sudut istimewa serta konsep kuadran untuk pemodelan kontekstual.</p>', NULL, '<p>Langkah penyelesaian adalah sketsa/modelkan masalah ke segitiga siku-siku, namai sisi (De/Sa/Mi), pilih rumus (sin, cos, atau tan) yang tepat, dan susun persamaannya.</p>', NULL, '<p>Strategi ditentukan oleh konteks data: gunakan Sin/Cos/Tan atau Pythagoras untuk siku-siku, Aturan Sinus/Kosinus untuk sembarang, atau aturan kuadran untuk sudut besar, selalu memilih alat matematis yang paling efisien.</p>', NULL, '2025-12-13 21:56:37', '2025-12-13 21:58:03'),
(487, 2, 306, '<p>Materi ini mencakup definisi dan bentuk umum Sistem Persamaan Linear Tiga Variabel (SPLTV), serta penggunaan konsep Fungsi Eksponen dan deret geometri </p>', NULL, '<p>Langkah prosedural yang sebaiknya dilakukan sebelum menghitung adalah memahami masalah, mengidentifikasi data yang diketahui dan ditanya, lalu menentukan model matematika yang tepat (yaitu model deret geometri eksponensial) </p>', NULL, '<p>Strategi yang tepat adalah mengidentifikasi konteks pertumbuhan eksponensial dan memilih model deret geometri untuk menghitung jumlah total kumulatif orang yang tertular, kemudian menyelesaikan pertidaksamaan untuk menemukan fase minimal </p>', NULL, '2025-12-13 21:57:54', '2025-12-13 22:01:11'),
(488, 5, 198, '<p>Konsepnya, penerapannya dalam kehidupan sehari-hari, grafiknya dan soal serta cara penyelesaiannya</p>', NULL, '<p>Sebelum menghitung, pahami konteks dan identifikasi pola perulangan dalam soal. Lalu tentukan basis dan eksponen, kemudian buat model matematika dalam bentuk aⁿ atau a × bⁿ.</p>', NULL, NULL, NULL, '2025-12-13 22:02:05', '2025-12-13 22:05:14'),
(489, 3, 327, '<p>Hubungan sudut dan sisi dari segitiga siku-siku,perbandingan trigonometri untuk sudut lancip, hubungan antar sinus,cosinus untuk sudut penyiku,aturan sinus dan cosinus,perbandingan trigonometri dan theorema phytagoras</p>', NULL, '<p>membaca soal dengan teliti ,.menentukan sisi atau sudut yang ingin dicari dan pilih perbandingan trigonometri yang sesuai (sin, cos, tan). Lalu menggambarkan segitiga jika perlu untuk memudahkan visualisasi sebelum melakukan perhitungan</p>', NULL, '<p>Strategi dimiliki sejak awal membaca soal dengan memahami konteks masalah. Strategi dibentuk dengan menentukan konsep trigonometri yang tepat, memilih perbandingan yang sesuai, dan merencanakan langkah-langkah perhitungan </p>', NULL, '2025-12-13 22:09:50', '2025-12-13 22:14:33'),
(490, 2, 193, '<p>sistem persamaan linear 2 atau 3 variabel adalah penggabungan persamaan linear yang masing-masing persamaan linear memiliki lebih dari satu variabel dan dalam penyelesaiannya dibutuhkan metode eliminasi dan substitusi</p>', NULL, '<p>menentukan masing-masing variabel dan berapa nilai yang memenuhi variabel tersebut untuk memenuhi persamaan untuk itu dilakukan eliminasi dan substitusi </p>', NULL, '<p>strategi dalam menyelesaikan ini adalah menyususn masing masing komponen dalam model matematika kemudian menyelesaikan dengan eliminasi atau dengan substitudi untutk menentukan nilai yang memenuhi</p><p><br></p>', NULL, '2025-12-13 22:16:57', '2025-12-13 22:19:09'),
(491, 1, 248, '<p>Bilangan berpangkat adalah bentuk perkalian berulang yang ditulis an , dengan a sebagai basis dan n  sebagai pangkat. Eksponen memudahkan perhitungan dan sering digunakan untuk menunjukkan pertumbuhan berlipat.</p>', NULL, '<p>Langkahnya adalah membaca soal dengan cermat, menentukan data yang diketahui dan ditanyakan, mengubah cerita ke bentuk eksponen, lalu memilih sifat eksponen yang sesuai sebelum menghitung.</p><p><br></p>', NULL, '<p>Strategi yang digunakan adalah memahami konteks soal, memodelkannya ke dalam bentuk bilangan berpangkat, menerapkan sifat eksponen yang sesuai, lalu menyelesaikannya secara bertahap dan sistematis.</p><p><br></p>', NULL, '2025-12-13 22:23:09', '2025-12-13 22:33:16'),
(492, 2, 217, '<p>Definisi persamaan dan Pertidaksamaan linear dua variabel serta cara penyelesaiannya</p>', NULL, '<p>membaca soal, kemudian tentukan variabelnya, mengubah ke persamaan atau pertidaksamaan linear dua variabel, lalu memastikan bahwa model sudah tepat sebelum menghitung.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal terlebih dahulu, lalu memilih metode yang tepat—misalnya substitusi atau eliminasi—untuk menyusun dan menyelesaikan persamaan atau pertidaksamaan linear dua variabel sesuai dengan kondisi yang diberikan.</p>', NULL, '2025-12-13 22:23:24', '2025-12-13 22:27:26'),
(493, 4, 291, '<p>Konsep Persamaan Kuadrat, yaitu persamaan dengan pangkat tertinggi dua . Tiga cara penyelesaiannya adalah memfaktorkan, melengkapi kuadrat sempurna, dan rumus ABC.</p>', NULL, '<p><strong>Langkah-langkah sebelum menghitung:</strong> Memahami soal cerita, mengidentifikasi yang diketahui dan ditanyakan, lalu memodelkan cerita menjadi bentuk persamaan kuadrat.</p>', NULL, '<p><strong>Strategi penyelesaian:</strong> Pilih metode (memfaktorkan, kuadrat sempurna, atau rumus ABC) yang <strong>efisien</strong> untuk model persamaan, lalu <strong>selesaikan</strong> dan <strong>verifikasi</strong> solusi sesuai konteks.</p>', NULL, '2025-12-13 22:32:01', '2025-12-13 22:33:18'),
(494, 5, 293, '<p>materi fungsi eksponen adalah  fungsi yang berbentuk f(x)=a^x dengan a&gt;0 dan a≠1, digunakan untuk menggambarkan pertumbuhan atau peluruhan yang berubah secara berlipat, serta memiliki sifat-sifat eksponen tertentu.</p>', NULL, '<p>Memahami konteks soal, menentukan besaran yang diketahui dan ditanyakan, memodelkan masalah ke dalam bentuk fungsi eksponen, dan menentukan sifat eksponen yang akan digunakan.</p>', NULL, '<p>Saat konteks masalah menunjukkan pola pertumbuhan atau peluruhan berulang. Strateginya adalah memilih model eksponen yang sesuai, menyelesaikannya secara sistematis, lalu mengecek kembali hasil agar sesuai dan masuk akal dengan konteks masalah.</p>', NULL, '2025-12-13 22:33:38', '2025-12-13 22:36:18'),
(495, 1, 264, '<p>Bilangan ekponen atau bilangan berpangkat adalah perkalian suatu bilangan secara berulang. Memiliki basis dan eksponen/pangkat</p>', NULL, '<p>Kita lihat dulu basis dan pangkatnya,kemudian baru menentukan basis itu dikalikan berulang kali sesuai pangkatnya. untuk operasi pada bilangan berpangkat kita harus memperhatikan sifat eksponen tersebut sebelum memecahkannya.</p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Eksponen menunjukkan berapa kali suatu angka (yang disebut basis) akan dikalikan dengan dirinya sendiri. Dengan pemahaman ini dan sering , kita bisa memecahkannya dengan cepat dan efisien</span></p>', NULL, '2025-12-13 22:35:10', '2025-12-13 22:45:30');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(496, 6, 198, '<p>Konsepnya, contoh dalam kehidupan sehari-hari, serta soal dan cara penyelesaiannya.</p>', NULL, '<p>Sebelum menghitung, pahami konteks soal dan identifikasi besaran vektor, kemudian definisikan vektor dengan notasi jelas. Selanjutnya tentukan sistem koordinat, gambar diagram vektor untuk visualisasi, dan tentukan operasi yang diperlukan.</p>', NULL, '<p>Saya menggunakan strategi dengan mengidentifikasi kata kunci dan jenis masalah, lalu menyesuaikan metode dengan konteks: visualisasi untuk fisika, analisis numerik untuk bisnis, diagram untuk navigasi. Strategi bersifat adaptif.</p>', NULL, '2025-12-13 22:45:32', '2025-12-13 22:51:12'),
(497, 2, 238, '<p>Materi ini membahas persamaan dan pertidaksamaan linear serta SPLDV, yaitu cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah, termasuk soal cerita.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel (misalnya xxx dan yyy), mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Strategi saya adalah memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar</p>', NULL, '2025-12-13 22:48:37', '2025-12-13 23:10:57'),
(498, 6, 210, '<p>Saya sudah belajar bahwa vektor adalah besaran yang punya nilai dan arah. Materinya fokus ke konsep dasar dan dua operasi utama: penjumlahan dan pengurangan, yang bisa dilakukan pakai gambar (geometris) atau hitungan (analitis).</p>', NULL, '<p>baca soal untuk tahu data dan pertanyaan, gambar situasi supaya gampang dibayangkan, pilih metode yang cocok, lalu hitung hasilnya.</p>', NULL, '<p>Strategi saya sederhana: pertama, saya pahami konteks soal dari teks dan gambar yang ada. Terus, saya putusin apakah butuh Google Search buat cari info tambahan atau bisa langsung jawab. </p>', NULL, '2025-12-13 22:50:04', '2025-12-13 22:54:48'),
(499, 5, 244, '<p>Fungsi Eksponen dinyatakan f(x)= a^x , dibedakan menjadi Pertumbuhan (a&gt;1) 2dan Peluruhan (0&lt;a&lt;1).Grafiknya selalu di atas sumbu x 4dan memiliki Asimtot Datar Y=0.</p>', NULL, '<p>Tentukan jenis fungsi: Pertumbuhan atau Peluruhan.Identifikasi nilai awal (n) dan faktor perubahan (a).Susun model matematika f(x)=a^x.Pastikan konversi variabel waktu (x) sudah tepat sebelum perhitungan (misalnya, jam ke fase).</p>', NULL, '<p>Kapan:Digunakan saat soal meminta  menghitung hasil untuk jangka waktu yang panjang/besar.Bagaimana:Strategi utama adalah dengan memodelkan fungsi secara benar (mengidentifikasi n,a, dan x) dan memastikan satuan waktu (x) </p>', NULL, '2025-12-13 22:51:12', '2025-12-13 22:59:44'),
(500, 2, 266, '<p>Saya mengetahui bahwa materi ini membahas sistem persamaan dan pertidaksamaan linear untuk menentukan nilai variabel yang memenuhi beberapa persamaan atau pertidaksamaan.</p>', NULL, '<p>Sebelum menghitung, saya memahami soal cerita, menentukan variabel, dan memodelkannya ke dalam bentuk sistem persamaan atau pertidaksamaan linear.</p>', NULL, '<p>Saya menggunakan strategi memilih metode yang sesuai (eliminasi, substitusi, atau grafik) lalu mengecek kembali hasil agar sesuai dengan konteks masalah.</p>', NULL, '2025-12-13 22:51:23', '2025-12-13 22:53:07'),
(501, 5, 245, '<p>Fungsi Eksponen dinyatakan f(x)=a^x, dibedakan menjadi Pertumbuhan (a&gt;1) dan Peluruhan (0&lt;a&lt;1).Grafiknya selalu di atas sumbu x 4dan memiliki Asimtot Datar Y=0.</p>', NULL, '<p>Tentukan jenis fungsi: Pertumbuhan atau Peluruhan.Identifikasi nilai awal (n) dan faktor perubahan (a).Susun model matematika f(x)= a^x.Pastikan konversi variabel waktu (x) sudah tepat sebelum perhitungan (misalnya, jam ke fase).</p>', NULL, '<p>Kapan:Digunakan saat soal meminta menghitung hasil untuk jangka waktu yang panjang.Bagaimana:Strategi utama adalah dengan memodelkan fungsi secara benar (mengidentifikasi n,a, dan x) dan memastikan satuan waktu (x)</p>', NULL, '2025-12-13 22:51:36', '2025-12-13 22:56:59'),
(502, 2, 317, '<p>Sistem Persamaan dan Pertidaksamaan Linier meliputi kajian tentang persamaan dan pertidaksamaan linier, serta sistem yang melibatkan dua atau tiga variabel dan juga solusi untuk penyelesaian masing masing</p>', NULL, '<ol><li>&nbsp;Memahami Masalah (Menganalisis Soal)</li><li>Membangun Model Matematika</li><li>Merencanakan Strategi Penyelesaian</li></ol>', NULL, '<p>caranya adalah dengan melakukan <strong>pemodelan matematika</strong> yang akurat (penentuan variabel untuk besaran yang tidak diketahui, diikuti dengan menerjemahkan semua informasi dan batasan</p>', NULL, '2025-12-13 22:51:37', '2025-12-13 22:59:32'),
(503, 2, 309, '<p>Materi ini membahas cara menyelesaikan sistem persamaan dan pertidaksamaan linear untuk mencari nilai variabel yang memenuhi syarat tertentu.</p><p><br></p>', NULL, '<p>Memahami soal, menentukan variabel, membuat model matematika, lalu memilih metode yang tepat.</p><p><br></p>', NULL, '<p>Menyesuaikan metode (grafik, eliminasi, atau substitusi) dengan bentuk dan konteks masalah serta mengecek kembali hasilnya</p>', NULL, '2025-12-13 22:52:56', '2025-12-13 22:54:42'),
(504, 1, 263, '<p>Eksponen adalah bilangan berpangkat yang memiliki basis dan pangkat. Memiliki beberapa sifat dalam operasi penyelesaiannya.</p>', NULL, '<p>pertama kita harus mengidentifikasi yang mana basis dan pangkat dalam soal eksponen tersebut. Karena perkalian berulangnya menggunakan basis yang dikalikan sebanyak pangkatnya.</p><p><br></p>', NULL, '<p>Kuncinya adalah latihan dan belajar agar ketika menemukan soal-soal sulit kita dapat memecahkannya. Dan tentunya kita harus memahami konsep dasarnya sebelum ketingkat lanjut</p>', NULL, '2025-12-13 22:57:59', '2025-12-13 23:01:19'),
(505, 3, 212, '<p>Perbandingan trigonometri adalah hubungan antara sudut dan sisi pada segitiga siku-siku yang digunakan untuk menghitung sudut atau panjang sisi.</p>', NULL, '<p>Membaca soal dengan teliti, memahami konteks masalah, menentukan diketahui dan ditanyakan, serta memilih perbandingan trigonometri yang tepat sebelum menghitung.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal, dengan menyesuaikan rumus dan langkah penyelesaian berdasarkan informasi yang diketahui dan tujuan yang ditanyakan.</p><p><br></p>', NULL, '2025-12-13 23:02:10', '2025-12-13 23:03:57'),
(506, 2, 278, '<p>Materi ini membahas sistem persamaan linear dua dan tiga variabel serta sistem pertidaksamaan linear.</p><p> Saya memahami cara menentukan himpunan penyelesaian dan kondisi banyaknya solusi pada masing-masing sistem.</p>', NULL, '<p>Langkahnya adalah memahami soal, menentukan variabel, lalu menyusun sistem persamaan atau pertidaksamaan linear dari informasi yang diberikan.</p><p> Setelah model matematika terbentuk, barulah dilakukan perhitungan untuk mendapatkan solusi.</p>', NULL, '<p>Strategi yang digunakan adalah memodelkan soal ke dalam sistem persamaan atau pertidaksamaan linear.</p><p> Kemudian memilih metode yang tepat untuk memperoleh himpunan penyelesaiannya.</p>', NULL, '2025-12-13 23:02:33', '2025-12-13 23:07:15'),
(507, 1, 250, '<p><span style=\"color: rgb(51, 65, 85);\">Ekspresi eksponen merupakan representasi matematis dari operasi perpangkatan.&nbsp;</span></p>', NULL, '<ol><li>baca soal dengan teliti</li><li>tentukan variabel</li><li>tuliskan ekspresi eksponen</li><li>sederhanakan ekspresi</li><li>cari solusi</li><li>verifikasi jawaban</li></ol><p><br></p>', NULL, '<ol><li>baca soal dengan teliti</li><li>tentukan variabel</li><li>tuliskan ekspresi eksponen</li><li>sederhanakan ekspresi</li><li>cari solusi</li><li>verifikasi jawaban</li></ol>', NULL, '2025-12-13 23:03:03', '2025-12-13 23:06:40'),
(508, 1, 223, '<p>Saya belajar bahwa perkalian berulang bisa ditulis dalam bentuk pangkat. Saya juga memahami bilangan pokok, pangkat, dan sifat-sifat eksponen yang memudahkan perhitungan.</p>', NULL, '<p>Sebelum menghitung, saya membaca soal dengan teliti lalu memahami apa yang diketahui dan yang ditanyakan. Setelah itu saya menentukan konsep atau rumus yang sesuai, misalnya bentuk pangkat atau sifat eksponen, baru kemudian melakukan perhitungan.</p>', NULL, '<p>Saya memahami konteks soal, mengubahnya ke bentuk eksponen, lalu menggunakan sifat-sifat eksponen untuk menyelesaikannya.</p>', NULL, '2025-12-13 23:04:10', '2025-12-13 23:09:22'),
(509, 5, 243, '<p>Fungsi Eksponen memilik bentuk: f(x) = a^x dengan a = basis (a &gt; 0, a ≠ 1) dan x = variabel.&nbsp;</p><p>Grafik Eksponen meliputi Domain, Range, Intersep,&nbsp;​Asimtot.</p>', NULL, '<p>Baca soal cermat, kenali konsep eksponen (pertumbuhan/peluruhan), ubah jadi persamaan, gunakan sifatnya untuk selesaikan, lalu cek jawaban apakah logis dan sesuai.</p>', NULL, '<p>Gunakan saat soal kompleks/baru. Analisis konteks dan variabel, pilih metode tepat (substitusi, grafik dll), terapkan langkah demi langkah, lalu evaluasi efektifitasnya.</p>', NULL, '2025-12-13 23:05:40', '2025-12-13 23:06:31'),
(510, 5, 291, '<p>Materi yang telah dipelajari pada topik ini adalah eksponen atau bilangan berpangkat , yang merupakan bentuk perkalian berulang dengan bilangan yang sama</p>', NULL, '<p>Langkah menyelesaikan soal cerita: Pahami soal (diketahui/ditanya), tentukan konsep eksponen, lalu pilih rumus atau sifat yang relevan.</p>', NULL, '<p>Strategi dipilih ketika: Masalahnya terkait <strong>perkalian berulang</strong> (pertumbuhan/peluruhan), lalu pilih rumus eksponen yang spesifik (misalnya pertumbuhan populasi atau bunga majemuk) untuk perhitungan</p>', NULL, '2025-12-13 23:06:35', '2025-12-13 23:07:55'),
(511, 4, 193, '<p>persamaan kuadrat adlah persamaan dengan pangkatvariabel tertinggi 2 </p>', NULL, '<p>langkah awal adalah menentukan apa yang diketahui dan menotasikan dalam model persamaan yaitu mengetahui yang mana koefisien dan konstanta</p>', NULL, '<p>srategi adalah merumuskan semua yang diketahui dalam konsep persamaan kuadrat</p>', NULL, '2025-12-13 23:07:04', '2025-12-13 23:08:42'),
(512, 1, 300, '<p>definisi eksponen, sifat-sifat eksponen, dan cara menyederhanakan eksponen</p>', NULL, '<p>Menentukan informasi yang diketahui, Menentukan apa yang ditanyakan, Mengubah kalimat cerita ke dalam model matematika, Menentukan sifat eksponen yang akan digunakan</p><p> </p>', NULL, '<p>Memahami konteks masalah terlebih dahulu, Mengidentifikasi informasi penting, Menentukan tujuan penyelesaian, Membuat model matematika yang tepat, Memilih sifat eksponen yang relevan, Mengecek kembali kesesuaian dengan konteks</p><p><br></p><p><br></p>', NULL, '2025-12-13 23:15:34', '2025-12-13 23:22:02'),
(513, 2, 263, '<p>Persamaan dan pertidaksamaan linear memuat variabel berpangkat satu. Digunakan untuk menyelesaikan masalah sehari-hari yang melibatkan hubungan linier.</p>', NULL, '<p>Baca dan pahami soal, tentukan variabelnya, buat model matematika (persamaan/pertidaksamaan), selesaikan, tafsirkan hasilnya dan periksa kembali</p>', NULL, '<p>Gunakan persamaan untuk nilai pasti, pkai persamaan untuk batasan, jika perlu gunakan grafik, Pastikan hasil logis dan sesuai soal.</p>', NULL, '2025-12-13 23:29:24', '2025-12-13 23:33:08'),
(514, 6, 244, '<p>Vektor adalah besaran punya nilai dan arah. Operasi utamanya: Penjumlahan, Pengurangan, dan Perkalian Skalar.</p>', NULL, '<p>1.Identifikasi Vektor &amp; Operasi yang dibutuhkan. 2. Representasi Komponen (aljabar) atau Gambar (grafis). 3. Hitung sesuai aturan komponen seletak</p>', NULL, '<p>Kapan: Jika soal melibatkan besaran berarah (perpindahan, kecepatan) dan butuh resultan. Bagaimana: Gunakan Metode Komponen untuk hasil akurat (kuantitatif) atau Metode Grafis (Segitiga/Jajar Genjang) untuk visualisasi cepat (kualitatif).</p>', NULL, '2025-12-13 23:32:14', '2025-12-13 23:33:11'),
(515, 6, 243, '<p>Vektor didefinisikan sebagai ruas garis yang memiliki panjang dan arah. Secara geometri menggunakan panah sedangkan secara aljabar menggunakan (a, b) /(a, b, c). Operasi pada vektor yaitu penjumlahan, pengurangan dan perkalian.</p>', NULL, '<p>Pahami soal, visualisasi vektornya, pilih metode (penjumlahan, perkalian, dll.), ubah ke bentuk aljabar, tulis persamaan, sederhanakan, hitung, terus periksa jawaban.</p>', NULL, '<p>Strategi tergantung konteks soal. Resultan gaya pakai penjumlahan, usaha pakai perkalian titik, momen gaya pakai perkalian silang, gerak proyektil pakai uraian komponen. Pilih strategi berdasarkan kata kunci dan visualisasi.</p>', NULL, '2025-12-13 23:32:32', '2025-12-13 23:33:46'),
(516, 6, 245, '<p>Vektor adalah besaran punya nilai dan arah. Operasi utamanya: Penjumlahan, Pengurangan, dan Perkalian Skalar.</p>', NULL, '<p>1. Identifikasi Vektor &amp; Operasi yang dibutuhkan. 2. Representasi Komponen (aljabar) atau Gambar (grafis). 3. Hitung sesuai aturan komponen seletak</p>', NULL, '<p>Kapan: Jika soal melibatkan besaran berarah (perpindahan, kecepatan) dan butuh resultan. Bagaimana: Gunakan Metode Komponen untuk hasil akurat (kuantitatif) atau Metode Grafis (Segitiga/Jajar Genjang) untuk visualisasi cepat (kualitatif).</p>', NULL, '2025-12-13 23:32:41', '2025-12-13 23:33:47'),
(517, 2, 294, '<p>dari materi pada topik ini, saya sudah memahami bahwa eksponen(pangkat) adalah cara menyantakan perkalian berulang suatu bilangan. saya mengetahui arti bilangan pokok(basis) dan pangkat, serta memahami sifat-sifat eksponen</p>', NULL, '<p>membaca soal dengan cermat, menentukan informasi yang diketahui dan yang ditanyakan, mengidentifikasi pola pertumbuhan atau perubahan, menentukan model matematika yang tepat, menentukan sifat eksponen yang digunakan</p>', NULL, '<p>mengaitkan cerita ke model eksponen yang tepat, mengenali pola perubahan atau pertumbuhan, menentukan rumus atau sifat eksponen yang sesuai, menyederhanakan bentuk perhitungannya</p>', NULL, '2025-12-13 23:35:46', '2025-12-14 00:15:36'),
(518, 4, 278, '<p>Materi ini membahas persamaan dan fungsi kuadrat beserta sifat grafiknya.</p><p> Saya memahami cara menentukan akar, titik puncak, dan penerapannya dalam kehidupan sehari-hari.</p><p><br></p>', NULL, '<p>Langkahnya adalah memahami konteks soal dan menentukan variabel yang tepat.</p><p> Selanjutnya menyusun model persamaan atau fungsi kuadrat sebelum melakukan perhitungan.</p><p><br></p>', NULL, '<p>Strategi yang digunakan adalah mengubah masalah ke dalam bentuk persamaan atau fungsi kuadrat sesuai konteks soal.</p><p> Kemudian memilih metode penyelesaian yang tepat agar hasilnya sesuai dan logis.</p>', NULL, '2025-12-13 23:39:32', '2025-12-13 23:59:46'),
(519, 4, 217, '<p>karakteristik fungsi kuadrat dan cara menentukan atau menyelesaikan persamaan kuadrat</p>', NULL, '<p>saya memahami konteks soal, menentukan apa yang diketahui dan ditanya, memisalkan variabel, lalu mengubahnya ke model fungsi kuadrat sebelum menghitung</p>', NULL, '<p>saya memilih bentuk fungsi kuadrat yang sesuai masalah, menentukan koefisien dari informasi soal, lalu menafsirkan hasil sesuai konteks masalah.</p>', NULL, '2025-12-13 23:41:00', '2025-12-14 07:02:53'),
(520, 2, 275, '<p>Pada topik ini yang saya sudah ketahui ialah di dalam persaman linear dua variabel dapat diselesaikan dengan metode substitusi, eliminasi, campuran, atau grafik. sedangkan, pertidaksamaan digambarkan dengan daerah arsiran.</p>', NULL, '<p>langkah pertama yang dilaakukan  sebaiknya memahami soalnya dengan baik, kemudian mengidentifikasi apa yang diketahui dan yang ditanyakan. setelah itu selesaikan dengan metode yang sesuai seperti substitusi, eliminasi, atau secara grafik.</p>', NULL, '<p>Langkah awal adalah mengidentifikasi variabel dan persamaan pada soal. kemudian pilih metode penyelesaian yang sesuai seperti eliminasi atau substitusi.</p>', NULL, '2025-12-13 23:44:49', '2025-12-14 00:25:14'),
(521, 4, 238, '<p>Definisi persamaan kuadrat, tiga cara untuk menentukan akar-akar (penyelesaian) persamaan kuadrat, fungsi kuadrat dalam x berbentuk f(x)=ax^2+bx+c, dan diskriminan (D): Nilai D=b^2-4ac.</p>', NULL, '<p>Yaitu dengan memahami konteks masalah, identifikasi variabel-variabel yang ada, tentukan apa yang ditanyakan oleh soal, lalu memilih cara penyelesaian yang paling efektif.</p>', NULL, '<p>Dengan cara mengidentifikasi serta memodelkan apa yang dminta soal.</p>', NULL, '2025-12-13 23:45:18', '2025-12-13 23:47:41'),
(522, 1, 310, '<ol><li>Definisi eksponen adalah cara untuk menulis perkalian berulang dari suatu bilangan dengan dirinya sendiri. Contoh: 2^2 = 2x2</li><li>Sifat-sifat eksponen</li><li>Makna eksponen dalam kehidupan nyata</li><li>Jenis-jenis eksponen</li></ol>', NULL, '<p>Tentukan pola pertumbuhan atau struktur eksponen gunakan sifat eksponen secara tepat visualisasi atau pemetaan per fase cek kembali dengan contoh kecil dan sederhanakan dulu bentuk aljabarnya.</p>', NULL, '<p>Pahami konteks soal cerita, tentukan apa yang diketahui dan ditanya, ubah cerita ke bentuk matematika, tentukan aturan-aturan yang sesuai, susunlah langkah operasi eksponen, lakukan perhitungan, dan interpretasi kembali jawaban.</p>', NULL, '2025-12-13 23:50:31', '2025-12-13 23:54:45'),
(523, 4, 266, '<p>Saya memahami bentuk persamaan dan fungsi kuadrat, sifat grafiknya, serta cara menentukan akar, titik puncak, dan sumbu simetri.</p><p><br></p>', NULL, '<p>Langkah awal menyelesaikan soal cerita adalah memahami konteks, menentukan variabel, lalu membentuk persamaan atau fungsi kuadrat.</p><p><br></p>', NULL, '<p>Strategi yang digunakan adalah memilih metode penyelesaian yang tepat (faktorisasi, melengkapi kuadrat, atau rumus abc) sesuai dengan masalahnya.</p>', NULL, '2025-12-13 23:51:02', '2025-12-13 23:52:08'),
(524, 5, 193, '<p>eksponen disebut juga dengan bilangan beroangkat yaitu penulisan ringkas utntuk menotasikan perkalian bilangan berulang</p>', NULL, '<p>dalam mengerjakan soal cerita bertema eksponen langkah pertama asalah menentukan basis serta apa yang menjadi fungsi dalam soal selanjutnya selesaikan dalam model matemtika</p>', NULL, '<p>strategi dalam menyelesaikan fungsi eksponen adalah dengan tetap memperhatikan sifat sifat ekspoenen </p>', NULL, '2025-12-13 23:51:38', '2025-12-13 23:53:38'),
(525, 4, 263, '<p>Persamaan kuadrat memiliki bentuk umum ax2+bx+c=0. Solusinya bisa dicari dengan rumus kuadrat, pemfaktoran, melengkapi kuadrat ataupun grafik.</p>', NULL, '<p>Pahami soal cerita, tentukan variabel dan bentuk persamaan kuadrat, susun model matematika, pilih metode penyelesaian, hitung dan tafsirkan hasilnya.</p>', NULL, '<p>Gunakan strategi sesuai konteks: jika bisa difaktorkan gunakan pemfaktoran. Jika tidak, gunakan rumus kuadrat, pastikan solusi sesuai dengan situasi dalam soal (misalnya, nilai harus positif jika menyangkut jumlah benda).</p>', NULL, '2025-12-13 23:55:47', '2025-12-13 23:59:23'),
(526, 2, 250, '<p>Persamaan linear adalah kalimat matematika dengan tanda (=) dan variabel berpangkat satu.</p><p> Pertidaksamaan linear adalah kalimat matematika dengan tanda (&lt;, &gt;, ≤, ≥) dan variabel berpangkat satu.</p><p><br></p>', NULL, '<p>Membaca soal dengan teliti dan memahami permasalahan.</p><p> Menentukan apa yang diketahui, ditanyakan, dan menetapkan variabel.</p><p> Mengubah soal cerita ke dalam model persamaan atau pertidaksamaan linear.</p><p><br></p>', NULL, '<p>Memahami konteks soal dan menentukan variabel yang tepat.</p><p> Menyusun model persamaan atau pertidaksamaan linear sesuai informasi soal.</p><p> Memilih metode penyelesaian yang paling sesuai dengan model yang dibuat.</p>', NULL, '2025-12-13 23:55:57', '2025-12-14 00:00:43'),
(527, 3, 243, '<p>Segitiga siku-siku punya sudut 90°. Ada 3 sisi: dua kaki dan sisi miring (terpanjang). Teorema Pythagoras (a²+b²=c²) buat cari sisi. Dua sudut lain lancip, jumlah 90°. Ada sin, cos, tan untuk hubungkan sudut dan sisi.</p>', NULL, '<p>Baca soal dengan teliti, catat yang diketahui &amp; ditanyakan. Pilih rumus yang pas (Pythagoras atau sin/cos/tan), masukkan angka, hitung, lalu cek apakah jawaban masuk akal.</p>', NULL, '<p>Saya memilih strategi sesuai jenis soal dan info yang ada. Cari sisi pakai Pythagoras, cari sudut/sisi pakai sin/cos/tan. Kadang perlu gambar, kalau soal sulit saya akan memecahnya menjadi langkah kecil.</p>', NULL, '2025-12-13 23:59:16', '2025-12-14 00:00:09'),
(528, 4, 317, '<p>pengertian persamaan kuadrat dan cara penyelesaiannya</p><p><br></p>', NULL, '<p>Memahami Konteks dan Mengidentifikasi Variabel</p><p>Membangun Model Matematika (Fungsi Kuadrat)</p><p>Merencanakan Strategi Penyelesaian</p>', NULL, '<p> Pemodelan, Analisis Puncak, dan Interpretasi Kontekstual</p>', NULL, '2025-12-13 23:59:56', '2025-12-14 00:04:41'),
(529, 6, 291, '<p>Vektor adalah besaran yang punya nilai dan arah , direpresentasikan geometris atau aljabar komponen , dan bisa dioperasikan untuk besaran fisis seperti gaya dan kecepatan.</p>', NULL, '<p>Identifikasi Vektor dan Data. Pilih Operasi yang sesuai. Laksanakan Perhitungan. Verifikasi Logika dan pastikan semua data terpakai.</p>', NULL, '<p>Strategi dipilih saat hasil yang dicari sudah jelas dan harus didasarkan pada logika yang konsisten, memastikan semua data terpakai dan satuan akhir logis.</p>', NULL, '2025-12-14 00:03:06', '2025-12-14 00:07:21'),
(530, 2, 264, '<p>Sistem persamaan dan pertidaksamaan linear membahas penyelesaian beberapa persamaan atau pertidaksamaan secara bersamaan.</p><p> Penyelesaiannya dapat menggunakan metode substitusi, eliminasi, atau grafik.</p>', NULL, '<p>Pahami isi soal dan tentukan apa yang diketahui serta ditanyakan.</p><p>Tentukan variabel dan buat model persamaan atau pertidaksamaan.</p><p>Pilih metode penyelesaian sebelum menghitung.</p>', NULL, '<p>Memahami konteks masalah dan hubungan antar data yang diberikan.</p><p>Menentukan model persamaan atau pertidaksamaan yang sesuai dengan masalah.</p><p>Memilih strategi penyelesaian yang paling tepat dan efisien.</p>', NULL, '2025-12-14 00:05:13', '2025-12-14 00:11:37'),
(531, 2, 252, '<p>sistem persamaan dan pertidaksamaan linear</p>', NULL, '<p>Membaca soal dengan teliti untuk memahami cerita dan konteks permasalahan.</p><p>Menentukan informasi yang diketahui dan yang ditanyakan dari soal.</p><p>Menyusun rencana penyelesaian secara runtut dan logis</p>', NULL, '<ol><li>Memahami konteks dan tujuan masalah</li><li>Mengidentifikasi data yang diketahui dan yang ditanyakan</li><li>Menentukan konsep atau model matematika yang sesuai</li><li>Menyusun langkah penyelesaian secara sistematis</li></ol><p><br></p>', NULL, '2025-12-14 00:08:20', '2025-12-14 00:14:12'),
(532, 3, 208, '<p>Yang telah saya ketahui adalah mengenai konsep trigonometri</p>', NULL, '<p>menganalisis masalahnya, menerapkan konsep yang sesai dengan masalah,melakukan langkah penyelesaian, memeriksa kembali langkah langkah dan hasilnya</p>', NULL, '<p>saya memiliki suatu strategi ketika sudah memahami isi masalah matematika. setelah memahami saya langsung melakukan penyelesaian sesuani dengan konsep matematika dalam masalah matematika.</p>', NULL, '2025-12-14 00:10:16', '2025-12-14 00:27:23'),
(533, 6, 193, '<p>vektor adalah suatu besaran yang memiliki nilai dan juga arah</p>', NULL, '<p>dalam menyelesaikan soal yang berkaitan dengan vektor maka hal yang harus diperhatikan adalah berapa besaran dan kemana arah itu berjalan untuk menotasikannya dapat dituliskan dalam model matematika</p>', NULL, '<p>ketika suatu jarak beriringan dengan waktu maka bersaran vektor dapat dengan ,udah diselesaikan</p>', NULL, '2025-12-14 00:22:17', '2025-12-14 00:24:40'),
(534, 5, 263, '<p>Fungsi eksponen menggambarkan pertumbuhan atau peluruhan yang cepat, dengan variabel berada pada pangkat.</p>', NULL, '<p>Memahami soal,menentukan variabel, dan model fungsi eksponen, lalu menghitung sesuai yang ditanyakan.</p>', NULL, '<p>Menyesuaikan dengan konteks soal, apakah pertumbuhan atau peluruhan, agar model dan cara kerja serta jawaban tepat</p>', NULL, '2025-12-14 00:27:00', '2025-12-14 00:29:18'),
(535, 1, 260, '<p>perkalian berulang adalah perkalian yang dilakukan secara berulang dengan faktor yang sama. Selain itu saya dapat memahami cara menyederhanakan bentuk eksponen dan menyelesaikan soal-soal yang berkaitan dengan bilangan berpangkat dalam matematika.</p>', NULL, '<p>Membaca soal dengan teliti, Menentukan data yang diketahui dan yang ditanyakan, Mengubah cerita ke bentuk matematika, Menentukan sifat eksponen yang sesuai, Menyederhanakan bentuk eksponen, Menghitung hasil akhir dan mengecek jawaban.</p>', NULL, '<p>memahami konteks soal terlebih dahulu, kemudian mengubah cerita ke bentuk eksponen, memilih sifat eksponen yang tepat, dan menyederhanakan bentuknya sebelum menghitung hasil akhir, sehingga penyelesaian lebih mudah dan tidak salah langkah.</p>', NULL, '2025-12-14 00:28:00', '2025-12-14 00:33:11'),
(536, 3, 261, '<p>tentang trigonometri , rumus perbandingan nya ,serta koordinat polar dan koordinat kartesius</p>', NULL, '<p>pahami soal dengan seksama ,identifikasii konsep trigonometri yang relevan ,tuliskan rumus yang di gunakan , hitung dan sederhanakan dan periksa kembali jawaban.</p>', NULL, '<p>saat saya membaca soal nya sa sudah memikirkan strategi nya yang sesuai dengan konsep trigonometri</p><p><br></p>', NULL, '2025-12-14 00:28:13', '2025-12-14 00:34:59'),
(537, 4, 252, '<p>fungsi kuadrat</p>', NULL, '<p>Membaca soal dengan teliti untuk memahami cerita dan konteks permasalahan.</p><p>Menentukan informasi yang diketahui dan yang ditanyakan dari soal.</p><p>Menyusun rencana penyelesaian secara runtut dan logis.</p>', NULL, '<p>Memahami konteks dan tujuan masalah</p><p>Mengidentifikasi data yang diketahui dan yang ditanyakan</p><p>Menentukan konsep atau model matematika yang sesuai</p><p>Menyusun langkah penyelesaian secara sistematis</p><p><br></p>', NULL, '2025-12-14 00:28:40', '2025-12-14 00:32:00'),
(538, 3, 209, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan panjang sisi pada segitiga, khususnya segitiga siku-siku, melalui perbandingan sinus, cosinus, dan tangen</p>', NULL, '<p>membaca soal dengan teliti, membuat sketsa atau gambar, menentukan sudut dan sisi yang diketahui serta yang ditanyakan, lalu memilih perbandingan trigonometri yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Saya memiliki strategi dengan melihat konteks soal, misalnya masalah tinggi, jarak, atau sudut, kemudian menentukan apakah menggunakan sinus, cosinus, atau tangen. Setelah itu, hasil perhitungan dicek agar sesuai dengan situasi nyata pada soal.</p>', NULL, '2025-12-14 00:30:01', '2025-12-14 00:31:13'),
(539, 4, 250, '<p>Fungsi kuadrat adalah fungsi dengan variabel berpangkat dua yang berbentuk parabola. Grafiknya memiliki sumbu simetri dan satu titik puncak sebagai nilai maksimum atau minimum. </p><p><br></p>', NULL, '<p>1.membaca soal dengan teliti menentukan diketahui serta yang ditanyakan. </p><p>2.Selanjutnya, memodelkan soal cerita ke dalam bentuk fungsi kuadrat yang sesuai. 3.menentukan metode penyelesaian  sebelum melakukan perhitungan hasil akhirnya.</p>', NULL, '<p><strong>Memahami bentuk fungsi kuadrat</strong> </p><p><strong>Menentukan tujuan penyelesaian</strong>,</p><p><strong>Memilih metode yang tepat</strong>, </p>', NULL, '2025-12-14 00:30:07', '2025-12-14 00:35:20'),
(540, 6, 238, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki besar dan arah, dapat direpresentasikan dalam bentuk komponen, dan dapat dijumlahkan atau dikalikan dengan skalar.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan vektor dan komponennya → buat diagram jika perlu → susun persamaan vektor → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis arah dan besar vektor, memilih operasi vektor yang sesuai, dan menyusun langkah penyelesaian sistematis.</p>', NULL, '2025-12-14 00:31:24', '2025-12-14 00:32:42'),
(541, 3, 254, '<p>yang saya ketahui adalah tentang pengertian trigonometri yaitu, Trigonometri adalah studi pola bermakna mengenai hubungan antara sudut dan sisi segitiga.</p>', NULL, '<p>Saya membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, menetapkan variabel, lalu menyusun model matematika sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi dengan terlebih dahulu memahami konteks soal, mengidentifikasi informasi yang diketahui dan ditanyakan, kemudian memilih konsep atau rumus yang sesuai dengan materi agar penyelesaian masalah tepat dan sistematis.</p>', NULL, '2025-12-14 00:32:28', '2025-12-14 00:33:23'),
(542, 2, 300, '<p>definisi sistem persamaan linear dan pertidaksamaan linear, konsep persamaan linear tiga variabel, Penyelesaian sistem persamaan linear, dan penyelesaian sistem pertidaksamaan linear</p>', NULL, '<p>Membaca soal dengan cermat, Menentukan informasi yang diketahui, Menentukan apa yang ditanyakan, Menentukan variabel yang sesuai, Menyusun model matematika, Menentukan metode penyelesaian, dan Memeriksa kembali model yang dibuat</p>', NULL, '<p>Saya menggunakan metode substitusi, eliminasi, grafik, atau uji nilai sesuai dengan bentuk model matematika yang dibuat.</p>', NULL, '2025-12-14 00:39:14', '2025-12-14 00:43:47'),
(543, 3, 210, '<p>Materi ini mempelajari&nbsp;<span style=\"color: rgb(10, 10, 10);\">perbandingan trigonometri&nbsp;(sin, cos, tan) pada&nbsp;segitiga siku-siku&nbsp;untuk menyelesaikan masalah&nbsp;pengukuran tidak langsung&nbsp;dalam kehidupan sehari-hari.</span></p>', NULL, '<p>Langkah penyelesaian soal cerita trigonometri:&nbsp;<span style=\"color: rgb(10, 10, 10);\">Sketsa&nbsp;dan&nbsp;Pilih Rumus&nbsp;(sin/cos/tan) yang menghubungkan sisi terkait.</span></p>', NULL, '<p>Strategi saya muncul saat mengidentifikasi&nbsp;konteks&nbsp;soal. Caranya:&nbsp;Klasifikasi&nbsp;masalah, lalu&nbsp;pilih rumus/metode&nbsp;yang paling efisien berdasarkan konteks tersebut.</p><p><br></p><p><br></p><p><br></p>', NULL, '2025-12-14 00:41:37', '2025-12-14 00:43:39'),
(544, 5, 252, '<p>fungsi eksponen</p>', NULL, '<p>Membaca soal dengan teliti untuk memahami cerita dan konteks permasalahan.</p><p>Menentukan informasi yang diketahui dan yang ditanyakan dari soal.</p><p>Mengidentifikasi konsep atau model matematika yang sesuai dengan topik </p>', NULL, '<p>Membaca soal dengan cermat untuk memahami situasi masalah</p><p>Mengidentifikasi informasi yang diketahui dan yang ditanyakan</p><p>Menentukan konsep atau model matematika yang sesuai dengan konteks soal</p><p><br></p>', NULL, '2025-12-14 00:42:57', '2025-12-14 00:46:24'),
(545, 4, 264, '<p>Grafik fungsi kuadrat berbentuk parabola yang memiliki titik puncak dan sumbu simetri.</p><p>Fungsi kuadrat dapat digunakan untuk menentukan nilai maksimum atau minimum serta akar-akarnya.</p><p><br></p>', NULL, '<p>Pahami isi soal dan tentukan apa yang diketahui serta ditanyakan.</p><p>Buat model fungsi kuadrat dari masalah.</p><p>Tentukan cara penyelesaian sebelum menghitung.</p>', NULL, '<p>Memahami konteks soal dan hubungan antar variabel pada fungsi kuadrat.</p><p>Menyusun model fungsi kuadrat yang sesuai dengan permasalahan.</p><p>Memilih strategi penyelesaian yang tepat berdasarkan tujuan soal.</p>', NULL, '2025-12-14 00:45:27', '2025-12-14 00:48:42'),
(546, 1, 302, '<p>definisi eksponen/bilangan pangkat dan sifat-sifat eskponen</p>', NULL, '<p><span style=\"color: rgb(55, 65, 81);\">langkahnya yaitu baca soal, identifikasi variabel/eksponen, buat model, terjemahkan ke persamaan, periksa aturan, rencanakan penyelesaian.</span></p>', NULL, '<p>Strateginya itu i<span style=\"color: rgb(55, 65, 81);\">dentifikasi konteks, terjemahkan ke ekspresi eksponen, terapkan aturan, hitung langkah demi langkah, verifikasi, dan adaptasi.&nbsp;</span></p>', NULL, '2025-12-14 00:47:29', '2025-12-14 00:54:18'),
(547, 3, 245, '<p>Trigonometri adalah studi tentang hubungan antara sudut dan sisi dalam segitiga siku-siku, yang digunakan bersama Identitas Pythagoras untuk memecahkan masalah yang melibatkan segitiga siku-siku.</p>', NULL, '<p>Langkah-langkahnya meliputi: analisis informasi ,membuat sketsa untuk memodelkan masalah menjadi segitiga siku-siku dan melabeli sisi-sisinya, memilih perbandingan trigonometri yang tepat,lalu menyusun persamaan matematis yang akan diselesaikan.</p>', NULL, '<p>Strategi penyelesaian soal adalah memodelkan masalah ke dalam bentuk geometris/aljabar lalu memilih alat/rumus yang paling efisien seperti trigonometri atau Pythagoras untuk menghubungkan variabel.</p>', NULL, '2025-12-14 00:51:15', '2025-12-14 00:56:05'),
(548, 5, 278, '<p>Eksponen membentuk fungsi eksponensial melalui perkalian berulang.</p><p> Fungsi eksponensial memodelkan pertumbuhan dan peluruhan dengan grafik berasimtot y=0.</p>', NULL, '<p>Membaca soal dengan teliti untuk menentukan apakah masalah termasuk pertumbuhan atau peluruhan eksponensial.</p><p> Menetapkan variabel dan menyusun model fungsi eksponensial sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal apakah termasuk pertumbuhan atau peluruhan eksponensial.</p><p> Selanjutnya strategi diterapkan dengan menyusun model fungsi eksponensial yang sesuai.</p>', NULL, '2025-12-14 00:52:09', '2025-12-14 00:57:19'),
(549, 3, 244, '<p>Trigonometri adalah studi tentang hubungan antara sudut dan sisi dalam segitiga siku-siku,  (Sin, Cos, Tan, dan kebalikannya), yang digunakan bersama Identitas Pythagoras untuk memecahkan masalah yang melibatkan segitiga siku-siku.</p>', NULL, '<p>Langkah-langkahnya meliputi: analisis informasi ,membuat sketsa untuk memodelkan masalah menjadi segitiga siku-siku dan melabeli sisi-sisinya, memilih perbandingan trigonometri yang tepat,lalu menyusun persamaan matematis yang akan diselesaikan.</p>', NULL, '<p>Strategi penyelesaian soal adalah memodelkan masalah ke dalam bentuk geometris/aljabar lalu memilih alat/rumus yang paling efisien seperti trigonometri atau Pythagoras untuk menghubungkan variabel.</p>', NULL, '2025-12-14 00:52:13', '2025-12-14 00:57:06'),
(550, 5, 317, '<p>definisi fungsi eksponen dan bentuk  grafiknya</p>', NULL, '<p>Memahami Konteks dan Mengidentifikasi Jenis Fungsi</p><p>Identifikasi dan Tetapkan Parameter</p><p>Membangun Model Matematika</p><p>Merencanakan Strategi Perhitungan</p>', NULL, '<p>Strategi untuk menyelesaikan soal cerita Fungsi Eksponen adalah dengan fokus pada pemodelan matematika yang akurat, dimulai dengan mengidentifikasi apakah konteks masalah melibatkan pertumbuhan  atau peluruhan .</p>', NULL, '2025-12-14 00:54:27', '2025-12-14 00:59:17'),
(551, 5, 266, '<p>Eksponen membentuk fungsi eksponensial melalui perkalian berulang.</p><p>Fungsi eksponensial memodelkan pertumbuhan dan peluruhan dengan grafik berasimtot </p><p>y = 0.</p>', NULL, '<p>Membaca soal dengan teliti untuk menentukan apakah masalah termasuk pertumbuhan atau peluruhan eksponensial. Menetapkan variabel dan menyusun model fungsi eksponensial sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal apakah termasuk pertumbuhan atau peluruhan eksponensial.</p><p>Selanjutnya strategi diterapkan dengan menyusun model fungsi eksponensial yang sesuai.</p>', NULL, '2025-12-14 00:55:15', '2025-12-14 00:57:51'),
(552, 6, 263, '<p>Vektor adalah besaran yang memiliki nilai dan arah, dapat dinyatakan dalam bentuk komponen, diagram, atau koordinat, serta digunakan untuk mempresentasikan perpindahan, gaya dan arah gerak.</p>', NULL, '<p>Memahami cerita soal, menentukan vektor yang terlibat, menuliskannya dalam bentuk komponen, lalu melakukan operasi vektor yang diperlukan seperti penjumlahan, pengurangan, atau perkalian skalar.</p>', NULL, '<p>Strategi ditentukan dengan melihat konteks soal, apakah berkaitan dengan perpindahan, arah, atau resultan, sehingga dapat memilih operasi vektor yang tepat agar solusi sesuai dan logis.</p>', NULL, '2025-12-14 00:55:58', '2025-12-14 01:00:39'),
(553, 5, 238, '<p>Saya mengetahui bahwa fungsi eksponen adalah fungsi dengan bentuk f(x)=axf(x) = a^xf(x)=ax di mana a&gt;0a &gt; 0a&gt;0 dan a≠1a \\neq 1a=1, dan memiliki sifat pertumbuhan atau peluruhan tergantung nilai basisnya.</p>', NULL, '<p>Langkah-langkahnya: pahami soal, tentukan variabel, tulis persamaan eksponensial sesuai informasi, lalu rencanakan metode penyelesaian sebelum menghitung.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis informasi yang diberikan, memilih metode atau rumus yang tepat, dan menyesuaikan langkah penyelesaian dengan tipe soal.</p>', NULL, '2025-12-14 00:56:16', '2025-12-14 00:58:00'),
(554, 1, 284, '<p>Saya memahami aljabar dan fungsi sebagai cara menyederhanakan masalah dengan simbol, mengenali pola, serta melihat hubungan antarvariabel melalui grafik, tabel, dan contoh nyata dari video pembelajaran.</p><p><br></p>', NULL, '<p>langkah yang saya lakukan adalah membaca soal dengan teliti, mengidentifikasi variabel yang terlibat, menuliskan persamaan atau fungsi yang sesuai, memahami hubungan antarvariabel, lalu menyelesaikannya secara bertahap sebelum menarik kesimpulan.</p>', NULL, '<p>terlebih dahulu pahami konteks masalah terlebih dahulu, menentukan apakah dapat dimodelkan dengan aljabar atau fungsi, menetapkan variabel, menyusun persamaan atau fungsi yang sesuai, lalu menyelesaikan dan menafsirkan hasilnya sesuai situasi soal.</p>', NULL, '2025-12-14 00:58:37', '2025-12-14 01:01:42'),
(555, 6, 252, '<p>vektor</p>', NULL, '<p>Membaca soal dengan teliti untuk memahami cerita dan konteks permasalahan.</p><p>Menentukan informasi yang diketahui dan yang ditanyakan dari soal.</p><p>Mengidentifikasi konsep atau model matematika yang sesuai dengan topik </p>', NULL, '<p>Memahami konteks dan tujuan masalah</p><p>Mengidentifikasi data yang diketahui dan yang ditanyakan</p><p>Menentukan konsep atau model matematika yang sesuai</p>', NULL, '2025-12-14 01:00:56', '2025-12-14 01:02:55'),
(556, 2, 310, '<p>Materi ini membahas persamaan dan pertidaksamaan linear serta SPLDV, yaitu cara mencari nilai variabel berpangkat satu untuk menyelesaikan masalah, termasuk soal cerita.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel (misalnya xxx dan yyy), mengubah soal cerita menjadi model matematika (persamaan atau pertidaksamaan)</p>', NULL, '<p>Strategi saya adalah memahami soal, membuat model persamaan atau pertidaksamaan, lalu memilih metode penyelesaian yang tepat agar hasilnya benar</p>', NULL, '2025-12-14 01:04:28', '2025-12-14 01:24:19'),
(557, 3, 257, '<p>Topik ini membahas perbandingan trigonometri pada segitiga siku-siku, meliputi pengertian sudut dan sisi-sisi segitiga serta konsep sinus, cosinus, dan tangen, yang digunakan untuk menentukan panjang sisi atau besar sudut dalam soal kontekstual.</p>', NULL, '<p>Pahami soal, tentukan data yang diketahui dan ditanya, buat sketsa segitiga, pilih perbandingan trigonometri yang tepat, lalu hitung.</p>', NULL, '<p>Strategi ditentukan setelah memahami konteks soal dengan menyesuaikan data yang ada dan tujuan soal pada konsep trigonometri yang sesuai.</p>', NULL, '2025-12-14 01:11:41', '2025-12-14 01:12:48'),
(558, 5, 264, '<p>Saya mengetahui bahwa fungsi kuadrat berbentuk persamaan&nbsp;dan grafiknya berupa parabola.</p><p>Arah buka grafik ditentukan oleh nilai , sedangkan titik puncak menunjukkan nilai maksimum atau minimum.</p>', NULL, '<p>Mengubah cerita ke dalam model matematika fungsi kuadrat dengan menetapkan variabel dan persamaan yang sesuai.</p><p>Setelah itu, menentukan strategi atau rumus yang akan digunakan, baru kemudian melakukan perhitungan hasil akhirnya.</p>', NULL, '<p>Strategi ditentukan dengan menyesuaikan jenis masalah dengan konsep matematika yang tepat (misalnya fungsi kuadrat, grafik, atau nilai maksimum/minimum)  supaya terarah dan sesuai dengan konteks masalah.</p><p><br></p>', NULL, '2025-12-14 01:12:50', '2025-12-14 01:18:21'),
(559, 5, 268, '<p>Fungsi eksponen adalah fungsi yang memuat variabel pada pangkatnya.</p>', NULL, '<p>Memahami permasalahan, menentukan variabel dan nilai awal, menyusun model fungsi eksponen sesuai informasi soal, lalu menghitung hasil yang diminta.</p>', NULL, '<p>Strategi digunakan ketika masalah melibatkan pertumbuhan atau penurunan berulang dengan faktor tetap, dengan menyesuaikan model eksponen pada konteks soal.</p><p><br></p>', NULL, '2025-12-14 01:15:33', '2025-12-14 01:16:54'),
(560, 2, 248, '<p>Materi ini membahas <strong>persamaan dan pertidaksamaan linear</strong> serta cara menentukan <strong>penyelesaiannya</strong>.</p>', NULL, '<p><strong>memahami soal</strong>, <strong>menentukan variabel</strong>, <strong>membuat model matematika (persamaan/pertidaksamaan linear)</strong>, lalu <strong>memilih metode penyelesaian yang tepat</strong> sebelum menghitung hasil akhir.</p>', NULL, '<p>Strateginya adalah <strong>memahami soal, membuat model linear, lalu menyelesaikannya dan mengecek hasilnya</strong>.</p>', NULL, '2025-12-14 01:19:57', '2025-12-14 01:25:04'),
(561, 6, 202, '<ol><li>definisi vektor</li><li>pengoperasikan vektor</li><li>operasi vektor dengn cara analitik dan geometri</li></ol>', NULL, '<p>Langkah-langkahnya adalah membaca soal dengan teliti, menentukan besaran vektor yang diketahui dan ditanyakan, membuat diagram vektor, memilih sistem koordinat, serta menentukan operasi vektor yang digunakan sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi dipilih setelah memahami konteks soal. Saya menggunakan metode yang sesuai, seperti diagram atau komponen vektor, tergantung pada jenis masalah agar penyelesaiannya tepat dan efisien.</p>', NULL, '2025-12-14 01:21:43', '2025-12-14 05:18:33'),
(562, 2, 192, '<p>Persamaan dan pertidaksamaan linear memuat variabel berpangkat satu, yang digunakan untuk menyelesaikan masalah sehari-hari yang melibatkan hubungan linier.</p>', NULL, '<p>menuliskan variabel, menyusun model matematika dari informasi yang ada, menentukan metode penyelesaian yang tepat, dan memastikan kembali model tersebut sesuai dengan konteks soal cerita.</p>', NULL, '<p>Dengan cara Memahami konteks soal, menentukan variabel yang tepat, memodelkan masalah ke dalam sistem persamaan atau pertidaksamaan linear, memilih metode penyelesaian yang sesuai, kemudian menafsirkan hasil sesuai dengan situasi pada soal.</p>', NULL, '2025-12-14 01:22:39', '2025-12-14 01:24:22'),
(563, 3, 291, '<p>Saya memahami pola hubungan antara sudut dan sisi pada segitiga siku-siku, jenis perbandingan trigonometri, serta penggunaannya untuk mengukur tinggi atau jarak dalam situasi nyata.</p>', NULL, '<p>&nbsp;Pahami cerita soal secara utuh, buat sketsa gambar segitiga untuk memvisualisasikan masalah, lalu tentukan posisi sisi dan sudut yang diketahui.</p><p><br></p>', NULL, '<p>Strategi ditentukan saat awal mengidentifikasi masalah, caranya dengan mencocokkan informasi yang tersedia dengan rumus atau konsep yang paling relevan dan efisien.</p>', NULL, '2025-12-14 01:27:40', '2025-12-14 01:28:22'),
(564, 1, 256, '<p>Yang saya ketahui dari topik ini ialah:</p><ol><li>Definisi bilangan eksponen</li><li>Sifat sifat eksponen</li><li>Cara menyederhanakan bilangan eksponen</li></ol>', NULL, '<ol><li>Pahami Soal:&nbsp;Identifikasi data dan pertanyaan.</li><li>Buat Model Matematika:&nbsp;Susun persamaan eksponen.</li><li>Gunakan Sifat Eksponen:&nbsp;Sederhanakan persamaan.</li></ol><p><br></p>', NULL, '<ol><li>Pahami Soal:&nbsp;Apa yang diketahui, apa yang ditanya.</li><li>Rumuskan Model:&nbsp;Ubah soal jadi persamaan matematika.</li><li>Gunakan Konsep:&nbsp;Terapkan teorema, rumus, sifat eksponen.</li></ol><p><br></p>', NULL, '2025-12-14 01:29:23', '2025-12-14 01:35:45'),
(565, 6, 317, '<p>definisi dan operasi vektor</p>', NULL, '<p>Memahami Konteks dan Memodelkan Vektor</p><p>Identifikasi Pertanyaan Kunci dan Operasi</p><p>Merencanakan Perhitungan</p>', NULL, '<p>ketika masalah yang melibatkan besaran yang memiliki arah dan besar (magnitudo) , seperti perpindahan, kecepatan, gaya, atau percepatan. Strategi ini fokus pada pemodelan geometri atau aljabar dan analisis arah .</p>', NULL, '2025-12-14 01:31:53', '2025-12-14 01:36:15'),
(566, 6, 264, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki nilai dan arah serta dapat dituliskan dalam bentuk komponen.</p><p>Vektor dapat dioperasikan dengan penjumlahan, pengurangan, dan perkalian skalar.</p><p><br></p>', NULL, '<p>membaca soal cerita dengan teliti untuk memahami arah dan besar vektor yang terlibat, lalu menentukan bagaimana vektor direpresentasikan </p><p>Setelah itu barulah melakukan perhitungan untuk memperoleh hasil akhir.</p>', NULL, '<p>Saat sudah mengetahui besaran, arah, dan hubungan yang ditanyakan. Tentukan dengan memilih konsep atau operasi matematika yang sesuai dengan masalah.</p><p>Dengan begitu, penyelesaian menjadi terarah dan sesuai konteks soal.</p>', NULL, '2025-12-14 01:32:24', '2025-12-14 01:39:04'),
(567, 3, 263, '<p>Perbandingan trigonometri menjelaskan hubungan antara sudut dan sisi pada segitiga siku-siku, yaitu sinus, cosinus dan tangen, yang digunakan untuk menentukan panjang sisi atau besar sudut.</p>', NULL, '<p>Membaca soal dengan cermat, menggambar sketsa segitiga, menentukan sudut acuan, memilih perbandingan trigonometri yang sesuai lalu menghitung nilai yang diminta.</p>', NULL, '<p>Strategi ditentukan dengan melihat konteks soal, misalnya mencari tinggi, jarak, atau kemiringan, sehingga dapat memilih perbandingan trigonometri yang tepat agar penyelesaian logis dan sesuai masalah.</p>', NULL, '2025-12-14 01:33:58', '2025-12-14 01:44:05'),
(568, 6, 268, '<p>Vektor adalah besaran yang memiliki besar dan arah. Vektor dapat direpresentasikan dengan panah, pasangan koordinat, atau komponen pada sumbu, serta dapat dioperasikan melalui penjumlahan, pengurangan, dan perkalian dengan skalar.</p>', NULL, '<p>Membaca soal dengan cermat, menentukan vektor yang diketahui dan ditanya, mengubah ke bentuk komponen, lalu memilih operasi vektor yang sesuai.</p>', NULL, '<p>Strategi dipilih berdasarkan konteks soal, misalnya menggunakan komponen vektor untuk perhitungan atau diagram vektor untuk memahami arah dan hubungan antarvektor.</p>', NULL, '2025-12-14 01:34:49', '2025-12-14 01:35:33'),
(569, 6, 266, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki nilai dan arah serta dapat dituliskan dalam bentuk komponen. Vektor dapat dioperasikan dengan penjumlahan, pengurangan, dan perkalian skalar.</p>', NULL, '<p>Membaca soal cerita dengan teliti untuk memahami arah dan besar vektor yang terlibat, lalu menentukan bagaimana vektor direpresentasikan , Setelah itu barulah melakukan perhitungan untuk memperoleh hasil akhir.</p>', NULL, '<p>Saya memiliki strategi setelah memahami konteks soal dengan jelas, yaitu saat sudah mengetahui besaran, arah, dan hubungan yang ditanyakan.</p>', NULL, '2025-12-14 01:35:54', '2025-12-14 01:41:01'),
(570, 6, 278, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki nilai dan arah serta dapat dituliskan dalam bentuk komponen.</p><p>Vektor dapat dioperasikan dengan penjumlahan, pengurangan, dan perkalian skalar.</p>', NULL, '<p>Baca soal dengan teliti untuk memahami arah dan besar vektor serta cara merepresentasikannya (anak panah, koordinat, atau komponen).</p><p> Tentukan operasi vektor yang tepat, lalu lakukan perhitungan untuk memperoleh hasil akhir.</p>', NULL, '<p>Strategi ditentukan setelah memahami besaran, arah, dan hubungan pada soal dengan jelas.</p><p> Kemudian memilih konsep atau operasi yang sesuai agar penyelesaian terarah dan sesuai konteks.</p>', NULL, '2025-12-14 01:36:30', '2025-12-14 01:43:00'),
(571, 2, 260, '<p>Sistem persamaan linear adalah himpunan beberapa persamaan linear yang saling terkait, dengan koefisien-koefisien persamaan adalah bilangan real.&nbsp;</p>', NULL, '<p>1. Membaca dan memahami soal cerita dengan teliti</p><p>2. Menentukan apa yang diketahui dan apa yang ditanyakan.</p><p>3. Menentukan variabel yang sesuai.</p><p>4. Menyusun model matematika berupa persamaan atau pertidaksamaan linear.</p><p><br></p>', NULL, '<p>memahami konteks soal, menentukan variabel yang tepat, menyusun persamaan atau pertidaksamaan linear sesuai informasi, lalu memilih metode penyelesaian yang paling sesuai agar hasil yang diperoleh sesuai dengan konteks masalah.</p>', NULL, '2025-12-14 01:43:31', '2025-12-14 01:50:03'),
(572, 4, 275, '<p>Fungsi kuadrat ialah fungsi dalam bentuk umum y = ax^2 + bx + c yang grafiknya berupa parabola serta memiliki konsep penting seperti titik balik, sumbu simetri dan akar-akar.</p>', NULL, '<p>Langkah awal yang dilakukan adalah pahami soal yang diberikan dan konsep fungsi kuadrat. kemudian tentukan nilai/akar maksimum/minimum menggunakan metode yang sesuai.</p>', NULL, '<p>Strategi yang saya lakukan dalam menyelesaikan soal fungsi kuadrat, pahami bentuk umumnya, identifikasi a,b,c dan gunakan rumus kuadrat untuk menentukan akar serta bentuk parabola.</p>', NULL, '2025-12-14 01:50:32', '2025-12-14 02:03:03'),
(573, 3, 251, '<p>Trigonometri membahas hubungan antara sudut dan panjang sisi pada segitiga, terutama segitiga siku-siku.</p>', NULL, '<p>1. Baca soal dan tandai informasi penting</p><p>2. Buat gambar/sketsa segitiga</p><p>3. Pilih perbandingan trigonometri yang tepat</p><p>4. Susun persamaan lengkap dan cek satuan</p><p>5. Baru lakukan perhitungan akhir</p>', NULL, '<p>Bagaimana strategi itu dilakukan</p><p>Membaca dan menandai informasi penting: apa yang diketahui, apa yang ditanya, satuannya apa (orang, meter, hari, derajat, dan lain-lain).</p>', NULL, '2025-12-14 01:52:20', '2025-12-14 02:19:46');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(574, 1, 343, '<p>Penerapan dalam pemecahan masalah:</p><p>Masalah kontekstual seperti penyebaran virus dapat diselesaikan dengan model eksponen karena jumlahnya bertambah secara berlipat ganda setiap fase.</p>', NULL, '<p>1. Membaca soal dengan teliti</p><p>2.Menentukan informasi yang diketahui</p><p>3.Menentukan apa yang ditanyakan</p><p>4.Mengidentifikasi pola eksponen</p><p>5.Memisalkan dengan simbol atau model matematika</p>', NULL, '<p>1.Memahami konteks masalah terlebih dahulu</p><p>2.Menerjemahkan cerita kedalam model matematika</p><p>3.Menentukan variabel yang mewakili masalah</p>', NULL, '2025-12-14 01:55:58', '2025-12-14 02:19:52'),
(575, 2, 302, '<p>Sistem Persamaan Linear mencari solusi tunggal menggunakan eliminasi atau substitusi. Sistem Pertidaksamaan mencari daerah solusi dengan metode grafik. Aplikasinya fokus pada masalah optimasi.</p>', NULL, '<p><strong>Langkah Prosedural Soal Cerita:</strong> Mulai dengan memahami soal dan mengidentifikasi variabel. Kemudian, buatlah model matematis yang konsisten berupa persamaan atau pertidaksamaan.</p>', NULL, '<p><strong>Strategi Penyelesaian:</strong> Gunakan aljabar untuk hasil presisi numerik tunggal. Pilih grafik untuk visualisasi daerah solusi dan optimasi. Interpretasikan jawaban sesuai konteks.</p>', NULL, '2025-12-14 01:57:09', '2025-12-14 01:57:59'),
(576, 4, 310, '<p>Definisi persamaan kuadrat, tiga cara untuk menentukan akar-akar (penyelesaian) persamaan kuadrat, fungsi kuadrat dalam x berbentuk f(x)=ax^2+bx+c, dan diskriminan (D): Nilai D=b^2-4ac.</p>', NULL, '<p>Yaitu dengan memahami konteks masalah, identifikasi variabel-variabel yang ada, tentukan apa yang ditanyakan oleh soal, lalu memilih cara penyelesaian yang paling efektif.</p>', NULL, '<p>Dengan cara mengidentifikasi serta memodelkan apa yang dminta soal.</p>', NULL, '2025-12-14 02:07:18', '2025-12-14 02:09:01'),
(577, 3, 238, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi pada segitiga, termasuk fungsi sinus, cosinus, dan tangen serta penerapannya dalam masalah sudut dan panjang.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan sudut dan sisi yang diketahui → pilih fungsi trigonometri yang sesuai → susun persamaan → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal dengan menganalisis informasi sudut dan sisi, lalu memilih fungsi trigonometri dan langkah perhitungan yang tepat.</p>', NULL, '2025-12-14 02:09:14', '2025-12-14 02:10:46'),
(578, 2, 256, '<p>definisi persamaan linear</p><p>menyelesaikan persamaan linear dengan 2 variabel : menggunakan metode subtitusi,eliminasi dan campuran.</p><p>menyelesaikan persamaan linear dengan 3 variabel</p><p><br></p>', NULL, '<p>Baca soal dengan teliti, Tentukan yang diketahui dan yang ditanyakan, Misalkan variabel, Ubah cerita menjadi model matematika, Periksa tanda dan kondisi.</p>', NULL, '<p>&nbsp;Pahami konteks masalah,Tentukan variabel, Ubah kalimat soal menjadi model matematika, Selesaikan persamaan atau pertidaksamaan, Tulis himpunan solusi dan Periksa jawaban sesuai konteks.</p>', NULL, '2025-12-14 02:17:22', '2025-12-14 02:20:20'),
(579, 6, 293, '<p>vektor merupakan besaran yang memiliki nilai dan arah, dapat direpresentasikan dalam bentuk koordinat atau panah, serta dapat dioperasikan melalui penjumlahan, pengurangan, dan perkalian dengan skalar sesuai aturan tertentu.</p>', NULL, '<p>Memahami soal, menentukan vektor yang terlibat, menggambarkannya, lalu memodelkan dan memilih operasi vektor yang tepat sebelum menghitung.</p>', NULL, '<p>Strategi digunakan ketika konteks masalah sudah dipahami, dengan cara menentukan model matematika yang sesuai, memilih konsep atau operasi yang tepat, lalu menyelesaikannya secara sistematis dan mengecek kembali hasilnya.</p>', NULL, '2025-12-14 02:27:13', '2025-12-14 02:30:39'),
(580, 3, 266, '<p>Dari materi perbandingan trigonometri, saya mengetahui hubungan antara sudut dan sisi pada segitiga siku-siku. Saya juga memahami perbandingan sinus, cosinus, dan tangen serta cara menggunakannya.</p>', NULL, '<p>yaitu,  memodelkan soal ke dalam sketsa segitiga siku-siku ; melabeli sisi-sisi (depan, samping, miring); dan memilih perbandingan trigonometri yang tepat (sinus, kosinus, atau tangen) untuk menyusun persamaannya.</p>', NULL, '<p>Strategi penyelesaian soal dibentuk segera setelah mengidentifikasi konteks masalah.</p><p>Untuk Soal Cerita (Trigonometri): Strateginya adalah pemodelan (membuat sketsa geometris yang baku) dan penyusunan persamaan yang efisien.</p><p><br></p>', NULL, '2025-12-14 02:34:40', '2025-12-14 02:50:43'),
(581, 3, 264, '<p>Dari materi perbandingan trigonometri, saya mengetahui hubungan antara sudut dan sisi pada segitiga siku-siku. Saya juga memahami perbandingan sinus, cosinus, dan tangen serta cara menggunakannya.</p>', NULL, '<p>memodelkan soal ke dalam sketsa segitiga siku-siku ; melabeli sisi-sisi (depan, samping, miring); dan memilih perbandingan trigonometri yang tepat (sinus, kosinus, atau tangen) untuk menyusun persamaannya.</p>', NULL, '<p>Mengidentifikasi konteks masalah.</p><p>Untuk Soal Cerita (Trigonometri): Strateginya adalah pemodelan (membuat sketsa geometris yang baku) dan penyusunan persamaan yang efisien.</p><p><br></p>', NULL, '2025-12-14 02:37:46', '2025-12-14 02:49:49'),
(582, 3, 278, '<p>Dari materi perbandingan trigonometri, saya mengetahui hubungan antara sudut dan sisi pada segitiga siku-siku. Saya juga memahami perbandingan sinus, cosinus, dan tangen serta cara menggunakannya. </p>', NULL, '<p> memodelkan soal ke dalam sketsa segitiga siku-siku ; melabeli sisi-sisi (depan, samping, miring); dan memilih perbandingan trigonometri yang tepat (sinus, kosinus, atau tangen) untuk menyusun persamaannya.</p>', NULL, '<p>Strategi penyelesaian soal dibentuk segera setelah mengidentifikasi konteks masalah.</p><p>Untuk Soal Cerita (Trigonometri): Strateginya adalah pemodelan (membuat sketsa geometris yang baku) dan penyusunan persamaan yang efisien.</p><p><br></p>', NULL, '2025-12-14 02:40:51', '2025-12-14 02:49:54'),
(583, 4, 302, '<p>Fungsi kuadrat Fungsi polinomial berderajat dua, berbentuk f(x) = ax^2 + bx + c. Grafiknya Selalu berbentuk parabola. Titik Puncak (xp, yp) mewakili nilai ekstrem (maksimum atau minimum).</p>', NULL, '<p>Tentukan apakah soal mencari nilai maksimum atau minimum.Terjemahkan soal ke dalam bentuk f(x) = ax^2 + bx + c. Pastikan tanda a sesuai dengan jenis ekstrem yang dicari (positif untuk minimum, negatif untuk maksimum).</p>', NULL, '<p>Penentuan Titik Puncak (xp dan yp): Hitung xp = -b/2a (nilai input optimal). Hitung yp = f(xp) (nilai maksimum atau minimum). Strategi ini digunakan untuk semua masalah optimasi (ketinggian maksimum, keuntungan maksimum, luas terbesar).</p><p><br></p>', NULL, '2025-12-14 02:53:26', '2025-12-14 02:57:21'),
(584, 4, 192, '<p>Saya mengetahui bahwasanya fungsi kuadrat berbentuk  dengan grafik parabola yang bisa digunakan untuk menentukan nilai maksimum atau minimum</p>', NULL, '<p>Membaca soal dengan cermat, memahami konteks masalahnya, menentukan variabel yang sesuai, memodelkan soal ke dalam bentuk fungsi kuadrat,lalu menyusun rencana penyelesaian sebelum melakukan perhitungan hasil akhir.</p>', NULL, '<p>Gunakan strategi sesuai konteks: jika bisa difaktorkan maka gunakan pemfaktoran. Jika tidak bisa, maka gunakan rumus kuadrat, pastikan solusi sesuai dengan situasi dalam soal (misalnya, nilai harus positif jika menyangkut jumlah benda).</p>', NULL, '2025-12-14 02:54:49', '2025-12-14 02:56:39'),
(585, 3, 287, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi segitiga, khususnya segitiga siku-siku. Saya memahami perbandingan sin, cos, dan tan, nilai dan sudut istimewa, </p>', NULL, '<p>Memahami soal, menuliskan informasi yang diketahui dan ditanya, membuat sketsa, menentukan perbandingan trigonometri yang tepat, lalu baru melakukan perhitungan.</p>', NULL, '<p>Saya menentukan strategi setelah memahami konteks soal, dengan menyesuaikan konsep atau rumus matematika yang tepat berdasarkan informasi yang diketahui dan yang ditanyakan.</p>', NULL, '2025-12-14 03:01:56', '2025-12-14 03:04:51'),
(586, 1, 297, '<p>defenisi eksponen, sifat sifat eksponen &amp; cara menyederhanakan eksponen</p>', NULL, '<p>mengidentifikasi soal dengan menuliskan apa yang diketahui terlebih dahulu, kemudian mendaftarkan semua yang diketahui, menuliskan rumusan masalah atau yang ditanyakan kemudian membuat penyelesaian</p><p><br></p>', NULL, '<p>memahami cerita dengan cari kata kunci misalnya “berlipat ganda”</p><p>Tentukan:</p><ul><li><strong>nilai awal</strong></li><li><strong>faktor pengali</strong></li><li><strong>jumlah pengulangan</strong></li></ul><p>Ubah ke model eksponen:</p>', NULL, '2025-12-14 03:02:14', '2025-12-14 03:11:15'),
(587, 1, 224, '<p>Saya mengetahui bahwa bilangan berpangkat adalah bentuk perkalian berulang dari bilangan yang sama dan memiliki sifat-sifat tertentu untuk memudahkan perhitungan.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan yang diketahui dan ditanya, mengubah ke bentuk eksponen, lalu menggunakan sifat eksponen yang sesuai.</p>', NULL, '<p>Saya menyelesaikan soal dengan memodelkan masalah ke bentuk eksponen dan memilih sifat eksponen yang tepat sesuai konteks soal.</p>', NULL, '2025-12-14 03:14:27', '2025-12-14 03:15:51'),
(588, 5, 275, '<p>Fungsi eksponen memiliki variabel di pangkat, grafik selalu positif melewati (0,1), dan persamaan eksponen diselesaikan dengan menyamakan pangkat.</p>', NULL, '<p>Sebelum menghitung hasil akhir soal cerita fungsi eksponen, pertama pahami informasi dalam soal seperti basis, eksponen, dan kondisi lain, lalu identifikasi apa yang diminta, apakah nilai eksponen, basis, atau hasil perhitungan fungsi eksponen.</p>', NULL, '<p>Dalam menyelesaikan soal fungsi eksponen, pahami konsep dasar, amati pola antara basis dan eksponen, lalu tentukan nilai yang diminta.</p>', NULL, '2025-12-14 03:20:35', '2025-12-14 03:27:07'),
(589, 5, 242, '<p>Dari materi ini, saya mengetahui bahwa fungsi eksponen digunakan untuk memodelkan pertumbuhan dan peluruhan, dituliskan dalam bentuk . Jika&nbsp;menunjukkan pertumbuhan (misalnya bakteri), sedangkan&nbsp;menunjukkan peluruhan (misalnya dosis obat).</p>', NULL, '<p>Langkah yang dilakukan adalah memahami konteks soal, menentukan nilai awal dan faktor perubahan, menetapkan variabel waktu, lalu memodelkannya ke dalam fungsi eksponen sebelum menghitung hasil akhir.</p>', NULL, '<p>Strategi dimiliki ketika saya mampu mengenali apakah masalah termasuk pertumbuhan atau peluruhan, lalu memilih model eksponen yang sesuai dan menyesuaikannya dengan satuan waktu serta kondisi yang diberikan dalam soal.</p>', NULL, '2025-12-14 03:25:27', '2025-12-14 03:26:05'),
(590, 5, 251, '<p>Eksponen merupakan bentuk perkalian berulang suatu bilangan dengan dirinya sendiri, juga dikenal sebagai bilangan berpangkat.</p>', NULL, '<p>Langkah-langkah menyelesaikan soal cerita matematika pada topik eksponen dilakukan secara sistematis sebelum perhitungan akhir untuk memastikan pemahaman konteks.</p>', NULL, '<p>Strategi pemecahan masalah matematika pada konteks cerita, termasuk eksponen, diterapkan saat soal menyajikan skenario nyata seperti pertumbuhan populasi atau bunga majemuk yang memerlukan identifikasi pola eksponensial terlebih dahulu.</p>', NULL, '2025-12-14 03:28:13', '2025-12-14 03:33:26'),
(591, 3, 293, '<p>Trigonometri mempelajari hubungan antara sudut dan panjang sisi segitiga, terutama segitiga siku-siku. </p>', NULL, '<p>Langkah yang dilakukan adalah membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, lalu memilih rumus yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Saya memiliki strategi setelah memahami masalah dan menentukan rumus yang sesuai, lalu menyelesaikannya secara sistematis.</p>', NULL, '2025-12-14 03:30:46', '2025-12-14 03:35:45'),
(592, 3, 216, '<p>Hubungan sudut dan sisi dari segitiga siku - siku, perbandingan trigonometri untuk sudut lancip, hubungan sinus dan cosinus untuk sudut penyiku, serta perbandingan trigonometri dan teorema phytagoras</p>', NULL, '<p>sebelum menghitung hasil akhir dari soal langkah pertama pahami dengan baik informasi yang terdapat pada soal, selanjutnya menggambar diagram atau sketsa, lalu cek kembali langkah langkah perhitungan yang akan dilakukan</p>', NULL, '<p>Saat menghadapi soal trigonometri,</p><ol><li> identifikasi informasi yang diberikan soal</li><li>Pahami konsep dasar trigonometri</li></ol><p><br></p>', NULL, '2025-12-14 03:36:06', '2025-12-14 03:43:16'),
(593, 1, 200, '<p>saya mengetahui bilangan eksponen yaitu, bentuk sederhana dari perkalian berulang</p>', NULL, '<p>Yaitu:</p><ol><li>Membaca soal dengan teliti.</li><li>Menentukan apa yang diketahui dan ditanyakan.</li><li>Menentukan konsep yang digunakan.</li><li>Menyusun model matematika.</li><li>Baru melakukan perhitungan.</li></ol><p><br></p>', NULL, '<p>Strategi saya adalah memahami konteks soal, menentukan konsep yang digunakan, mengubahnya ke model matematika, lalu menyelesaikannya langkah demi langkah.</p>', NULL, '2025-12-14 03:41:18', '2025-12-14 03:48:12'),
(594, 5, 250, '<p>Fungsi eksponen adalah <strong>fungsi matematika yang variabelnya terletak pada pangkat (eksponen)</strong>, dengan bentuk umum:</p><p>f(x)=axf(x) = a^xf(x)=axdengan syarat:</p><ul><li>a&gt;0a &gt; 0a&gt;0</li><li>a≠1a \\neq 1a=1</li></ul><p><br></p>', NULL, '<h2>memahami soal → mengidentifikasi data → menentukan model → memeriksa → menghitung</h2>', NULL, '<p>strategi muncul <strong>sebelum perhitungan dilakukan</strong>, tepatnya pada saat menganalisis soal.</p>', NULL, '2025-12-14 03:41:20', '2025-12-14 03:45:45'),
(595, 5, 302, '<p><span style=\"color: rgb(55, 65, 81);\">Fungsi eksponen f(x) = a · b^x menunjukkan pertumbuhan jika b &gt; 1 dan peluruhan jika 0 &lt; b &lt; 1.</span></p>', NULL, '<p><span style=\"color: rgb(55, 65, 81);\">Baca soal teliti. Tentukan besaran diketahui/ditanyakan. Identifikasi pertumbuhan (b&gt;1) atau peluruhan (0&lt;b&lt;1). Tentukan nilai awal dan rasio. Buat model f(x)=a·b^x. Hitung jawaban</span></p>', NULL, '<p><span style=\"color: rgb(55, 65, 81);\">Setelah paham konteks. Gunakan fungsi eksponen pertumbuhan untuk peningkatan berkala, peluruhan untuk pengurangan. Sesuaikan dengan persentase perubahan dan waktu agar model cocok situasi nyata.</span></p>', NULL, '2025-12-14 03:44:15', '2025-12-14 03:47:26'),
(596, 2, 242, '<p>Saya mengetahui bahwa SPL digunakan untuk mencari nilai variabel, sedangkan SPtL digunakan untuk menentukan daerah penyelesaian, dengan metode grafik, eliminasi, dan substitusi.</p>', NULL, '<p>Memahami soal, memodelkan ke bentuk SPL atau SPtL, lalu memilih metode penyelesaian sebelum menghitung.</p><p><br></p>', NULL, '<p>Strategi ditentukan dengan menyesuaikan jenis sistem dan konteks soal, kemudian menginterpretasikan hasil sesuai masalah.</p><p><br></p>', NULL, '2025-12-14 03:49:07', '2025-12-14 03:49:47'),
(597, 4, 248, '<p>Materi ini tentang <strong>persamaan dan fungsi kuadrat</strong>, cara menyelesaikannya, serta grafik parabola dan sifat-sifatnya.</p>', NULL, '<p>Baca soal, tentukan diketahui dan ditanya, ubah ke model matematika, lalu pilih cara penyelesaiannya.</p><p><br></p>', NULL, '<p>Strateginya adalah memahami konteks soal, memodelkannya ke persamaan atau fungsi kuadrat, lalu memilih metode penyelesaian yang paling sesuai.</p>', NULL, '2025-12-14 03:49:24', '2025-12-14 03:51:12'),
(598, 6, 275, '<p><span style=\"color: rgb(51, 65, 85);\">Saya telah mempelajari bahwa vektor adalah besaran yang memiliki besar dan arah serta dapat direpresentasikan dengan panah dalam matematika.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Vektor dalam matematika adalah besaran yang memiliki besar dan arah, seperti panjang dan arah gerak. Contoh vektor adalah gaya, percepatan, dan kecepatan</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Ketika menghadapi soal matematika tentang vektor, penting untuk memahami definisi vektor dan operasinya terlebih dahulu sebelum merumuskan strategi penyelesaiannya.</span></p>', NULL, '2025-12-14 03:55:09', '2025-12-14 03:58:35'),
(599, 3, 198, '<p>Konsepnya, contohnya dalam kehidupan sehari-hari serta soal dan penyelesaiannya</p>', NULL, '<p>Baca soal dengan teliti dan identifikasi informasi penting. Tulis yang diketahui dan ditanya. Buat sketsa segitiga dan beri label pada sisi serta sudut. Tentukan rumus trigonometri yang sesuai (sin, cos, tan).</p>', NULL, '<p>Saya memilih strategi setelah memahami jenis masalah. Identifikasi tipe soal, analisis informasi, tentukan konsep yang relevan, pilih metode penyelesaian (diagram/persamaan), lalu evaluasi hasilnya agar logis dan efisien.​​​​​​​​​​​​​​​​</p>', NULL, '2025-12-14 03:56:20', '2025-12-14 04:02:59'),
(600, 1, 351, '<p><strong>yang saya ketahui pada materi ini adalah </strong></p><ol><li>definisi eksponen</li><li>sifat sifat eksponen </li><li>penyederhanaan eksponen</li></ol>', NULL, NULL, NULL, NULL, NULL, '2025-12-14 04:03:09', '2025-12-14 04:03:09'),
(601, 3, 285, '<p><span style=\"color: rgb(51, 65, 85);\">Perbandingan trigonometri, seperti sin, cos, dan tan, penting untuk menghitung sudut dalam segitiga siku-siku dan menyelesaikan masalah trigonometri.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Sebelum menghitung hasil akhir, langkah pertama  adalah mengidentifikasi informasi yang diberikan dalam soal. Kemudian, hubungkan informasi tersebut dengan konsep perbandingan trigonometri </span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Saya memiliki strategi saat menyelesaikan soal matematika dengan memahami terlebih dahulu konsep dasarnya, kemudian mencari pola-pola yang relevan untuk menyelesaikan masalah tersebut.</span></p>', NULL, '2025-12-14 04:07:02', '2025-12-14 04:10:05'),
(602, 5, 248, '<p>Saya mengetahui bahwa eksponen adalah bentuk perkalian berulang yang ditulis dalam bentuk pangkat serta memiliki aturan-aturan tertentu untuk memudahkan perhitungan.</p>', NULL, '<p>Langkah-langkahnya adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, mengubah soal cerita ke bentuk matematika, lalu memilih rumus yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Saya memiliki strategi ketika sudah memahami konteks soal, dengan cara memilih metode atau rumus yang sesuai, membuat langkah-langkah sistematis, dan menyesuaikan perhitungan agar relevan dengan masalah yang diberikan.</p>', NULL, '2025-12-14 04:07:46', '2025-12-14 04:09:06'),
(603, 3, 317, '<p>Hubungan Sudut dan Sisi Dari Segitiga Siku-Siku</p><p>Perbandingan Trigonometri Untuk Sudut Lancip</p><p>Hubungan Antara Sinus dan Cosinus Untuk Sudut Penyiku</p><p>Perbandingan Trignometri dan Teorema Phytagoras</p>', NULL, '<p>Pahami Konteks dan Identifikasi Data Kunci</p><p>Visualisasikan dan Gambar Sketsa</p><p>Tentukan Hubungan Sisi dan Sudut</p><p>Pilih perbandingan Trigonometri yang Tepat</p><p>Tuliskan Model Persamaan Matematika</p>', NULL, '<p>Strategi penyelesaian ditentukan pada fase pembacaan dan pemodelan awal soal.</p><p>Pemilihan strategi adalah</p><ol><li>SOH CAH TOA </li><li>Aturan Sinus </li><li>&nbsp;Aturan Kosinus </li></ol><p><br></p>', NULL, '2025-12-14 04:13:07', '2025-12-14 04:19:03'),
(604, 6, 250, '<p><strong>Vektor</strong>&nbsp;adalah konsep matematika yang menggambarkan besaran yang memiliki&nbsp;<strong>arah dan besar (magnitude)</strong>.</p>', NULL, '<p>Pahami dan representasikan vektor</p><p> Lakukan operasi vektor dengan aturan yang benar</p><p> Periksa dan tafsirkan hasil akhir</p>', NULL, '<p><strong>setelah memahami soal</strong>, <strong>saat memilih bentuk vektor</strong>, dan <strong>ketika menentukan operasi yang digunakan</strong>.</p><p><br></p>', NULL, '2025-12-14 04:25:13', '2025-12-14 04:29:51'),
(605, 3, 268, '<p>Saya sudah memahami perbandingan trigonometri pada segitiga siku-siku (sin, cos, tan), identitas trigonometri dasar, serta penerapan trigonometri dalam menghitung tinggi, jarak, dan sudut.</p>', NULL, '<p>Saya akan memahami konteks soal terlebih dahulu, menggambar atau memvisualisasikan situasi, lalu memilih rumus trigonometri yang sesuai untuk menghitung yang ditanyakan.</p><p><br></p>', NULL, '<p>Saya menggunakan strategi trigonometri saat soal melibatkan sudut dan panjang sisi pada segitiga, terutama dalam konteks tinggi bangunan, bayangan, atau kemiringan bidang.</p>', NULL, '2025-12-14 04:26:53', '2025-12-14 04:27:57'),
(606, 4, 260, '<p>Tiga cara menyelesaikan persamaan kuadrat, yaitu:</p><p>Faktorisasi</p><p>Melengkapkan kuadrat sempurna</p><p>Menggunakan rumus kuadrat (rumus ABC)</p><p>&nbsp;</p>', NULL, '<p>Membaca dan memahami soal dengan teliti</p><p>Menentukan apa yang diketahui dan apa yang ditanyakan</p><p>Menetapkan variabel yang mewakili besaran yang dicari dan Menyusun model matematika dalam bentuk fungsi kuadrat sesuai cerita soal.</p>', NULL, '<p>Menentukan tujuan soal (mencari nilai maksimum/minimum, akar, atau grafik).</p><p>Memilih metode yang sesuai  dan Menafsirkan hasil perhitungan kembali ke konteks soal untuk memastikan jawabannya masuk akal.</p>', NULL, '2025-12-14 04:27:39', '2025-12-14 04:42:56'),
(607, 6, 248, '<p><strong>Vektor:</strong> besaran dengan <strong>besar &amp; arah</strong>, direpresentasikan <strong>panah/koordinat</strong>, bisa dijumlahkan, dikurang, dikalikan skalar, digunakan di <strong>gaya, kecepatan, navigasi</strong>.</p><p><br></p>', NULL, '<p>Baca soal → tentukan vektor &amp; arahnya → pilih representasi → tulis persamaan → cek data sebelum menghitung.</p>', NULL, '<p>Pahami masalah → identifikasi informasi → pilih operasi → rencanakan perhitungan → cek jawaban.</p>', NULL, '2025-12-14 04:35:15', '2025-12-14 04:37:32'),
(608, 4, 306, '<p>Fungsi kuadrat adalah fungsi yang memiliki pangkat tertinggi dan Grafik fungsi kuadrat berbentuk parabola yang dapat terbuka ke atas atau ke bawah.</p>', NULL, '<p>Langkah awal adalah memahami soal cerita dan menentukan variabel yang digunakan. Selanjutnya menyusun fungsi kuadrat sesuai konteks soal sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi penyelesaian dipilih berdasarkan tujuan soal, seperti mencari titik puncak, akar, atau nilai maksimum dan minimum. Pemilihan metode yang tepat membantu memperoleh solusi yang sesuai dengan konteks masalah.</p>', NULL, '2025-12-14 04:37:52', '2025-12-14 04:38:29'),
(609, 6, 302, '<p>Vektor adalah besaran yang memiliki besar dan arah, direpresentasikan dengan anak panah atau komponen, serta digunakan dalam fisika, matematika, dan geometri.</p>', NULL, '<p>Langkahnya membaca soal, mengidentifikasi vektor dan arahnya, menggambar diagram, menentukan operasi vektor yang tepat, lalu melakukan perhitungan secara sistematis.</p>', NULL, '<p>Strategi digunakan ketika soal melibatkan arah dan besar, dengan memilih metode diagram atau komponen sesuai konteks agar penyelesaian lebih tepat dan efisien.</p>', NULL, '2025-12-14 04:46:30', '2025-12-14 04:47:05'),
(610, 3, 242, '<p>Saya memahami SPL dan SPtL untuk menentukan nilai atau daerah solusi, serta trigonometri untuk menyelesaikan masalah sudut dan jarak.</p>', NULL, '<p>Menentukan variabel, memodelkan soal ke bentuk SPL, SPtL, atau trigonometri, lalu memilih metode yang sesuai sebelum menghitung.</p>', NULL, '<p>Strategi ditentukan dari konteks soal: SPL untuk nilai pasti, SPtL untuk batasan, dan trigonometri untuk hubungan sudut dan sisi.</p>', NULL, '2025-12-14 04:47:09', '2025-12-14 04:47:40'),
(611, 1, 290, '<p>Eksponen adalah bentuk perkalian bilangan berpangkat</p><p>Misal, 3⁴ = 3 × 3 × 3 × 3</p><p>dengan 3 sebagai basis, dan</p><p>4 sebagai eksponennya</p>', NULL, '<ol><li>Membaca soal dengan cermat</li><li>Menentukan apa saja yang diketahui dan ditanyakan</li><li>Menghubungkan cerita dengan konsep eksponen</li><li>Meniliskan bentuk matematikanya</li><li>Menentukan strategi penyelesaian</li></ol>', NULL, '<p>Untuk memiliki strategi dalam menyelesaikan soal pada topik ini sesuai konteks masalah matematika, yaitu melakukan pendekatan sistematis dengan pemahaman konsep bukan langsung mengerjakannya, tapi menerapkan langkah-langkah pengerjaannya.</p>', NULL, '2025-12-14 04:48:02', '2025-12-14 05:01:32'),
(612, 1, 234, '<p>apa itu bilangan eksponen dan sifat-sifat bilangan eksponen</p>', NULL, '<p>pertama membuat bentuk matematika dan pahami soalnya secara seksama agar tidak salah dalam menempatkan bilangan pangkatnya</p>', NULL, NULL, NULL, '2025-12-14 04:59:40', '2025-12-14 05:05:17'),
(613, 1, 289, '<p>saya mengetahui bahwa pengetahuan metakognisi adalah kemampuan seseorang untuk memahami dan menyadari proses berpikirnya sendiri.</p>', NULL, '<p>Langkah menyelesaikan soal eksponen adalah membaca soal dengan cermat, menentukan apa yang diminta, menerapkan konsep eksponen, menghitung secara sistematis, dan memeriksa kembali jawaban.</p>', NULL, '<p>Pahami konsep eksponen sebagai perkalian berulang, lalu terapkan aturan-aturan eksponen untuk menyelesaikan soal.</p>', NULL, '2025-12-14 05:06:59', '2025-12-14 05:20:49'),
(614, 3, 302, '<p>Trigonometri mempelajari hubungan sudut dan sisi segitiga siku-siku melalui perbandingan sinus cosinus tangen serta penerapannya untuk menghitung jarak dan tinggi dalam kehidupan sehari-hari.</p>', NULL, '<p>Baca soal dengan teliti, identifikasi sudut dan sisi, tentukan perbandingan trigonometri yang sesuai, buat sketsa segitiga, tulis rumus, lalu hitung secara sistematis dan periksa hasil.</p><p><br></p>', NULL, '<p>Strategi dipilih ketika memahami konteks soal, dengan menyesuaikan perbandingan trigonometri yang digunakan, mempertimbangkan sudut diketahui, tujuan perhitungan, serta informasi yang tersedia dalam kehidupan sehari-hari nyata.</p>', NULL, '2025-12-14 05:08:52', '2025-12-14 05:09:34'),
(615, 5, 306, '<p>Eksponen adalah bentuk perkalian berulang dengan bilangan yang sama dan disebut juga bilangan berpangkat. Aturan-aturan eksponen digunakan untuk menyederhanakan dan menyelesaikan perhitungan matematika.</p>', NULL, '<p>Langkah awal adalah memahami soal cerita dan mengidentifikasi bentuk eksponen yang digunakan. Selanjutnya menerapkan sifat-sifat eksponen secara tepat sebelum menghitung hasil akhirnya.</p>', NULL, '<p>Strategi dipilih sesuai dengan jenis soal, misalnya menggunakan sifat eksponen untuk menyederhanakan perhitungan. Pemilihan strategi dilakukan agar penyelesaian lebih efisien dan sesuai konteks masalah.</p>', NULL, '2025-12-14 05:11:16', '2025-12-14 05:12:02'),
(616, 4, 246, '<p><br></p><p>Persamaan kuadrat tidak hanya diselesaikan secara aljabar, tetapi juga dapat dipahami secara grafik dan Grafik fungsi kuadrat memiliki sifat-sifat khas yang ditentukan oleh koefisien dan diskriminan</p><p><br></p>', NULL, '<p>pahami soal, tentukan variabel dan model matematika, lalu pilih metode penyelesaian yang tepat sebelum menghitung</p>', NULL, '<p>memahami soal dan menentukan variabel, membuat metode persamaan,  memilih metode penyelesaian yang tepat, melalkukan perhitungan, lalu memeriksa hasil.</p>', NULL, '2025-12-14 05:21:15', '2025-12-14 05:29:28'),
(617, 4, 256, '<ul><li>Bentuk Umum:&nbsp;f(x) = ax² + bx + c</li><li>Grafik:&nbsp;Parabola (terbuka ke atas jika a &gt; 0, terbuka ke bawah jika a &lt; 0)</li></ul><p><br></p>', NULL, '<ol><li>Pahami soal:&nbsp;Apa yang diketahui dan ditanyakan?</li><li>Buat model matematika:&nbsp;Ubah soal cerita jadi persamaan/fungsi kuadrat.</li></ol><p><br></p><p><br></p>', NULL, '<ol><li>Nilai Maksimum/Minimum</li><li>Akar-Akar</li></ol>', NULL, '2025-12-14 05:22:52', '2025-12-14 05:28:11'),
(618, 6, 241, '<ol><li>Definisi vektor</li><li>Pengoperasian vektor</li><li>Operasi vektor dengan cara analitik dan geometri</li></ol>', NULL, '<p>Pahami soal, identifikasi vektor dan tujuannya. Rencanakan dengan membuat diagram atau menentukan operasi vektor (penjumlahan, perkalian). Kerjakan dengan teliti, lalu periksa kembali sebelum menyimpulkan jawaban dengan jelas dan satuan yang tepat.</p>', NULL, '<p>Strategi soal vektor penting untuk masalah kompleks yang butuh pemahaman mendalam. Kembangkan strategi dengan melihat konteks, hubungan antar vektor, dan pilih metode efisien (grafis, analitis, atau prinsip fisika) agar penyelesaian terarah.</p>', NULL, '2025-12-14 05:24:17', '2025-12-14 05:29:58'),
(619, 1, 229, '<p>yang saya ketahui&nbsp;dari materi aljabar pada topik ini adalah bahwa perkalian berulang dapat ditulis dalam bentuk perpangkatan. perpangkatan digunakan untuk menyerdehanakan penulisan perkalian dengan bilangan yang sama secara berulang.</p>', NULL, '<ol><li>membaca soal dengan teliti</li><li>menentukan informasi penting</li><li>mengubah kalimat cerita dalam bentuk matematika</li><li>menentukan rumus atau konsep yang sesuai</li><li>menyusun langkah penyelesaian secara sistematis  </li></ol>', NULL, '<p>memhami konteks soal, menentukan informasi yang diketahui daan ditanyakan </p>', NULL, '2025-12-14 05:26:12', '2025-12-14 05:38:06'),
(620, 4, 309, '<p>Fungsi kuadrat berbentuk ax² + bx + c.</p><p> Grafiknya parabola.</p><p> a &gt; 0 terbuka ke atas, a &lt; 0 terbuka ke bawah.</p><p> Memiliki titik puncak dan sumbu simetri.</p><p> Akar ditentukan dengan diskriminan.</p><p><br></p>', NULL, '<p>Membaca soal dengan teliti.</p><p> Menentukan diketahui dan ditanya.</p><p> Menentukan variabel.</p><p> Membuat model matematika.</p>', NULL, '<p>Memahami konteks soal.</p><p> Menentukan model fungsi kuadrat yang sesuai.</p><p> Memilih cara penyelesaian yang tepat.</p><p> Menafsirkan hasil sesuai masalah.</p>', NULL, '2025-12-14 05:27:40', '2025-12-14 05:30:37'),
(621, 5, 260, '<p>Fungsi eksponen adalah fungsi dengan variabel di pangkat yang digunakan untuk menggambarkan pertumbuhan atau peluruhan.</p><p><br></p>', NULL, '<p>Memahami soal, menentukan data yang diketahui dan ditanya, mengenali jenis eksponen, lalu membuat model matematika.</p><p><br></p>', NULL, '<p>Strategi dipilih setelah memahami konteks soal, kemudian menggunakan metode yang paling sesuai agar penyelesaian tepat.</p>', NULL, '2025-12-14 05:29:16', '2025-12-14 05:30:26'),
(622, 2, 234, '<p>definisi sistem persamaan linear dan pertidaksamaan lenear salah  satunya yang tiga variabel dan mengetahui konsep dan cara penyelesaiannya serta langkah proses penyelesaiaannya</p>', NULL, '<p>memisalkan untuk suatu objek ke bentuk variabel dan bentuk ke bentuk matematika setelah di analisis soalnya serta melakukan dengan penyesalain yang sesuai dengan soalnya</p>', NULL, NULL, NULL, '2025-12-14 05:29:29', '2025-12-14 05:31:20'),
(623, 4, 300, '<p>karakteristik fungsi kuadrat, cara menentukan akar-akar persamaan kuadrat</p>', NULL, '<p>Membaca soal dengan cermat, Mengidentifikasi informasi yang diketahui, Menentukan apa yang ditanyakan, Menentukan variabel yang sesuai, Menyusun model matematika, Menyederhanakan persamaan, Dan Memeriksa kembali model yang dibuat</p>', NULL, '<p>Saya menetapkan variabel untuk mewakili besaran yang belum diketahui agar model matematika menjadi jelas.</p>', NULL, '2025-12-14 05:31:12', '2025-12-14 05:48:20'),
(624, 3, 250, '<p>Perbandingan trigonometri merupakan konsep penting dalam matematika yang menjelaskan hubungan antara besar sudut dan panjang sisi pada sebuah segitiga yang memiliki satu sudut siku-siku.</p>', NULL, '<p>Membaca dan memahami soal </p><p>Menentukan sudut acuan dan posisi sisi</p><p>Memilih perbandingan trigonometri yang tepat</p>', NULL, '<p><strong>Membaca dan memahami soal</strong> </p><p><strong>Menentukan sudut acuan dan posisi sisi</strong> </p><p><strong>Memilih perbandingan trigonometri yang tepat</strong> </p>', NULL, '2025-12-14 05:33:18', '2025-12-14 05:39:53'),
(625, 3, 217, '<p>hubungan antara sudut dan sisi pada segitiga siku-siku, perbandingan trigonometri untuk sudut lancip, hubungan sinus dan cosinus pada sudut penyiku, serta keterkaitannya dengan Teorema Pythagoras dalam menentukan panjang sisi segitiga.</p>', NULL, '<p> memahami isi soal, menentukan sudut dan sisi yang diketahui serta ditanyakan, membuat sketsa segitiga siku-siku, kemudian memilih perbandingan trigonometri yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi penyelesaian saya tentukan berdasarkan konteks masalah dan informasi yang ada. Jika soal melibatkan sudut dan sisi segitiga siku-siku, saya menggunakan perbandingan trigonometri yang sesuai agar memperoleh jawaban yang tepat.</p>', NULL, '2025-12-14 05:35:08', '2025-12-14 05:37:51'),
(626, 3, 215, '<p>1. Menentukan perbandingan trigonometri, </p><p>2. Memecahkan masalah yang melibatkan segitiga siku-siku</p>', NULL, '<p><span style=\"background-color: oklch(0.9902 0.004 106.47); color: oklch(0.3039 0.04 213.68);\"> membaca soal secara teliti, menggambar sketsa segitiga siku-siku, dan menentukan rasio trigonometri Selanjutnya, susun persamaan.</span></p>', NULL, '<p>ketika soal melibatkan pengukuran tidak langsung. mengg<span style=\"background-color: oklch(0.9902 0.004 106.47); color: oklch(0.3039 0.04 213.68);\">unakan aturan sinus/cosinus jika segitiga tidak siku-siku, dan menyesuaikan dengan konteks.</span></p>', NULL, '2025-12-14 05:37:54', '2025-12-14 05:45:18'),
(627, 3, 202, '<ol><li>pebandingan trigonometri</li><li>teorema pytagoras</li><li>pemamfaatan perbandingan triginometri</li></ol>', NULL, '<p>Baca soal dengan cermat, Identifikasi segitiga dan sisi/sudut yang diketahui, Pilih perbandingan trigonometri yang sesuai (sin, cos, tan), Tuliskan persamaan dan hitung nilai yang dicari dan Periksa hasil agar masuk akal dengan konteks soal.</p>', NULL, '<p>Gunakan strategi trigonometri ketika ada <strong>segitiga dengan sisi atau sudut diketahui</strong>. Pilih fungsi yang tepat, buat persamaan, dan hitung secara sistematis agar hasil sesuai konteks masalah.</p>', NULL, '2025-12-14 05:40:14', '2025-12-14 05:44:27'),
(628, 2, 200, '<p>pengertian sistem persamaam linear yaitu himpunan beberapa persamaan linear yg saling terkait, dimana keofisien persamaannya adalah bilangan real.</p>', NULL, '<ol><li>memahami soal secara menyeluruh</li><li>mengumpulkan informasi kunci</li><li>merumuskan strategi</li><li>periksa kembali</li></ol>', NULL, '<p>Pahami soal: identifikasi pertanyaan dan konteks masalah</p><p>kumpulkan data: catat nilai numerik, tetapkan variabel dan abaikan data yg tdk penting</p><p>rumuskan strategi: pilih rumus/operasi yg tepat lalu tuliskan model matematika (persamaan).</p>', NULL, '2025-12-14 05:41:02', '2025-12-14 05:49:27'),
(629, 5, 246, '<p>Eksponen adalah perkalian berulang dari bilangan yang sama, dan disebut bilangan pangkat.</p>', NULL, '<p>Baca dan pahami soal, tentukan informasi yang diberikan dan yang ditanya, modelkan ke fungsi eksponen sesuai konteks, susun tabel nilai, lakukan perhitungan, dan gambarkan grafik untuk memvisualisasikan perubahan nilai.</p>', NULL, '<p>Gunakan strategi setelah memahami konteks soal: untuk pertumbuhan gunakan fungsi eksponen dengan a&gt;1a &gt; 1a&gt;1, untuk peluruhan gunakan 0&lt;a&lt;10 &lt; a &lt; 10&lt;a&lt;1. </p>', NULL, '2025-12-14 05:50:57', '2025-12-14 05:51:54'),
(630, 3, 275, '<p><span style=\"color: rgb(51, 65, 85);\">Saya sudah memahami bahwa perbandingan trigonometri merupakan hubungan antara panjang sisi-sisi dalam segitiga dengan sudut-sudutnya.</span></p>', NULL, '<p>langkah yang dapat saya lakukan yaitu perbandingan trigonometri menghubungkan sisi dan sudut melalui sin, cos, dan tan sehingga dapat menghitung panjang sisi atau ukuran sudut dalam soal.</p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Pada saat menyelesaikan soal matematika, saya biasanya memulai dengan memahami konsep dasar terlebih dahulu sebelum mencari strategi yang tepat untuk menyelesaikannya.</span></p>', NULL, '2025-12-14 05:51:46', '2025-12-14 06:08:39'),
(631, 5, 310, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki besar dan arah, dapat direpresentasikan dalam bentuk komponen, dan dapat dijumlahkan atau dikalikan dengan skalar.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan vektor dan komponennya → buat diagram jika perlu → susun persamaan vektor → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis arah dan besar vektor, memilih operasi vektor yang sesuai, dan menyusun langkah penyelesaian sistematis.</p>', NULL, '2025-12-14 05:51:50', '2025-12-14 05:52:52'),
(632, 5, 234, '<p>apa  itu definisi fungsi eksponen, pertumbuhan dan penurunan eksponen serta grafik fungsi eksponen</p>', NULL, '<p>menganalisis soal tersebut lalu membuat bentuk matematika lalu menyelesaikannya dengan  rumus penyelesaian  yang sesuai materi topik di bahas soal</p>', NULL, NULL, NULL, '2025-12-14 05:54:36', '2025-12-14 05:57:02'),
(633, 3, 248, '<p>Trigonometri mempelajari hubungan sudut dan sisi segitiga siku-siku serta penerapannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Baca soal dan pahami yang ditanyakan.</p><p>Tentukan sisi dan sudut yang diketahui.</p><p>Gambar segitiga jika perlu.</p><p>Pilih perbandingan trigonometri yang sesuai.</p><p>Tulis persamaan sebelum menghitung.</p>', NULL, '<p>Strategi dilakukan dengan <strong>memahami soal, memilih konsep yang tepat, merencanakan langkah, menghitung, dan memeriksa hasil</strong> sesuai konteks masalah.</p>', NULL, '2025-12-14 05:59:34', '2025-12-14 06:01:46'),
(634, 6, 260, '<p>Vektor adalah besaran yang memiliki arah dan besar, dapat dinyatakan dengan komponen, gambar panah, atau koordinat.</p><p><br></p>', NULL, '<p>Membaca soal dengan teliti, menentukan vektor yang diketahui dan ditanya, menetapkan arah dan satuan, lalu memodelkan masalah ke bentuk vektor.</p><p><br></p>', NULL, '<p>Strategi dipilih setelah memahami konteks soal, misalnya menggunakan komponen, penjumlahan vektor, atau rumus besar vektor agar penyelesaian tepat.</p>', NULL, '2025-12-14 06:01:10', '2025-12-14 06:01:58'),
(635, 2, 297, '<p>defenisi persamaan dan pertidaksamaan linear, cara penyelesaian nya, dan himpunan penyelesaian persamaan tiga variabel</p>', NULL, '<ol><li>mendaftarkan yang diketahui, </li><li>menentukan variabel</li><li>membentuk persamaan </li><li>memilih metode penyelesaian</li></ol>', NULL, '<p>mengidentifikasi yang diketahui dan menetapkan variabel variabel berdasarkan yang diketahui dalam soal, lalu memodelkannya dalam persamaan atau pertidaksamaan linear kmudian menyelesaikannya untuk menentukan solusi yang sesuai</p><p><br></p>', NULL, '2025-12-14 06:01:15', '2025-12-14 06:04:54'),
(636, 4, 234, '<p>karakteristik fungsi kuadrat dan bagaimana cara menyelesaikannya</p>', NULL, '<p>analisis soalnya terlebih dahulu lalu memisalkan teru membentuknya ke bentuk umum fungsi kuadrat</p>', NULL, NULL, NULL, '2025-12-14 06:05:08', '2025-12-14 06:05:56'),
(637, 5, 256, '<ul><li>Bentuk:&nbsp;f(x) = a * b^x</li><li>Grafik:&nbsp;Kurva naik/turun tajam</li></ul><p><br></p>', NULL, '<ol><li>Pahami Soal:&nbsp;Baca teliti, identifikasi info &amp; pertanyaan.</li><li>Model Matematika:&nbsp;Ubah soal jadi persamaan eksponen.</li></ol><p><br></p>', NULL, '<ol><li><strong>Identifikasi Jenis:</strong>&nbsp;Pertumbuhan/Penyusutan?</li><li><strong>Cari Info Penting:</strong>&nbsp;a (awal), b (faktor), x (waktu).</li></ol><p><br></p>', NULL, '2025-12-14 06:06:11', '2025-12-14 06:08:38'),
(638, 6, 310, '<p>Saya mengetahui bahwa vektor adalah besaran yang memiliki besar dan arah, dapat direpresentasikan dalam bentuk komponen, dan dapat dijumlahkan atau dikalikan dengan skalar.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan vektor dan komponennya → buat diagram jika perlu → susun persamaan vektor → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal; caranya dengan menganalisis arah dan besar vektor, memilih operasi vektor yang sesuai, dan menyusun langkah penyelesaian sistematis.</p>', NULL, '2025-12-14 06:08:47', '2025-12-14 06:10:01'),
(639, 3, 227, '<p>Trigonometri adalah studi tentang hubungan sudut dan sisi pada segitiga. Segitiga Siku-Siku adalah fondasi utama. Sisi-sisinya diidentifikasi sebagai: Sisi Depan, Sisi Samping, dan Sisi Miring (Hipotenusa).</p><p><br></p><p><br></p>', NULL, '<p>Pertama membaca soal cerita dengan cermat lalu melihat bagian pertanyaanya. Setelah itu mencatat informasi-informasi penting berupa data angka, dan semacamnya lalu mulai meniliskan rumusnya untuk menyelesaikannya</p>', NULL, '<p>Ketika saya sudah bisa mevisulisasi dari soal yang ada</p>', NULL, '2025-12-14 06:08:58', '2025-12-14 06:20:33'),
(640, 6, 246, '<p>Vektor adalah besaran yang memiliki besar dan arah, bisa dioperasikan, serta memiliki jenis khusus seperti vektor nol, lawan, dan ekuivalen.</p>', NULL, '<p>&nbsp;Baca soal, identifikasi vektor, tentukan metode operasi (aljabar atau grafik), lalu hitung resultan.</p>', NULL, '<p>Gunakan strategi saat soal melibatkan arah dan besar, dengan memisahkan komponen, memilih metode yang tepat, dan memvisualisasikan vektor agar hasil logis.</p><p><br></p>', NULL, '2025-12-14 06:11:09', '2025-12-14 06:11:55'),
(641, 4, 315, NULL, NULL, NULL, NULL, '<p>Strategi utama untuk menyelesaikan soal aplikasi fungsi kuadrat selalu berpusat pada menemukan titik ekstrem (titik puncak) dari fungsi tersebut, karena titik puncak mewakili nilai maksimum atau minimum yang diminta oleh masalah.</p>', NULL, '2025-12-14 06:16:25', '2025-12-14 06:16:25'),
(642, 3, 290, '<p>Perbandingan trigonometri adalah perbandingan panjang sisi-sisi pada segitiga siku-siku yang bergantung pada besar sudutnya. Perbandingan ini digunakan untuk menghubungkan sudut dan sisi segitiga.</p>', NULL, '<ol><li>Membaca soal dan memahaminya</li><li>Menulis yang diketahui dan ditanyakan</li><li>Membuat sketsa atau gambar</li><li>Menentukan perbandingan trigonometri yang tepat</li><li>Menuliskan model matemaikanya</li></ol>', NULL, '<p>Memiliki strategi sejak mulai membaca soal, mengidentifikasi apa yang diketahui dan apa yang ditanyakan.</p><p><br></p>', NULL, '2025-12-14 06:23:47', '2025-12-14 07:11:23'),
(643, 3, 310, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi pada segitiga, termasuk fungsi sinus, cosinus, dan tangen serta penerapannya dalam masalah sudut dan panjang.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan sudut dan sisi yang diketahui → pilih fungsi trigonometri yang sesuai → susun persamaan → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal dengan menganalisis informasi sudut dan sisi, lalu memilih fungsi trigonometri dan langkah perhitungan yang tepat.</p>', NULL, '2025-12-14 06:30:11', '2025-12-14 06:31:05'),
(644, 4, 305, '<p>saya mengetahui bahwa Fungsi kuadrat memiliki grafik berbentuk parabola. Arah buka grafik dapat ke atas atau ke bawah dan memiliki satu titik puncak yang menunjukkan nilai maksimum atau minimum, serta titik potong dengan sumbu-x dan sumbu-y.</p>', NULL, '<p>Langkahnya adalah membaca soal dengan teliti, memahami apa yang diketahui dan ditanyakan, menentukan variabel, mengubah soal ke model matematika, lalu memilih cara penyelesaian yang tepat sebelum menghitung hasil akhir.</p>', NULL, '<p>Strategi saya adalah memahami konteks soal, menentukan data yang diketahui dan ditanyakan, membuat model matematika, lalu memilih cara penyelesaian yang tepat.</p>', NULL, '2025-12-14 06:30:25', '2025-12-14 06:35:44'),
(645, 2, 347, '<p>tentang penyelesaian <span class=\"ql-cursor\">﻿</span>Sistem Persamaan dan Pertidaksamaan Linear</p>', NULL, '<p>Membaca soal dengan cermat Menentukan variabel yang mewakili besaran yang belum diketahui, Menyusun model matematika, Menentukan metode penyelesaian yang tepat</p><p><br></p>', NULL, '<p>Strateginya adalah memodelkan masalah ke sistem persamaan atau pertidaksamaan linear, menyelesaikannya dengan metode yang sesuai, lalu menafsirkan hasilnya sesuai konteks masalah.</p><p><br></p>', NULL, '2025-12-14 06:31:49', '2025-12-14 06:37:12'),
(646, 4, 200, '<p>Fungsi kuadrat dalam x adalah suatu fungsi yang berbentuk 𝑓(𝑥)=𝒂𝒙𝟐+𝒃𝒙+𝒄<strong>,</strong></p><p>dengan a,b,c adalah bilangan real dan 𝑎≠0</p><p><br></p>', NULL, '<ol><li>baca dan pahami soal</li><li>definisi kan variabel </li><li>modelkan soal kedalam fungsi kuadrat </li><li><br></li></ol>', NULL, '<ol><li> analisis soal</li><li>definisi kan variabel</li><li>bangun model fungsi kuadrat</li><li>tahap perhitungan </li><li>tahap verifikasi </li><li>verifikasi dan logika</li></ol>', NULL, '2025-12-14 06:41:59', '2025-12-14 06:46:12'),
(647, 5, 309, '<p>Eksponen adalah perkalian berulang (bilangan berpangkat).</p><p> Fungsi eksponen berbentuk f(x) = n·a^x dengan a &gt; 0 dan a ≠ 1.</p><p> Terdapat pertumbuhan (a &gt; 1) dan peluruhan (0 &lt; a &lt; 1).</p>', NULL, '<p>Membaca dan memahami soal dengan cermat.</p><p>Menentukan apa yang diketahui dan yang ditanyakan.</p><p>Menentukan jenis fungsi eksponen yang digunakan (pertumbuhan atau peluruhan).</p><p>Membuat model matematika (rumus fungsi).</p><p><br></p>', NULL, '<p>Strategi ditentukan setelah memahami soal dan konteks masalah.</p><p> Caranya dengan mengidentifikasi jenis masalah, memilih rumus yang sesuai, lalu menyelesaikan secara sistematis sesuai langkah yang tepat.</p>', NULL, '2025-12-14 06:44:22', '2025-12-14 06:45:57'),
(648, 3, 223, '<p>yang telah saya ketahui yaitu mengenai definisi peluang dan trigonometri serta penjelasan tentang materi trigonometri</p>', NULL, '<p>Pahami Konteks &amp; Data</p><p>Buat Model:</p><ul><li>Trigonometri</li><li>Peluang</li></ul><p>Hitung: Aplikasikan rumus pada data.</p>', NULL, '<p>Saya membangun strategi dengan:</p><ol><li>Memilih Mode</li><li>Merumuskan Langkah</li></ol>', NULL, '2025-12-14 06:45:36', '2025-12-14 06:50:49'),
(649, 6, 256, '<p><span style=\"color: rgba(0, 0, 0, 0.85);\">Vektor adalah besaran yang memiliki nilai (magnitude) dan arah.</span></p>', NULL, '<p><strong>Baca Soal dengan Teliti:</strong>&nbsp;Jangan cuma sekali baca! Baca berulang-ulang sampai benar-benar paham apa yang ditanyakan dan informasi apa saja yang diberikan. Garis bawahi atau catat poin-poin pentingnya.</p><p><br></p>', NULL, '<p><span style=\"color: rgba(0, 0, 0, 0.85);\">Strategi dasarku terbentuk dari pemahaman konsep dasar vektor dan operasi-operasinya (penjumlahan, pengurangan, perkalian skalar, dot product, cross product). Ini seperti fondasi bangunan.</span></p>', NULL, '2025-12-14 06:46:58', '2025-12-14 06:49:31'),
(650, 5, 192, '<p>Fungsi eksponen menggambarkan sebuah proses perubahan yang terjadi secara sangat cepat, baik meningkat maupun menurun. Pada fungsi ini, suatu nilai bertambah atau berkurang dengan kecepatan yang semakin lama semakin besar.</p>', NULL, '<p>Pahami soal,tentukan variabel, serta model fungsi eksponen, kemudian menghitung sesuai yang ditanyakan.</p>', NULL, '<p>Strategi penyelesaian dipilih ketika soal memperlihatkan pola pertumbuhan yang cepat, dengan menyesuaikan model eksponen berdasarkan konteks masalah agar solusi yang diperoleh tepat dan logis.</p>', NULL, '2025-12-14 06:47:50', '2025-12-14 06:49:56'),
(651, 3, 260, '<p>Saya mengetahui bahwa trigonometri mempelajari hubungan antara sudut dan sisi pada segitiga, termasuk fungsi sinus, cosinus, dan tangen serta penerapannya dalam masalah sudut dan panjang.</p>', NULL, '<p>Langkah-langkahnya: pahami soal → tentukan sudut dan sisi yang diketahui → pilih fungsi trigonometri yang sesuai → susun persamaan → rencanakan perhitungan sebelum menyelesaikan.</p>', NULL, '<p>Saya memiliki strategi saat memahami konteks soal dengan menganalisis informasi sudut dan sisi, lalu memilih fungsi trigonometri dan langkah perhitungan yang tepat.</p>', NULL, '2025-12-14 07:00:45', '2025-12-14 07:01:31'),
(652, 1, 226, '<p>saya sudah mengetahui eksponen,fungsi kuadrat,sistem persamaan linear,serta vektor juga</p>', NULL, '<p>Baca soal dengan teliti, tentukan variabel yang sesuai, buat model matematika, pilih rumus atau metode yang tepat, substitusi dan sederhanakan, hitung hasilnya, periksa kembali hasil, tulis jawaban akhir.</p>', NULL, '<p>Pahami konteks soal, identifikasi informasi penting, tentukan variabel, pilih metode matematika yang tepat, susun dan selesaikan persamaan, periksa hasilnya.</p>', NULL, '2025-12-14 07:06:42', '2025-12-14 07:11:41'),
(653, 3, 241, '<ol><li>Perbandingan trigonometri</li><li>Teorema Pythagoras</li><li>Pemanfaatan perbandingan trigonometri</li></ol>', NULL, '<p>Baca soal dengan cermat, identifikasi segitiga dan sisi/sudut yang diketahui, pilih perbandingan trigonometri yang sesuai (sin, cos, tan), tuliskan persamaan dan hitung nilai yang dicari, periksa hasil agar masuk akal dengan konteks soal.</p>', NULL, '<p>Gunakan strategi trigonometri ketika ada segitiga dengan sisi atau sudut diketahui. Pilih fungsi yang tepat, buat persamaan, dan hitung secara sistematis agar hasil sesuai konteks masalah.</p>', NULL, '2025-12-14 07:08:06', '2025-12-14 07:10:23'),
(654, 5, 200, '<p>yang saya ketahui bahwa eksponen digunakan untuk menyatakan perkalian berulang dari suatu bilangan yang sama. Eksponen juga ditulis dalam bentuk bilangan berpangkat, di mana terdapat bilangan pokok dan pangkat.</p><p><br></p>', NULL, '<p>membaca dan menganalisis soal lalu menentukan rumus</p>', NULL, '<p>saat mengidentifikasi bahwa soal tersebut melibatkan operasi pangkat dan saat menentukan apa yg di minta oleh soal</p>', NULL, '2025-12-14 07:09:52', '2025-12-14 07:40:03');
INSERT INTO `jawaban_pengetahuan_metakognisi` (`id_jawaban_pengetahuan_metakognisi`, `id_eksplorasi_konsep`, `id_user`, `deklaratif`, `nilai_deklaratif`, `prosedural`, `nilai_prosedural`, `kondisional`, `nilai_kondisional`, `created_at`, `updated_at`) VALUES
(655, 2, 318, '<p>Saya mengetahui perbedaan persamaan dan pertidaksamaan linear serta cara menyelesaikannya menggunakan metode grafik, eliminasi, dan substitusi.</p>', NULL, '<p>Langkah-langkah yang sebaiknya dilakukan adalah memahami soal, menentukan variabel, membuat model matematika (persamaan atau pertidaksamaan), lalu memilih metode penyelesaian yang sesuai sebelum menghitung hasil akhirnya.</p>', NULL, '<p>Saya menyusun strategi dengan memahami konteks soal, menentukan variabel yang tepat, memodelkan masalah ke dalam persamaan atau pertidaksamaan linear, lalu memilih metode penyelesaian yang paling sesuai dengan masalah.</p>', NULL, '2025-12-14 07:11:25', '2025-12-14 07:13:13'),
(656, 4, 297, '<p>karakteristik fungsi kuadrat dan cara menentukan akar akar persamaan kuadrat</p><p><br></p>', NULL, '<p>memodelkannya dalam bentuk matematika tang sesuai, kemudian menyelesaikannya dengan metode yang saya anggap paling mudah</p>', NULL, '<p>strategi saya yaitu banyak banyak latihan soal dengan menggunakan metode yang saya pahami </p><p><br></p>', NULL, '2025-12-14 07:14:29', '2025-12-14 07:16:14'),
(657, 6, 309, '<p>Vektor adalah besaran yang memiliki besar dan arah serta dapat dioperasikan dan digunakan untuk menyatakan perpindahan, kecepatan, dan gaya.</p>', NULL, '<p>Membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, memilih konsep vektor yang sesuai, lalu membuat model matematikanya sebelum menghitung.</p>', NULL, '<p>Strategi ditentukan setelah memahami soal dan konteksnya, dengan cara mengidentifikasi jenis masalah, memilih konsep vektor yang tepat, lalu menyelesaikannya secara sistematis.</p>', NULL, '2025-12-14 07:17:19', '2025-12-14 07:18:38'),
(658, 1, 307, '<p>Menjelaskan pengertian solusi dari sistem persamaan linear tiga variabel berdasarkan pemahaman solusi dari sistem persamaan linear dua variabel.<span class=\"ql-cursor\">﻿</span></p>', NULL, '<p>Menentukan operasi matematika yang sesuai (perkalian berulang atau bentuk pangkat).</p><p>Menuliskan model matematika dari soal cerita tersebut.</p><p>Melakukan perhitungan untuk memperoleh hasil akhir.</p>', NULL, '<p>Pahami Konteks Soal</p><p>Tentukan Apa yang Diketahui dan Ditanyakan</p><p>Kenali Jenis Operasi yang Digunakan</p>', NULL, '2025-12-14 07:17:25', '2025-12-14 07:20:56'),
(659, 6, 200, '<p>pengertian vektor: vektor adalah besaran yg mempunyai besar atsu nilai dan arah</p>', NULL, '<p>menganalisis soal</p>', NULL, '<p>mengidentifikasi besaran vektor yg di ketahui dan ditanyakan, menentukan konsep atau rumus vektor yg sesuai, lalu menyesuaikan langkah penyelesaian dengsn konteks masalah agar hasilnya tepat</p><p><br></p>', NULL, '2025-12-14 07:17:30', '2025-12-14 07:21:53'),
(660, 5, 217, '<p>definisi fungsi eksponen dan sifat-sifat grafiknya</p>', NULL, '<p>Saya membaca soal dengan cermat, menentukan data yang diketahui dan ditanya, mengenali pola perubahan sebagai fungsi eksponen, lalu menyusun model matematika yang sesuai sebelum menghitung hasil akhir.</p><p><br></p>', NULL, '<p>Saya menggunakan strategi fungsi eksponen saat masalah melibatkan pertumbuhan atau penyusutan berulang, dengan mengubah soal cerita ke model eksponen yang sesuai konteks.</p>', NULL, '2025-12-14 07:19:48', '2025-12-14 07:22:23'),
(661, 3, 252, '<p>trigonometri</p>', NULL, '<ol><li>Membaca dan memahami soal</li><li>Menentukan diketahui dan ditanyakan</li><li>Membuat gambar/sketsa</li></ol><p><br></p>', NULL, '<p>Saya memiliki strategi untuk menyelesaikan soal matematika setelah memahami konteks masalah yang diberikan, yaitu dengan membaca soal secara teliti, mengidentifikasi informasi yang diketahui dan yang ditanyakan.</p>', NULL, '2025-12-14 07:21:37', '2025-12-14 07:25:23'),
(662, 6, 192, '<p>Vektor adalah besaran yang memiliki arah dan besar, dan dapat direpresentasikan dalam berbagai bentuk. Vektor digunakan untuk menjelaskan gerak, gaya, serta arah dalam kehidupan sehari-hari dan bidang teknologi.</p>', NULL, '<p>Pahami cerita soal, tentukan vektor yang terlibat, menuliskannya dalam bentuk komponen, kemudian melakukan operasi vektor yang diperlukan seperti penjumlahan, pengurangan, atau perkalian skalar.</p>', NULL, '<p>Ketika membaca soal. Identifikasi informasi penting, tentukan operasi yang dibutuhkan, pecah menjadi komponen, terus susun langkah perhitungan</p>', NULL, '2025-12-14 07:31:48', '2025-12-14 07:33:26'),
(663, 1, 271, '<p>saya mengetahuai definisi esponen,sofat sofat eksponen dan cara menyederhanakan eksponen</p>', NULL, '<p>Memahami masalah, merumuskan model matematika eksponensial yang sesuai, menyederhanakan menggunakan sifat eksponen, dan melakukan perhitungan.</p>', NULL, '<p>dengan memahami sifat-sifat dasar, menyamakan basis, menyederhanakan ekspresi, dan menggunakan logaritma bila diperlukan, lalu memastikan kebenaran jawaban.</p>', NULL, '2025-12-14 07:37:02', '2025-12-14 07:42:36'),
(664, 2, 226, '<p>SPLDV memiliki satu, tidak ada, atau banyak solusi, SPLTV menggunakan eliminasi, substitusi, atau Sarrus, pertidaksamaan linear solusi berupa daerah, penyelesaian sistem persamaan adalah nilai variabel yang memenuhi semua persamaan.</p>', NULL, '<ol><li>Pahami soal dan tentukan variabel.</li><li>Susun persamaan matematika.</li><li>Tentukan batasan masalah.</li><li>Pilih metode penyelesaian yang sesuai.</li><li>Hitung solusi.</li><li>Verifikasi hasil.</li></ol><p><br></p>', NULL, '<p>Pahami masalah, tentukan tujuan, buat persamaan, pilih metode yang tepat, hitung solusi, verifikasi hasil.</p>', NULL, '2025-12-14 07:37:54', '2025-12-14 07:40:29'),
(665, 5, 297, '<p>defenisi fungsi, sifat sifat dan cara menyelesaikan masalah berkaitan dengan fungsi eksponen</p><p><br></p>', NULL, '<p>menuliskan yang diketahui, memodelkannya dalam matematika dan bila perlu gambarkan dengan grafiknya agar membantu melihat penyelesaian</p>', NULL, '<p>ketika dihadapkan dengan masalah yang berkaitan dengan ini, strateginya mencatat yang diketahui lalu membuat pemodelan nya dalam matematia yang sesuai untuk kemudian di selesaikan agar mendapat solusi yang sesuai.</p>', NULL, '2025-12-14 07:38:08', '2025-12-14 07:42:29'),
(666, 4, 318, '<p><br></p><p>Persamaan kuadrat berbentuk ax^2+bx+c=0&nbsp;dan dapat diselesaikan dengan beberapa metode. Grafik fungsi kuadrat berupa parabola dengan arah buka dan titik puncak tertentu.</p>', NULL, '<p>Langkah yang sebaiknya dilakukan adalah membaca soal dengan teliti, memahami informasi yang diketahui dan yang ditanyakan, menentukan variabel, lalu menyusun model matematika dalam bentuk persamaan atau fungsi kuadrat sebelum melakukan perhitungan.</p>', NULL, '<p>Saya menggunakan strategi dengan memahami konteks soal, menentukan variabel dan model fungsi atau persamaan kuadrat yang sesuai, memilih metode penyelesaian yang tepat, lalu menafsirkan hasilnya kembali ke dalam konteks masalah.</p>', NULL, '2025-12-14 07:45:05', '2025-12-14 07:46:55'),
(667, 6, 306, '<p>Vektor adalah besaran yang memiliki besar dan arah serta dapat direpresentasikan dengan anak panah atau koordinat. Operasi vektor meliputi penjumlahan, pengurangan, dan perkalian dengan skalar</p>', NULL, '<p>Vektor adalah besaran yang memiliki besar dan arah serta dapat direpresentasikan dengan anak panah atau koordinat. Operasi vektor meliputi penjumlahan, pengurangan, dan perkalian dengan skalar</p>', NULL, '<p>Strategi penyelesaian dipilih sesuai konteks soal, misalnya menggunakan diagram vektor atau koordinat. Pemilihan strategi dilakukan agar solusi yang diperoleh lebih efisien dan tepat.</p>', NULL, '2025-12-14 07:46:59', '2025-12-14 07:47:41'),
(668, 2, 307, '<p>Materi ini membahas persamaan dan pertidaksamaan linear, sistem persamaan linear dua dan tiga variabel (SPLDV dan SPLTV), bentuk umum,jenis solusi (satu, banyak, atau tidak ada),</p>', NULL, '<p>Langkah yang dilakukan adalah memahami konteks soal, menentukan apa yang diketahui dan ditanyakan, memisalkan variabel, menyusun model matematika (persamaan atau pertidaksamaan), lalu memilih metode penyelesaian yang paling sesuai.</p>', NULL, '<p>Strategi yang digunakan adalah menyesuaikan metode dengan konteks masalah, misalnya menggunakan grafik untuk melihat daerah solusi, eliminasi atau substitusi untuk mencari nilai variabel, </p>', NULL, '2025-12-14 07:49:33', '2025-12-14 07:50:42'),
(669, 6, 217, '<p>definisi dan operasi vektor</p>', NULL, '<p>membaca dan memahami informasi serta pertanyaan, menentukan representasi vektor, membuat sketsa, memilih operasi yang tepat, merancang strategi penyelesaian, dan memeriksa konsistensi satuan serta arah.</p>', NULL, '<p>Strategi digunakan ketika soal kompleks atau menuntut pemahaman arah, besar, atau posisi vektor, sehingga langkah-langkah penyelesaian sesuai konteks masalah matematika.</p>', NULL, '2025-12-14 07:50:04', '2025-12-14 07:53:56'),
(670, 6, 297, '<p>defenisi vektor dan operasi vektor</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-14 08:03:20', '2025-12-14 08:03:20'),
(671, 4, 226, '<p>Persamaan kuadrat adalah persamaan dengan pangkat dua, grafisnya parabola, cara menyelesaikan: faktorisasi, melengkapi kuadrat, rumus kuadrat, grafik memiliki titik puncak, sumbu simetri, dan titik potong bergantung pada diskriminan.</p>', NULL, '<p>Pahami soal, tentukan variabel, buat persamaan, pilih metode, hitung, periksa hasil.</p>', NULL, '<p>Pahami konteks soal, identifikasi informasi, pilih metode yang sesuai, hitung dengan teliti, verifikasi hasil.</p>', NULL, '2025-12-14 08:13:03', '2025-12-14 08:16:15'),
(672, 3, 347, '<p>Perbandingan trigonometri</p>', NULL, NULL, NULL, NULL, NULL, '2025-12-14 08:13:18', '2025-12-14 08:13:18'),
(673, 5, 318, '<p>Saya mengetahui bahwa eksponen adalah perkalian berulang dan fungsi eksponensial digunakan untuk menggambarkan pertumbuhan dan peluruhan dalam berbagai peristiwa sehari-hari.</p>', NULL, '<p>Bacalah soal dengan teliti, tentukan data yang diketahui dan ditanyakan, kenali pola pertumbuhan atau peluruhan, lalu buat model fungsi eksponensial yang sesuai sebelum menghitung.</p><p><br></p>', NULL, '<p>Saya memiliki strategi untuk menyelesaikan soal matematika sejak membaca dan memahami konteks masalah. </p>', NULL, '2025-12-14 08:18:29', '2025-12-14 08:21:31'),
(674, 4, 307, '<p>Bentuk umum fungsi kuadrat</p>', NULL, '<p>Membaca soal dengan teliti, menentukan variabel, membuat model persamaan atau fungsi kuadrat, dan menentukan apa yang ditanyakan (akar, maksimum, minimum, atau grafik)</p>', NULL, '<p>Menyesuaikan metode dengan konteks masalah, misalnya menggunakan titik puncak untuk mencari nilai maksimum/minimum dan mencari akar persamaan untuk titik potong sumbu x, serta menafsirkan hasil sesuai masalah nyata</p>', NULL, '2025-12-14 08:21:26', '2025-12-14 08:22:09'),
(675, 5, 226, '<p>Eksponen menggambarkan pertumbuhan atau peluruhan, grafiknya di atas sumbu (x), asimtot di (y = 0), memotong sumbu (y) di (0,1), naik jika (a &gt; 1), turun jika (0 &lt; a &lt; 1).</p>', NULL, '<p>Pahami soal, tentukan variabel, buat persamaan, identifikasi informasi penting, pilih metode yang tepat, verifikasi sebelum menghitung.</p>', NULL, '<p>Pahami soal, identifikasi variabel, pilih metode sesuai konteks, hitung dengan tepat, verifikasi hasil.</p>', NULL, '2025-12-14 08:39:38', '2025-12-14 08:41:57'),
(676, 5, 307, '<p>Saya mengetahui bahwa <strong>fungsi eksponen</strong> </p>', NULL, '<p>Memahami konteks masalah (pertumbuhan atau peluruhan),Menentukan nilai awal dan rasio pertumbuhan/peluruhan,Menentukan variabel waktu,Menyusun model fungsi eksponen yang sesuai.</p>', NULL, '<p>Menggunakan fungsi pertumbuhan eksponensial untuk kasus jumlah yang bertambah (bakteri),Menggunakan fungsi peluruhan eksponensial untuk kasus jumlah yang berkurang (obat, pantulan bola),Menafsirkan hasil sesuai konteks masalah nyata, </p>', NULL, '2025-12-14 08:54:18', '2025-12-14 08:55:25'),
(677, 3, 192, '<p>perbandingan trigonometri (sin, cos, dan tan) menjelaskan hubungan antara sudut dan panjang sisi pada segitiga siku-siku serta dapat digunakan untuk menentukan sudut atau panjang sisi dalam berbagai masalah nyata.</p>', NULL, '<p>Langkah-langkahnya yaitu memahami masalah, menggambar sketsa segitiga, menentukan sisi yang diketahui dan ditanya, memilih perbandingan trigonometri yang sesuai, lalu melakukan perhitungan.</p><p><br></p>', NULL, '<p>Strategi digunakan ketika soal melibatkan sudut dan jarak atau tinggi, dengan menyesuaikan perbandingan trigonometri yang tepat berdasarkan informasi yang diketahui dalam konteks masalah</p>', NULL, '2025-12-14 08:56:40', '2025-12-14 08:57:09'),
(678, 3, 297, '<p>perbandingan trogonometri dengan teorema phytagoras, hubungan sudut dan sisi dalam segitiga siku siku dan kedudukan sinus dan kosinus dalam sudut yang berhadapan</p><p><br></p>', NULL, '<p>baca soal tentukan yang diketahui buat apa yang ditanyakan lihat sudut apa yang tepat untuk digunakan kemudian lakukan perhitungan</p>', NULL, '<p>pandai  pandai merumuskan apayang diketahui, kalau perlu di sketsakan agar tidak salah menentukan pendekatan sudut yang akan digunakan</p>', NULL, '2025-12-14 08:58:14', '2025-12-14 09:04:36'),
(679, 6, 307, '<p>Saya mengetahui bahwa <strong>vektor</strong> adalah besaran yang memiliki <strong>besar dan arah</strong>.</p>', NULL, '<p>Memahami konteks masalah (arah dan besar perpindahan),Menentukan vektor-vektor yang terlibat,Menentukan metode yang sesuai (komponen atau grafik),Menentukan operasi vektor yang digunakan (jumlah, kurang, atau skalar).</p>', NULL, '<p>Metode <strong>komponen</strong> untuk perhitungan cepat dan tepat,Metode <strong>grafik (segitiga/jajar genjang)</strong> untuk memvisualkan hasil,Pemilihan strategi disesuaikan dengan konteks masalah.</p>', NULL, '2025-12-14 09:13:48', '2025-12-14 09:14:54'),
(680, 6, 226, '<p>Vektor adalah besaran yang memiliki besar dan arah, dapat dijumlahkan atau dikurangkan secara aljabar atau grafis, serta dapat dikalikan dengan skalar untuk mengubah panjangnya. Vektor ekuivalen memiliki besar dan arah yang sama.</p>', NULL, '<p>Baca soal, identifikasi vektor, tentukan komponen, pilih metode operasi, gambarkan grafis jika perlu, hitung, verifikasi hasil.</p>', NULL, '<p>Saya menyelesaikan soal matematika dengan memahami soal, mengidentifikasi elemen penting, memilih metode yang sesuai, dan memverifikasi hasil agar sesuai konteks.</p>', NULL, '2025-12-14 09:20:55', '2025-12-14 09:23:36'),
(681, 3, 307, '<p>Saya telah mempelajari bahwa <strong>trigonometri membahas hubungan antara sudut dan sisi segitiga</strong></p>', NULL, '<p>Memahami situasi soal dan menggambarkannya dalam <strong>bentuk segitiga,</strong>Menentukan <strong>sudut yang diketahui</strong> dan <strong>sisi yang ditanyakan,</strong>Menentukan jenis perbandingan trigonometri </p>', NULL, '<p>Jika berhubungan dengan <strong>tinggi dan sisi miring</strong>, gunakan <strong>sinus,</strong>Jika berhubungan dengan <strong>alas dan sisi miring</strong>, gunakan <strong>cosinus</strong></p>', NULL, '2025-12-14 09:40:19', '2025-12-14 09:42:28'),
(682, 3, 226, '<p>Trigonometri mempelajari hubungan sudut dan sisi segitiga, digunakan untuk mengukur jarak, ketinggian, dan aplikasi praktis lainnya.</p>', NULL, '<p>Pahami soal, gambar diagram, tentukan tipe segitiga dan sudutnya, pilih perbandingan trigonometri yang tepat, aplikasikan rumus, hitung, dan verifikasi hasilnya.</p>', NULL, '<p>Strategi dimulai dengan menganalisis soal, memilih rumus yang sesuai, dan menyelesaikan langkah demi langkah berdasarkan konteks masalah.</p>', NULL, '2025-12-14 09:41:59', '2025-12-14 09:44:25'),
(683, 3, 246, '<p>Trigonometri mempelajari hubungan antara sudut dan sisi segitiga, khususnya segitiga siku-siku. Segitiga ini memiliki tiga sisi: miring, depan, dan samping, serta perbandingan dasar sin, cos, dan tan.</p>', NULL, '<p>Langkah awal menyelesaikan soal cerita adalah mengidentifikasi informasi yang diketahui, lalu membuat sketsa segitiga. Setelah itu, pilih rumus trigonometri yang sesuai sebelum melakukan perhitungan.</p>', NULL, '<p>Strategi digunakan saat menghadapi masalah nyata yang melibatkan sudut, jarak, atau tinggi. Caranya dengan menggambar segitiga, memilih rumus yang tepat, dan memastikan hasil sesuai konteks masalah.</p>', NULL, '2025-12-14 10:54:13', '2025-12-14 10:55:02'),
(684, 2, 124, '<ol><li>cara memodelkan masalah</li><li>menyelesaikan masalah dengan menggunakan metode eliminasi, subtitusi dan grafik</li></ol>', NULL, NULL, NULL, NULL, NULL, '2026-01-12 02:33:22', '2026-01-12 02:33:22'),
(685, 24, 188, '<p>Definisi Sistem Pertidaksamaan Linear</p>', NULL, '<p>Baca seluruh soal cerita secara perlahan untuk memahami konteks, alur cerita, dan apa yang sebenarnya ditanyakan.</p>', NULL, '<p>Ubah salah satu persamaan untuk menyatakan satu variabel (misal \\(x\\)) dalam bentuk variabel lainnya (misal \\(y\\)), menjadi \\(x=f(y)\\) atau \\(y=g(x)\\).</p>', NULL, '2026-01-13 21:37:21', '2026-01-13 21:56:24'),
(686, 24, 158, '<p>titik</p>', NULL, '<p>dengan membaca</p>', NULL, '<p>menghitung</p>', NULL, '2026-01-13 21:46:01', '2026-01-13 21:47:25'),
(687, 24, 187, '<p>pertidaksamaan</p>', NULL, '<p>berpikir</p>', NULL, '<p>titik-titik </p>', NULL, '2026-01-13 21:46:56', '2026-01-13 21:47:59'),
(688, 24, 185, '<p>Sistem pertidaksamaan linear dua variabel terdiri dari dua persamaan linear yang memiliki dua variabel, biasanya disimbolkan dengan x dan y.</p>', NULL, '<p>langkah pertama yang sebaiknya dilakukan adalah memahami dengan baik informasi yang terdapat dalam soal tersebut. </p>', NULL, NULL, NULL, '2026-01-13 21:47:32', '2026-01-13 21:49:00'),
(689, 24, 183, '<p>Definisi sistem pertidaksamaan linear</p>', NULL, '<p>membaca soal dengan cermat</p>', NULL, NULL, NULL, '2026-01-13 21:47:43', '2026-01-13 22:01:35'),
(690, 24, 161, '<p>Konsep ini membantu agar kita bisa membuat keputusan</p>', NULL, '<p>Harus memperhitungkan hasil dengan tepat agar tidak keliru</p>', NULL, '<p>Harus fokus</p>', NULL, '2026-01-13 21:48:23', '2026-01-13 21:53:40'),
(691, 24, 173, '<p>Sistem pertidaksamaan linear dua variabel </p>', NULL, '<p>Menghitung dan menyimak sebuah Topik yang di sediakan </p>', NULL, '<p>Berusaha dan menyimak masalah</p>', NULL, '2026-01-13 21:48:36', '2026-01-13 21:53:37'),
(692, 24, 162, '<p>karena tujuannya utamanya adalah untuk mencari nilai variabel yang memenuhi kedua persamaan tersebut secara bersamaan </p>', NULL, '<p>Untuk yang pertama ≤, kedua ≥, dan ketiga ≤.</p><p><br></p><p><br></p>', NULL, '<p>Tanda ≤ artinya boleh sama atau kurang, tanda ≥ artinya boleh sama atau lebih.</p><p><br></p><p><br></p>', NULL, '2026-01-13 21:48:39', '2026-01-13 22:00:47'),
(693, 24, 175, '<p>Karena tujuan utamanya  adalah untuk mencari nilai variabel yang memenuhi kedua persamaan tersebut secara bersamaan </p>', NULL, '<p>Saya akan mendengarkan dengan baik dulu sebelum menjawab pertanyaan nya </p>', NULL, '<p>Saya akan mencari jawaban yang tepat </p>', NULL, '2026-01-13 21:48:43', '2026-01-13 21:53:11'),
(694, 24, 165, '<p>Saya mengetahui bahwa sistem pertidaksamaan linear dua variabel adalah kumpulan pertidaksamaan yang melibatkan dua variabel (misalnya x dan y) dan membentuk suatu daerah penyelesaian pada bidang koordinat.&nbsp;</p>', NULL, '<p>Memahami dengan baik informasj yang di berikan dalam soal</p><p>Menerjemahkan informasj tersebut dalam bentuk persamaan matematika</p><p>Menyelesaikan sistem pertidaksamaan dua variabel</p>', NULL, '<p>Memahami konsep dasarnya</p><p>Menyamakan koefisien salah satu variabel dalam kedua persamaan</p><p><br></p>', NULL, '2026-01-13 21:48:47', '2026-04-18 22:45:26'),
(695, 24, 179, '<p>mencakup konsep dasar kalimat terbuka dengan variabel berpangkat satu, menggunakan tanda \'=\' untuk persamaan dan \'&lt;, &gt;, ≤, ≥\' untuk pertidaksamaan</p>', NULL, '<ul><li>Baca dengan cermat&nbsp;seluruh soal cerita dari awal hingga akhir untuk mendapatkan gambaran umum tentang situasi yang dijelaskan.</li></ul><p><br></p>', NULL, '<p><span style=\"color: rgb(0, 29, 53);\">mengadaptasi pendekatan pemecahan masalah umum yang dikenal sebagai metode Polya</span></p>', NULL, '2026-01-13 21:48:56', '2026-01-13 21:51:16'),
(696, 24, 172, '<p>sistem persamaan liner dua variabel </p>', NULL, '<p>1. Baca dan pahami cerita.</p><p>2. Identifikasi informasi.</p><p>3. Tentukan operasi matematika.</p><p>4. Buat rencana Baca dan pahamj</p>', NULL, '<p>dengan cara memahami konsep dan memilih suatu rumus atau metode lalu menghitung , dan memeriksa jawaban kembali</p>', NULL, '2026-01-13 21:49:22', '2026-01-13 21:51:51'),
(697, 24, 159, '<p>Yang saya ketahui adalah Persamaan linear dua variabel adalah sebuah persamaan aljabar yang memuat dua variabel (biasanya dinyatakan sebagai x dan y) yang pangkat tertinggi dari setiap variabelnya adalah satu.</p>', NULL, '<p>1.&nbsp;Pahami soal.</p><p>2.&nbsp;Buat model matematika.</p><p>3.&nbsp;Rencanakan penyelesaian.</p><p>4.&nbsp;Hitung dengan cermat.</p><p>5.&nbsp;Cek jawaban.</p><p>6.&nbsp;Buat kesimpulan.</p>', NULL, '<p>1.&nbsp;Pahami soal.</p><p>2.&nbsp;Buat model matematika.</p><p>3.&nbsp;Rencanakan strategi.</p><p>4.&nbsp;Lakukan perhitungan.</p><p>5.&nbsp;Verifikasi jawaban.</p><p>6.&nbsp;Simpulkan.</p>', NULL, '2026-01-13 21:50:20', '2026-04-18 20:04:59'),
(698, 24, 156, '<p>saya bisa tahu kalau sistem pertidak samaan linear  adalah himpunan pertidak samaan linear yang saling tidak terkait</p>', NULL, '<p>memulai dari yang lebih mudah dan menyelesaikan atau menghitung hasilakhirnya</p>', NULL, '<p>saya memakai strategi  untuk menyelesaikan konteks masalah dengan cepat</p><p>dengan cara mencatat atau menghafal</p>', NULL, '2026-01-13 21:51:21', '2026-01-13 21:56:50'),
(699, 24, 157, '<p>sistem pertidaksamaan linear dua variabel  membahas kumpulan dua atau lebih pertidaksamaan linear yang melibatkan dua variabel, biasanya x dan y.</p>', NULL, '<p>Membaca dan memahami soal dengan teliti.</p><p>Menentukan informasi yang diketahui dan ditanyakan.</p><p>Menetapkan variabel yang akan digunakan.</p><p>Menyusun model pertidaksamaan dari cerita soal.</p>', NULL, '<p>memahami konteks soal terlebih dahulu, lalu mengubahnya ke dalam model pertidaksamaan linear dua variabel. </p>', NULL, '2026-01-13 21:52:02', '2026-01-23 22:02:27'),
(700, 24, 160, '<p>Contohnya adalah \\(2x + 3y &gt; 8\\) dan \\(4x - y &lt; 2\\). Untuk memaham</p>', NULL, '<p>1 baca dn pahami soal </p>', NULL, '<p>Contohnya, jika kita memiliki sistem pertidaksamaan x + y = 5 dan 2x - y = 1, kita akan mencari nilai x dan</p>', NULL, '2026-01-13 21:53:29', '2026-01-13 22:02:42'),
(701, 24, 176, '<p>Titik</p>', NULL, '<p>Titik</p>', NULL, '<p>Titik</p>', NULL, '2026-01-13 21:54:05', '2026-01-13 21:54:51'),
(702, 24, 184, '<p>Contoh sistem pertidaksamaan linear dua variabel adalah:</p><p>2x + 3y ≤ 12</p><p>x - y &gt; 4</p>', NULL, NULL, NULL, NULL, NULL, '2026-01-13 21:54:28', '2026-01-13 21:54:28'),
(703, 24, 181, '<p>Yang saya ketahui adalah saya jadi tau bahwa pertidaksamaan linear adalah 2 variabel </p>', NULL, '<p>Sebaiknya saya akan memperhatikan hasil jawaban saya dan saya akan menghitung kembali lagi </p>', NULL, '<p>Saya akan berusaha mencari jawaban yang benar </p>', NULL, '2026-01-13 21:59:15', '2026-01-13 22:01:25'),
(704, 24, 166, '<p> Semua contoh di atas adalah pertidaksamaan, karena tidak ada tanda sama dengan yang pasti</p><p><br></p>', NULL, '<p>Untuk yang pertama ≤, kedua ≥, dan ketiga ≤.</p>', NULL, '<p>Tanda ≤ artinya boleh sama atau kurang, tanda ≥ artinya boleh sama atau lebih.</p>', NULL, '2026-01-13 22:00:07', '2026-01-13 22:01:40'),
(705, 24, 174, '<p>Semua contoh di atas adalah pertidaksamaan, karena tidak ada tanda sama dengan yang pasti</p><p><br></p>', NULL, '<p><br></p><p>Untuk yang pertama ≤, kedua ≥, dan ketiga ≤.</p><p><br></p>', NULL, '<p><br></p><p>Tanda ≤ artinya boleh sama atau kurang, tanda ≥ artinya boleh sama atau lebih.</p>', NULL, '2026-01-13 22:00:23', '2026-01-13 22:01:49'),
(706, 24, 178, '<p>dalam hidup tidak selalu menggunakan = tapi kurang dari atau lebih dari juga</p>', NULL, '<p>Mengubah dari bentuk pertidaksamaan menjadi persamaan kemudian membentuk model matematika </p>', NULL, '<p>menganalisis soal dengan memimsalkan x dan y</p>', NULL, '2026-01-13 22:00:42', '2026-01-13 22:02:12'),
(707, 24, 177, '<p><span style=\"color: rgb(51, 65, 85);\">1) 2x + 3y = 10</span></p><p><span style=\"color: rgb(51, 65, 85);\">2) x - y = 1</span></p>', NULL, '<p>Membaca soal dengan teliti</p><p>Menentukan apa yang diketahui dan ditanyakan</p><p>Menentukan variabel</p><p>Mengubah soal ke bentuk pertidaksamaan</p><p>Menuliskan semua batasan</p>', NULL, '<p>Saya menggunakan strategi bertahap: membuat model matematika, menggambar grafik, lalu menentukan solusi. Jika ada nilai maksimum atau minimum, saya menggunakan titik pojok.</p>', NULL, '2026-01-13 22:04:48', '2026-04-20 12:57:57'),
(709, 30, 385, '<p>Pada materi Sistem Persamaan Linear Tiga Variabel membahas cara menyelesaikan tiga persamaan yang melibatkan tiga variabel berbeda, serta kegunaannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, mengubah soal ke bentuk matematika, menggunakan rumus yang sesuai, lalu menghitung dan mengecek kembali hasilnya.</p>', NULL, '<p>Saya menggunakan strategi yang disesuaikan dengan konteks soal matematika, misalnya memilih metode penyelesaian yang paling efektif berdasarkan jenis masalah yang diberikan</p>', NULL, '2026-01-21 16:57:39', '2026-02-03 21:19:49'),
(710, 30, 377, '<p>Adalah materi sistem persamaan linear tiga variabel berbeda serta kegunaannya dalam kehidupan sehari-hari </p>', NULL, '<p>Langkah-langkah ny adalah menghitung dengan baik dan memahami cara kerja ny</p>', NULL, '<p> Adalah Kerja Dengan baik dan menyelesaikan masalah konteks matematika </p>', NULL, '2026-01-21 17:04:13', '2026-01-21 17:06:58'),
(711, 30, 392, '<p><br></p><p>seri Yana Aviva </p><p><br></p><p>jawaban: adalah pada materi sistem persamaan linier tiga variabel berbeda serta kegunaannya dalam kehidupan sehari-hari </p>', NULL, '<p>seri Yana Aviva </p><p><br></p><p>jawaban: menghitung dengan baik dan memahami cara kerjanya </p>', NULL, '<p>seri Yana Aviva</p><p><br></p><p>jawaban: menyelesaikan topik yg tertulis oleh soal  dan memahami konteks masalah matematika </p>', NULL, '2026-01-21 17:06:03', '2026-01-21 17:11:59'),
(712, 30, 362, '<p>Bahwa solusi spltv itu memiliki tiga bagian yaitu solusi tunggal, tidak memiliki solusi dan tak hingga atau banyak solusi </p>', NULL, '<p>Pertama kita harus mengetahui soalnya dengan membuat permisalan apa yang di ketahui dan apa yang di tanyakan </p>', NULL, '<p>Membaca soal dengan teliti dulu memastikan informasi yang di berikan dalam soal lalu memilih metode penyelesaiannya, menghitung soalnya, lalu memastikan lagi jawsbannya sudah sesuai dengan soalnya dan sudah benar hasil akhirnya </p>', NULL, '2026-01-21 17:11:33', '2026-01-25 12:39:18'),
(714, 24, 180, '<p>Tentang pertidaksamaan linear</p>', NULL, '<p>Materi tentang pertidaksamaan linear</p>', NULL, '<p>Dengan cara memahami apa yang sudah di jelaskan atau di terangkan</p>', NULL, '2026-01-23 21:38:29', '2026-01-23 21:42:49'),
(715, 24, 182, '<p>sistem pertidaksamaan linear dua variabel terdiri dari dua persamaan linear yang memiliki dua variabel, biasanya di simbol kan dengan x dan y. </p>', NULL, '<p>langkah pertama sebaiknya dilakukan adalah memahami dengan baik informasi yang terdapat dalam soal tersebut. </p>', NULL, NULL, NULL, '2026-01-23 22:12:10', '2026-01-23 22:13:05'),
(716, 24, 171, '<p><strong>Dengan cara ini, jawaban terbukti benar secara hitungan, masuk akal secara logika, dan menjawab semua poin pertanyaan yang diberikan.</strong></p>', NULL, '<p><strong>Dengan cara ini, jawaban terbukti benar secara hitungan, masuk akal secara logika, dan menjawab semua poin pertanyaan yang diberikan.</strong></p><p><br></p><p><br></p>', NULL, '<p><strong>Dengan cara ini, jawaban terbukti benar secara hitungan, masuk akal secara logika, dan menjawab semua poin pertanyaan yang diberikan.</strong></p><p><br></p><p><br></p>', NULL, '2026-01-23 22:19:18', '2026-01-23 22:19:46'),
(717, 24, 164, '<p>perbedaan dari persamaan dan pertidaksamaan linear dua variabel </p>', NULL, '<p>menentukan model matematika terlebih dahulu</p>', NULL, '<p>strategi saya harus lebih teliti dalam menentukan model matematika agar tidak terjadi kesalahan dalam permisalan </p>', NULL, '2026-01-24 06:43:52', '2026-01-24 06:45:50'),
(718, 30, 370, '<p>saya dapat mengetahui materi tentang persamaan liner 3 variabel dan cara² menyelesaikannya</p>', NULL, NULL, NULL, NULL, NULL, '2026-01-27 21:26:21', '2026-01-27 21:26:21'),
(719, 30, 367, '<p>saya jadi lebih memahami tentang konsep sistem persamaan linear ini.</p>', NULL, '<p>mengindentifikasi soal sebelu mmenjawabnya dengan teliti </p>', NULL, '<p>dengan meneliti soal matematika lalu mencoba untuk membuat cakaran dari jawabnnya, setelah mendapat kepastian, saya menuliskan jawaban nya</p>', NULL, '2026-01-27 21:27:37', '2026-01-27 21:29:35'),
(720, 30, 390, '<p dir=\"ltr\">Saya memahami bahwa SPLTV adalah kumpulan tiga persamaan yang masing-masing memiliki tiga variabel (biasanya x, y, z)</p><p>\r\n</p>', NULL, '<p>identifikasi variabel</p><p>susun sistem</p><p>pilih metode</p><p>cek konsistensi</p>', NULL, '<p>pilih target</p><p>reduksi (SPLTV - SPLDV)</p><p>selesaikan SPLDV</p><p>substitusi balik</p>', NULL, '2026-01-27 21:31:51', '2026-01-27 21:37:34'),
(721, 32, 362, '<p>Cara membuat grafik sistem pertidaksamaan linear</p>', NULL, '<p>Mengidentifikasi  kata kunci pertidaksamaan menentukan vatiabel</p>', NULL, '<p>Mengidentifikasi variabel lalu memodelkan soal </p>', NULL, '2026-01-27 22:41:20', '2026-01-27 22:46:34'),
(722, 32, 374, '<p>Sama mengetahui bahwa sistem ketidaksamaan linear dua variabe adalah kumpulan beberapa ketidaksamaan  yang melibatkan dua variabel, biasanya x &amp; y.</p>', NULL, NULL, NULL, '<p>Saya memilih strategi dengan menggambar grafik ketika soal berkaitan dengan daerah penyelesaian, karena lebih mudah melihat irisan daerah yang memenuhi semua pertidaksamaan</p>', NULL, '2026-01-27 22:48:01', '2026-01-27 23:16:02'),
(723, 32, 395, '<p>gabungan dari dua atau lebih tidak persamaan linear yg menggunakan variabel x.y</p>', NULL, '<p>identifikasi variabel</p><p>menyusun model</p><p>menentukan syarat tambahan</p>', NULL, '<p>menggambar setiap garis pembatas dari pertidak samaan  yg telah di buat</p><p><br></p>', NULL, '2026-01-28 16:46:14', '2026-01-28 16:49:33'),
(724, 32, 380, '<p>tentang sistem pertidaksamaan linear</p>', NULL, '<p>menggunakan langkah langkah yang tepat</p>', NULL, '<p>menggunakan strategi pembelajaran yang efektif</p>', NULL, '2026-01-28 16:56:54', '2026-01-28 16:58:04'),
(725, 32, 369, '<p>perencanaan : menentukan variabel, menyusun model dari batasan soal dan merencanakan grafik. </p>', NULL, '<p>refleksi: memeriksa apakah langkah pemodelan sudah sesuai dengan batasan dan waktu target uang yg di minta</p>', NULL, '<p>evaluasi: memastikan jawaban benar dgn menguji titik koordinat di dalam daerah arsiran ke dalam model matematika</p>', NULL, '2026-01-28 17:02:09', '2026-01-28 17:08:38'),
(726, 32, 366, '<p>perencanaan: menentukan variabel menyusun model dari batasan soal dan merencanakan grafik</p>', NULL, '<p>refleksi: memeriksa apakah  langkah pemodelan sdh sesuai dgn batasan dann waktu target uang yg diminta</p>', NULL, '<p>evaluasi: memastikan jawaban benar dengan menguji titik koordinat di dlm daerah arsiiran ke dlm model matematika</p>', NULL, '2026-01-28 17:11:40', '2026-01-28 17:14:18'),
(727, 32, 365, '<p>yaitu tentang sumbu x dan sumbu y serta sumbu horizontal dan sumbu vertikal dan gambar grafik </p>', NULL, '<p>dengan cara menggambar grafik dan mencarii apa sja  angka angka yang masuk dalam soal tersebut </p>', NULL, '<p>dengan menggunakan sumbu x dan y dan garis batas dan titik potong</p>', NULL, '2026-01-28 17:12:40', '2026-01-28 17:22:03'),
(728, 30, 365, '<p>tentang (SPLTV) atau kumpulan tiga persmaan linear yang melibatkan tiga variabel (biasanya x,y,z,) berpangkat 1 dimana ketiganya memiliki nilai yang sama</p>', NULL, '<p>membaca dan memahami soal dengan saksama,menentukan variabel,tentukan solusii dari sistem persamaan </p>', NULL, '<p>memakai metode subtitusi paling efektif jika ada persaman dengan koefesien 1 atau -1, metode eliminasi dan metode gabungan.</p>', NULL, '2026-01-30 23:53:25', '2026-01-31 00:00:51'),
(729, 30, 360, '<p>Yang saya ketahui adalah sistem persamaan linear adalah dua atau lebih persamaan linear yang saling terkait dengan koefisien² persamaan </p>', NULL, '<p><strong>membuat langkah² penyelesaiannya</strong></p>', NULL, NULL, NULL, '2026-02-03 21:05:29', '2026-02-03 21:08:58'),
(730, 32, 378, '<p>algoritma</p>', NULL, '<p>perpindahan pindahan lakukan sesuai denagn contoh yang di beri kan</p>', NULL, '<p>dengan menggunakan rumus  yang sesuai den soal</p>', NULL, '2026-02-03 21:08:40', '2026-02-03 21:12:34'),
(731, 30, 379, '<p>Pada materi Sistem Persamaan Linear Tiga Variabel membahas cara menyelesaikan tiga persamaan yang melibatkan tiga variabel berbeda, serta kegunaannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, mengubah soal ke bentuk matematika, menggunakan rumus yang sesuai, lalu menghitung dan mengecek kembali hasilnya.</p>', NULL, '<p>Saya menggunakan strategi yang disesuaikan dengan konteks soal matematika, misalnya memilih metode penyelesaian yang paling efektif berdasarkan jenis masalah yang diberikan</p>', NULL, '2026-02-03 21:10:03', '2026-02-03 21:17:14'),
(732, 30, 381, '<p>Pada materi Sistem Persamaan Linear Tiga Variabel membahas cara menyelesaikan tiga persamaan yang melibatkan tiga variabel berbeda, serta kegunaannya dalam kehidupan sehari-hari.</p>', NULL, '<p>Langkah yang saya lakukan adalah membaca soal dengan teliti, menentukan informasi yang diketahui dan ditanyakan, mengubah soal ke bentuk matematika, menggunakan rumus yang sesuai, lalu menghitung dan mengecek kembali hasilnya.</p>', NULL, '<p>Saya menggunakan strategi yang disesuaikan dengan konteks soal matematika, misalnya memilih metode penyelesaian yang paling efektif berdasarkan jenis masalah yang diberikan</p>', NULL, '2026-02-03 21:13:00', '2026-02-03 21:24:39'),
(733, 30, 376, '<p>materi matematika yang membahas sistem persamaan linear yang memiliki tiga variabel, biasanya x, y, dan z.</p>', NULL, '<p>Membaca soal dengan teliti</p><p>Menentukan apa yang diketahui dan ditanyakan</p><p>Mebentukan variabel</p><p>Menyusun model mtk</p><p>Memilih metode penyelesaian</p><p>Mengecek kembali</p>', NULL, '<p>Memahami konteks masalah</p><p>Menentukan variabel</p><p>Menyusun persamaan</p><p>Memilih metode</p><p>Menghitung secara bertahap</p><p>Menyesuaikan hasil</p>', NULL, '2026-02-03 21:14:29', '2026-02-03 21:18:39'),
(734, 32, 379, '<p>Saya mengetahui bahwa sistem pertidaksamaan linear dua variabel adalah kumpulan pertidaksamaan yang digunakan untuk menentukan daerah penyelesaian pada bidang Kartesius.</p>', NULL, '<p>Langkah yang dilakukan adalah membaca soal, menentukan variabel, membuat pertidaksamaan dari informasi soal, menggambar grafik, lalu menentukan daerah penyelesaiannya.</p>', NULL, '<p>Saya memilih strategi penyelesaian dengan menyesuaikan jenis batasan pada soal, seperti menggunakan grafik untuk melihat daerah yang memenuhi semua pertidaksamaan.</p>', NULL, '2026-02-03 21:35:39', '2026-02-03 21:36:24'),
(735, 30, 393, '<p>saya mengetahui cara penyelesaian sistem persamaan linear dua variabel dengan tepat</p>', NULL, '<p>menulis hal apa yang diketahui, ditanya, kemudian melakukan penyelesaian sesuai dengan soal bercerita nya</p>', NULL, '<p>dengan cara berpikir sebelum bertindak, menganalisis terlebih dahulu hal hal yang perlu diperhatikan kemudian mengevaluasi kan diri pada masalah dan mencari tahu solusi yang tepat</p>', NULL, '2026-02-03 21:37:02', '2026-02-03 21:39:26'),
(736, 32, 393, '<p>saya sekarang sudah bisa memahami dan menyelesaikan tugas atau soal mengenai sistem pertidaksamaan linear dua variabel</p>', NULL, '<p>langkah pertama adalah dengan menentukan atau menulis apa yang diketahui terlebih dahulu, lalu menganalisis pertanyaan dari soal tsb dengan cermat, kemudian melakukan penyelesaian sesuai dengan yang diketahui </p>', NULL, '<p>strategi saya adalah menganalisis suatu masalah yang diketahui, lalu menanyakan hal apa yang tidak diketahui dan menjawabnya dengan melakukan penyelesaian secara logis, sistematis, dan tepat.</p>', NULL, '2026-02-03 21:40:42', '2026-02-03 21:42:55'),
(737, 30, 371, '<p>Yaitu dengan memahami sistem tiga fariabel</p>', NULL, '<p>Langkah2 yg saya lakukan adalah dengan memahami sistem tiga variabel dan dan menjumlahkan nya</p>', NULL, '<p>Dengan memahami sistem tiga variabel dan penjumlahan yg tepat untuk menjawabnya</p>', NULL, '2026-02-03 22:46:25', '2026-02-03 22:49:16'),
(738, 24, 167, '<p>kumpulan dua atau lebih pertidaksamaan linear yang melibatkan dua variabel (biasanya x dan y).</p>', NULL, '<p>Langkah yang saya lakukan adalah memahami soal cerita terlebih dahulu, menentukan apa yang diketahui dan ditanyakan, kemudian membuat variabel, dan mengubah informasi dalam soal menjadi bentuk pertidaksamaan sebelum melakukan penyelesaian.</p>', NULL, '<p>Strategi saya adalah memahami konteks masalah, kemudian membuat model matematika yang sesuai, setelah itu menggunakan metode grafik untuk menentukan daerah solusi, dan terakhir memastikan bahwa jawaban sesuai dengan kondisi dalam soal.</p>', NULL, '2026-04-18 20:41:25', '2026-04-18 20:49:18'),
(739, 24, 168, NULL, NULL, '<p>Membaca soal dengan cermat</p><p>Menentukan informasi penting dan apa yang ditanyakan</p><p>Menetapkan variabel</p><p>Mengubah soal ke dalam bentuk pertidaksamaan</p><p>Memastikan semua batasan sudah benar</p>', NULL, '<p>Strategi saya adalah memulai dari pemodelan, lalu menggambar grafik untuk melihat daerah penyelesaian. Jika soal berkaitan dengan nilai maksimum atau minimum, saya menggunakan metode titik pojok untuk mendapatkan hasil yang paling optimal.</p>', NULL, '2026-04-18 23:03:18', '2026-04-18 23:03:33'),
(740, 24, 170, NULL, NULL, '<p>Membaca soal dengan teliti</p><p>Menentukan apa yang diketahui dan ditanyakan</p><p>Menentukan variabel (misalnya x dan y)</p><p>Mengubah kalimat soal menjadi bentuk pertidaksamaan</p><p>Menuliskan semua batasan yang ada</p>', NULL, NULL, NULL, '2026-04-18 23:44:00', '2026-04-18 23:44:00'),
(741, 24, 186, NULL, NULL, '<p>Membaca soal sampai benar-benar paham</p><p>Menentukan apa yang diketahui dan yang ditanya</p><p>Menentukan variabel (misalnya x dan y)</p><p>Mengubah soal menjadi bentuk pertidaksamaan</p><p>Menuliskan semua batasan yang ada</p>', NULL, NULL, NULL, '2026-04-20 13:19:53', '2026-04-20 13:19:53'),
(742, 34, 413, '<p>Penyajian data merupakan salah satu bagian penting dalam statistika yang bertujuan untuk menyusun data mentah menjadi bentuk yang lebih terstruktur, sehingga mudah dibaca, dipahami, dan dianalisis.&nbsp;</p>', NULL, '<p>dengan mengelompokkan data ke dalam beberapa kelas interval tertentu, kemudian menghitung banyaknya data (frekuensi) pada setiap kelas tersebut.&nbsp;</p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Memahami konsep dasar terlebih dahulu. Mengidentifikasi tipe data yang disajikan. Kemudian, pahami metode penyajian data seperti tabel, diagram, grafik, atau diagram batang.</span></p>', NULL, '2026-05-07 17:29:05', '2026-05-07 17:36:30'),
(743, 34, 406, '<p>Penyajian data merupakan salah satu bagian penting dalam statistika yang bertujuan untuk menyusun data mentah menjadi bentuk yang lebih terstruktur, sehingga mudah dibaca, dipahami, dan dianalisis.</p>', NULL, '<p>dengan mengelompokkan data ke dalam beberapa kelas interval tertentu, kemudian menghitung banyaknya data (frekuensi) pada setiap kelas tersebut.</p>', NULL, '<p>Memahami konsep dasar terlebih dahulu. Mengidentifikasi tipe data yang disajikan. Kemudian, pahami metode penyajian data seperti tabel, diagram, grafik, atau diagram batang.</p>', NULL, '2026-05-07 17:30:22', '2026-05-07 17:36:57'),
(744, 34, 423, '<p>Pengetahuan Deklaratif</p><p>Saya sudah mengetahui bahwa penyajian data dapat dilakukan dalam bentuk tabel, diagram, distribusi frekuensi, dan histogram untuk mempermudah membaca serta menganalisis data.</p>', NULL, '<p>Pengetahuan Prosedural</p><p>Langkah-langkahnya adalah membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, mengelompokkan data jika diperlukan, lalu memilih cara penyajian data yang tepat sebelum menghitung hasil akhirnya.</p>', NULL, NULL, NULL, '2026-05-07 17:35:19', '2026-05-07 17:36:53'),
(745, 34, 409, '<p>Penyajian data</p>', NULL, '<p>Baca pelan pelan</p><p>Tulis ulang materi sesuai pemahaman sendiri</p><p>Evaluasi diri apakah apa yang di tulis sudah tentu benar atau Masi kurang?</p><p><br></p>', NULL, '<p>Mendengar dan terus memahami secara berulang</p>', NULL, '2026-05-07 17:36:53', '2026-05-07 17:43:07'),
(746, 34, 407, '<p>saya mengetahui bahwa terdapat sebuah cara yang dapat kita gunakan untuk mempermudah dalam mengumpulkan data secara besar dan disajikan dlm histogram yaitu distribusi frekuensi kemudian,didalamnya terdapat frekuensi dan interval.</p>', NULL, '<p>dengan memperhatikan penjelasan yang telah diberikan dan memahami rumus, kemudia menghitung data yang diperoleh menggunakan langkah-langkah yang telah diberikan</p>', NULL, '<p>strategi saya yaitu, mengumpulkan data dengan tepat dan juga memahami soal maupun penjelasan yang sebelumnya telah diberikan</p>', NULL, '2026-05-07 17:42:17', '2026-05-07 17:44:48'),
(747, 34, 410, '<p>Penyajian data bertujuan memudahkan membaca dan menganalisis data. Data dapat disajikan dalam tabel, distribusi frekuensi, dan histogram.</p>', NULL, '<p>1. Urutkan data.</p><p>2. Tentukan jangkauan data.</p><p>3. Tentukan kelas interval.</p><p>4. Hitung frekuensi tiap kelas.</p><p>5. Susun dalam tabel.</p>', NULL, '<p>Strategi saya adalah mengurutkan data, menentukan interval kelas, menghitung frekuensi, lalu menyajikannya dalam tabel distribusi frekuensi dan histogram agar data mudah dipahami.</p>', NULL, '2026-05-07 17:43:20', '2026-05-07 17:48:04'),
(748, 34, 401, '<p>yg saya pahami dari materi tersebut adalah penyajian data digunakan untuk membuat data lebih rapi dan mudah dipahami. data dapat disajikan dalam bentuk tabel, distribusi frekuensi, dan histogram agar lebih mudah dianalisis dan ditarik kesimpulannya</p>', NULL, '<p>langkahnya yaitu membaca soal dengan teliti, menentukan data yang diketahui dan ditanyakan, lalu memilih rumus yang sesuai sebelum menghitung hasil akhirnya</p>', NULL, '<p>strategi saya adalah memahami isi soal terlebih dahulu, menentukan data yang penting, lalu memilih cara atau rumus yang sesuai dengan konteks masalah. setelah itu, saya menghitung secara teliti agar hasilnya benar</p>', NULL, '2026-05-07 17:44:38', '2026-05-07 17:52:21'),
(749, 34, 397, NULL, NULL, '<p>susun data berdasarkan urutan terkecil hingga terbesar</p>', NULL, '<p>penting untuk memahami konsep dasar terlebih dahulu. Penyajian data melibatkan pengumpulan, pengolahan, dan penyajian informasi dalam bentuk grafik, tabel, atau diagram.</p>', NULL, '2026-05-07 17:44:51', '2026-05-07 17:48:48'),
(750, 34, 432, NULL, NULL, NULL, NULL, '<p>strateginya yaitu menyelesaikan perhitungan\" pertama dan menentukan range dan kelas interval agar kemudian dapat dengan mudah dimasukkan datanya ke dalam bentuk tabel distribusi frekuensi ataupun histogram </p>', NULL, '2026-05-07 17:59:35', '2026-05-07 17:59:35'),
(751, 34, 424, '<p>tentang cara menganalisis data</p>', NULL, '<p>perlu memahami masalah dan menyederhanakan data</p>', NULL, '<p>dengan pendekatan sistematis</p>', NULL, '2026-05-07 18:00:24', '2026-05-07 18:02:24');
INSERT INTO `jawaban_perencanaan_refleksi_evaluasi` (`id_jawaban_perencanaan_refleksi_evaluasi`, `id_materi`, `id_user`, `jenis`, `perencanaan`, `nilai_perencanaan`, `refleksi`, `nilai_refleksi`, `evaluasi`, `nilai_evaluasi`, `created_at`, `updated_at`) VALUES
(3, 1, 32, 'demonstrasi_konseptual', '<p><span style=\"color: rgb(51, 65, 85);\">Tentu! Dalam menyelesaikan masalah matematika, terutama yang berkaitan dengan ekspresi eksponen, langkah-langkah berikut dapat membantu Anda:</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">1. Memahami Konsep: Pastikan Anda memahami konsep dasar ekspresi eksponen, seperti aturan perkalian eksponen, aturan pembagian eksponen, dan sifat-sifat lainnya terkait eksponen.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">2. Identifikasi Masalah: Baca masalah dengan cermat dan identifikasi apa yang diminta dalam soal. Perhatikan apakah terdapat ekspresi eksponen yang perlu disederhanakan atau dihitung.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">3. Terapkan Aturan Eksponen: Gunakan aturan-aturan eksponen yang telah dipelajari untuk menyederhanakan ekspresi eksponen sesuai dengan kebutuhan soal.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">4. Lakukan Perhitungan: Setelah menyesuaikan ekspresi eksponen sesuai aturan yang relevan, lakukan perhitungan matematika secara sistematis.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">5. Periksa Kembali Jawaban: Jangan lupa untuk selalu memeriksa kembali jawaban Anda dan pastikan bahwa langkah-langkah yang dilakukan sudah benar dan logis.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">Dengan mengikuti langkah-langkah di atas dan memahami konsep dasar ekspresi eksponen, diharapkan Anda dapat menyelesaikan masalah matematika terkait dengan lebih mudah dan efektif. Jika ada pertanyaan lebih lanjut atau butuh bantuan dalam mengerjakan soal tertentu, jangan ragu untuk bertanya!</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Setelah menyelesaikan soal matematika tersebut, penting untuk mengevaluasi kembali langkah-langkah yang telah digunakan. Dalam ekspresi eksponen, langkah-langkah yang perlu dievaluasi antara lain pengelompokan ekspresi, penggunaan sifat-sifat eksponen seperti hukum perkalian dan pembagian eksponen, serta penerapan aturan dalam mengurangi ekspresi dengan eksponen yang sama.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">Untuk menilai langkah-langkah yang telah digunakan, Anda perlu memeriksa apakah telah menggunakan properti eksponen dengan benar, apakah langkah-langkahnya konsisten, dan apakah hasil akhirnya konsisten dengan aturan-aturan eksponen yang berlaku. Jika terdapat kesalahan, perlu diidentifikasi titik-titik kekeliruan tersebut dan diperbaiki dengan langkah-langkah yang benar. Dengan mengevaluasi kembali langkah-langkah tersebut, Anda dapat memastikan pemahaman konsep ekspresi eksponen Anda semakin baik dan dapat menghindari kesalahan di masa mendatang.</span></p>', NULL, '<p><span style=\"color: rgb(51, 65, 85);\">Untuk memastikan bahwa jawaban akhir dari soal matematika sudah benar, logis, dan sesuai dengan pertanyaan yang diberikan, ada beberapa langkah yang dapat Anda lakukan. Pertama, pastikan Anda telah memahami dengan baik pertanyaan yang diajukan. Selanjutnya, periksa kembali langkah-langkah perhitungan yang Anda lakukan. Pastikan tidak terjadi kesalahan aritmatika atau pemahaman konsep.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">Selain itu, Anda juga bisa melakukan uji ulang jawaban dengan cara substitusi. Artinya, Anda menggantikan nilai variabel dalam ekspresi eksponen dengan angka yang sesuai dan melakukan perhitungan ulang untuk memastikan hasilnya konsisten dengan jawaban yang Anda berikan. Jika hasilnya tidak sesuai, ada kemungkinan terdapat kesalahan dalam perhitungan.</span></p><p><br></p><p><span style=\"color: rgb(51, 65, 85);\">Jika masih merasa ragu, Anda juga bisa meminta bantuan teman atau guru untuk memeriksa jawaban Anda. Diskusikan langkah-langkah perhitungan dan pemahaman konsep matematika yang mendasarinya. Dengan cara tersebut, Anda dapat memastikan bahwa jawaban akhir yang Anda berikan sudah benar, logis, dan sesuai dengan pertanyaan yang diberikan.</span></p>', NULL, '2025-11-11 19:44:14', '2025-11-11 19:48:50'),
(4, 1, 38, 'elaborasi_pemahaman', '<p>1. Pahami terlebih dahulu konsep dasar tentang eksponen. Ingatlah bahwa eksponen menunjukkan berapa kali suatu bilangan dikalikan dengan dirinya sendiri.</p><p><br></p><p>2. Periksa masalah dengan teliti dan identifikasi eksponen yang terlibat. Pastikan Anda memahami basis (bilangan pokok) dan pangkat (eksponen) yang terkait.</p><p><br></p><p>3. Gunakan properti eksponen untuk menyederhanakan ekspresi jika diperlukan. Misalnya, aturan perkalian atau pembagian eksponen dengan basis yang sama.</p><p><br></p><p>4. Jika terdapat operasi matematika lain seperti penambahan atau pengurangan, pastikan Anda melakukan operasi tersebut setelah menyederhanakan ekspresi eksponen.</p><p><br></p><p>5. Jangan ragu untuk mencoba beberapa cara pendekatan untuk menyelesaikan masalah. Terkadang, melihat masalah dari sudut pandang yang berbeda dapat membantu Anda menemukan solusi yang tepat.</p>', NULL, NULL, NULL, NULL, NULL, '2025-11-11 19:52:46', '2025-11-11 19:52:46'),
(5, 1, 94, 'demonstrasi_konseptual', '<p>ya bagus</p>', NULL, '<p>ya bagus</p>', NULL, NULL, NULL, '2025-11-17 18:23:33', '2025-11-17 18:23:59'),
