INSERT INTO `modul` (`id_modul`, `nama_modul`, `desk`, `pengalaman_belajar`, `koneksi_materi`, `tes_kompetensi`, `aksi_nyata`, `id_mata_pelajaran`, `created_at`, `updated_at`) VALUES
(1, 'Aljabar', 'Ini bab 1', '<p>Setelah mempelajari bab ini, siswa dapat:\r\n</p><ol><li><span style=\"color: windowtext;\">Menginterpretasi bagian dari ekspresi (bentuk) eksponen sederhana, dan kompleks</span>  </li><li><span style=\"color: windowtext;\">Menjelaskan pengertian solusi dari sistem persamaan linear tiga variabel berdasarkan pemahaman solusi dari sistem persamaan linear dua variabel.</span></li><li><span style=\"color: windowtext;\">Menyelesaikan masalah dengan memodelkan ke dalam sistem persamaan linear.</span></li><li><span style=\"color: windowtext;\">Menentukan solusi dari sistem pertidaksamaan linear dua variabel secara grafik.</span></li><li><span style=\"color: windowtext;\">Menyelesaikan masalah dengan memodelkan ke dalam sistem pertidaksamaan linear.</span></li><li><span style=\"color: windowtext;\">Menginterpretasi karakteristik utama dari tabel maupun grafik dari fungsi kuadrat.</span></li><li><span style=\"color: windowtext;\">Menganalisis perbedaan sifat dari berbagai bentuk fungsi kuadrat (bentuk umum, bentuk titik puncak, dan bentuk akar).</span></li><li><span style=\"color: windowtext;\">Memodelkan fenomena atau data dengan fungsi kuadrat.</span></li><li><span style=\"color: windowtext;\">Menginterpretasi karakteristik utama dari tabel maupun grafik dari fungsi eksponen.</span></li><li><span style=\"color: windowtext;\">Membedakan situasi yang dapat dimodelkan dengan fungsi eksponen dan yang dapat dimodelkan dengan fungsi linear.</span></li><li><span style=\"color: windowtext;\">Memodelkan fenomena atau data dengan fungsi eksponen.</span></li><li><span style=\"color: windowtext;\">Menjelaskan pengertian vektor, notasi vektor dan panjang vektor&nbsp;</span></li><li><span style=\"color: windowtext;\">Melakukan operasi vektor (penjumlahan, pengurangan, dan perkalian dengan skalar) secara geometris</span></li><li><span style=\"color: windowtext;\">Melakukan operasi vektor (penjumlahan, pengurangan, dan perkalian dengan skalar) secara aljabar vektor </span></li><li>&nbsp;Menentukan hasil kali skalar dua vektor</li><li>&nbsp;Menentukan besar sudut antara dua vektor</li></ol><p><br></p>', 'koneksi_materi/soal/hQegwn1tzRu3qWPD44C5c2cBx3WkQ2dWHLUjLEgS.docx', 'lorem', '<p class=\"ql-align-justify\">Setelah mempelajari keseluruhan subtopik pada topik aljabar dan fungsi, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari yang melibatkan penyelesaiannya dengan konsep aljabar dan fungsi.</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Deskripsikan kegiatan rencana aksinya</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Konsep apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kendala dan tantangan yang akan dihadapi dalam implementasinya.&nbsp;</p><p><br></p>', 2, '2025-09-07 01:01:41', '2025-11-11 17:13:56'),
(2, 'Trigonometri', 'Bab kedua', '<p>Setelah mempelajari materi trigonometri, siswa diharapkan dapat:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;</p><p>1. Menentukan perbandingan trigonometri,</p><p>2. Memecahkan masalah yang melibatkan segitiga siku-siku.&nbsp;</p>', 'koneksi_materi/soal/D18QO5y3S4rkXwtHuZPR6B6x1EiPlMWOKrNmjQC3.docx', 'loem', '<p class=\"ql-align-justify\">	Setelah mempelajari keseluruhan subtopik pada topik trigonometri, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari yang melibatkan penyelesainnya dengan konsep trigonometri. </p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Deskripsikan kegiatan rencana aksinya</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Konsep trigonometri apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi </p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kendala dan tantangan yang akan dihadapi dalam implementasinya.</p><p><br></p>', 2, '2025-09-07 01:02:15', '2025-10-01 08:38:05'),
(10, 'Modul 1 (Nama Materi)', NULL, 'Masukan Tujuan Pembelajaran', 'nanti diupdate', '-', '-', 3, '2025-11-11 19:58:49', '2025-11-11 19:58:49'),
(11, 'Lingkaran', '-', '<p>Tujuan Pembelajaran:</p>', '-', '-', '-', 3, '2025-11-11 20:13:29', '2025-11-11 20:13:48'),
(14, 'Aljabar', 'Materi Aljabar kelas X', '<p>Setelah mempelajari bab ini, siswa dapat:</p><ol><li><span style=\"color: windowtext;\">Menginterpretasi bagian dari ekspresi (bentuk) eksponen sederhana, dan kompleks</span></li><li><span style=\"color: windowtext;\">Menjelaskan pengertian solusi dari sistem persamaan linear tiga variabel berdasarkan pemahaman solusi dari sistem persamaan linear dua variabel.</span></li><li><span style=\"color: windowtext;\">Menyelesaikan masalah dengan memodelkan ke dalam sistem persamaan linear.</span></li><li><span style=\"color: windowtext;\">Menentukan solusi dari sistem pertidaksamaan linear dua variabel secara grafik.</span></li><li><span style=\"color: windowtext;\">Menyelesaikan masalah dengan memodelkan ke dalam sistem pertidaksamaan linear.</span></li><li><span style=\"color: windowtext;\">Menginterpretasi karakteristik utama dari tabel maupun grafik dari fungsi kuadrat.</span></li><li><span style=\"color: windowtext;\">Menganalisis perbedaan sifat dari berbagai bentuk fungsi kuadrat (bentuk umum, bentuk titik puncak, dan bentuk akar).</span></li><li><span style=\"color: windowtext;\">Memodelkan fenomena atau data dengan fungsi kuadrat.</span></li><li><span style=\"color: windowtext;\">Menginterpretasi karakteristik utama dari tabel maupun grafik dari fungsi eksponen.</span></li><li><span style=\"color: windowtext;\">Membedakan situasi yang dapat dimodelkan dengan fungsi eksponen dan yang dapat dimodelkan dengan fungsi linear.</span></li><li><span style=\"color: windowtext;\">Memodelkan fenomena atau data dengan fungsi eksponen.</span></li><li><span style=\"color: windowtext;\">Menjelaskan pengertian vektor, notasi vektor dan panjang vektor&nbsp;</span></li><li><span style=\"color: windowtext;\">Melakukan operasi vektor (penjumlahan, pengurangan, dan perkalian dengan skalar) secara geometris</span></li><li><span style=\"color: windowtext;\">Melakukan operasi vektor (penjumlahan, pengurangan, dan perkalian dengan skalar) secara aljabar vektor </span></li><li>&nbsp;Menentukan hasil kali skalar dua vektor</li><li>&nbsp;Menentukan besar sudut antara dua vektor</li></ol><p><br></p>', 'koneksi_materi/soal/rWU2WJSVQMxFoY4P3Du1MaRUHFteYpHLnLUjIOHH.docx', 'Silahkan jawabn', '<p class=\"ql-align-justify\">Setelah mempelajari keseluruhan subtopik pada topik aljabar dan fungsi, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari yang melibatkan penyelesaiannya dengan konsep aljabar dan fungsi.</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Deskripsikan kegiatan rencana aksinya</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Konsep apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kendala dan tantangan yang akan dihadapi dalam implementasinya.&nbsp;</p><p><br></p>', 4, '2025-12-10 18:33:33', '2025-12-12 08:22:52'),
(15, 'Trigonometri', 'Materi Trigonometri kelas X', '<p>Setelah mempelajari materi trigonometri, siswa diharapkan dapat:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p><p>&nbsp;</p><p>1. Menentukan perbandingan trigonometri,</p><p>2. Memecahkan masalah yang melibatkan segitiga siku-siku.&nbsp;</p>', 'koneksi_materi/soal/0I63vTFdeqG0G2OnqUrWCziCs1m6QHMUSDDGj0Z6.docx', 'fff', '<p class=\"ql-align-justify\">Setelah mempelajari keseluruhan subtopik pada topik trigonometri, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari yang melibatkan penyelesainnya dengan konsep trigonometri.</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Deskripsikan kegiatan rencana aksinya</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Konsep trigonometri apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi</p><p class=\"ql-align-justify\">·&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Kendala dan tantangan yang akan dihadapi dalam implementasinya.</p><p><br></p>', 4, '2025-12-10 18:43:14', '2025-12-10 19:22:22'),
(17, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Sistem pertidaksamaan linear dua variabel adalah kumpulan dari dua atau lebih pertidaksamaan linear yang masing-masing melibatkan dua variabel (biasanya \r\n𝑥 dan y). Tujuannya adalah untuk menentukan daerah penyelesaian (region solution), yaitu himpunan semua pasangan (𝑥,𝑦) yang memenuhi seluruh pertidaksamaan dalam sistem tersebut.', '<p>Setelah mempelajari bab ini, siswa dapat:</p><ol><li><span style=\"color: windowtext;\">Menentukan solusi dari sistem pertidaksamaan linear dua variabel secara grafik.</span></li><li><span style=\"color: windowtext;\">Menyelesaikan masalah dengan memodelkan ke dalam sistem pertidaksamaan linear.</span></li></ol><p><br></p>', 'koneksi_materi/soal/dwcxuvVc6JsC4z8MmnnrQ0IF6nBT1svEzqttD3ex.docx', 'a', '<p>Setelah mempelajari keseluruhan subtopik pada materi sistem pertidaksamaan linear, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari.</p><p>Pergilah ke kantin sekolah yang menjual makanan secara paket. Pilihlah paket-paket yang dapat dinyatakan sebagai sistem pertidaksamaan linear dua variabel, kemudian tentukan harga setiap jenis makanan/minumannya.&nbsp;</p>', 2, '2026-01-05 23:20:24', '2026-01-28 02:45:11'),
(23, 'Sistem Persamaan Linear', 'BAB 5', '<p>Setelah mempelajari materi ini, siswa dapat: </p><ol><li>Menjelaskan pengertian solusi dari sistem persamaan linear tiga variabel berdasarkan pemahaman solusi dari sistem persamaan linear dua variabel.</li><li>Menyelesaikan masalah dengan memodelkan ke dalam sistem persamaan linear.</li></ol>', 'koneksi_materi/soal/jOUVkcx3aRzEQOzKX7NCIHqLztqDgAE3vNwD3vIU.pdf', 'Tes Kompetensi ini untuk mengukur pemahaman kalian terhadap materi yang sudah dipelajari', 'Setelah mempelajari keseluruhan subtopik pada materi sistem persamaan linear, buatlah sebuah rencana aksi nyata dalam kehidupan sehari hari yang melibatkan penyelesaiannya dengan konsep sistem persamaan linear tiga variabel. \r\n1.	Deskripsikan kegiatan rencana aksinya.\r\n2.	Konsep apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi.\r\n3.	Kendala dan tantangan yang akan dihadapi dalam implementasinya.', 5, '2026-01-20 02:38:32', '2026-01-21 04:41:15'),
(28, 'Sistem Pertidaksamaan Linear', 'Lanjutan BAB 5', '<p>Setelah mempelajari modul ini, siswa dapat:</p><ol><li>Menentukan solusi dari sistem pertidaksamaan linear dua variabel secara grafik.</li><li>Menyelesaikan masalah dengan memodelkan ke dalam sistem pertidaksamaan linear.</li></ol>', 'koneksi_materi/soal/Vw4ShsXDV8mMm4ZRecjirolqTTAuyVLzGtuapufx.pdf', 'kerjakan tes ini', 'Setelah mempelajari keseluruhan subtopik pada materi sistem pertidaksamaan linear dua variabel, buatlah sebuah rencana aksi nyata dalam kehidupan sehari hari yang melibatkan penyelesaiannya dengan konsep sistem pertidaksamaan linear dua variabel. \r\n1.	Deskripsikan kegiatan rencana aksinya.\r\n2.	Konsep apa yang digunakan untuk menjawab penyelesaian kegiatan rencana aksi.\r\n3.	Kendala dan tantangan yang akan dihadapi dalam implementasinya', 5, '2026-01-27 07:50:37', '2026-01-28 05:32:48'),
(34, 'Penyajian Data', 'Penyajian data adalah proses menyusun, menampilkan, atau menyajikan data yang telah dikumpulkan agar mudah dipahami, dianalisis, dan diambil kesimpulan.', '<p>Setelah mempelajari bab ini, Siswa dapat :</p><ol><li class=\"ql-align-justify\">Membedakan berbagai macam jenis data serta membuat graik yang sesuai dan merepresentasikan data tersebut, serta melakukan analisis data untuk pengambilan kesimpulan.</li><li class=\"ql-align-justify\">Menggambar dan menginterpretasikan histogram, diagram garis batang, line plot.</li></ol>', 'koneksi_materi/soal/y9ZtooDo73k5LEeiBw1yVVdaUUjTiaWxPwd0xmud.docx', NULL, '<p>Setelah mempelajari keseluruhan subtopik pada materi penyajian data, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari.</p><p>Carilah data yang dapat kamu kumpulkan secara langsung, seperti ukuran tinggi badan atau berat badan siswa.</p><p>Kemudian sajikan data yang diperoleh dalam bentuk tabel distribusi frekuansi dan histogram. </p><p>Selanjutnya, tentukan data yang paling banyak muncul dan buatlah kesimpulan berdasarkan data tersebut.</p>', 2, '2026-05-01 20:10:33', '2026-05-17 18:29:40'),
(35, 'Penyajian Data', 'Penyajian data adalah proses menyusun, menampilkan, atau menyajikan data yang telah dikumpulkan agar mudah dipahami, dianalisis, dan diambil kesimpulan.', '<p>Setelah mempelajari bab ini, Siswa dapat :</p><ol><li class=\"ql-align-justify\">Membedakan berbagai macam jenis data serta membuat graik yang sesuai dan merepresentasikan data tersebut, serta melakukan analisis data untuk pengambilan kesimpulan.</li><li class=\"ql-align-justify\">Menggambar dan menginterpretasikan histogram, diagram garis batang, line plot.</li></ol><p><br></p>', 'koneksi_materi/soal/FUc3siGtRuanzG7Lfel6CfITTRe0qBmeujLNcdcE.docx', NULL, '<p>Setelah mempelajari keseluruhan subtopik pada materi penyajian data, buatlah sebuah rencana aksi nyata dalam kehidupan sehari-hari.</p><p>Carilah data yang dapat kamu kumpulkan secara langsung, seperti tinggi badan atau berat badan siswa.</p><p>Kemudian sajikan data yang diperoleh dalam bentuk tabel distribusi frekuansi dan histogram. </p><p>Selanjutnya, tentukan data yang paling banyak muncul dan buatlah kesimpulan berdasarkan data tersebut.</p>', 4, '2026-05-03 06:13:11', '2026-05-17 16:56:50'),
(38, 'Aljabar', 'mmmmm', 'Siswa dapat menjelaskan', 'koneksi_materi/soal/gPIY70BJV6MvtnX8ytylGdepg5B5qKItX3ZjZHKR.pdf', 'vv', 'vv', 6, '2026-06-12 08:46:01', '2026-06-12 08:52:25');
