INSERT INTO `topik_diskusi` (`id_topik_diskusi`, `id_materi`, `id_user`, `judul`, `deskripsi`, `status`, `dibuka_pada`, `ditutup_pada`, `created_at`, `updated_at`) VALUES
(2, 20, 2, 'Diskusi ruang sampel dan kejadian', 'Dalam percobaan melempar satu koin dan satu dadu secara bersamaan, ruang sampelnya dapat ditulis sangat panjang (12 titik sampel), atau cukup ditulis dalam pola “(H/M, 1–6)”.\r\n Menurut pendapatmu, apakah penulisan ruang sampel harus selalu dituliskan lengkap per titik sampel, atau boleh disingkat asalkan maknanya jelas? Jelaskan alasanmu!', 'aktif', '2025-11-10 02:01:25', NULL, '2025-11-10 02:01:25', '2025-11-10 02:01:25'),
(3, 21, 2, 'Diskusi Peluang Suatu Kejadian', 'Apa yang dimaksud peluang suatu kejadian', 'aktif', '2025-11-10 04:36:42', NULL, '2025-11-10 04:36:42', '2025-11-10 04:36:42'),
(4, 1, 2, 'Diskusi Ekspresi Eksponen', 'Mengapa konsep pertumbuhan yang sangat cepat, seperti jumlah pengguna media sosial atau penyebaran informasi di internet, sering disebut bersifat eksponensial?\r\nSilahkan beri komentar sesuai pendapat masing-masing', 'aktif', '2025-11-11 07:57:47', NULL, '2025-11-11 07:57:47', '2025-11-11 07:57:47'),
(5, 2, 2, 'Diskusi Sistem Persamaan dan Pertidaksamaan Linear', 'Bagaimana kalian dapat menjelaskan konsep “dua variabel yang saling memengaruhi” dengan contoh sederhana dari kehidupanmu sehari-hari?', 'aktif', '2025-11-11 08:23:56', NULL, '2025-11-11 08:23:56', '2025-11-11 08:23:56'),
(6, 8, 2, 'Diskusi Fungsi Kuadrat', 'Jika kalian diminta menjelaskan fungsi kuadrat kepada teman yang tidak suka matematika, contoh apa yang akan kalian gunakan agar mudah dipahami?', 'aktif', '2025-11-11 08:36:07', NULL, '2025-11-11 08:36:07', '2025-11-11 08:36:07'),
(7, 9, 2, 'Diskusi Fungsi Eksponensial', 'Bagaimana fungsi eksponensial dapat menjelaskan penyebaran virus atau informasi yang sangat cepat dari satu orang ke banyak orang?', 'aktif', '2025-11-11 08:45:39', NULL, '2025-11-11 08:45:39', '2025-11-11 08:45:39'),
(8, 10, 2, 'Diskusi Vektor', 'Dalam olahraga seperti sepak bola atau basket, bagaimana pemain menggunakan konsep vektor secara tidak langsung saat menendang atau melempar bola?', 'aktif', '2025-11-11 08:56:01', NULL, '2025-11-11 08:56:01', '2025-11-11 08:56:01'),
(9, 23, 2, 'Diksusi Persamaan garis singgung', 'Menurutmu, apa makna “arah perubahan” pada titik singgung dalam kehidupan nyata, misalnya pada gerak kendaraan di tikungan?', 'aktif', '2025-11-11 20:20:44', NULL, '2025-11-11 20:20:44', '2025-11-11 20:20:44'),
(10, 29, 213, 'Diskusi Ekspresi Eksponen', 'Mengapa konsep pertumbuhan yang sangat cepat, seperti jumlah pengguna media sosial atau penyebaran informasi di internet, sering disebut bersifat eksponensial?\r\nSilahkan beri komentar sesuai pendapat masing-masing', 'aktif', '2025-12-10 18:46:17', NULL, '2025-12-10 18:46:17', '2025-12-10 18:46:17'),
(11, 30, 213, 'Diskusi Sistem Persamaan dan Pertidaksamaan Linear', 'Bagaimana kalian dapat menjelaskan konsep “dua variabel yang saling memengaruhi” dengan contoh sederhana dari kehidupanmu sehari-hari?', 'aktif', '2025-12-10 18:52:37', NULL, '2025-12-10 18:52:37', '2025-12-10 18:52:37'),
(12, 31, 213, 'Diskusi Fungsi Kuadrat', 'Jika kalian diminta menjelaskan fungsi kuadrat kepada teman yang tidak suka matematika, contoh apa yang akan kalian gunakan agar mudah dipahami?', 'aktif', '2025-12-10 19:01:19', NULL, '2025-12-10 19:01:19', '2025-12-10 19:01:19'),
(13, 32, 213, 'Diskusi Fungsi Eksponen', 'Bagaimana fungsi eksponensial dapat menjelaskan penyebaran virus atau informasi yang sangat cepat dari satu orang ke banyak orang?', 'aktif', '2025-12-10 19:05:33', NULL, '2025-12-10 19:05:33', '2025-12-10 19:05:33'),
(14, 33, 213, 'Diskusi Vektor', 'Dalam olahraga seperti sepak bola atau basket, bagaimana pemain menggunakan konsep vektor secara tidak langsung saat menendang atau melempar bola?', 'aktif', '2025-12-10 19:09:23', NULL, '2025-12-10 19:09:23', '2025-12-10 19:09:23'),
(15, 33, 213, 'Diskusi Vektor', 'Dalam olahraga seperti sepak bola atau basket, bagaimana pemain menggunakan konsep vektor secara tidak langsung saat menendang atau melempar bola?', 'aktif', '2025-12-10 19:09:23', NULL, '2025-12-10 19:09:23', '2025-12-10 19:09:23'),
(16, 34, 213, 'Diskusi Perbandingan Trigometri', 'Seorang teknisi ingin mengetahui ketinggian menara listrik tanpa harus memanjatnya. Ia membawa alat pengukur sudut, tetapi jarak horizontal yang ia tempuh tidak bisa diukur dengan pasti karena medan yang tidak rata.\r\nPertanyaan Diskusi:\r\nBagaimana teknisi dapat meminimalkan kesalahan pengukuran ketika jarak datar tidak dapat diukur dengan akurat? Strategi alternatif apa yang bisa digunakan untuk tetap menggunakan konsep perbandingan trigonometri?', 'aktif', '2025-12-10 19:31:38', NULL, '2025-12-10 19:31:38', '2025-12-10 19:31:38'),
(17, 11, 213, 'Diskusi Perbandingan Trigonometri', 'Seorang teknisi ingin mengetahui ketinggian menara listrik tanpa harus memanjatnya. Ia membawa alat pengukur sudut, tetapi jarak horizontal yang ia tempuh tidak bisa diukur dengan pasti karena medan yang tidak rata.\r\nPertanyaan Diskusi:\r\nBagaimana teknisi dapat meminimalkan kesalahan pengukuran ketika jarak datar tidak dapat diukur dengan akurat? Strategi alternatif apa yang bisa digunakan untuk tetap menggunakan konsep perbandingan trigonometri?', 'aktif', '2025-12-12 08:43:28', NULL, '2025-12-12 08:43:28', '2025-12-12 08:43:28'),
(18, 35, 189, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Seorang siswa ingin membeli dua jenis barang di koperasi sekolah.\r\nUang yang dimilikinya terbatas, sehingga jumlah pembelian tidak boleh melebihi batas yang ada.\r\nBatasan apa yang terdapat dalam masalah tersebut dan bagaimana batasan itu dinyatakan dalam model matematika?', 'aktif', '2026-01-06 01:42:21', NULL, '2026-01-06 01:42:21', '2026-01-06 01:42:21'),
(19, 35, 189, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Seorang siswa ingin membeli dua jenis barang di koperasi sekolah.\r\nUang yang dimilikinya terbatas, sehingga jumlah pembelian tidak boleh melebihi batas yang ada.\r\nBatasan apa yang terdapat dalam masalah tersebut dan bagaimana batasan itu dinyatakan dalam model matematika?', 'aktif', '2026-01-06 01:42:22', NULL, '2026-01-06 01:42:22', '2026-01-06 01:42:22'),
(20, 35, 189, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Perhatikan pernyataan berikut:\r\n1.	“Uang yang digunakan tidak boleh lebih dari Rp20.000.”\r\n2.	“Jumlah siswa minimal 30 orang.”\r\n3.	“Kecepatan kendaraan tidak melebihi 60 km/jam.”\r\nDiskusikan bersama kelompok kalian:\r\n1.	Pernyataan mana yang menunjukkan persamaan dan mana yang menunjukkan pertidaksamaan?\r\n2.	Menurut kalian, pernyataan tersebut lebih cocok menggunakan tanda =, ≤, atau ≥?\r\n3.	Jelaskan arti tanda tersebut dengan bahasa kalian sendiri', 'aktif', '2026-01-08 02:45:07', NULL, '2026-01-08 02:45:07', '2026-01-08 02:45:07'),
(21, 38, 359, 'Diskusi Solusi Persamaan Linear Tiga Variabel', '1.	Apa yang dimaksud solusi SPLTV? \r\n2. Apakah solusi SPLTV harus memenuhi satu persamaan saja? Jelaskan.\r\n3. Berikan contoh SPLTV, kemudian tentukan solusinya.\r\n4.	Ada berapa solusi dari contoh yang kalian buat? Jelaskan.', 'aktif', '2026-01-14 05:19:28', NULL, '2026-01-14 05:19:28', '2026-01-14 05:19:28'),
(22, 42, 359, 'Solusi Persamaan Linear Tiga Variabel', 'Jawablah pertanyaan berikut bersama teman kelompok mu!\r\n1. Apa yang dimaksud solusi SPLTV?\r\n2. Apakah solusi SPLTV harus memenuhi satu persamaan saja? Jelaskan. \r\n3. Diberikan sistem persamaan linear tiga variabel yaitu 3x + 7y + 2z = 8; 4x + 2y - 5z = -19; dan 6y - 4z = 14. Tentukan solusi dari sistem persamaan linear tersebut!', 'aktif', '2026-01-20 02:55:33', NULL, '2026-01-20 02:55:33', '2026-01-20 02:55:33'),
(23, 46, 359, 'Ueue', 'Jdudu', 'aktif', '2026-01-23 04:44:07', NULL, '2026-01-23 04:44:07', '2026-01-23 04:44:07'),
(24, 50, 359, 'penyelesaian sistem pertidaksamaan linear dua variabel', 'Jawablah pertanyaan berikut bersama teman kelompok mu!\r\nTentukan daerah penyelesaian dari sistem pertidaksamaan 3x+4y≤12; 2x+y≥4; x≥0; y≥0.', 'aktif', '2026-01-27 08:06:58', NULL, '2026-01-27 08:06:58', '2026-01-27 08:06:58'),
(25, 35, 189, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Pada kegiatan bazar sekolah, panitia menjual dua jenis paket:\r\nPaket A membutuhkan: 3 kue dan 2 minuman\r\nPaket B membutuhkan: 2 kue dan 4 minuman\r\nPersediaan: 120 kue dan 160 minuman\r\nPanitia ingin menjual paket sebanyak mungkin tanpa melebihi persediaan.\r\n1.	Apa yang kamu misalkan sebagai variabel?\r\n2.	Tuliskan Model matematika dari masalah tersebut.\r\n3.	Jelaskan arti setiap pertidaksamaan yang kamu buat.', 'aktif', '2026-03-03 00:41:41', NULL, '2026-03-03 00:41:41', '2026-03-03 00:41:41'),
(26, 35, 189, 'Sistem Pertidaksamaan Linear Dua Variabel', 'Pada kegiatan bazar sekolah, panitia menjual dua jenis paket:\r\nPaket A membutuhkan: 3 kue dan 2 minuman\r\nPaket B membutuhkan: 2 kue dan 4 minuman\r\nPersediaan: 120 kue dan 160 minuman\r\nPanitia ingin menjual paket sebanyak mungkin tanpa melebihi persediaan.\r\n1.	Apa yang kamu misalkan sebagai variabel?\r\n2.	Tuliskan Model matematika dari masalah tersebut.\r\n3.	Jelaskan arti setiap pertidaksamaan yang kamu buat.', 'aktif', '2026-03-03 00:41:41', NULL, '2026-03-03 00:41:41', '2026-03-03 00:41:41'),
(27, 56, 433, 'Penyajian Data', 'Kantin di SMA Negeri 10 beroperasi aktif pada hari Senin sampai Sabtu. Pihak sekolah ingin mengetahui waktu paling ramai di kantin agar dapat mengatur jumlah makanan yang disediakan setiap hari.\r\nSelama 5 minggu (30 hari sekolah), dicatat jumlah pembeli kantin pada jam istirahat sebagai berikut:\r\n12, 15, 18, 20, 22, 25, 28, 30, 14, 16,\r\n19, 21, 23, 26, 29, 31, 13, 17, 24, 27,\r\n18, 20, 22, 25, 28, 30, 15, 19, 21, 23\r\nTugas Kelompok\r\n1. Sajikan data tersebut ke dalam tabel distribusi frekuensi dengan langkah:\r\na. Mengurutkan data\r\nb. Menentukan nilai minimum dan maksimum\r\nc. Menghitung jangkauan\r\nd. Menentukan banyak kelas\r\ne. Menentukan panjang interval\r\nf.  Menyusun tabel distribusi frekuensi\r\n2. Buatlah histogram dari data tersebut!\r\n3. Berdasarkan hasil yang diperoleh, diskusikan:\r\na. Pada interval berapa jumlah pembeli paling banyak?\r\nb. Pada kondisi seperti apa kantin dianggap paling ramai?\r\n\r\nJika kamu sebagai pengelola kantin, bagaimana cara mengatur:\r\njumlah makanan\r\nwaktu persiapan\r\nagar tidak terjadi kekurangan atau pemborosan?', 'aktif', '2026-05-03 10:11:38', NULL, '2026-05-03 10:11:38', '2026-05-03 10:11:38'),
(28, 55, 433, 'Distribusi Frekuensi', 'Kantin di SMA Negeri 10 beroperasi aktif pada hari Senin sampai Sabtu. Pihak sekolah ingin mengetahui waktu paling ramai di kantin agar dapat mengatur jumlah makanan yang disediakan setiap hari.\r\nSelama 5 minggu (30 hari sekolah), dicatat jumlah pembeli kantin pada jam istirahat sebagai berikut:\r\n12, 15, 18, 20, 22, 25, 28, 30, 14, 16,\r\n19, 21, 23, 26, 29, 31, 13, 17, 24, 27,\r\n18, 20, 22, 25, 28, 30, 15, 19, 21, 23\r\nTugas Kelompok\r\n1. Sajikan data tersebut ke dalam tabel distribusi frekuensi dengan langkah:\r\na. Mengurutkan data\r\nb. Menentukan nilai minimum dan maksimum\r\nc. Menghitung jangkauan\r\nd. Menentukan banyak kelas\r\ne. Menentukan panjang interval\r\nf.  Menyusun tabel distribusi frekuensi\r\n2. Buatlah histogram dari data tersebut!\r\n3. Berdasarkan hasil yang diperoleh, diskusikan:\r\na. Pada interval berapa jumlah pembeli paling banyak?\r\nb. Pada kondisi seperti apa kantin dianggap paling ramai?\r\n\r\nJika kamu sebagai pengelola kantin, bagaimana cara mengatur:\r\njumlah makanan\r\nwaktu persiapan\r\nagar tidak terjadi kekurangan atau pemborosan?', 'aktif', '2026-05-07 05:21:02', NULL, '2026-05-07 05:21:02', '2026-05-07 05:21:02'),
(29, 58, 359, 'j', 'k', 'aktif', '2026-05-18 08:10:52', NULL, '2026-05-18 08:10:52', '2026-05-18 08:10:52');
